-- the defence slot (the game's MainCharacterPowersSlotGroup): Armour is worn over whichever attack power is out
-- (user: "броня должна работать вне зависимости от выбранной мутации"); the shield / spines share that slot
local ARMOUR
for i, f in ipairs(FORMS) do if f.name == "Броня" then ARMOUR = i end end
ALEX_MERCER_ARMOUR = ARMOUR
for i, f in ipairs(FORMS) do if f.shield then ALEX_MERCER_SHIELD = i end end
local ARMOUR_MODELS = {["Обычный"] = "models/mercer/alex_mercer_armor.mdl",
	["Когти"] = "models/mercer/alex_mercer_claws_armor.mdl", ["Клинок"] = "models/mercer/alex_mercer_blade_armor.mdl",
	["Молот"] = "models/mercer/alex_mercer_hammer_armor.mdl", ["Хлыст"] = "models/mercer/alex_mercer_whip_armor.mdl",
	["Мускулы"] = "models/mercer/alex_mercer_muscle_armor.mdl",
	-- (user 2026-10-08: the armour with the shield too - not in the game) the armour's body and arms + the shield
	["Щит"] = "models/mercer/alex_mercer_shield_armor.mdl"}
for _, f in ipairs(FORMS) do f.armorModel = ARMOUR_MODELS[f.name] end

function ENT:GetMercerForm()
	local i = self:GetNW2Int("MercerForm", 1)
	if i == ARMOUR then i = 1 end
	return FORMS[i] or FORMS[1]
end

function ENT:MercerArmour()
	return self:GetNW2Int("MercerDefense", 0) == ARMOUR
end

-- the shield out: worn over the attack power (the defence slot, ENT:MercerSetShield) or as a power of its own (the old way)
function ENT:MercerShieldOut()
	return self:GetNW2Bool("MercerShieldOn") or self:GetMercerForm().shield == true
end

-- Stances = the prototype graph's idle banks (build/graph_prototype.txt). bank combat while outOfCombatTimer < 10 s
-- (an attack, a hit given or taken restarts it): the armour's alex_armor_amb_fight; with no attack power out
-- alex_amb_fight_A, after 1.2 s a random alex_amb_fight_B / _C and back to A; once 10 s pass, back to the calm idle
-- (user: after a punch, even into the air, he stays in the fight stance). bank calm: the attack powers keep their own
-- stance all the time (claws alex_claw_amb_fight, blades / whipfist amb_fight, hammerfist amb_combat with a fidget -
-- amb_fake / knuckle slam - after every 1-2 s), the armour alone alex_claw_amb_stand, else the normal idle.
local COMBAT_TIME = 10
local FIDGETS = {
	bare = {base = "alex_amb_fight_a", wait = {1.2, 1.2}, list = {"alex_amb_fight_b", "alex_amb_fight_c"}},
	hammer = {base = "alex_hammer_amb_combat", wait = {1, 2},
		list = {"alex_hammer_amb_fake", "alex_hammer_amb_knuckle_slam_001_brett"},
		-- the knuckle slam's sound item: whoosh_small at 0.45 s (volume 0.6154, pitch 0.7-0.75)
		onStart = function(self, a)
			if SERVER and a == "alex_hammer_amb_knuckle_slam_001_brett" and self.Timer then
				-- its sound items: whoosh_small 0.45 s and alex_punch_human 0.5 s (volume 0.6154, pitch 0.7-0.75)
				self:Timer(0.45, function(ent) if ent.MercerCue then ent:MercerCue("whoosh_small", 0.6154, 0.72) end end)
				self:Timer(0.5, function(ent) if ent.MercerCue then ent:MercerCue("alex_punch_human", 0.6154, 0.72) end end)
			end
		end},
	-- prototype loco/default/bank/idles/calm/default: alex_amb_stand, wait 1-2 s, then one of the random poses (weights
	-- 5 / 16 / 16 / 13 / 11 / 11; break_2 only without a power, look_left only with the musclemass), back to the stand
	calm = {base = "alex_amb_stand", wait = {1, 2}, list = {
		{"alex_amb_stand_break_2", 5, function(self) return self:GetMercerForm().name == "Обычный" end},
		{"alex_amb_stand_look_back", 16},
		{"alex_amb_stand_look_left", 16, function(self) return self:GetMercerForm().name == "Мускулы" end},
		{"alex_amb_stand_look_right", 13},
		{"alex_amb_stand_shift_weight_1", 11},
		{"alex_amb_stand_shift_weight_2", 11}}},
}

function ENT:MercerCombatEvent()
	self:SetNW2Float("MercerCombatT", CurTime())
end

function ENT:MercerInCombat()
	return CurTime() - self:GetNW2Float("MercerCombatT", -100) < COMBAT_TIME
end

local function fidget(self, F)
	local now = CurTime()
	local st = self.MercerFidget
	if not st or st.set ~= F or now - st.seen > 0.25 then
		st = {set = F, anim = F.base, t0 = now, dur = math.Rand(F.wait[1], F.wait[2])}
		self.MercerFidget = st
	end
	st.seen = now
	if now - st.t0 >= st.dur then
		if st.anim == F.base then
			-- weighted (the graph's random items) among the ones whose condition holds; plain names weigh 1
			local pool, sum = {}, 0
			for _, x in ipairs(F.list) do
				local name, w, ok = x, 1, nil
				if type(x) == "table" then name, w, ok = x[1], x[2], x[3] end
				if not ok or ok(self) then
					pool[#pool + 1] = {name, w}
					sum = sum + w
				end
			end
			local a = pool[1] and pool[1][1] or F.base
			local r = math.random() * sum
			for _, x in ipairs(pool) do
				r = r - x[2]
				if r <= 0 then a = x[1] break end
			end
			st.anim, st.t0 = a, now
			st.dur = ((ALEX_MERCER_FRAMES and ALEX_MERCER_FRAMES[a] or 37) - 1) / 30
			if F.onStart then F.onStart(self, a) end
		else
			st.anim, st.t0, st.dur = F.base, now, math.Rand(F.wait[1], F.wait[2])
		end
	end
	return st.anim
end

function ENT:MercerStance(f)
	local combat = self:MercerInCombat()
	if self:MercerArmour() and f.name == "Обычный" then
		-- the armour's own stances (alex_armor_amb_fight in combat, alex_claw_amb_stand calm) only with the bare fists:
		-- every mutation keeps its own stance on the armour (user's choice over the game's idles order, where the
		-- armour node came first in combat)
		if combat then return FORMS[ARMOUR].idle end
		return "alex_claw_amb_stand"
	end
	-- (the game's idles/calm/hammerfist also calms him into alex_claw_amb_stand after 10 s out of combat - tried, the user
	-- kept the hammer stance; its face is neutralised in the anim build instead: tools/build_all.py FACE_NEUTRAL)
	if f.stance then return fidget(self, FIDGETS[f.stance]) end
	-- (the shield up - alex_shield_impact 9-10 held - only under fire: the shield block's guard node; the stance looped the
	-- whole hit flinch before)
	if f.kind ~= "attack" or f.name == "Обычный" or f.name == "Мускулы" then
		-- the default idles: combat (fight_A + B / C), calm (the stand and its random poses)
		if combat then return fidget(self, FIDGETS.bare) end
		if f.idle == "alex_amb_stand" then return fidget(self, FIDGETS.calm) end
	end
	return f.idle
end

function ENT:MercerModel()
	local f = self:GetMercerForm()
	if self:MercerArmour() then return f.armorModel or FORMS[ARMOUR].model end
	return f.model
end

-- Possession --
ENT.PossessionEnabled = true
ENT.PossessionCrosshair = false -- (user: no crosshair while playing as him; the lock's reticle instead)
-- Custom movement like the game: no snapping to the camera. Standing still keeps the facing; moving turns
-- smoothly toward the input direction (sprint 360 °/s from the game's sprint controller).
ENT.PossessionMovement = POSSESSION_MOVE_CUSTOM
ENT.PossessionViews = {
	{offset = Vector(0, 30, 20), distance = 140},
	{offset = Vector(0, 0, 0), distance = 0, eyepos = true},
}
ENT.PossessionBinds = {
	-- LMB / RMB are read every tick in CustomThink (MercerKeyPressed / MercerPress: DrGBase reads KeyPressed inside
	-- the behaviour coroutine, which doesn't run every tick - user: LMB / RMB sometimes did nothing); the coroutine
	-- binds only run what has to yield (the spines' strikes), queued by MercerPress
	[IN_ATTACK] = {{coroutine = true, onkeydown = function(self) self:MercerCoPress() end,
		onkeyup = function(self) self:MercerCoPress() end}},
	[IN_ATTACK2] = {{coroutine = true, onkeydown = function(self) self:MercerCoPress() end,
		onkeyup = function(self) self:MercerCoPress() end}},
	-- (the jump: ENT:MercerJumpKeys, from these two every think; the two below only with alex_mercer_jump_edges 0)
	[IN_JUMP] = {{coroutine = false,
		onkeydown = function(self, p) self:MercerJumpKeys(p, true) end,
		onkeyup = function(self, p) self:MercerJumpKeys(p, false) end,
		onkeypressed = function(self) if not self.MercerJumpEdges:GetBool() then self:MercerJumpCharge() end end,
		onkeyreleased = function(self) if not self.MercerJumpEdges:GetBool() then self:MercerJumpRelease() end end}},
	-- (the next power: ENT:MercerReloadKeys, from the two below every think; the first only with alex_mercer_jump_edges 0)
	[IN_RELOAD] = {{coroutine = true, onkeypressed = function(self)
		if not self.MercerJumpEdges:GetBool() then self:MercerNextPower() end
	end}, {coroutine = false,
		onkeydown = function(self, p) self:MercerReloadKeys(p, true) end,
		onkeyup = function(self, p) self:MercerReloadKeys(p, false) end}},
}

-- Locomotion = the game's own motion drivers, field for field. Graph items locoSprint (prototype_sprint →
-- sprint/loco/default) and locoCrowd (alex_fig.p3d prototype → loco/default); their fields and update code were
-- read out of prototypeenginef.dll (MODLOG 2026-10-03 "locomotion port", tools build/re_loco*.asm):
--  locoSprint: velocityMin/Mid/Max 10 / 14 / 20 m/s with animMin/Mid/Max = run_sprint_n / n1 / n2 (forced anim
--   velocities: every anim plays at its own cycle rate, whatever the speed), acceleration 2.5 at 10 m/s -> 0.75 at
--   14 -> 1.5 at 20 m/s² (smoothstep between), deceleration 5 m/s², turn rate 360 °/s at 10 m/s .. 90 °/s at
--   20 m/s, turn acceleration 4800 .. 1200 °/s², turning brakes the sprint by up to 5 m/s², lean (banking anims
--   trans_sprint_bnk_w/e_min) follows the turn at rate 5, unlockables Sprint1..Sprint3 (13 m/s without any).
--   It starts at max(current speed, 10 m/s), entered by the graph's dash node, left by its exit node
--   (run_sprint_stop).
--  locoCrowd: acceleration 15 m/s², heading 300 °/s, run = the run anim's own speed, twist anims
--   (run_upper_left / right) blended in at 3 /s while turning, out at 1.5 /s.
local M2U = 39.37
local SPR = {vMin = 10, vMid = 14, vMax = 20, accMin = 2.5, accMid = 0.75, accMax = 1.5, decel = 5,
	turnVelMin = 360, turnVelMax = 90, turnAccMin = 4800, turnAccMax = 1200, turnDecel = 5, leanRate = 5,
	unlockVelMin = 13, unlockCount = 3}
local SPRINT_TURN_FULL = 45 -- heading error (deg) that asks for the full sprint turn rate (game: 180)
local DASH_PEAK = 16 -- m/s: the dash push is kept up to this, and the sprint goes on from it
local CROWD = {accel = 15, turn = 300, twistOn = 3, twistOff = 1.5}
-- cycle lengths (s) of the mercer_sprint grid (rows lean W / 0 / E, columns n / n1 / n2) for the playback rate
local SPR_T = {{0.4667, 0.4667, 0.4667}, {0.5333, 0.4667, 0.4}, {0.4667, 0.4667, 0.4667}}
-- user: the game's ramp (~8 s to 20 m/s) felt slow -> its accelerations are multiplied by this
