local SprintLevel = CreateConVar("alex_mercer_sprint_level", "3", {FCVAR_ARCHIVE, FCVAR_REPLICATED},
	"Alex Mercer sprint upgrades unlocked 0-3 (game: Sprint1..Sprint3; 3 = top speed 20 m/s)", 0, 3)

-- the game's target sprint speed for the unlocked upgrades (full stick)
local function sprintTarget()
	local frac = (math.Clamp(SPR.unlockVelMin, SPR.vMin, SPR.vMax) - SPR.vMin) / (SPR.vMax - SPR.vMin)
	local x = frac + math.Clamp(SprintLevel:GetInt(), 0, SPR.unlockCount) / SPR.unlockCount * (1 - frac)
	if x > 0.5 then return (x - 0.5) * 2 * (SPR.vMax - SPR.vMid) + SPR.vMid end
	return x * 2 * (SPR.vMid - SPR.vMin) + SPR.vMin
end

local function smooth01(x)
	if x <= 0 then return 0 elseif x >= 1 then return 1 end
	return x * x * (3 - 2 * x)
end

-- 0..1 sprint intensity for effects / camera (0 = not sprinting)
function ENT:GetMercerSprint()
	return self:GetNW2Float("MercerSprint", 0)
end

-- mercer_sprint pose: speed 0..2 across n / n1 / n2 (10 / 14 / 20 m/s)
local function sprintSpeedParam(v)
	if v <= SPR.vMid then return math.Clamp((v - SPR.vMin) / (SPR.vMid - SPR.vMin), 0, 1) end
	return math.Clamp(1 + (v - SPR.vMid) / (SPR.vMax - SPR.vMid), 1, 2)
end

-- playback rate of mercer_sprint that gives the game's phase speed: the game advances the phase by
-- dt / (sum w * cycle length); Source by dt * sum(w / cycle length)
local function sprintRate(u, lean)
	local i = math.min(math.floor(u), 1)
	local fu = math.Clamp(u - i, 0, 1)
	local v = math.Clamp(lean + 1, 0, 2)
	local j = math.min(math.floor(v), 1)
	local fv = math.Clamp(v - j, 0, 1)
	local T, cps = 0, 0
	for dj = 0, 1 do
		for di = 0, 1 do
			local w = (di == 0 and 1 - fu or fu) * (dj == 0 and 1 - fv or fv)
			local t = SPR_T[j + dj + 1][i + di + 1]
			T = T + w * t
			cps = cps + w / t
		end
	end
	return 1 / (T * cps)
end

-- Skydive / glide pose: the game's "skydive" state uses alex_bullet_smash_glide_forward/left/right/backward.
function ENT:MercerGlideAnim()
	local p = self:GetPossessor()
	if IsValid(p) then
		if p:KeyDown(IN_MOVELEFT) and not p:KeyDown(IN_MOVERIGHT) then return "alex_bullet_smash_glide_left" end
		if p:KeyDown(IN_MOVERIGHT) and not p:KeyDown(IN_MOVELEFT) then return "alex_bullet_smash_glide_right" end
	end
	return "alex_bullet_smash_glide_forward"
end

-- Dynamic third-person camera (replaces DrGBase's fixed preset): lags behind Mercer, pulls back with speed
-- and with height above the ground so a big jump never loses him; the client also widens the FOV.
-- (user: ordinary landings pulled the camera far out, it went too far overall) only the horizontal speed counts
-- (falling no longer pushes it back), the height only from 3 m up, and never past 330 u (was up to ~670)
function ENT:MercerCamDistance()
	local v = self:GetVelocity()
	local dist = 150 + math.min(Vector(v.x, v.y, 0):Length() * 0.08, 80)
	if not self:IsOnGround() then
		local tr = util.TraceLine({start = self:GetPos(), endpos = self:GetPos() - Vector(0, 0, 3000),
			filter = self, mask = MASK_SOLID_BRUSHONLY})
		dist = dist + math.min(math.max(0, self:GetPos().z - tr.HitPos.z - 120) * 0.15, 120)
	end
	dist = math.min(dist, 330)
	-- (user: the camera pulls far back on the devastators, as in the game - effectfully) MercerDevastate sets the
	-- pull: out in 0.35 s (ease-out), held to 3 s, back over 1.5 s
	local e = CurTime() - self:GetNW2Float("MercerDevCamT", -100)
	if e >= 0 and e < 4.5 then
		local k = e < 0.35 and math.sin(e / 0.35 * math.pi / 2) or (e < 3 and 1 or 1 - (e - 3) / 1.5)
		dist = dist + self:GetNW2Float("MercerDevCamD", 0) * k
	end
	return dist
end

-- (user 2026-10-29: "an option: the camera as the game's"; 2026-11-04: "redo it"; "Камеру игры": everyone's now, no checkbox) the game's chase camera:
-- lua/autorun/client/alex_mercer_chasecam.lua. 0 from the console = our own camera below
local GameCam = CLIENT and CreateClientConVar("alex_mercer_camera_game", "1", true, false,
	"Alex Mercer: the camera as the game's chase camera (1) or our own (0)")

-- (2026-11-04: the game camera for all) its view turns off the mouse's angles, toward where he runs up to 18 deg, 8 deg down in a jump, by what only the client's state knows. So the client says where it is
-- and where it looks (CC.View, 10 times a second) and the server's aim goes by that: a shot, a whip, a throw goes where the screen's centre is, not 18 deg and 17 u off it. Nothing said (the default camera): the mouse's
if SERVER then
	util.AddNetworkString("alex_mercer_view")
	net.Receive("alex_mercer_view", function(_, ply)
		local e = ply.DrG_GetPossessing and ply:DrG_GetPossessing()
		if not IsValid(e) or e:GetClass() ~= "drg_alex_mercer" then return end
		local off, dp, dy = net.ReadVector(), net.ReadFloat(), net.ReadFloat()
		if off:LengthSqr() > 1000000 or math.abs(dp) > 180 or math.abs(dy) > 180 then return end
		local v = e.MercerView
		if not v then
			v = {}
			e.MercerView = v
		end
		v.off, v.p, v.y, v.t = off, dp, dy, CurTime()
	end)
end
function ENT:MercerAimVector(p)
	local v = self.MercerView
	if v and CurTime() - v.t < 0.5 then
		local a = p:EyeAngles()
		a.p, a.y = a.p + v.p, a.y + v.y
		return a:Forward()
	end
	return p:GetAimVector()
end

function ENT:PossessorView()
	if not self:IsPossessed() then return end
	if CLIENT and ALEX_MERCER_MPSMOOTH then ALEX_MERCER_MPSMOOTH(self) end -- (MP fix 8: the camera on the smoothed place)
	local ang = self:GetPossessor():EyeAngles()
	if CLIENT and GameCam and GameCam:GetBool() and ALEX_MERCER_CHASECAM then return ALEX_MERCER_CHASECAM.View(self, ang) end
	local v = SERVER and self.MercerView
	if v and CurTime() - v.t < 0.5 then
		ang.p, ang.y = ang.p + v.p, ang.y + v.y
		return self:GetPos() + v.off, ang
	end
	local target = self:WorldSpaceCenter() + Vector(0, 0, 24)
	local dist = self:MercerCamDistance()
	if CLIENT then
		local st = self.MercerCam
		if not st or st.ent ~= self then
			st = {ent = self, pos = target, dist = dist}
			self.MercerCam = st
		end
		-- (once a frame: DrGBase may ask more than once, a lock's own turn in the user command)
		if st.frame ~= FrameNumber() then
			st.frame = FrameNumber()
			local ft = FrameTime()
			-- lag: follow position quickly, but let fast motion (sprint, launches) run ahead a little
			-- (user 2026-11-03: "резче") the lag (0.11 s) softened every start and stop on screen, a strike's lunge is over in
			-- 0.1 s; the game's pivot is his position every frame. Tight under 8 m/s; the height keeps the lag (steps, stairs)
			local rate = Lerp(math.Clamp((self:GetVelocity():Length2D() / M2U - 8) / 6, 0, 1), self.MercerCamFollow:GetFloat(), 9)
			-- (2026-11-04, alex_mercer_camera_run_lag) on the run and the sprint the game's moving average takes over from this follow; in the air, standing, walking as before
			local hx, hy, runK = target.x, target.y, 0
			if ALEX_MERCER_CHASECAM then hx, hy, runK = ALEX_MERCER_CHASECAM.RunLag(self, st, target, ft) end
			-- (the follow's lag fades out as the average's comes in, in the follow's own terms: no corner where a clamp would let go)
			local kh, kv = runK >= 1 and 1 or (runK <= 0 and math.min(1, ft * rate) or ft / math.max(ft, (1 - runK) / rate + runK * ft)), math.min(1, ft * 9)
			st.pos = Vector(Lerp(kh, st.pos.x, hx), Lerp(kh, st.pos.y, hy), Lerp(kv, st.pos.z, target.z))
			st.dist = Lerp(math.min(1, ft * 2.5), st.dist, dist)
		end
		target, dist = st.pos, st.dist
	end
	local tr = util.TraceHull({start = target, endpos = target - ang:Forward() * dist, mins = Vector(-8, -8, -8),
		maxs = Vector(8, 8, 8), filter = self, mask = MASK_SOLID_BRUSHONLY})
	return tr.HitPos, ang
end

-- Wall run direction: 0° = up, +90° = Mercer's left, -90° = right, ±180° = down (NW2 float MercerWallDir).
-- Anim choice mirrors the game's wall-run controller (prototype_wall → loco, 0f194a6b:178087b8).
function ENT:MercerWallAnim()
	if self:GetNW2Bool("MercerClimb") then
		-- prototype_wall climb -> locoClimb: idle / north / east / south / west
		local m = self:GetNW2String("MercerClimbMove", "")
		if m ~= "" then self.MercerClimbLastM = m end
		if m == "up" then return "alex_climb_up" elseif m == "dwn" then return "alex_climb_dwn"
		elseif m == "l" then return "alex_climb_l" elseif m == "r" then return "alex_climb_r" end
		-- (climb loco: the stick let go -> alex_climb_idle_tense, then the idle cycle)
		if (self.MercerClimbLastM or "") ~= "" then self.MercerClimbStopT = CurTime() end
		self.MercerClimbLastM = m
		-- (2026-11-04: it is 3.67 s long and loops: at 3.7, this asked for every 0.1 s, it came round to its frame 0 before the cycle, a hand 24 u in a tick; 3.5 lets it never get there)
		if CurTime() - (self.MercerClimbStopT or 0) < 3.5 then return "alex_climb_idle_tense" end
		return "alex_climb_idle_cycle"
	end
	local a = self:GetNW2Float("MercerWallDir", 0)
	local aa = math.abs(a)
	-- the game's _l anims plant the feet on the model's right side, _r on its left: with our tilt (model up = out of
	-- the wall, forward = run direction) running LEFT needs the _r set so the feet stay below the body (with _l he
	-- hung under his feet with the right arm reaching up: "рука как будто он опирается об что то")
	local side = a > 0 and "l" or "r" -- (swapped back: user, 2026-10-03 - the arms read better this way)
	-- sideways / diagonally up: the straight run (user, 2026-10-04: no hand on the wall); the body still turns to
	-- the run direction - the model's forward follows MercerWallDir in the render matrix (CLIENT)
	-- holding a human (graph_wall wall_run/loco/pose/human): the *_split anims
	local split = self:GetNW2Bool("MercerHolding") and "_split" or ""
	if aa <= 112.5 then return "alex_wall_run_up" .. split end
	return "alex_wall_run_" .. side .. "_diagonal_down" .. split
end

-- Animations --
-- (user 2026-10-28, multiplayer: strikes / jumps jerked - the client trace: the pose back to frame 0 every 0.1 s)
-- DrGBase runs UpdateAnimation every 0.1 s on the client too, and this OnUpdateAnimation knows the graph nodes only on
-- the server: the client set its own sequence / cycle 0 until the server's next update put it back. In multiplayer the
-- client leaves his animation to the server
if CLIENT and not game.SinglePlayer() then
	function ENT:UpdateAnimation() end
end
function ENT:OnUpdateAnimation()
	if self:IsDown() or self:IsDead() then return end
	if SERVER and ALEX_MERCER_PLAYER then
		-- airborne without a node (walked off a ledge, knocked up...): start the game's air pose right now,
		-- so DrGBase's leave-ground update never flashes some other anim for a tick
		if not self.MercerNode and not self:IsOnGround() and not self:GetNW2Bool("MercerWall")
			and self:GetNW2Float("MercerDive", 0) <= 0 and not self:GetNW2Bool("MercerGlide") then
			-- (2026-11-04: the step off a ledge goes first: this update, DrGBase's _HandleLeaveGround, comes before the think that also asks for it,
			-- the debug log's "animations.lua:413 < hooks.lua:251", and the fall's pose here left it nothing to start on)
			self:MercerOffLedge()
			if not self.MercerNode then self:MercerAirPose() end
		end
		if self.MercerNode then
			local a = ALEX_MERCER_PLAYER.EnterNow(self)
			-- (the rate the graph player set - 0 in single player as before; in multiplayer its track's speed, which
			-- DrGBase's 0.1 s update would otherwise zero: the client lost its smooth playback)
			if a then return a, self:GetPlaybackRate() end
		end
	end
	if self:GetNW2Bool("MercerWall") then return self:MercerWallAnim(), 1 end
	if self:GetNW2Bool("MercerHolding") then
		-- holding a human: locoSteer alex_grap_hmn_amb_gv / walk / run / sprint (the claws: their own amb)
		local v = self:GetVelocity():Length2D()
		-- (the speed comes from the anim: standing he picked the stand and never got going - only the sprint, with its
		-- own speed, moved him) movement held = walk (Alt) / run, the sprint on Shift
		local md = self.MercerMoveDir
		local input = SERVER and self:IsPossessed() and md ~= nil and not md:IsZero()
		if self:IsOnGround() and (v > 2 * M2U or input) then
			if self:GetMercerSprint() > 0 then return "alex_loco_grap_sprint_n_gv", 1 end
			local p = self:GetPossessor()
			if self:MercerWalking(p) then return "alex_loco_grap_walk_n_gv", 1 end
			if input then return "alex_loco_grap_run_n_gv", 1 end
			return v > 4 * M2U and "alex_loco_grap_run_n_gv" or "alex_loco_grap_walk_n_gv", 1
		end
		return self:GetMercerForm().name == "Когти" and "alex_claw_grap_hmn_amb_gv" or "alex_grap_hmn_amb_gv", 1
	end
	if self:GetNW2Bool("MercerMissileHold") and self:IsOnGround() and self:GetMercerSprint() <= 0 then
		-- a caught rocket in hand (holding/grabbing/missile loco: locoSteer alex_weap_missile_idle / alex_loco_grap_walk_n_gv /
		-- alex_loco_grap_run_n_gv; the sprint keeps the bare sprint, as with a gun)
		local md = self.MercerMoveDir
		if (SERVER and self:IsPossessed() and md ~= nil and not md:IsZero()) or self:GetVelocity():Length2D() > 1.5 * M2U then
			return self:MercerWalking(self:GetPossessor()) and "alex_loco_grap_walk_n_gv" or "alex_loco_grap_run_n_gv", 1
		end
		return "alex_weap_missile_idle", 1
	end
	if self:GetNW2String("MercerGun", "") ~= "" and self:IsOnGround() and self:GetMercerSprint() <= 0 then
		-- a gun in hand (prototype_firearm loco; the sprint keeps the bare sprint - sprint_split_body is an upper-body
		-- pose only). (user 2026-10-29: "a proper aim: free, where you look; softer movement") the graph's
		-- animationBlendVerticalAimStrafe = blends: the aim's pitch (-67..78) between the down / neutral / up anims, the
		-- move direction between the four strafes - here the model's blend sequences on the pose parameters aim_pitch /
		-- move_yaw (alex_rifle_aim / fire / move / fire_move / walk, tools/build_all.py); the yaw eased so a change of
		-- direction swings, not snaps
		local aiming = CurTime() - self:GetNW2Float("MercerGunAim", -10) < 0.15
		local md = self.MercerMoveDir
		local input = SERVER and self:IsPossessed() and md ~= nil and not md:IsZero()
		-- (user 2026-10-29: "take the run from before the free aim, it had no problems") the movement is the earlier
		-- one: the game's own strafe anims picked by the move direction (fwd / back / left / right, the slow ones on
		-- the walk), run_fwd when not aiming; the free aim (the aim_pitch blend, alex_rifle_aim) only standing. The
		-- blend strafes (alex_rifle_move / walk) stay in the model, unused
		if input or self:GetVelocity():Length2D() > 1.5 * M2U then
			local walk = self:MercerWalking(self:GetPossessor())
			if not aiming and not walk then return "alex_weap_rifle_run_fwd", 1 end
			local a = math.AngleDifference((input and md or self:GetVelocity()):Angle().y, self:GetAngles().y)
			local pre = walk and "alex_weap_rifle_strafe_slow_" or "alex_weap_rifle_strafe_"
			if math.abs(a) <= 45 then return pre .. "fwd", 1 end
			if math.abs(a) >= 135 then return pre .. "back", 1 end
			return a > 0 and pre .. "left" or pre .. "right", 1
		end
		if aiming then return "alex_rifle_aim", 1 end
		return "alex_weap_rifle_stand", 1
	end
	if self:GetNW2Bool("MercerObjHold") then
		-- carrying an object: locoSteer alex_weap_2hnd_sml_amb / alex_loco_weap_2hnd_walk_n / run_n / sprint_n
		local v = self:GetVelocity():Length2D()
		-- (user 2026-10-28: "running with a prop is really ugly") the anim by the gait he is in, not by the speed of the
		-- moment: the walk (Alt) or the run from the first step, its rate following the speed (BodyMoveXY: the anims'
		-- own 1.61 / 4.47 m/s) - by speed it flashed the walk at up to 1.9x through every start, then popped to the run
		local moving = v > 0.5 * M2U or (self.MercerMoveDir and not self.MercerMoveDir:IsZero())
		if self:IsOnGround() and moving then
			if self:GetMercerSprint() > 0 then return "alex_loco_weap_2hnd_sprint_n", 1 end
			local walk = self:MercerWalking(self:GetPossessor())
			return walk and "alex_loco_weap_2hnd_walk_n" or "alex_loco_weap_2hnd_run_n", 1
		end
		return "alex_weap_2hnd_sml_amb", 1
	end
	if self:GetNW2Bool("MercerCharging") and not self.MercerAirCharge then
		-- (alex_mercer_jump_graph 0) on the sprint alex_loco_pedal_straight once, then the run: taken for prototype_sprint's jump_charging. (2026-11-04, the user's "в игре ее нет") that pedal is the sprint's
		-- start (sprint/actions/skid/common/pedal); jump_charging (graph_jump 1024-1161) has only the meter and the effects: he just runs on
		if self:IsMoving() then
			if not self.MercerJumpGraph:GetBool() and not self:GetNW2Bool("MercerChargeAnimDone") and self:GetNW2Float("MercerSprint", 0) > 0 then
				return "alex_loco_pedal_straight", 1
			end
		else
			-- the standing charge is played by the graph node; never drop to the idle pose here
			return "alex_loco_jump_charged_stand", 0
		end
	end
	local f = self:GetMercerForm()
	-- the armour's own stance when no attack power is out (prototype armour node: alex_armor_amb_fight)
	local idle = self:MercerStance(f)
	if self:GetMercerSprint() > 0 and self:IsOnGround() then
		-- the game's locoSprint blend: n / n1 / n2 by speed x banking (pose parameters + rate in BodyUpdate)
		if f.sprint then return f.sprint, 1 end
		return "mercer_sprint", self.MercerSprintRate or 1
	end
	if not self:IsOnGround() then
		-- glide: the game's skydive pose (every other airborne pose comes from the graph nodes above)
		if self:GetNW2Float("MercerDive", 0) > 0 or self:GetNW2Bool("MercerGlide") then return self:MercerGlideAnim(), 1 end
		return "alex_loco_jump_long_D", 0
	end
	-- (MercerStartT: movement just pressed - the anim comes with the press, not once he is moving)
	if self:IsMoving() or (self.MercerStartT and CurTime() - self.MercerStartT < 0.15) then
		-- locoCrowd: run_n with its twist anims (mercer_twist set in BodyUpdate); walk = Alt
		if self:IsPossessed() then
			local p = self:GetPossessor()
			-- DrGBase's IsMoving is "any velocity": the last few u/s after a stop flashed the run for a moment
			local d = self.MercerMoveDir
			if (not d or d:IsZero()) and self:GetVelocity():Length2D() < 2 * M2U then return idle, 1 end
			if self:MercerWalking(p) then return f.walk or "alex_loco_walk_n", 1 end
			return f.run or "mercer_run", 1
		end
		if self:IsRunning() then return f.run or "mercer_run", 1 end
		return f.walk or "alex_loco_walk_n", 1
	end
	return idle, 1
end

if SERVER then
	include("alex_mercer/hits.lua")
	include("alex_mercer/graph.lua") -- the game's behaviour-graph node timelines (tools/figexport.py)
	-- the claws' stance with the claw hand override baked on (tools/build_all.py *_claw): its frame count
	ALEX_MERCER_FRAMES["alex_claw_amb_fight_claw"] = ALEX_MERCER_FRAMES["alex_claw_amb_fight"]
	include("alex_mercer/graphplayer.lua")
	include("alex_mercer/atkfx.lua") -- each attack node's own effect spawns (tools/atkfx.py)
	local GP = ALEX_MERCER_PLAYER
	-- Graph nodes used below (paths inside startup_fig.p3d; flow decoded with tools/figrefs.py, where the
	-- execute/spawn/sequence/opportunity items reference structs by pre-order index):
	-- standing: jump/stand/hold executes the pose bank and offers the release bank; default (crouch) spawns
	--   cycle at 1.5 s; release bank: charge < 0.1 -> release/stand/tactical (then air/fall), otherwise
	--   charged/release (10-14 in 0.1 s) -> charged/charged -> pose bank -> normal (15-65 over 2 s, priority
	--   -5 over the air pose) + common (spawns //prototype_air/air/fall/fall/pose).
	-- running charged: jump/enter -> pose/default (jump_long_D 0-2 in 0.133 s) -> release -> blends
	--   (jump_long_D 2-74 over 2.333 s, or jump_long_D_2 0-38 over 1.667 s when charge > 0.5, weights 10:20).
	-- air/fall/fall/pose: "default" (directional blend, full at 2.5 m/s) with an opportunity to "down"
	--   (vertical velocity < -2 m/s: charged_stand 74-104 cyclic @0.8); nothing leads back from down.
	-- air/fall/land (on ground): huge < -60 m/s (exit_passive after 1 s), heavy < -20 m/s or Jump held
	--   (exit_passive after 0.3 s), else soft: after a tactical jump land_soft, no movement input land_stop,
	--   moving land_touch_fwd (not used: user saw him slide).
	-- (prototype_air/high, super_high, medium, low = the GROUND POUND, bank "drop", input Special in the
	--   air - not a falling pose; using it for fast falls was the "kneels in mid-air" bug.)
	include("alex_mercer/rootspeed.lua") -- root motion speed profiles (tools/build_all.py)
	include("alex_mercer/fightpaths.lua") -- attack joint paths for the hit items (tools/fight_paths.py)
	include("alex_mercer/sounds.lua") -- the game's sound patches as cues (tools/sndlua.py)
	include("alex_mercer/ssgrip.lua") -- the NPC pack's Super Soldier seizing him (nothing without the pack)
	include("alex_mercer/ride.lua") -- his half of the pack's Supreme Hunter: its ride, its tendrils (nothing without the pack)
	include("alex_mercer/grabpair.lua") -- his halves of the pack's grabs, per frame (tools/grab_pair_lua.py)
	-- The game's charge cycle (prototype_jump/cycle: charged_stand frames 12 -> 9 over 2 s, 9 -> 12 over 2 s)
	-- baked into the forward-looping sequence alex_loco_jump_charged_cycle (tools/build_all.py). Played backwards
	-- on charged_stand itself, the client showed that anim's frame 0 (standing upright) for one frame when the
	-- hold began at 1.5 s (user: "на долю секунды становится в обычную позу").
	ALEX_MERCER_GRAPH["mercer/charge_cycle"] = {{start = 0, stop = 4, anim = "alex_loco_jump_charged_cycle", rate = 1,
		f0 = 0, f1 = 120, cyclic = false, part = "", blendin = 0.1, blendout = 0.1}}
	ALEX_MERCER_FRAMES["alex_loco_jump_charged_cycle"] = 121
	-- Run stops from Mercer's own graph (alex_fig.p3d prototype → idles bank → stop node: movement released at
	-- more than 2 m/s; pose bank: over 8 m/s run_sprint_stop from frame 6, else run_stop, blend in 0.35 s)
	ALEX_MERCER_GRAPH["mercer/run_stop"] = {{start = 0, stop = -1, anim = "alex_loco_run_stop", rate = 1,
		f0 = 0, f1 = -1, cyclic = false, part = "", blendin = 0.35, blendout = 0.6}}
	ALEX_MERCER_GRAPH["mercer/run_stop_fast"] = {{start = 0, stop = -1, anim = "alex_loco_run_sprint_stop", rate = 1,
		f0 = 6, f1 = -1, cyclic = false, part = "", blendin = 0.1, blendout = 0.2}}
	local NODE_CHARGE = "prototype_jump/default"            -- charged_stand 0-10 over 1.133 s, 10-12
	local NODE_CHARGE_HOLD = "mercer/charge_cycle"          -- 12-9-12 while held (see above)
	local NODE_RELEASE = "prototype_jump/charged/release"   -- 10-14 in 0.1 s
	-- sprint graph (prototype_sprint): dash = trans_dash 0-2 in 0.067 s, 2-7 by 0.4 s (Run + movement pressed);
	-- exit = run_sprint_stop (Run or movement released)
	local NODE_SPRINT_DASH = "prototype_sprint/#00000001dd794691/sprint/#30c34ab776fd6058/dash"
	local NODE_SPRINT_EXIT = "prototype_sprint/exit"
	local NODE_RUN_STOP, NODE_RUN_STOP_FAST = "mercer/run_stop", "mercer/run_stop_fast"
	local NODE_CHARGED_AIR = "prototype_jump/normal"        -- 15-65 over 2 s (user: launch "10/10")
	local NODE_TAP = "prototype_jump/release/stand/tactical" -- tact_stand 0-19 over 0.833 s
	local NODE_RUN_ENTER = "prototype_jump/pose/default"    -- jump_long_D 0-2 in 0.133 s
	local BLEND_RUN = "prototype_jump/blends/alex_loco_jump_long_D"     -- 2-74 over 2.333 s
	local BLEND_RUN2 = "prototype_jump/blends/alex_loco_jump_long_D_2"  -- 0-38 over 1.667 s
	local BLEND_AIR = "prototype_air/default"                -- air pose (directional blend, cyclic)
	local NODE_AIR_DOWN = "prototype_air/down/down"          -- falling loop
	local NODE_LAND_SOFT = "prototype_air/landings/#87e777ff6ed5097e" -- land_soft from frame 4
	local NODE_LAND_STOP = "prototype_air/#227b3ad220e78743"  -- land_stop 2-end @0.9
	local NODE_LAND_HEAVY = "prototype_air/heavy/default"    -- land_heavy 8-50
	local NODE_LAND_HUGE = "prototype_air/land/land/huge/default" -- land_heavy_2 in 3 parts
	local AIR_FALL_SPEED = 2 * M2U                           -- "down" below -2 m/s
	local LAND_HEAVY_SPEED, LAND_HUGE_SPEED = 20 * M2U, 60 * M2U
	-- prototype_air fall (bank turning → default): gravity 25 m/s² (GMod's 1000 u/s² = 25.4), maxVelocity 60 m/s,
	-- turning 60 °/s up to 6 m/s forward speed .. 15 °/s from 20 m/s; drift 0..5 m/s of air control.
	-- Jump graph's own fall (prototype_jump): 1500 °/s .. 60 °/s from 6 m/s.
	local FALL_MAX = 60 * M2U
