	-- Debug trace (temporary): every sequence change on the server with who caused it, node starts/stops,
	-- landings, and the state each tick while charging. Written to garrysmod/data/alex_mercer_debug_sv.txt.
	local DebugAnim = CreateConVar("alex_mercer_debug", "0", FCVAR_NONE, "Trace Mercer animation changes to data/alex_mercer_debug_sv.txt")
	local dbgBuf, dbgSize = {}, 0
	local function dbg(fmt, ...)
		if not DebugAnim:GetBool() or dbgSize > 30000000 then return end
		local line = string.format("%.3f ", CurTime()) .. string.format(fmt, ...)
		dbgBuf[#dbgBuf + 1] = line
		dbgSize = dbgSize + #line
	end
	local function caller()
		local out = {}
		for lvl = 3, 7 do
			local info = debug.getinfo(lvl, "Sln")
			if not info then break end
			out[#out + 1] = string.format("%s:%d", (info.short_src or "?"):match("[^/\\]+$") or "?", info.currentline or 0)
		end
		return table.concat(out, " < ")
	end
	timer.Create("alex_mercer_debug_flush", 1, 0, function()
		if #dbgBuf == 0 then return end
		file.Append("alex_mercer_debug_sv.txt", table.concat(dbgBuf, "\n") .. "\n")
		dbgBuf = {}
	end)
	if DebugAnim:GetBool() then
		file.Append("alex_mercer_debug_sv.txt", "\n==== session " .. os.date("%Y-%m-%d %H:%M:%S") .. " ====\n")
	end
	local entMeta = FindMetaTable("Entity")
	function ENT:ResetSequence(seq)
		if isstring(seq) then seq = self:LookupSequence(seq) end
		if DebugAnim:GetBool() and seq ~= self:GetSequence() then
			dbg("ResetSequence %s -> %s node=%s ground=%s charging=%s  [%s]", self:GetSequenceName(self:GetSequence()),
				self:GetSequenceName(seq), self.MercerNode and self.MercerNode.path or "-", tostring(self:IsOnGround()),
				tostring(self:GetNW2Bool("MercerCharging")), caller())
		end
		return entMeta.ResetSequence(self, seq)
	end
	function ENT:SetSequence(seq)
		if isstring(seq) then seq = self:LookupSequence(seq) end
		if DebugAnim:GetBool() and seq ~= self:GetSequence() then
			dbg("SetSequence %s -> %s node=%s ground=%s charging=%s  [%s]", self:GetSequenceName(self:GetSequence()),
				self:GetSequenceName(seq), self.MercerNode and self.MercerNode.path or "-", tostring(self:IsOnGround()),
				tostring(self:GetNW2Bool("MercerCharging")), caller())
		end
		return entMeta.SetSequence(self, seq)
	end
