	local STEPS = {
		[MAT_GRASS] = "alex_feet_dirt", [MAT_DIRT] = "alex_feet_dirt", [MAT_SAND] = "alex_feet_dirt",
		[MAT_FOLIAGE] = "alex_feet_leaves", [MAT_WOOD] = "alex_feet_wood", [MAT_METAL] = "alex_feet_metal_thick",
