	local AS_CUE = {feet = "alex_feet", feet_run = "alex_feet_run", sprint = "alex_sprint", walk = "alex_walk",
		jump = "alex_fol_jump_a", jump_wind = "jumpwind_gust", land = "alex_land", land_heavy = "alex_land_heavy",
