	-- the armour: its own footstep patch (alex_armour_feet = alex_step_armor_*) for every step sound - ground, wall run,
	-- graph items - and no clothes foley (alex_run / alex_walk / alex_sprint are the alex_*_foley rustles; user)
	local ARMOUR_CUE = {alex_feet = "alex_armour_feet", alex_feet_run = "alex_armour_feet", alex_run = false,
		alex_walk = false, alex_sprint = false}
	function ENT:MercerCue(name, volMul, pitchMul)
		if ARMOUR_CUE[name] ~= nil and self:MercerArmour() then
			name = ARMOUR_CUE[name]
			if not name then return end
		end
		-- the clothes foley at half volume (user: "слишком громкие")
		if ARMOUR_CUE[name] == false then volMul = (volMul or 1) * 0.5 end
		local c = ALEX_MERCER_CUES and ALEX_MERCER_CUES[name]
		if not c then return end
		local pitch = math.Clamp(math.random(c.pmin, c.pmax) * (pitchMul or 1), 1, 255)
		local f = c.files[math.random(#c.files)]
		-- (diagnostics: the blade's RMB sounds going silent - every cue he plays)
		dbg("cue %s %s lvl=%d pitch=%d vol=%.2f node=%s", name, f, c.level, pitch, math.min(1, c.vol * (volMul or 1)),
			self.MercerNode and self.MercerNode.path or "-")
		self:EmitSound(f, c.level, pitch, math.min(1, c.vol * (volMul or 1)))
	end

	-- the sprint's breath (graph_sprint 1406, {fast}'s one sound): the patch of audio/alex.p3d is a loop, fading in over 2 s and out in 0.1 s, volume 0.55, pitch 1 - 1.1, one of three files. So he breathes while he's at speed and stops
	-- with it. (2026-10-03's by eye: a new file every 2.5 - 4 s, each 4 - 5 s long, nothing to stop them: "odd moans that kept going after stopping".) The wavs have no loop points: the next one at its end, on the clock: the slow motion doesn't slow a sound
	-- (user 2026-11-04: "пусть разные типы отдышек сделает, а то там только одну по кругу крутит") those three are all the game has for him: no other breath in its banks, none after a sprint (alldialogue's Effort: pain, cough, hits). They differ: 03 is 1.8 breaths a
	-- second, 02 2.1, 01 2.8. A new pick at each end, never the same twice running, the patch's pitch again. BY EYE, the graph has only the random pick: a pause of 0.1 - 0.5 s between them (the loop has none), and the longer he's been at speed the likelier the quicker one, to 15 s
	do
	local BREATH = {["mercer/fx/alex_speed_breathe_01.wav"] = {3.89, 0.25, 1}, ["mercer/fx/alex_speed_breathe_02.wav"] = {4.38, 1, 1}, ["mercer/fx/alex_speed_breathe_03.wav"] = {4.93, 1, 0.25}}
	local function breathPick(c, last, k)
		local sum = 0
		for _, f in ipairs(c.files) do
			local w = BREATH[f]
			if f ~= last and w then sum = sum + Lerp(k, w[2], w[3]) end
		end
		local x = math.Rand(0, sum)
		local pick
		for _, f in ipairs(c.files) do
			local w = BREATH[f]
			if f ~= last and w then
				pick = f
				x = x - Lerp(k, w[2], w[3])
				if x <= 0 then break end
			end
		end
		return pick or c.files[1]
	end
	function ENT:MercerBreath(on)
		local b = self.MercerBreathSnd
		if not on then
			if b then
				b.snd:FadeOut(0.1)
				self.MercerBreathSnd = nil
				self.MercerBreathEnd = RealTime()
			end
			return
		end
		local now = RealTime()
		if b and now < b.t then return end
		local c = ALEX_MERCER_CUES and ALEX_MERCER_CUES.alex_speed_breathe
		if not c then return end
		if b then
			b.snd:Stop()
		else
			self:CallOnRemove("MercerBreath", function(ent) ent:MercerBreath(false) end)
			-- (a jump on the way is the same run; a stop of 5 s isn't)
			if now - (self.MercerBreathEnd or -100) > 5 then self.MercerBreathT0 = now end
		end
		local f = breathPick(c, self.MercerBreathLast, math.Clamp((now - self.MercerBreathT0) / 15, 0, 1))
		local pitch = math.random(c.pmin, c.pmax)
		self.MercerBreathLast = f
		if not b then dbg("breath %s pitch=%d vol=%.2f", f, pitch, c.vol) end
		local snd = CreateSound(self, f)
		snd:SetSoundLevel(c.level)
		snd:PlayEx(b and c.vol or 0, pitch)
		if not b then snd:ChangeVolume(c.vol, 2) end
		local w = BREATH[f]
		self.MercerBreathSnd = {snd = snd, t = now + (w and w[1] or 4) * 100 / pitch + math.Rand(0.1, 0.5)}
	end
	end

	function ENT:MercerCueAt(name, pos, volMul, pitchMul)
		local c = ALEX_MERCER_CUES and ALEX_MERCER_CUES[name]
		if not c then return end
		local pitch = math.Clamp(math.random(c.pmin, c.pmax) * (pitchMul or 1), 1, 255)
		sound.Play(c.files[math.random(#c.files)], pos, c.level, pitch, math.min(1, c.vol * (volMul or 1)))
	end

	function ENT:MercerSound(list, level, pitch)
		if type(list) == "string" then return self:MercerCue(list) end
		if list then self:EmitSound(pick(list), level or 75, pitch or math.random(95, 105)) end
	end

	-- (user 2026-10-23: his grunts, groans, cries) the game's Effort dialogue of "alex" (01audio.rcf
	-- audio/english/dialogue/alldialogue.p3d: each event's own lines, embedded RADP -> sound/mercer/vo/efforts, 44.1 kHz)
	-- played where the graphs' dialogue tracks put them, with their chance (MercerVO calls)
	local VO_EV = {
		alex_punch = {"alex_punch02", "alex_punch04", "alex_punch09", "alex_punch13", "alex_punch19", "alex_punch38"},
		alex_punchkickbig = {"alex_punchkickbig01", "alex_punchkickbig02", "alex_punchkickbig03"},
		alex_throw = {"alex_throw_01", "alex_throw_02", "alex_throw_03", "alex_throw04", "alex_throw05"},
		alex_throw_sml = {"alex_throw_sml_01", "alex_throw_sml_02", "alex_throw_sml_04"},
		alex_hit = {"alex_hit01", "alex_hit02", "alex_hit03", "alex_hit04", "alex_hit05"},
		alex_hitbody = {"alex_hitbody01", "alex_hitbody02", "alex_hitbody03"},
		alex_jump_sml_start = {"alex_jump_sml_start01", "alex_jump_sml_start02", "alex_jump_sml_start03"},
		alex_jump_sml_land = {"alex_jump_sml_land01", "alex_jump_sml_land02"},
		alex_pickup = {"alex_pickup_01", "alex_pickup_02", "alex_pickup_03"},
		alex_pickup_sml = {"alex_pickup_sml_01", "alex_pickup_sml_02", "alex_pickup_sml_03"},
		alex_strength = {"alex_strength01", "alex_strength02", "alex_strength03", "alex_strength04"},
		alex_pain = {"alex_pain01", "alex_pain02", "alex_pain03"},
		alex_cough = {"alex_cough_01", "alex_cough_02"},
	}
	function ENT:MercerVO(ev, chance, delay)
		if math.random() > (chance or 1) then return end
		local function say(ent)
			local list = VO_EV[ev]
			if not list or CurTime() < (ent.MercerVOT or 0) then return end
			ent.MercerVOT = CurTime() + 0.3
			ent:EmitSound("mercer/vo/efforts/" .. list[math.random(#list)] .. ".wav", 78, math.random(97, 103), 1, CHAN_VOICE)
		end
		if delay and delay > 0 then self:Timer(delay, say) else say(self) end
	end

	function ENT:MercerVoice(chance)
		do return end -- the extracted lines are mission dialogue, not combat efforts
		if math.random() < (chance or 1) and CurTime() > (self.MercerNextVoice or 0) then
			self.MercerNextVoice = CurTime() + 6
			self:EmitSound(pick(SND.voice), 80, 100, 1, CHAN_VOICE)
		end
	end

	function ENT:MercerFootstep()
		if self:MercerArmour() then
			-- the armour's own patch (alex_step_armor_01/03/04) on every surface; no clothes foley under the plates (user)
			return self:MercerCue("alex_armour_feet")
		end
		local tr = util.TraceLine({start = self:GetPos() + Vector(0, 0, 8), endpos = self:GetPos() - Vector(0, 0, 24), filter = self})
		local fast = self:GetVelocity():Length2D() > 6 * M2U
		local cue = STEPS[tr.MatType]
		if not (cue and ALEX_MERCER_CUES and ALEX_MERCER_CUES[cue]) then cue = fast and "alex_feet_run" or "alex_feet" end
		self:MercerCue(cue)
		self:MercerCue(fast and "alex_run" or "alex_walk", 0.6) -- the clothes foley on each step
	end

	function ENT:CustomInitialize()
		self:SetNW2Int("MercerForm", 1)
		self:SetNW2Int("MercerDefense", 0)
		self.MercerComboIndex = 0
		self:MercerApplyHealthMult(true)
	end

	-- the health multiplier: the max health = SpawnHealth x it x DrGBase's own "Health multiplier" (user: the health
	-- didn't change - DrGBase's slider was overwritten, and a missed convar callback left it as it was). Checked every
	-- 0.5 s from CustomThink; a change keeps the current health's share of the max
	function ENT:MercerApplyHealthMult(full)
		local a, b = GetConVar("alex_mercer_hp_scale"), GetConVar("drgbase_multiplier_health")
		local mult = math.max(a and a:GetFloat() or 1, 0.01) * math.max(b and b:GetFloat() or 1, 0.01)
		local max = math.Clamp(math.floor(self.SpawnHealth * mult), 1, 2147483647)
		if not full and max == self:GetMaxHealth() then return end
		local share = full and 1 or self:Health() / math.max(self:GetMaxHealth(), 1)
		self:SetMaxHealth(max)
		local hp = math.max(1, math.floor(max * share))
		self:SetHealth(hp)
		self:SetNW2Int("DrGBaseHealth", hp)
	end
	-- the damage multiplier: everything a Mercer deals (fists, powers, devastators, throws ...)
	-- (user 2026-10-28: "the disguise on F") the flashlight key (F by default) of the player possessing him toggles the
	-- disguise (the last form - the wheel's disguise slot: MercerSetForm toggles it; nothing without a consumed look);
	-- the flashlight itself stays off
	hook.Add("PlayerSwitchFlashlight", "alex_mercer_disguise_key", function(ply)
		local m = ply.DrG_GetPossessing and ply:DrG_GetPossessing()
		if not IsValid(m) or m:GetClass() ~= "drg_alex_mercer" then return end
		if not ply:FlashlightIsOn() then
			if CurTime() > (m.MercerDisguiseKeyT or 0) then
				m.MercerDisguiseKeyT = CurTime() + 0.3
				m:MercerSetForm(#FORMS, true)
			end
			return false
		end
	end)

	hook.Add("EntityTakeDamage", "alex_mercer_dmg_scale", function(target, dmg)
		-- (players 2026-10-27: Hazama's Wesker parried and killed the player inside Alex - possession lost) the player
		-- possessing him takes no damage at all: only Alex is hit
		if target:IsPlayer() and target.DrG_GetPossessing then
			local m = target:DrG_GetPossessing()
			if IsValid(m) and m:GetClass() == "drg_alex_mercer" then return true end
		end
		local a = dmg:GetAttacker()
		if IsValid(a) and a:GetClass() == "drg_alex_mercer" and target ~= a then
			local k = GetConVar("alex_mercer_dmg_scale"):GetFloat()
			if k ~= 1 then dmg:ScaleDamage(k) end
			return a:MercerVehicleDamage(target, dmg)
		end
	end)

	-- (players 2026-11-03: "make Mercer damage armored vehicles, and more with the hammerfist") his hits on the vehicle bases.
	-- None of them is required: each is told by a field of its own on the entity
	do
		-- the game's damageScaleByType on its vehicles (proto::AdvancedHealthBehaviour in tank_ram, apc_m2, heli_bh, heli_gunship,
		-- f45Thunder _tod.p3d). The tank and the APC have two records each, 850 / 500 and 650 / 350 health, the same but for
		-- Hammerfist: 1.2 on the heavier, 1.5 on the lighter (the lighter's here). A car has none (proto::HealthBehaviour): 1
		-- (user 2026-11-03: "yes, set them") the rest of his attack types, the same records: GroundSpike the APC's 1.8 / 1.7,
		-- DevastatorTendril the tank's 0.00828 / 0.0065: read so in both, its other near-zeros are 0.01 (rotor, infected)
		local SCALE = {
			tank = {Bare = 0.5, Claws = 0.5, Blades = 2, Hammerfist = 1.5, Whipfist = 0.5, Throw = 0.3, GroundSpike = 1,
				DevastatorExplosion = 3, DevastatorTendril = 0.0065, DevastatorGroundSpike = 1, ObstacleBash = 0},
			apc = {Bare = 0.5, Claws = 0.5, Blades = 1.5, Hammerfist = 1.5, Whipfist = 0.1, Throw = 0.4, GroundSpike = 1.7,
				DevastatorExplosion = 3.01, DevastatorTendril = 3, DevastatorGroundSpike = 1, ObstacleBash = 0},
			heli = {Bare = 2, Claws = 1, Blades = 1.01, Hammerfist = 1, Whipfist = 1.01, Throw = 1.3, GroundSpike = 1,
				DevastatorExplosion = 1.01, DevastatorTendril = 1.01, DevastatorGroundSpike = 1, ObstacleBash = 0},
			plane = {Bare = 1, Claws = 1, Blades = 1, Hammerfist = 1, Whipfist = 0, Throw = 1, GroundSpike = 1,
				DevastatorExplosion = 1, DevastatorTendril = 1, DevastatorGroundSpike = 1, ObstacleBash = 1},
		}
		-- graph_devastator: ground_pound's hits DevastatorGroundSpike, sonic_clap's DevastatorTendril (its track's 400 has no
		-- type of its own: taken as the node's), tendrilDevastator DevastatorExplosion
		local DEV_KIND = {spikes = "DevastatorGroundSpike", tendrils = "DevastatorTendril", impale = "DevastatorExplosion",
			impale360 = "DevastatorExplosion"}
		-- which of them a mod's vehicle is (ours: the game can't say); nil = a car
		local function vehicleRow(e)
			if e.LVS then
				local t = isfunction(e.GetVehicleType) and e:GetVehicleType()
				if t == "tank" then return SCALE.tank end
				if t == "helicopter" then return SCALE.heli end
				if t == "plane" or t == "starfighter" then return SCALE.plane end
				-- anything else with armor plates (AddArmor): the half-track, the armored car
				return istable(e._armorParts) and #e._armorParts > 0 and SCALE.apc or nil
			elseif e.IsGlideVehicle then
				local T = Glide and Glide.VEHICLE_TYPE
				local t = T and e.VehicleType
				if not t then return nil end
				return t == T.TANK and SCALE.tank or t == T.HELICOPTER and SCALE.heli or t == T.PLANE and SCALE.plane or nil
			elseif e.IsSimfphyscar then
				return e.IsArmored and SCALE.tank or nil
			end
		end
		-- a hit's multiplier on this vehicle, by the game's attack type (read as in the pack's HunterAttackType; kind = named by
		-- the hit itself). With no fight running: the hammer's toss, stomp and drop are Hammerfist; the rest have no type: 1
		function ENT:MercerVehicleScale(e, slash, blade, whip, kind)
			local row = self.MercerVehicleHits:GetBool() and vehicleRow(e)
			if not row then return 1 end
			if kind then return row[kind] or 1 end
			local a = self.MercerFight and self.MercerFight.atk
			if whip then return row.Whipfist end
			if blade then return row.Blades end
			if slash then return row.Claws end
			if a then
				if a.devastator then return row[DEV_KIND[a.devastator]] or 1 end
				return row[a.blade and "Blades" or a.hammer and "Hammerfist" or a.whip and "Whipfist" or a.slash and "Claws" or "Bare"]
			end
			return self:GetMercerForm().name == "Молот" and row.Hammerfist or 1
		end
		-- what each base does to a blow on its way, undone (from their sources; no numbers of ours):
		-- LVS (CalcDamage) takes DSArmorDamageReductionType, DMG_CLUB among it, down to DSArmorDamageReduction (0.1): fists and
		-- the hammer did a tenth, claws all of it. It also drops a hit weaker than DSArmorIgnoreForce (his have no impulse at
		-- times). Its plates stop only shells and blast (AddArmor's callback): a blow goes through them.
		-- Simfphys Armed's tanks (TankApplyDamage) have no DMG_SLASH on their list: claws and blades did nothing.
		-- A wheel hands its hit on to the hull (LVS track links in full, LVS tires a share, Simfphys bulletproof tires in full),
		-- every wheel in reach, on top of the hull's own hit: the table would mean nothing beside the tracks. true = no damage
		function ENT:MercerVehicleDamage(e, dmg)
			if dmg:GetInflictor() ~= self or not dmg:IsDamageType(DMG_CLUB + DMG_SLASH + DMG_CRUSH) then return end
			if not self.MercerVehicleHits:GetBool() then return end
			local blow = dmg:IsDamageType(DMG_CLUB + DMG_SLASH)
			if e.LVS then
				local r, types = e.DSArmorDamageReduction, e.DSArmorDamageReductionType
				if blow and r and r > 0 and types and dmg:IsDamageType(types) then dmg:ScaleDamage(1 / r) end
				-- (the hammer drop's crush too: its push is far under a tank's threshold)
				local min = e.DSArmorIgnoreForce
				if min and dmg:GetDamageForce():Length() < min then
					local dir = e:WorldSpaceCenter() - self:WorldSpaceCenter()
					dir:Normalize()
					dmg:SetDamageForce(dir * (min + 1))
				end
				return
			end
			if e.IsSimfphyscar then
				if dmg:GetDamageType() == DMG_SLASH then dmg:SetDamageType(DMG_CLUB) end
				return
			end
			local c = e:GetClass()
			if c == "lvs_wheeldrive_wheel" then
				if e.GetWheelChainMode and e:GetWheelChainMode() then return true end
				-- (a club is cut to a tenth on the way through; a slash isn't. This flag: the tire's own damage only)
				if dmg:IsDamageType(DMG_SLASH) then dmg:SetDamageType(bit.bor(dmg:GetDamageType(), DMG_PREVENT_PHYSICS_FORCE)) end
			elseif c == "gmod_sent_vehicle_fphysics_wheel" then
				local base = e.GetBaseEnt and e:GetBaseEnt()
				if IsValid(base) and base.GetBulletProofTires and base:GetBulletProofTires() then return true end
			end
		end
		-- (user 2026-11-03: "he sometimes doesn't vault cars, only tries to push them") what he vaults, not shoves: "body" = a
		-- vehicle or a prop of a car's weight (200 kg and up: ours), "part" = a vehicle's wheel, a physics object of its own
		function ENT:MercerHeavyThing(e)
			if not IsValid(e) then return nil end
			local root = e:GetParent()
			if IsValid(root) then e = root end
			if e:GetMoveType() ~= MOVETYPE_VPHYSICS then return nil end
			if e.LVS or e.IsGlideVehicle or e.IsSimfphyscar or e:IsVehicle() then return "body" end
			local c = e:GetClass()
			if c == "lvs_wheeldrive_wheel" or c == "gmod_sent_vehicle_fphysics_wheel" then return "part" end
			local ph = e:GetPhysicsObject()
			return IsValid(ph) and ph:GetMass() >= 200 and "body" or nil
		end
		-- the shove's say on it: not a car (he vaults it), unless the armour's bash; never a wheel on its own
		function ENT:MercerMayShove(e, armour)
			if not self.MercerCarVault:GetBool() then return true end
			local kind = self:MercerHeavyThing(e)
			return not kind or (kind == "body" and armour)
		end
		-- (user 2026-11-03, a player's wish: "the launch by mass") a blow's velocity is impulse x 0.12 u/s (IMPULSE 0.06, x 2 in
		-- MercerFightDamage): what the game's impulse gives 328 kg (impulse / mass m/s, 39.37 u/m). Lighter things keep
		-- it (a crate would fly off at any speed); heavier by their mass: a 1500 kg car 22%, a 20 t tank 1.6%. A vehicle's
		-- wheel moves with its vehicle, not on its own
		function ENT:MercerMassScale(ph, e)
			if not self.MercerMassLaunch:GetBool() then return 1 end
			if self:MercerHeavyThing(e) == "part" then return 0 end
			local m = ph:GetMass()
			return m <= 328 and 1 or 328 / m
		end
		-- DrGBase's Attack (the drop, the landings) pushes whatever it hits by one velocity: by mass too
		function ENT:PushEntity(ent, force)
			-- (user 2026-11-05: the big bosses don't fly, the pack's ProtoNoLaunch: their reactions are their graphs')
			if isentity(ent) and IsValid(ent) and ent.ProtoNoLaunch then return end
			if isentity(ent) and IsValid(ent) and not (ent:IsPlayer() or ent:IsNPC() or ent:IsNextBot()) then
				local ph = ent:GetPhysicsObject()
				if IsValid(ph) then force = force * self:MercerMassScale(ph, ent) end
			end
			return baseclass.Get("drgbase_nextbot").PushEntity(self, ent, force)
		end
	end

	-- Prototype's own particle effects (client lua/autorun/client/alex_mercer_vfx.lua)
	local VFX = {land_soft = 1, land_heavy = 2, land_huge = 3, foot = 4, wall = 5, boost = 6, dash = 7, dive = 8,
		air_dash = 9, skid = 10, hit = 11, pound = 12, blood_gush = 13, blood_mist = 14, blood_squib = 15, sparks = 16,
		concrete = 17, crush_concrete = 18, crush_generic = 19, crush_metal = 20, wood = 21, slash_metal = 22, wave = 23,
		decal_crack = 24, decal_line = 25, decal_spike = 26, decal_scorch = 27, decal_blood = 28,
		air_dash_wave = 29, boost_wave = 30, pound_generic = 31, decal_step = 32, bullet_dive_wave = 33,
		bullet_land_wave = 34, bullet_land_hot = 35}
	-- (user: the dents should not stay for ever - fade over ~15 s) cracks, crush marks and the scorch are drawn by the
	-- client as fading quads (VFX decal_*, alex_mercer_vfx.lua V.Decal: 10 s, then 5 s fading), at the size the engine
	-- decal had (texture x $decalscale) or the size given; the slashes stay engine decals
	local FADE_DECALS = {AlexMercerCrack = {"decal_crack", 154}, AlexMercerCrackSmall = {"decal_line", 64},
		AlexMercerSpikeCrack = {"decal_spike", 470}, Scorch = {"decal_scorch", 128},
		AlexMercerCrush075 = {"decal_crack", 30}, AlexMercerCrush1 = {"decal_crack", 39},
		AlexMercerCrush15 = {"decal_crack", 59}, AlexMercerCrush2 = {"decal_crack", 79},
		AlexMercerCrush3 = {"decal_crack", 118},
		AlexMercerBlood = {"decal_blood", 90}, AlexMercerStep = {"decal_step", 59}} -- (user: the blood too) decal_blood01-03 x 0.3537
	function ENT:MercerDecal(name, a, b, filter, size)
		local fd = FADE_DECALS[name]
		if not fd then return util.Decal(name, a, b, filter) end
		local tr = util.TraceLine({start = a, endpos = b, filter = filter, mask = MASK_SOLID_BRUSHONLY})
		if not tr.Hit or tr.HitSky then return end
		local ed = EffectData()
		ed:SetOrigin(tr.HitPos)
		ed:SetNormal(tr.HitNormal)
		ed:SetScale(size or fd[2])
		ed:SetFlags(VFX[fd[1]])
		util.Effect("alex_mercer_vfx", ed, true, true)
	end

	-- ent (optional): the Mercer the effect belongs to, for the client (the dash waves' blur goes on his player's screen)
	function ENT:MercerVFX(name, pos, normal, scale, ent)
		local ed = EffectData()
		ed:SetOrigin(pos or self:GetPos())
		ed:SetNormal(normal or Vector(0, 0, 1))
		ed:SetScale(scale or 1)
		ed:SetFlags(VFX[name] or 0)
		if ent then ed:SetEntity(ent) end
		util.Effect("alex_mercer_vfx", ed, true, true)
	end

	do -- camera shake (a block of its own: the file's main chunk is near Lua's 200 locals)
		-- The game's cameraShakeRequest {magnitude} {duration} (small / medium / large; the common store's fast/light =
		-- small small, fast/medium = medium medium, fast/heavy = medium large, punches/punch = small small). DrGBase's
		-- possession view replaces the engine's, so util.ScreenShake / ViewPunch never reached the possessor: the client
		-- applies these to that view (alex_mercer_fx_cl.lua); the others around get the engine's shake. kick = a view kick
		-- (pitch, yaw degrees) in place of ViewPunch.
		local SHAKE_LEVEL = {small = 1, medium = 2, large = 3}
		local ENGINE_AMP, ENGINE_DUR = {2, 5, 9}, {0.25, 0.45, 0.9}
		function ENT:MercerShake(mag, dur, delay, kick)
			if delay and delay > 0 then
				return self:Timer(delay, function(ent) ent:MercerShake(mag, dur, nil, kick) end)
			end
			local m, d = SHAKE_LEVEL[mag] or 0, SHAKE_LEVEL[dur] or 0
			local p = self:GetPossessor()
			if IsValid(p) then
				net.Start("alex_mercer_shake")
				net.WriteUInt(m, 2)
				net.WriteUInt(d, 2)
				net.WriteFloat(kick and kick.p or 0)
				net.WriteFloat(kick and kick.y or 0)
				net.Send(p)
			end
			if m > 0 then util.ScreenShake(self:GetPos(), ENGINE_AMP[m], 20, ENGINE_DUR[math.max(d, 1)], 400 + 300 * m) end
		end
	end

	-- effect programs from the graphs (lua/alex_mercer/fxprogs.lua) played by the client: {{name, delay}, ...}
	function ENT:MercerFxProg(list)
		local parts = {}
		for _, x in ipairs(list) do parts[#parts + 1] = x[1] .. ":" .. (x[2] or 0) end
		self:SetNW2String("MercerFx", table.concat(parts, ";"))
		self:SetNW2Float("MercerFxT", CurTime())
	end

	-- the held attack's charge/<power>/... program (prototype_effects charge bank, by the power's graph spawns):
	-- hammerfist punches = hammerfist/punch/<hand> (distortion + biomass), its specials special/down; blades =
	-- blades/r_hand (along the blade); whipfist punches = whipfist/punch (out along the links to the spike), its
	-- specials special/down; bare / claws / musclemass = bare/punch|kick/<limb>
	function ENT:MercerHoldProgram(atk)
		if atk.holdFx then return atk.holdFx end
		local f = self:GetMercerForm().name
		local cj = atk.cj or ""
		if f == "Молот" then
			if atk.key == IN_ATTACK2 then return "charge_special_down_r_hand" end
			return cj == "Wrist_L" and "charge_hammer_l_hand" or "charge_hammer_r_hand"
		elseif f == "Клинок" then
			return "charge_blades_r_hand"
		elseif f == "Хлыст" then
			return atk.key == IN_ATTACK2 and "charge_special_down_r_hand" or "charge_whip_punch"
		end
		if cj == "Wrist_L" then return "charge_bare_l_hand"
		elseif cj == "Ankle_R" then return "charge_bare_r_foot"
		elseif cj == "Ankle_L" then return "charge_bare_l_foot" end
		return "charge_bare_r_hand"
	end

	-- the game's motiontrails/* spawned by a node (jump, jump_charged, backflip, frontflip): the client draws it for the
	-- trail's generateTime from now
	function ENT:MercerTrail(kind)
		self:SetNW2String("MercerTrail", kind)
		self:SetNW2Float("MercerTrailT", CurTime())
	end

	function ENT:MercerEffect(name, pos, scale)
		local ed = EffectData()
		ed:SetEntity(self)
		ed:SetOrigin(pos or self:WorldSpaceCenter())
		ed:SetScale(scale or 1)
		local f = self:GetMercerForm()
		ed:SetStart(Vector(f.color.r, f.color.g, f.color.b))
		util.Effect(name, ed, true, true)
	end

	-- Possession controls (POSSESSION_MOVE_CUSTOM): DrGBase passes the input direction already rotated by the camera.
	-- Heading like the game: running turns at locoCrowd's 300 °/s, sprinting steers with locoSprint's turn model.
	-- (players 2026-10-24/26, user 2026-10-28: in multiplayer he turns slowly, "like a car", and runs slower) DrGBase
	-- runs PossessionControls in the nextbot's behaviour coroutine, resumed less often than every tick in multiplayer:
	-- the turns stepped by FrameTime() (one tick) fell behind real time. In multiplayer the step is the real time since
	-- the last call (at most 0.25 s)
	-- (user 2026-11-03: "резче") single player too: its log's steps are 0.015 and 0.045 s, half the time each, so the turns
	-- stepped by one tick ran at about two thirds of their rates ("slow": alex_mercer_turn_speed's 2 came out at 1.3)
	local function controlsDt(self)
		local now = CurTime()
		local last = self.MercerPCLast
		self.MercerPCLast = now
		if last and now >= (self.MercerPCLogT or 0) then
			self.MercerPCLogT = now + 1
			dbg("possession controls step %.3f s (tick %.3f, single player %s)", now - last, FrameTime(),
				tostring(game.SinglePlayer()))
		end
		if not last or (game.SinglePlayer() and not self.MercerSharp:GetBool()) then return FrameTime() end
		return math.Clamp(now - last, FrameTime(), 0.25)
	end
	function ENT:PossessionControls(forward, backward, right, left, moveDir)
		local pdt = controlsDt(self)
		self.MercerMoveDir = moveDir
		self.MercerTurnSign = 0
		if self:GetNW2Bool("MercerWall") then return end
		if self.MercerNode and self.MercerNode.path == NODE_SPRINT_DASH then
			-- dash: orient to the input at once until 0.167 s, then at 90 °/s (the node's orient items), keep moving
			if moveDir and not moveDir:IsZero() then
				local want = moveDir:Angle().y
				local t = CurTime() - self.MercerNode.t0
				local yaw = t < 0.1667 and want or math.ApproachAngle(self:GetAngles().y, want, 90 * pdt)
				self:SetAngles(Angle(0, yaw, 0))
			end
			if self:IsOnGround() then self:Approach(self:GetPos() + self:GetForward() * 100) end
			return
		end
		if self.MercerNode and self.MercerNode.opts.block then
			-- the game's exit_passive: after a moment, movement input ends a landing / stop
			-- (the hit reactions' pushbacks: movement has its own time there, MercerHitThink)
			if self.MercerNode.opts.moveAfter or not (GP.CanExit(self) and moveDir and not moveDir:IsZero()) then return end
			GP.Stop(self)
			self:UpdateAnimation()
		end
		if self.MercerGunAiming and self:MercerGunAiming() and self:IsOnGround() and not self.MercerSprintOn then
			-- aiming a gun (prototype_firearm locoStrafe, 720 deg/s): facing the aim, moving along the input
			local want = self.MercerGunAimYaw or self:GetAngles().y
			self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, want, 720 * pdt), 0))
			if moveDir and not moveDir:IsZero() then self:Approach(self:GetPos() + moveDir * 100) end
			return
		end
		-- (2026-11-04) firing in the air: orient 180 deg/s to the aim (air/firearm). Not the graph's fall items with the shot: 15, 10, 5 m/s up
		-- for a burst's first three, a jump in the air (rejected)
		if self.MercerGunAiming and self:MercerGunAiming() and not self:IsOnGround() then
			self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, self.MercerGunAimYaw or self:GetAngles().y, 180 * pdt), 0))
			return
		end
		if not moveDir or moveDir:IsZero() then -- standing still: keep facing, camera orbits freely
			self.MercerTurnRate = 0
			return
		end
		local dt = pdt
		local want = moveDir:Angle().y
		local yaw = self:GetAngles().y
		if not self:IsOnGround() then
			-- the fall item's turning: fast at low forward speed, slow when flying fast
			local hs = Vector(self:GetVelocity().x, self:GetVelocity().y, 0):Length() / M2U
			local jumpNode = self.MercerNode and string.StartWith(self.MercerNode.path, "prototype_jump")
			local rate = jumpNode and Lerp(math.Clamp(hs / 6, 0, 1), 1500, 60)
				or Lerp(math.Clamp((hs - 6) / 14, 0, 1), 60, 15)
			yaw = math.ApproachAngle(yaw, want, rate * dt)
		elseif self.MercerSprintOn then
			-- (user 2026-10-28, multiplayer: "on the sprint he swings side to side") the steer's turn rate accelerates:
			-- one big multiplayer step overshot and swung back - stepped in ticks (single player: one step, unchanged)
			local n = math.max(1, math.ceil(dt / FrameTime() - 0.001))
			for _ = 1, n do yaw = self:MercerSprintSteer(yaw, want, dt / n) end
		else
			local err = math.AngleDifference(want, yaw)
			-- twist side for locoCrowd: turning left (counter-clockwise) = -1 (run_upper_left)
			if math.abs(err) > 3 then self.MercerTurnSign = err > 0 and -1 or 1 end
			if self:MercerRunTurnStart(err) then return end
			if self.MercerObj then
				-- (user 2026-10-28: "with props the turns are too sharp") carrying: the graph's locoSteer turns 600 deg/s -
				-- with a car overhead it snapped round. A weighty turn instead: 300 deg/s for light things down to 120 for
				-- a car (by its mass, 100 -> 1500 kg), eased into the heading (4 x the error per second, no snap at the end)
				local k = math.Clamp(((self.MercerObj.mass or 100) - 100) / 1400, 0, 1)
				local rate = math.min(Lerp(k, 300, 120), math.abs(err) * 4 + 20)
				yaw = math.ApproachAngle(yaw, want, rate * dt)
			else
				yaw = math.ApproachAngle(yaw, want, CROWD.turn * TurnSpeed:GetFloat() * dt)
			end
		end
		self:SetAngles(Angle(0, yaw, 0))
		if self:IsOnGround() then
			self:Approach(self:GetPos() + self:GetForward() * 100)
		end
	end

	-- The run's 180 (prototype opening/surface/ground/holding/bare/loco/default/bank: velocity Z < -2, axisDirection 180 120):
	-- the input 120-240 deg off his facing while he runs over 2 m/s forward -> alex_loco_run_180_turn_L 0-4 in 0.2 s, 5-10 by
	-- 0.4 s. Its root carries him on 0.77 m and turns him 180 deg in frames 0-3 (ROOTPATH, the anim pinned with its yaw), then he
	-- stands planted; the orient item goes to the input at 360 deg/s from 0.2 s; movement leaves it from 0.3 s, a press at once.
	-- Waits for the model: no ROOTPATH entry, no turn. Not with what has its own run: the claws (no hand override baked on it),
	-- a shield, a disguise, anything in hand
	-- (user 2026-11-03: "рванная анимация, не четко и вся дерганная") by eye: in the graph's times the foot goes 87 cm in frame
	-- 0-1, 26 cm a tick, and then all but stops; a frame is skipped at 0.2 s, 23 cm in a tick; the graph's exit at frame 7.5 left
	-- 68 cm for the run's blend. Each frame's time by the worst joint's step now, 15 cm a tick all through (tools/turneven.py; the
	-- path is the anim's own), the turn done by 0.15 s as before; movement leaves it at its end, frame 10 (40 cm to the run, and
	-- 3.6 m/s already going his way: the run's full speed sooner than from the old exit). Blend in 0.1, the game's is 0: from
	-- any phase of the run that was up to 60 cm a tick, it's 32 now
	do
		local T, tracks = {0, 0.0851, 0.1294, 0.1529, 0.1898, 0.2077, 0.2256, 0.2426, 0.2626, 0.2912, 0.3285}, {}
		for i = 1, #T - 1 do
			tracks[i] = {start = T[i], stop = T[i + 1], anim = "alex_loco_run_180_turn_l", rate = 1, f0 = i - 1, f1 = i, cyclic = false,
				part = "", blendin = 0, blendout = 0}
		end
		ALEX_MERCER_GRAPH["mercer/run_turn"] = tracks
	end
	function ENT:MercerRunTurnStart(err)
		if math.abs(err) < 120 or not self.MercerSharp:GetBool() then return false end
		if not (ALEX_MERCER_ROOTPATH and ALEX_MERCER_ROOTPATH["alex_loco_run_180_turn_l"]) then return false end
		-- (user 2026-11-03: "его крутит несколько раз очень быстро") rootspeed.lua arrived by autorefresh with the game still
		-- holding the model from before the rebuild (models load at a restart only): that anim's pose turns him by itself, on top
		-- of this turn. Its fade tells them apart: 0.1 in the model with the yaw pinned, Source's 0.2 before it. Off until then
		local si = self.GetSequenceInfo and self:GetSequenceInfo(self:LookupSequence("alex_loco_run_180_turn_l"))
		if not si or (si.fadeintime or 1) > 0.15 then return false end
		local f = self:GetMercerForm()
		if f.run or f.shield or f.kind == "disguise" or self.MercerObj or self.MercerGun or self.MercerNode
			or self:GetNW2Bool("MercerHolding") or self:GetNW2Bool("MercerObjHold") or self.MercerFight then return false end
		local hv = self.loco:GetVelocity()
		hv.z = 0
		if hv:Dot(self:GetForward()) <= 2 * M2U then return false end
		self.MercerRunTurn = {t0 = CurTime(), yaw = self:GetAngles().y, fw = 0}
		GP.Start(self, "mercer/run_turn", {block = true, exitAfter = 0.3285, pressAfter = 0,
			onDone = function(ent) ent:UpdateAnimation() end})
		self:MercerCue("alex_feet")
		self:MercerCue("alex_feet_scuff")
		return true
	end
	function ENT:MercerRunTurnThink(dt)
		local st = self.MercerRunTurn
		local node = self.MercerNode
		if not node or node.path ~= "mercer/run_turn" or not self:IsOnGround() then
			self.MercerRunTurn = nil
			-- (off a ledge in it: the air pose, not the rest of a turn in the air)
			if node and node.path == "mercer/run_turn" then
				GP.Stop(self)
				self:UpdateAnimation()
			end
			return
		end
		local anim, cycle = GP.Sample(self)
		if not anim or dt <= 0 then return end
		local path = ALEX_MERCER_ROOTPATH["alex_loco_run_180_turn_l"]
		local nf = #path / 3
		local last = (ALEX_MERCER_FRAMES["alex_loco_run_180_turn_l"] or nf) - 1
		local function pathAt(fr, col)
			local i = math.Clamp(math.floor(fr), 0, nf - 1)
			local j = math.min(i + 1, nf - 1)
			return Lerp(math.Clamp(fr - i, 0, 1), path[i * 3 + col], path[j * 3 + col])
		end
		local fw = pathAt(cycle * last, 1)
		local md = self.MercerMoveDir
		if CurTime() - st.t0 >= 0.2 and not st.dust then
			-- (spawn loco/foot_r from 0.2 s: the plant's dust)
			st.dust = true
			self:MercerVFX("foot", self:GetPos() + self:GetRight() * 7 + Vector(0, 0, 2), nil, 0.8)
		end
		if CurTime() - st.t0 < 0.2 then
			-- the yaw of the pose he really has: the nextbot's updates set the cycle every 0.015-0.045 s, and the root's turn at
			-- 1400 deg/s ran ahead of the pose between them, the pose turning back against it: he twisted about
			local onPose = self:GetSequence() == self:LookupSequence("alex_loco_run_180_turn_l")
			self:SetAngles(Angle(0, st.yaw + pathAt(onPose and self:GetCycle() * last or 0, 3), 0))
		elseif md and not md:IsZero() then
			self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, md:Angle().y, 360 * dt), 0))
		end
		-- the root's step, on the axis he came in on; from frame 7 it comes back along it: forward in the heading he has now
		local v = (fw - st.fw) * M2U / dt
		st.fw = fw
		local F = v >= 0 and Angle(0, st.yaw, 0):Forward() or self:GetForward()
		v = math.abs(v)
		self.loco:SetVelocity(Vector(F.x * v, F.y * v, self.loco:GetVelocity().z))
	end

	-- locoSprint steering, as prototypeenginef.dll 0x10127520 does it: with s = speed share of 10..20 m/s,
	-- maxVel = 360 -> 90 °/s and maxAcc = 4800 -> 1200 °/s², the turn rate accelerates by
	-- maxAcc * (heading error / 180° - rate / maxVel) - it settles at (error / 180°) * maxVel, so the heading closes
	-- in with a time constant of 180° / maxVel (0.5 s at 10 m/s, 2 s at 20 m/s: wide turns at full speed)
	function ENT:MercerSprintSteer(yaw, want, dt)
		local s = math.Clamp(((self.MercerSprintSpeed or SPR.vMin) - SPR.vMin) / (SPR.vMax - SPR.vMin), 0, 1)
		local k = TurnSpeed:GetFloat()
		local maxVel = Lerp(s, SPR.turnVelMin, SPR.turnVelMax) * k
		local maxAcc = Lerp(s, SPR.turnAccMin, SPR.turnAccMax) * k
		self.MercerTurnMax = maxVel
		local err = math.AngleDifference(want, yaw)
		local rate = self.MercerTurnRate or 0
		local held = math.Clamp(rate, -maxVel, maxVel)
		-- (the game's error term is err / 180°; user: too sluggish with the mouse -> full turn rate from 45°)
		rate = rate + maxAcc * (math.Clamp(err / SPRINT_TURN_FULL, -1, 1) - held / maxVel) * dt
		self.MercerTurnRate = rate
		return yaw + rate * dt
	end

	function ENT:MercerSprintTurnSet(turn)
		local was = self.MercerSprintTurnWas or 0
		if turn == was then return end
		self.MercerSprintTurnWas = turn
		self:SetNW2Float("MercerSprintTurn", turn)
		-- (the graph's two nodes each start theirs; a flicker on the 100 deg/s not a rattle, 0.3 s BY EYE)
		if turn ~= 0 and CurTime() >= (self.MercerTurnScuffT or 0) then
			self.MercerTurnScuffT = CurTime() + 0.3
			self:MercerCue("alex_feet_scuff")
		end
	end

	-- locoSprint speed and lean for one tick (after the dash node)
	function ENT:MercerSprintStep(dt)
		local v = self.MercerSprintSpeed or SPR.vMin
		local target = sprintTarget()
		if target >= v then
			local acc
			if v > SPR.vMid then
				acc = Lerp(smooth01((v - SPR.vMid) / (SPR.vMax - SPR.vMid)), SPR.accMid, SPR.accMax)
			else
				acc = Lerp(smooth01((v - SPR.vMin) / (SPR.vMid - SPR.vMin)), SPR.accMin, SPR.accMid)
			end
			v = math.Approach(v, target, acc * SprintAccel:GetFloat() * dt)
		else
			v = math.Approach(v, target, SPR.decel * dt)
		end
		v = math.Clamp(v, 0, SPR.vMax)
		-- turning brakes the sprint (turnDeceleration x share of the max turn rate), down to velocityMin
		local maxVel = self.MercerTurnMax or SPR.turnVelMin
		local tf = math.min(1, math.abs(self.MercerTurnRate or 0) / maxVel)
		if tf > 0 and v > SPR.vMin then v = math.Approach(v, SPR.vMin, tf * SPR.turnDecel * dt) end
		self.MercerSprintSpeed = v
		-- (user 2026-11-04: "что насчет других эффектов во время бега") prototype_sprint {effects}, graph_sprint 1488-1515: a fast turn, over 13 m/s and 100 deg/s (ours, alex_mercer_turn_speed in it): locoDust003 on the inside of it (the client)
		-- and alex_feet_scuff as it starts. Its {Footprint} marks stay out: 2026-10-30, "это не те foot print"
		local tr = self.MercerTurnRate or 0
		self:MercerSprintTurnSet(not self.MercerNode and v > 13 and math.abs(tr) >= 100 and (tr > 0 and 1 or -1) or 0)
		-- (user 2026-10-30: round dents, as in the game) prototype_sprint loco bank: footstepDamage {Crush} under each foot
		-- at the foot's touch - {slow} under 15 m/s 0.5 m, {fast} 1.5 m (crush_concrete: the round crack). (user 2026-11-05: "пыль как будто опаздывает") the cycle's 0.451 / 0.922, the graph's footstep items, with the client's dust: its 0.1909 / 0.5455 are 0.116 and 0.058 s later on this cycle; in the video the crack is in the frame of the touch
		local cyc, pc = self:GetCycle(), self.MercerStepCycle
		self.MercerStepCycle = cyc
		if pc and self:IsOnGround() and string.find(self:GetSequenceName(self:GetSequence()) or "", "sprint", 1, true) then
			for _, ph in ipairs({0.451, 0.922}) do
				if (pc < ph and cyc >= ph) or (cyc < pc and (ph > pc or ph <= cyc)) then
					-- (Ankle_L at the first, Ankle_R at the second, by the anims 4 u to that side of his root then. Not the bones: the server's are up to 0.1 s old, 2 m at this speed, off from the dust the client lays there)
					self:MercerFootprint(v >= 15 and 30 or 12, self:GetPos() + self:GetRight() * (ph < 0.6 and -4 or 4)) -- (user: "слишком большие": half the graph's 1.5 / 0.5 m)
					-- (user 2026-11-04, a video of the game: "там еще пыль") the effectType's sound, graph_hiteffects wall/wallrun/generic and the slow step's; its dust and debris: the client, alex_mercer_vfx.lua
					if v >= 15 then self:MercerCue("concrete_decal_run", 0.8764, math.Rand(1.5, 1.6)) else self:MercerCue("alex_feet_scuff", 1, math.Rand(0.8, 1.1)) end
				end
			end
		end
		-- banking into the turn (left turn = lean west = -1), at leanRate
		local want = math.Clamp(-(self.MercerTurnRate or 0) / maxVel, -1, 1)
		local lean = self.MercerLean or 0
		self.MercerLean = lean + (want - lean) * math.min(1, SPR.leanRate * dt)
	end

	-- locoCrowd twist (run_upper_left / right): toward the turn side at 3 /s while turning, back at 1.5 /s
	function ENT:MercerTwistStep(dt)
		local t = self.MercerTwist or 0
		local side = self.MercerTurnSign or 0
		if side ~= 0 then
			t = math.Clamp(t + (side > t and 1 or -1) * CROWD.twistOn * dt, -1, 1)
		else
			local m = math.max(0, math.abs(t) - CROWD.twistOff * dt)
			t = t < 0 and -m or m
		end
		self.MercerTwist = t
		self:SetPoseParameter("mercer_twist", t)
	end

	-- root motion of the stop nodes: the animation's own forward speed (rootspeed.lua) at the frames the
	-- node plays, blended in from the current velocity over the node's blend-in time
	local function rootDist(anim, frame)
		local prof = ALEX_MERCER_ROOTSPEED and ALEX_MERCER_ROOTSPEED[string.lower(anim)]
		if not prof then return 0 end
		local i = math.floor(frame)
		local d = 0
		for k = 1, math.min(i, #prof) do d = d + prof[k] end
		if i + 1 <= #prof then d = d + prof[i + 1] * (frame - i) end
		return d / 30
	end

	function ENT:MercerRootMotion(dt)
		local st = self.MercerNode
		if not st or dt <= 0 then return end
		if st.path == NODE_SPRINT_DASH then
			-- the dash node's own items: orient to the input at once until 0.167 s, then at 90 °/s; moveAtVelocity
			-- 7.5 -> 10 m/s forward from 0.133 to 0.4 s (before that he keeps the speed he had)
			local t = CurTime() - st.t0
			local cur = self.loco:GetVelocity()
			st.dashSpeed = st.dashSpeed or math.max(Vector(cur.x, cur.y, 0):Length(), (self.MercerEntrySpeed or 0))
			-- push of the dash anim's own root (rootspeed.lua: up to ~25 m/s while it plays frames 2-7) and the
			-- node's moveAtVelocity (7.5 -> 10 m/s); the speed only ever goes up during the dash (user: the run ->
			-- sprint switch braked him, "резко газу дает" in the game)
			local push = 0
			local anim, cycle = GP.Sample(self)
			if anim then
				local d = rootDist(anim, cycle * ((ALEX_MERCER_FRAMES[string.lower(anim)] or 2) - 1))
				if st.rootPrev and st.rootPrev.anim == anim then push = math.max(0, (d - st.rootPrev.d) / dt) end
				st.rootPrev = {anim = anim, d = d}
			end
			if t >= 0.1333 then push = math.max(push, Lerp(math.Clamp((t - 0.1333) / (0.4 - 0.1333), 0, 1), 7.5, 10)) end
			st.dashPeak = math.max(st.dashPeak or st.dashSpeed, math.min(push, DASH_PEAK) * M2U)
			-- a grounded NextBot ignores SetVelocity and brakes without Approach: drive the dash through the desired
			-- speed + Approach (PossessionControls) with the sprint's high loco acceleration
			self.MercerSprintSpeed = st.dashPeak / M2U
			self.loco:SetDesiredSpeed(st.dashPeak)
			return
		end
		if not st.opts.root then return end
		local anim, cycle = GP.Sample(self)
		if not anim then return end
		local frame = cycle * ((ALEX_MERCER_FRAMES[string.lower(anim)] or 2) - 1)
		local d = rootDist(anim, frame)
		local prev = st.rootPrev
		st.rootPrev = {anim = anim, d = d}
		local cur = self.loco:GetVelocity()
		if st.opts.carry and not st.carryV then
			local hv = Vector(cur.x, cur.y, 0)
			st.carryV, st.carryDir = hv:Length(), hv:LengthSqr() > 1 and hv:GetNormalized() or self:GetForward()
		end
		if not prev or prev.anim ~= anim then return end
		local v = math.max(0, (d - prev.d) / dt) * M2U
		local h
		if st.opts.carry then
			-- the momentum brakes at carry m/s² (ramping in over 0.1 s) until the anim's own root speed takes over
			local ramp = math.Clamp((CurTime() - st.t0) / 0.1, 0, 1)
			st.carryV = math.max(0, st.carryV - st.opts.carry * M2U * ramp * dt)
			h = st.carryV > v and st.carryDir * st.carryV or self:GetForward() * v
		else
			local k = math.Clamp((CurTime() - st.t0) / math.max(st.opts.root, 0.001), 0, 1)
			h = LerpVector(k, Vector(cur.x, cur.y, 0), self:GetForward() * v)
		end
		-- (loco:SetVelocity does drive a grounded stop node: moving it by MercerShove on top doubled the slide - user
		-- "как будто ты в несколько раз быстрее бежал")
		self.loco:SetVelocity(Vector(h.x, h.y, cur.z))
	end

	-- Sprint = the game's prototype_sprint: entered with the dash node, then locoSprint, left with the exit node.
	local SPRINT_LOCO_ACCEL = 6000 -- u/s²: only lets the NextBot track the sprint speed model tick by tick
	-- (user 2026-10-27: a freeze at the start of the sprint with a body) the graph's one track: 41-47 over 0.4 s - not
	-- 41-47 in 0.2 s and frame 47 held 0.2 s
	ALEX_MERCER_GRAPH["mercer/grab_dash"] = {
		{start = 0, stop = 0.4, anim = "alex_loco_grap_dash_gv", rate = 1, f0 = 41, f1 = 47, cyclic = false, part = "",
			blendin = 0, blendout = 0.1}}
	function ENT:MercerSprintBegin()
		self.MercerSprintOn = true
		self.MercerEntrySpeed = self:GetVelocity():Length2D()
		self.loco:SetAcceleration(SPRINT_LOCO_ACCEL)
		self.loco:SetDeceleration(SPRINT_LOCO_ACCEL)
		self.MercerTurnRate, self.MercerLean = 0, 0
		self.MercerSprintSpeed = math.Clamp(self:GetVelocity():Length2D() / M2U, SPR.vMin, SPR.vMax)
		if CurTime() - (self.MercerLandTime or 0) < 0.5 then
			-- landed from a sprint jump with Run still held: keep sprinting, no second dash
			self:UpdateAnimation()
			return
		end
		if self:GetNW2Bool("MercerObjHold") then
			-- (user 2026-10-28: carrying, the dash's own anim took his hands off the prop) straight into the carry sprint
			self:UpdateAnimation()
			return
		end
		if self:GetNW2Bool("MercerHolding") then
			-- holding a human (prototype_sprint dash, grabSlotGrabbableClass human): alex_loco_grap_dash_gv 41-47 over
			-- 0.4 s with the receiver's alex_loco_grap_dash_rcv, then the sprint with alex_loco_grap_sprint_n_gv
			GP.Start(self, "mercer/grab_dash", {onDone = function(ent) ent:UpdateAnimation() end})
			self:MercerVFX("dash", self:GetPos() + Vector(0, 0, 2))
			self:MercerSound(SND.sprint, 68)
			return
		end
		GP.Start(self, NODE_SPRINT_DASH, {root = 0.033, onDone = function(ent)
			-- locoSprint starts at the current speed, at least velocityMin (and never below the dash's peak)
			ent.MercerSprintSpeed = math.Clamp(math.max(ent.MercerSprintSpeed or 0, ent:GetVelocity():Length2D() / M2U),
				SPR.vMin, SPR.vMax)
			ent:UpdateAnimation()
		end})
		-- prototype_sprint dash node spawns only loco/dash (locoDust002 x1.5 under the feet) and motiontrails/dash
		-- (client: the trans_dash sequence); no ring (user: the old custom wave did not belong there)
		self:MercerVFX("dash", self:GetPos() + Vector(0, 0, 2)) -- loco/dash
		self:MercerSound(SND.sprint, 68)
		self:MercerVO("alex_jump_sml_start", 0.5385) -- (the dash node's dialogue, graph_sprint 44)
	end

	ALEX_MERCER_GRAPH["mercer/sprint_idle"] = {{start = 0, stop = 10 / 30, anim = "alex_loco_sprint_idle", rate = 1,
		f0 = 0, f1 = 10, cyclic = false, part = "", blendin = 0, blendout = 0.1667}}
	ALEX_MERCER_GRAPH["mercer/sprint_idle_cycle"] = {{start = 0, stop = -1, anim = "alex_loco_sprint_idle", rate = 1,
		f0 = 10, f1 = 40, cyclic = true, part = "", blendin = 0, blendout = 0}}
	ALEX_MERCER_GRAPH["mercer/sprint_idle_exit"] = {{start = 0, stop = 10 / 30, anim = "alex_loco_sprint_idle", rate = 1,
		f0 = 40, f1 = 50, cyclic = false, part = "", blendin = 0.1333, blendout = 0.1}}
	ALEX_MERCER_GRAPH["mercer/sprint_off_ledge1"] = {{start = 0, stop = 0.9333, anim = "alex_loco_sprint_off_ledge_1",
		rate = 1, f0 = 0, f1 = -1, cyclic = false, part = "", blendin = 0.1, blendout = 0.1}}
	ALEX_MERCER_GRAPH["mercer/sprint_off_ledge2"] = {{start = 0, stop = 1.167, anim = "alex_loco_jump_off_ledge_2",
		rate = 1, f0 = 0, f1 = -1, cyclic = false, part = "", blendin = 0.1, blendout = 0.1}}
	-- (2026-11-04) walking or running off an edge (prototype loco/default/off_ledge, pose: 50 / 50): the anim at 0.8 until the fall's
	-- opportunity at 0.8667 / 0.9667 s
	ALEX_MERCER_GRAPH["mercer/off_ledge1"] = {{start = 0, stop = 0.8667, anim = "alex_loco_jump_off_ledge_1", rate = 1,
		f0 = 0, f1 = 20.8, cyclic = false, part = "", blendin = 0.1, blendout = 0.2}}
	ALEX_MERCER_GRAPH["mercer/off_ledge2"] = {{start = 0, stop = 0.9667, anim = "alex_loco_jump_off_ledge_2", rate = 1,
		f0 = 0, f1 = 23.2, cyclic = false, part = "", blendin = 0.1, blendout = 0.2}}
	-- (no jump's node, just left the ground, not thrown up; the 1 m under him BY EYE: a curb or a stair is no ledge. With a body, an
	-- object or a gun in his hands their own fall as before)
	-- (user 2026-11-05, with a clip: "второй баг где если он томрозит после спринта, то летит вниз без анимаций") the skid holds its last frame till something stops it, and only the ground did: over an edge he fell the whole building standing straight, 1.29 s of it on the bench; the stops and landings the same for their length. The graph: on leaving the surface these nodes go to off_ledge (graph_sprint 291, its skid 1182 after 0.1 s; graph_air 2275, 3100, 3406; off_ledge graph_prototype 3906). Not for a kerb: nothing within 1 m below, as MercerOffLedge's own test
	ENT.MercerOffEdgeNodes = {[NODE_SPRINT_EXIT] = 0, [NODE_RUN_STOP] = 0, [NODE_RUN_STOP_FAST] = 0, [NODE_LAND_SOFT] = 0, [NODE_LAND_STOP] = 0, [NODE_LAND_HEAVY] = 0, [NODE_LAND_HUGE] = 0, ["mercer/pedal"] = 0.1}
	function ENT:MercerOffEdgeNode()
		local nd = self.MercerNode
		if not nd or nd.opts.air then return end
		local wait = self.MercerOffEdgeNodes[nd.path] or (string.sub(nd.path, 1, 12) == "mercer/skid_" and 0.1)
		if not wait or CurTime() - (self.MercerGroundT or 0) < wait then return end
		local pos = self:GetPos()
		if util.TraceLine({start = pos, endpos = pos - Vector(0, 0, M2U), filter = self, mask = MASK_SOLID_BRUSHONLY}).Hit then return end
		dbg("off the edge: %s over it, to off_ledge", nd.path)
		GP.Stop(self)
		GP.Start(self, math.random(2) == 1 and "mercer/off_ledge1" or "mercer/off_ledge2", {onDone = function(ent)
			if ent:IsOnGround() then ent:UpdateAnimation() else ent:MercerAirPose() end
		end})
	end
	function ENT:MercerOffLedge()
		if self.MercerNode or CurTime() - (self.MercerGroundT or 0) > 0.1 or self.MercerSprintOn or self:GetMercerSprint() > 0
			or self.MercerGrab or self.MercerObj or self.MercerGun or self.MercerHitSt
			or self:GetNW2Bool("MercerHolding") or self:GetVelocity().z >= 60 then return end
		self.MercerGroundT = nil
		local pos = self:GetPos()
		if util.TraceLine({start = pos, endpos = pos - Vector(0, 0, M2U), filter = self, mask = MASK_SOLID_BRUSHONLY}).Hit then return end
		GP.Start(self, math.random(2) == 1 and "mercer/off_ledge1" or "mercer/off_ledge2", {onDone = function(ent)
			if ent:IsOnGround() then ent:UpdateAnimation() else ent:MercerAirPose() end
		end})
	end
	function ENT:MercerSprintEnd()
		self.MercerSprintOn = false
		self.loco:SetAcceleration(self.Acceleration)
		self.loco:SetDeceleration(self.Deceleration)
		self.MercerTurnRate, self.MercerLean = 0, 0
		self:SetNW2Float("MercerSprint", 0)
		if self:GetNW2Bool("MercerHolding") or self:GetNW2Bool("MercerObjHold") then
			if self.MercerNode and self.MercerNode.path == "mercer/grab_dash" then GP.Stop(self) end
			self:UpdateAnimation()
		elseif self:IsOnGround() and not self:GetNW2Bool("MercerWall") and not self.MercerChargeStart
			and (not self.MercerNode or self.MercerNode.path == NODE_SPRINT_DASH or self.MercerNode.path == "mercer/pedal")
			and not self:MercerStickAngle() and self:GetVelocity():Length2D() > 10 * M2U then
			-- (user 2026-10-27: Shift held + W tapped -> a skid every time, not even up to speed) only from a real sprint:
			-- the back skid's own 10 m/s (below it he just stops)
			-- (list item 6) prototype_sprint actions/skid: the stick let go -> skid_neutral_2. (user 2026-10-08: only this
			-- one - the left / right skids and the skid on letting go of Run are out; Run let go = the exit below)
			self:MercerSkidStart("neutral")
		elseif not self:IsOnGround() and not self:GetNW2Bool("MercerWall") and not self.MercerNode and not self.MercerGrab
			and self:GetVelocity().z < 60 then
			-- actions/off_ledge (sprinted off an edge): the fall with alex_loco_sprint_off_ledge_1 (30) or
			-- alex_loco_jump_off_ledge_2 (70), then the air pose
			GP.Start(self, math.random(100) <= 30 and "mercer/sprint_off_ledge1" or "mercer/sprint_off_ledge2",
				{onDone = function(ent)
					if ent:IsOnGround() then ent:UpdateAnimation() else ent:MercerAirPose() end
				end})
		elseif self:IsOnGround() and not self:GetNW2Bool("MercerWall") and not self.MercerChargeStart then
			-- exit node: run_sprint_stop with its own braking; held movement takes over after 0.3 s
			self:MercerVFX("dash", self:GetPos() + Vector(0, 0, 2)) -- skids/dash_exit
			self:MercerSound(SND.feet, 68)
			self:MercerSound(SND.scuff, 65)
			-- carry: from the sprint's 10-20 m/s down to run_sprint_stop's own 8.8 m/s at 40 m/s² instead of in 0.1 s
			-- (11 g: user "мини слайд слишком резкий"), ~5 m from 20 m/s
			GP.Start(self, NODE_SPRINT_EXIT, {block = true, exitAfter = 0.3, pressAfter = 0, root = 0.1, carry = 40,
				onDone = function(ent) ent:UpdateAnimation() end})
		elseif self.MercerNode and self.MercerNode.path == NODE_SPRINT_DASH then
			GP.Stop(self)
		end
	end

	-- Attacks: turn instantly toward the held direction, otherwise strike straight ahead.
	function ENT:MercerFaceInput(instant)
		local d = self.MercerMoveDir
		if d and not d:IsZero() then
			self:SetAngles(Angle(0, d:Angle().y, 0))
		end
	end

	function ENT:MercerSetForm(index, animate)
		local f = FORMS[index]
		if not f then return end
		-- (user 2026-10-27: the transformation anim played with a body in his arms) holding: the power changes (the game's
		-- consume finishers differ per power) with the biomass wave only, no full-body transformation anim
		if self:GetNW2Bool("MercerHolding") then animate = false end
		-- (user 2026-10-28: "no other mutation while an RMB skill runs - the blade's strike, the claws' stab, the armour")
		-- a power's Special (RMB) move, a devastator, or the RMB moves with their own state (the claws' ground spike,
		-- the hammertoss and its slide, the Bullet Dive, the elbow drop, the stomp): no switch - not the armour either
		local fs = self.MercerFight
		if (fs and (fs.atk.key == IN_ATTACK2 or fs.key == IN_ATTACK2 or fs.atk.devastator)) or self.MercerClawSpike
			or self.MercerHToss or self.MercerHTossSlide or self.MercerBullet or self.MercerElbow or self.MercerStomp then
			return
		end
		if self.MercerHitCancel then self:MercerHitCancel() end -- (user 2026-10-23: a mutation cuts a hit reaction)
		-- (players / user 2026-10-28: "switching powers on the run he stops for the anim"; "spamming 2 3 4 he plays every
		-- one"; "no mutation anims while running / crawling on the wall"; "armour spam on 8") the showcase anim only
		-- standing on the ground, and not while one plays or within 1.5 s of the last switch - the armour too
		if animate and (self:GetVelocity():Length2D() > 1.5 * M2U or self.MercerTransforming
			or self:GetNW2Bool("MercerWall") or self.MercerWallRun or self.MercerClimb or not self:IsOnGround()
			or CurTime() - (self.MercerLastSwitchT or 0) < 1.5) then
			animate = false
		end
		self.MercerLastSwitchT = CurTime()
		if index == ARMOUR then return self:MercerSetArmour(not self:MercerArmour(), animate) end
		if f.shield and self.MercerShieldSlot:GetBool() then
			-- (out as a power of its own when the setting was changed: into the slot)
			if self:GetNW2Int("MercerForm", 1) == index then
				self:SetNW2Int("MercerForm", 1)
				self:MercerSwapModel()
			end
			return self:MercerSetShield(not self:GetNW2Bool("MercerShieldOn"), animate)
		end
		-- a power (claws, shield ...) over a gun in hand: the gun goes first
		if self.MercerGun and index ~= 1 and f.kind ~= "disguise" and self.MercerGunDrop then self:MercerGunDrop() end
		if f.kind == "disguise" then
			-- (user: the disguise stays while the mutations are out - the game drops it, its cutscenes don't) a layer
			-- over the attack power, toggled like the armour; the armour comes off for it
			if self:GetNW2String("MercerDisguiseModel", "") == "" then return end
			local on = not self:GetNW2Bool("MercerDisguised")
			if self:GetNW2Int("MercerForm", 1) == index then self:SetNW2Int("MercerForm", 1) end
			if on and self:MercerArmour() then self:MercerSetArmour(false) end
			if on and self:GetNW2Bool("MercerShieldOn") then self:MercerSetShield(false) end
			self:SetNW2Bool("MercerDisguised", on)
			-- (on while hunted: his side again only if none of the hunters sees him - MercerCoverTry)
			-- (user 2026-10-28: "if he changes the look before their eyes, all who see him go for him at once") the
			-- witnesses of the change - any NPC / nextbot that sees him now - are his enemies: wearing it, the look is
			-- blown with them as its hunters; taking it off, Mercer is theirs to fight (MercerAggro, any side)
			local witnesses = self:MercerWitnesses()
			if not on then
				self:MercerDisguiseSide(false)
				self:SetNW2Float("MercerDisgSwapT", CurTime())
				if self.MercerCoverBlown then self:MercerHunt(false) end -- (Mercer again: the aggro was the look's)
				if #witnesses > 0 then self:MercerSeenChange(witnesses, false) end
			elseif #witnesses > 0 then
				self:SetNW2Float("MercerDisgSwapT", CurTime())
				self:MercerSeenChange(witnesses, true)
			elseif self:MercerCoverTry() then
				self:MercerDisguiseSide(true)
			end
			self:DrawShadow(not on) -- (his own shadow would show his silhouette through the disguise)
			self:MercerTransformFx(f.name, false)
			self:MercerTransformSfx(f.name, false)
			return
		end
		if index == self:GetNW2Int("MercerForm", 1) then return end
		-- (players 2026-10-27: the blade's strike went on after the switch to the hammerfist) the old power's strike
		-- stops with the switch (not a devastator)
		local fs = self.MercerFight
		if fs and not fs.atk.devastator then
			self:MercerFightEnd()
			ALEX_MERCER_PLAYER.Stop(self)
		end
		-- the disguise: only once someone was consumed
		if f.kind == "disguise" and self:GetNW2String("MercerDisguiseModel", "") == "" then return end
		-- the spines / the disguise take the defence slot: the armour comes off (the shield keeps it: the user's wish)
		if (f.kind == "defense" and not f.shield) or f.kind == "disguise" then self:SetNW2Int("MercerDefense", 0) end
		self:SetNW2Int("MercerForm", index)
		self.MercerComboIndex = 0
		-- (player 2026-10-30: "creating weapons do not blow the disguise") a mutation before the eyes of the disguise's
		-- side blows it at once (alex_tod AlexDisguiseConfig incidentShapeshift: +100, the full suspicion, at any distance)
		if self:GetNW2Bool("MercerDisguised") and not self.MercerCoverBlown and self:MercerWatched() then
			self:MercerBlowCover()
		end
		-- the graph's wave (biomass) and the veins (client) cover the switch, the new power's model
		-- swaps in under it 0.12 s later
		-- (players / user 2026-10-28: "switching powers on the run he stops for the anim - it used to change on the run";
		-- "spamming 2 3 4 he plays every one, 15 presses = 15 anims") the showcase anim only standing still, and not
		-- while one plays or within 1.5 s of the last switch: on the move / in a spam the switch is instant (the wave only)
		self:MercerTransformFx(f.name, animate and f.transform ~= nil)
		self:MercerTransformSfx(f.name, animate and f.transform ~= nil)
		self:MercerSwapModel(animate and f.transform ~= nil)
		if animate and f.transform then
			-- the whip comes out in its own transformation (the anim drives Whip_Link_01..06 + the spike)
			if f.name == "Хлыст" then self:MercerWhipMode(1) end
			self:MercerVO("alex_strength", 1) -- (long_transformation/attack/*)
			self.MercerTransforming = true
			self:PlaySequenceAndWait(f.transform, 1) -- the graph plays these at rate 1
			self.MercerTransforming = nil
			if f.name == "Хлыст" then self:MercerWhipMode(0, 30) end
		end
	end

	do -- transformation effects (a block of its own: the file's main chunk is near Lua's 200 locals)
		-- Transformation effects = the game's: every switch runs prototype_consume transform/stuff/effects/type_effects
		-- (one of the chest_out / toe_to_head / head_to_toe biomass waves, debrisTransformSoft002); the showcase anims
		-- come with the prototype graph's long_transformation: long_transform/charge (the hot wave,
		-- debrisTransformSoftHot2Alpha001) and the power's own burst + alex_transform_flash. Times from the showcase
		-- anim's start (the graph's minus its 2.433 s alex_act_power_pain_arms lead-in, which is not played here):
		-- {quick wave delay, burst program, burst delay, flash delay, flash pitch}
		local WAVES = {"transform_chest_out", "transform_toe_to_head", "transform_head_to_toe"}
		local LONG_FX = {
			["Когти"] = {0.067, "long_claws", 0.567, 0.567},
			["Клинок"] = {0, nil, nil, 1.567},
			["Молот"] = {0.4, "long_hammerfist", -2.433},
			["Мускулы"] = {0, "long_musclemass", 1.0, 1.0},
			["Хлыст"] = {0, "long_whipfist", 0.767, 0.767, 0.8},
			["Щит"] = {0.4, "long_shield", 2.134, 2.134},
			["Броня"] = {1.667},
		}
		-- a showcase anim played by hand (PlaySequenceAndWait stops when a model swap resets the cycle): the model swaps
		-- at swapAt, the same frame goes on
		function ENT:MercerPlayTransform(anim, swapAt)
			local seq = self:LookupSequence(anim)
			if seq < 0 then return end
			local dur = math.max(self:SequenceDuration(seq), 0.1)
			local t0 = CurTime()
			self._DrGBasePlayingAnimation = seq
			self:ResetSequence(seq)
			self:SetPlaybackRate(0)
			local swapped = swapAt == nil
			while true do
				local t = CurTime() - t0
				if not swapped and t >= swapAt then
					swapped = true
					self:SetModel(self:MercerModel())
					self:SetCollisionBounds(Vector(-13, -13, 0), Vector(13, 13, 72))
					seq = self:LookupSequence(anim)
					self._DrGBasePlayingAnimation = seq
					self:ResetSequence(seq)
					self:SetPlaybackRate(0)
				end
				if t >= dur then break end
				self:SetCycle(t / dur)
				if self.YieldCoroutine then self:YieldCoroutine(false) else coroutine.yield() end
			end
			if not swapped then
				self:SetModel(self:MercerModel())
				self:SetCollisionBounds(Vector(-13, -13, 0), Vector(13, 13, 72))
			end
			self._DrGBasePlayingAnimation = nil
			self:UpdateAnimation()
		end

		-- (user: switching back to the fists flashed a T-pose) the model swap keeps the running sequence, its frame and rate
		function ENT:MercerSetModelKeep(mdl)
			local name, cyc, rate = self:GetSequenceName(self:GetSequence()), self:GetCycle(), self:GetPlaybackRate()
			self:SetModel(mdl)
			self:SetCollisionBounds(Vector(-13, -13, 0), Vector(13, 13, 72))
			if self:GetNW2Bool("MercerDisguised") then self:DrawShadow(false) end -- (no silhouette through the disguise)
			local seq = name and self:LookupSequence(name) or -1
			if seq and seq >= 0 then
				self:ResetSequence(seq)
				self:SetCycle(cyc)
				self:SetPlaybackRate(rate)
			end
		end

		function ENT:MercerSwapModel(now)
			self.MercerSwapN = (self.MercerSwapN or 0) + 1
			local n = self.MercerSwapN
			if now and coroutine.running() then
				-- a showcase anim follows in this coroutine: wait out the cover here, swap, then it plays
				local t = CurTime() + 0.12
				while CurTime() < t do coroutine.yield() end
				self:MercerSetModelKeep(self:MercerModel())
				return
			end
			self:Timer(0.12, function(ent)
				if ent.MercerSwapN ~= n then return end -- (switched again meanwhile: the last one swaps)
				ent:MercerSetModelKeep(ent:MercerModel())
			end)
		end

		function ENT:MercerTransformFx(name, long)
			local L = long and LONG_FX[name]
			-- (user: everything as in the game) the graph's own wave only; the veins cover the parts that change (client)
			local list = {{WAVES[math.random(#WAVES)], L and L[1] or 0}}
			-- the hammerfist's showcase: he drops and slams the ground twice (its hammer_drop_ss at 1.567 / 2.067 s) - a
			-- small camera shake on each (user)
			if L and name == "Молот" then
				for _, t in ipairs({1.567, 2.067}) do self:Timer(t, function(ent) ent:MercerShake("small", "small") end) end
			end
			if L then
				list[#list + 1] = {"long_charge", 0}
				if L[2] then list[#list + 1] = {L[2], L[3]} end
				if L[4] then
					self:Timer(L[4], function(ent) ent:MercerCue("alex_transform_flash", 1, L[5]) end)
				end
				-- the whip's crack: motiontrails/whipfist/sweep_charge at 3.033 s (0.6 s into the anim)
				if name == "Хлыст" then
					self:Timer(0.6, function(ent) ent:MercerTrail("whip_sweep") end)
					self:Timer(0.6333, function(ent) ent:MercerTrail("whip_transform") end)
				end
			end
			self:MercerFxProg(list)
		end
	end

	-- Transformation sounds = the game's. Every switch runs prototype_consume transform/... (one of chest_out /
	-- toe_to_head / head_to_toe at random: transform_short 0.79, or transform at 0.2 s); the showcase anims come
	-- with the prototype graph's long_transformation timeline (seconds from the anim's start, which is 2.433 s into
	-- that node: earlier items are played at the start): {time, cue, volume, pitch}
	local LONG_SFX = {
		["Броня"] = {{0, "fireball"}, {0.5, "transform_armor", 1, 0.72}, {1, "alex_reverse_jump_whoosh"}},
		["Щит"] = {{0, "alex_reverse_jump_whoosh"}, {0.567, "fireball"}, {2.067, "lethal_whoosh", 1, 0.72}},
		["Когти"] = {{0, "alex_reverse_jump_whoosh"}, {0.567, "lethal_whoosh"}},
		["Клинок"] = {{0, "alex_reverse_jump_whoosh"}, {0.067, "blade_swipe"}, {0.567, "blade_swipe"},
			{0.817, "blade_swipe"}, {1.267, "blade_swipe"}, {1.567, "blade_swipe"}, {1.567, "lethal_whoosh"}},
		["Молот"] = {{0, "alex_reverse_jump_whoosh"}, {1.567, "hammer_drop_ss"}, {2.067, "hammer_drop_ss"}},
		["Мускулы"] = {{0, "alex_reverse_jump_whoosh"}, {0, "fireball"}, {1.067, "explosion_sml"}},
		["Хлыст"] = {{0, "fireball"}, {0, "alex_reverse_jump_whoosh"}, {0.567, "big_ricochet"}},
	}
	function ENT:MercerTransformSfx(name, long)
		if math.random(3) == 3 then
			self:Timer(0.2, function(ent) ent:MercerCue("transform") end)
		else
			self:MercerCue("transform_short", 0.79)
		end
		for _, x in ipairs(long and LONG_SFX[name] or {}) do
			if x[1] <= 0 then self:MercerCue(x[2], x[3], x[4])
			else self:Timer(x[1], function(ent) ent:MercerCue(x[2], x[3], x[4]) end) end
		end
	end

	-- (player 2026-10-30: "creating weapons do not blow the disguise") the armour / the shield grown before their eyes takes
	-- the disguise off before them: as the F toggle does then (MercerSetForm) - they fight Mercer, the look blown
	function ENT:MercerDisguiseOffSeen()
		if not self:GetNW2Bool("MercerDisguised") then return end
		local witnesses = self:MercerWitnesses()
		self:SetNW2Bool("MercerDisguised", false) -- (it covers him: no disguise under it)
		self:MercerDisguiseSide(false)
		self:DrawShadow(true)
		if self.MercerCoverBlown then self:MercerHunt(false) end
		if #witnesses > 0 then self:MercerSeenChange(witnesses, false) end
	end

	-- Armour on / off over the current attack power (prototype graph armour: alex_act_armor_transformation)
	function ENT:MercerSetArmour(on, animate)
		if on == self:MercerArmour() then return end
		-- the same slot as the shield / spines: those go back to the normal arms
		local cf = self:GetMercerForm()
		if on and ((cf.kind == "defense" and not cf.shield) or cf.kind == "disguise") then self:SetNW2Int("MercerForm", 1) end
		if on then self:MercerDisguiseOffSeen() end
		self:SetNW2Int("MercerDefense", on and ARMOUR or 0)
		self:MercerTransformFx("Броня", animate and on)
		local a = FORMS[ARMOUR]
		local long = animate and on and a.transform ~= nil and coroutine.running() ~= nil
		self:MercerTransformSfx("Броня", animate and on and a.transform ~= nil)
		if long then
			-- prototype long_transformation/defense/armour (user: as in the game, video 1:00): the anim 4 s, the armour
			-- grows at 1.667 s under the biomass (effectConsume 1-4 s from the head down: NW2 MercerArmourFxT, client)
			self.MercerSwapN = (self.MercerSwapN or 0) + 1
			self:SetNW2Float("MercerArmourFxT", CurTime())
			self:MercerVO("alex_strength", 1) -- (long_transformation/defense/armour)
			self:MercerPlayTransform(a.transform, 1.667)
		else
			self:MercerSwapModel()
		end
	end

	-- The Senses (Thermal / Infected Vision) = the prototype graph's senses node (DpadRight held 0.5 s,
	-- transformationDesiredSenses): alex_act_power_pain_eyes (hands over the eyes, 2.433 s) then
	-- alex_power_transform_thermal_vision_hands; transformStart {Senses} at 2.4 s = the vision comes on;
	-- long_transform/charge 0-2.333 s (the hot wave), long_transform/senses at 3.467 s (glow001 on both eyes, 2.567 s);
	-- sounds alex_reverse_jump_whoosh 0 / alex_warp 1.5 / alex_transform_flash 2.2; dialogue alex_strength. Its
	-- scriptedCamera (the game's camera - not wanted), hideHUD, charge/senses point lights and FX_TimeOfDayBlend are not
	-- ported. The vision itself is the possessor's client (alex_mercer_vision.lua), told when the node switches it; off,
	-- or on the move / mid-anim / in a skill (the same gate as MercerSetForm's showcase): switched at once.
	function ENT:MercerSenses(mode, on)
		local function switch(ent, long)
			local p = ent:GetPossessor()
			if not IsValid(p) then return end
			net.Start("alex_mercer_senses")
			net.WriteString(mode)
			net.WriteBool(on)
			net.WriteBool(long or false)
			net.Send(p)
		end
		local fs = self.MercerFight
		local busy = (fs and (fs.atk.key == IN_ATTACK2 or fs.key == IN_ATTACK2 or fs.atk.devastator)) or self.MercerClawSpike
			or self.MercerHToss or self.MercerHTossSlide or self.MercerBullet or self.MercerElbow or self.MercerStomp
		local still = self:GetVelocity():Length2D() <= 1.5 * M2U and not self.MercerTransforming
			and not self:GetNW2Bool("MercerWall") and not self.MercerWallRun and not self.MercerClimb and self:IsOnGround()
			and CurTime() - (self.MercerLastSwitchT or 0) >= 1.5
		-- (user 2026-10-29: "9 / 0 pressed several times stacked") a request while the senses transformation runs is
		-- dropped: it answers at 2.4 s itself
		if self.MercerSensesT and CurTime() < self.MercerSensesT then return end
		if not on or busy or self:GetNW2Bool("MercerHolding") or not still then return switch(self) end
		self.MercerLastSwitchT = CurTime()
		self.MercerSensesT = CurTime() + 2.5
		self.MercerTransforming = true
		self:MercerFxProg({{"long_charge", 0}, {"long_senses", 3.467}})
		self:MercerCue("alex_reverse_jump_whoosh")
		self:Timer(1.5, function(ent) ent:MercerCue("alex_warp") end)
		self:Timer(2.2, function(ent) ent:MercerCue("alex_transform_flash") end)
		self:Timer(2.4, function(ent) switch(ent, true) end)
		self:MercerVO("alex_strength", 1)
		self:PlaySequenceAndWait("alex_act_power_pain_eyes", 1)
		self:PlaySequenceAndWait("alex_power_transform_thermal_vision_hands", 1)
		self.MercerTransforming = nil
	end

	-- Plays an attack sequence with root motion and deals damage at the strike moments found in the anim.
	-- chained = true: one click = one strike. The combo continues only if LMB is clicked again before the
	-- current strike recovers; otherwise the sequence is cut right after that strike (like the game).
	function ENT:MercerStrike(seq, f, mult, chained)
		local hits = ALEX_MERCER_HITS and ALEX_MERCER_HITS[string.lower(seq)] or {{0.35}}
		local nexthit = 1
		local enemy = self:GetEnemy()
		local p = self:GetPossessor()
		local queued, wasDown, stopDone = false, true, 0
		local function stopAfter(i)
			local h = hits[i][1]
			local nxt = hits[i + 1] and hits[i + 1][1]
			return nxt and (h + math.min(0.12, (nxt - h) * 0.6)) or nil
		end
		if self:IsPossessed() then self:MercerFaceInput(true) end
		local fs = FORM_SOUNDS[f.name] or {}
		self:MercerSound(fs.swing or SND.jump_wind, 70, math.random(100, 120))
		self:MercerVoice(0.15)
		self:PlaySequenceAndMove(seq, {rate = 1}, function(self, cycle)
			if not self:IsPossessed() and IsValid(enemy) and cycle < 0.25 then self:FaceTowards(enemy) end
			if chained and IsValid(p) then
				local down = p:KeyDown(IN_ATTACK)
				if down and not wasDown then
					queued = true
					self:MercerFaceInput(true)
				end
				wasDown = down
				local last = nexthit - 1
				local stop = last > stopDone and stopAfter(last)
				if stop and cycle >= stop then
					if not queued then return true end -- no follow-up click: end the combo here
					queued = false
					stopDone = last
				end
			end
			while hits[nexthit] and cycle >= hits[nexthit][1] do
				nexthit = nexthit + 1
				if f.spikes and seq == f.special then self:MercerSpikes(f) end
				self:Attack({
					damage = f.damage * (mult or 1), range = f.range, angle = f.angle or 110, type = f.type,
					force = Vector(f.push or 300, 0, f.lift or 150), push = true,
					viewpunch = Angle(8, math.random(-6, 6), 0),
				}, function(self, hit)
					for _, ent in ipairs(hit) do
						if IsValid(ent) then self:MercerEffect("alex_mercer_hit", ent:WorldSpaceCenter(), f.damage / 50) end
					end
					if #hit > 0 then
						self:MercerSound(fs.hit or SND.punch, 85)
						if f.damage * (mult or 1) >= 80 then self:MercerSound(SND.lethal, 85) end
						if math.random(3) == 1 then self:MercerSound(SND.bone, 75) end
					end
				end)
			end
		end)
	end

	local FIGHT -- every attack of every power by name (filled further down; MercerChordStart reads it)
	-- forms whose attacks run the graph machinery (FIGHT): the powers' own graphs, the rest are prototype_bare's
	-- (musclemass / shield / armour don't change the attacks in the game; Шипы keeps its old special)
	local GRAPH_FIGHT = {["Маскировка"] = true, ["Обычный"] = true, ["Когти"] = true, ["Клинок"] = true, ["Молот"] = true, ["Хлыст"] = true,
		["Мускулы"] = true, ["Щит"] = true, ["Броня"] = true,
		-- (user 2026-10-22: the spines had the oldest strikes) the game cut the spines (an empty graph, a model and a
		-- shader anim only): a defence like the shield / armour - the bare-hand moves from the graph
		["Шипы"] = true}
	function ENT:MercerCombo()
		if self.MercerGrind then return self:MercerGrindPress() end
		if self.MercerGrab then return self:MercerGrabInput("a") end
		local f = self:GetMercerForm()
		if GRAPH_FIGHT[f.name] then
			self:MercerFightPress("a")
			if not self:IsPossessed() and coroutine.running() then
				while self.MercerFight do coroutine.yield() end
			end
			return
		end
		if CurTime() - (self.MercerLastStrike or 0) > 1.0 then self.MercerComboIndex = 0 end
		self.MercerComboIndex = self.MercerComboIndex % #f.combo + 1
		self:MercerStrike(f.combo[self.MercerComboIndex], f, 1, self:IsPossessed())
		self.MercerLastStrike = CurTime()
	end

	function ENT:MercerSpecial()
		if self.MercerGrind then return self:MercerGrindPress() end
		if self.MercerGrab then return self:MercerGrabInput("s") end
		if not self:IsOnGround() then return end -- in the air RMB is the elbow drop (CustomThink)
		local f = self:GetMercerForm()
		if GRAPH_FIGHT[f.name] then
			self:MercerFightPress("s")
			if not self:IsPossessed() and coroutine.running() then
				while self.MercerFight or self.MercerClawSpike do coroutine.yield() end
			end
			return
		end
		self:MercerStrike(f.special, f, 1.5)
	end

	-- the possessor's presses: the KeyPress hook (every user command, so even a click shorter than a tick counts) and
	-- KeyDown edges sampled in CustomThink - one press each
	hook.Add("KeyPress", "alex_mercer_keys", function(ply, key)
		-- (2026-11-04, multiplayer: E too, a batch of user commands can hold a tap between two samples; single player as before)
		if key ~= IN_ATTACK and key ~= IN_ATTACK2 and key ~= IN_JUMP and key ~= IN_RELOAD and (key ~= IN_USE or game.SinglePlayer()) then return end
		local ent = ply.DrG_Possessing and ply:DrG_Possessing()
		if IsValid(ent) and ent.MercerKeyPressed then
			ent.MercerKeyHook = ent.MercerKeyHook or {}
			ent.MercerKeyHook[key] = true
		end
	end)
	function ENT:MercerKeyPressed(p, key)
		self.MercerKeyHook = self.MercerKeyHook or {}
		self.MercerKeyWas = self.MercerKeyWas or {}
		local down = IsValid(p) and p:KeyDown(key) or false
		local was = self.MercerKeyWas[key]
		local hooked = self.MercerKeyHook[key]
		self.MercerKeyWas[key], self.MercerKeyHook[key] = down, nil
		return (down and not was) or hooked == true
	end
	-- the attack powers in turn (the armour and the shield are toggles of their own: the wheel / keys 8 and 7)
	-- (2026-11-03: with the shield in its slot the form stays put, so stopping on it R went no further than the musclemass)
	function ENT:MercerNextPower()
		local slot = self.MercerShieldSlot:GetBool()
		local i = self:GetNW2Int("MercerForm", 1) % #FORMS + 1
		while i == ARMOUR or FORMS[i].kind == "disguise" or FORMS[i].hidden or (slot and FORMS[i].shield) do i = i % #FORMS + 1 end
		self:MercerSetForm(i, true)
	end
	-- (user 2026-11-03: "yes, fix it") R as the jump below, and worse: its bind read KeyPressed, one tick's flag, in the
	-- behaviour coroutine, which runs only every nb_update_frequency - most presses were lost at any FPS. Read here every
	-- think; MercerSetForm itself still in the coroutine (its showcase anim waits there), as the wheel's and number keys'
	function ENT:MercerReloadKeys(p, down)
		local now = CurTime()
		if self.MercerReloadOwner ~= p or now - (self.MercerReloadT or 0) > 0.5 then
			-- just possessed: R already down then is no press
			self.MercerReloadOwner = p
			self.MercerKeyWas = self.MercerKeyWas or {}
			self.MercerKeyWas[IN_RELOAD] = down
		end
		self.MercerReloadT = now
		if self:MercerKeyPressed(p, IN_RELOAD) and self.MercerJumpEdges:GetBool() then
			self:CallInCoroutine(function(ent) ent:MercerNextPower() end)
		end
	end
	-- (players 2026-11-03: "i keep pressing space, i can't jump for some reason") DrGBase's bind reads KeyPressed /
	-- KeyReleased in the entity's think, and those hold only the last user command's change. The engine runs several
	-- commands at once when a frame has several ticks (under the 66 tick rate's FPS in single player: a frame's commands
	-- are sent together at its last tick) and on a server by cl_cmdrate 30 at any FPS: a change in any command but the
	-- last is gone - from ~33 FPS down every press was, so he never jumped. KeyDown holds and the KeyPress hook sees every
	-- command, as for LMB / RMB / E. Called from the same bind, in the same tick and place, so nothing else changes when
	-- no press was being lost. alex_mercer_jump_edges 0 = the old way
	function ENT:MercerJumpKeys(p, down)
		self.MercerJumpThinks = (self.MercerJumpThinks or 0) + 1 -- (alex_mercer_jump_check counts them)
		if not self.MercerJumpEdges:GetBool() then
			self.MercerJumpHeld = nil
			return
		end
		local now = CurTime()
		if self.MercerJumpOwner ~= p or now - (self.MercerJumpT or 0) > 0.5 then
			-- just possessed: Space already down then is no press (as KeyPressed), letting it go is a release
			self.MercerJumpOwner, self.MercerJumpHeld = p, down or nil
			self.MercerKeyWas = self.MercerKeyWas or {}
			self.MercerKeyWas[IN_JUMP] = down
		end
		self.MercerJumpT = now
		if self:MercerKeyPressed(p, IN_JUMP) then
			if self.MercerJumpHeld then self:MercerJumpRelease() end -- (let go and pressed again between two thinks)
			self.MercerJumpHeld = true
			self:MercerJumpCharge()
		end
		if self.MercerJumpHeld and not down then -- (a tap between two thinks: both at once)
			self.MercerJumpHeld = nil
			self:MercerJumpRelease()
		end
	end

	-- two buttons together (the second within 0.12 s of the first) = the devastator banks' moves: Attack + Action =
	-- palm strike, Attack + Special = ground pound, Special + Action = sonic clap ("a" / "s" / "e")
	ENT.MercerChordWindow = 0.12
	local CHORDS = {ae = "ps", as = "gpd", es = "scl"}
	function ENT:MercerChord(kind)
		local pt = self.MercerPressT or {}
		self.MercerPressT = pt
		local now = CurTime()
		pt[kind] = now
		for other, t in pairs(pt) do
			if other ~= kind and now - t <= self.MercerChordWindow then
				local a, b = kind, other
				if a > b then a, b = b, a end
				if CHORDS[a .. b] then
					self.MercerPressT = {}
					return CHORDS[a .. b]
				end
			end
		end
	end
	function ENT:MercerChordStart(mv)
		if self.MercerBullet then return false end -- (user 2026-10-28: nothing cuts the Bullet Dive)
		self.MercerUseHeld = nil
		if self.MercerHitCancel then self:MercerHitCancel() end
		if self.MercerGrab or self.MercerGrind or self.MercerClawSpike or self.MercerHToss or self.MercerObj
			or self.MercerGun then return false end
		-- the first button's air move, started within the window, gives way
		local win = (mv == "acb" and self.MercerBallAfterL or self.MercerChordWindow) + 0.05
		local fk = self.MercerFKick
		if fk then
			if (fk.phase ~= "windup" and fk.phase ~= "lunge") or CurTime() - fk.t0 > win then return false end
			self:MercerFKickEnd()
			self.MercerFKickUsed = nil
		end
		local stomp = self.MercerStomp
		if stomp then
			if CurTime() - stomp.t0 > win then return false end
			self.MercerStomp = nil
			self.loco:SetGravity(1000)
			self:SetNW2String("MercerHoldJoint", "")
		end
		local elb = self.MercerElbow
		if elb then
			if CurTime() - elb.t0 > win then return false end
			self.MercerElbow = nil
			self.loco:SetGravity(1000)
		end
		local st = self.MercerFight
		if st then
			if CurTime() - st.fightT0 > self.MercerChordWindow + 0.05 then return false end -- a combo under way
			self:MercerFightEnd()
		end
		if mv == "acb" then return self:MercerFKickStart(true) end -- (the cannonball: the flying kick's machinery)
		-- (user 2026-10-08: the move's own swing, then the devastator's charge pose after it, looked wrong) with critical
		-- mass the two buttons go straight into the devastator's charge (its antic); let go before it is full = the plain
		-- move at the charge so far (MercerFightThink); the critical mass is spent only when the antic completes
		local a = FIGHT[mv]
		if a and a.full and a.fullCrit and FIGHT[a.full] and self:MercerCanDevastate() then
			self:MercerFightStart(a.full, 1)
			if self.MercerFight then self.MercerFight.devFrom = mv end
			return true
		end
		self:MercerFightStart(mv)
		return true
	end
	-- the air banks of the same buttons (the palm strike's is the cannonball)
	ENT.MercerAirChords = {ps = "acb", gpd = "agp", scl = "acl"}
	-- (user 2026-11-05: "пушечное ядро не работает, потому что там конфликты с захватом на Е, и с девастатором, поэтому вот, 1-2 раза еле как получилось его сделать, но это трудно")
	-- What it was: within 0.12 s of each other, both ways, and not at all in a dash or a glide; E first with a man in reach the catch, with a man locked a flight of up to 3 m at him, before it; past 0.12 s the kick.
	-- The graph: graph_devastator 1005 bank {cannonball} Attack and Action pressed; and store {opportunity} 1646, air_opportunities: in the first 0.1 s of the kick's windup (graph_air 866) and of the other air moves' Attack down and Action down go to its {windup}. So LMB pressed with E down is the ball, however long E has been down; E within the kick's first 0.1 s, LMB down.
	-- BY EYE, for fingers: LMB a tap's 0.12 s after an E let go; E up to 0.2 s after LMB. E alone waits those 0.12 s with the catch and the lock's flight (MercerAirGrabThink): its pose at once, no second thing before the ball. In a dash or the kick's flight the catch doesn't wait, there 0.12 s is 3 m. From a dash and a glide too: the graph's dash takes attacks, and E down leaves the glide by itself
	-- And with the jump: the two pressed while Space is down (a jump's press lasts 0.1 to 0.3 s), on the ground still, were the ground's own: with a devastator to give his Critical Pain, cut by the jump or not (the user's alex_mercer_devastator_free 1, test_cannonkeys.py's "Space held 0.15 s"). Now they wait for the air: BY EYE the top of the rise or 0.6 s, so the ball has some height
	ENT.MercerBallAfterE, ENT.MercerBallAfterL, ENT.MercerBallDevT = 0.12, 0.2, 1.5
	function ENT:MercerBallPress(kind, p)
		if not IsValid(p) or self:GetNW2Bool("MercerWall") or self.MercerSlide or self.MercerDive then return false end
		local ground = self:IsOnGround()
		if ground and not self.MercerChargeStart then return false end
		if self.MercerBallQueued then return true end
		local fk = self.MercerFKick
		if fk and fk.cannon then return true end -- (both in one tick: the first of them has it)
		local now, go = CurTime(), false
		if kind == "a" then
			self.MercerBallLmbT = now
			go = p:KeyDown(IN_USE) or now - (self.MercerUsePressT or -9) <= self.MercerBallAfterE
		else
			go = p:KeyDown(IN_ATTACK) and now - (self.MercerBallLmbT or -9) <= self.MercerBallAfterL
		end
		if not go then return false end
		if ground then
			self.MercerBallQueued = {t = now}
			self.MercerUseHeld = nil
			self.MercerPressT = {}
			dbg("cannonball: the two with the jump's Space down: waits for the air")
			return true
		end
		if not self:MercerChordStart("acb") then return false end
		self.MercerPressT = {}
		if self:GetNW2Bool("MercerGlide") then
			self:SetNW2Bool("MercerGlide", false)
			self:SetNW2Float("MercerDive", 0)
		end
		dbg("cannonball: %s pressed; E down %s, %.2f s ago; LMB down %s, %.2f s ago", kind == "a" and "LMB" or "E", tostring(p:KeyDown(IN_USE)), now - (self.MercerUsePressT or -9), tostring(p:KeyDown(IN_ATTACK)), now - (self.MercerBallLmbT or -9))
		return true
	end
	-- (MercerBallPress, the two with the jump) on the ground as long as the charge goes on; let go there, or a charge too long after the keys: dropped
	function ENT:MercerBallQueueThink(p)
		local q = self.MercerBallQueued
		local now = CurTime()
		local down = IsValid(p) and p:KeyDown(IN_ATTACK) and p:KeyDown(IN_USE)
		if down then q.t = now end
		if self:IsOnGround() then
			if self.MercerChargeStart then q.off = nil else q.off = q.off or now end
			if (q.off and now - q.off > 0.1) or now - q.t > 0.5 then self.MercerBallQueued = nil end
			return
		end
		q.air = q.air or now
		if self:GetNW2Bool("MercerWall") or now - q.t > 0.5 then
			self.MercerBallQueued = nil
			return
		end
		if self.loco:GetVelocity().z > 2 * M2U and now - q.air < 0.6 then return end
		self.MercerBallQueued = nil
		if self:MercerChordStart("acb") then dbg("cannonball: off the jump") end
	end
	function ENT:MercerAirChordOk()
		return not self:IsOnGround() and not self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerGlide")
			and self:GetNW2Float("MercerDive", 0) <= 0 and not self.MercerAirDash and not self.MercerSlide
			and not self.MercerGrab and not self.MercerGrind and not self.MercerHToss
	end
	function ENT:MercerCanDevastate()
		return GetConVar("alex_mercer_devastator_free"):GetBool() or self:GetNW2Float("MercerCrit", 0) >= 0.05
	end

	-- LMB ("a") / RMB ("s") of the possessor, from CustomThink
	function ENT:MercerPress(kind)
		if self.MercerGrind then return self:MercerGrindPress() end
		if self.MercerGrab then return self:MercerGrabInput(kind) end
		if self.MercerObj then return self:MercerObjInput(kind) end
		if self.MercerGun then return end
		if self.MercerHitCancel then self:MercerHitCancel() end
		if not GRAPH_FIGHT[self:GetMercerForm().name] then
			self.MercerCoQueued = kind -- (the spines: their strikes wait on the anim, in the behaviour coroutine)
			return
		end
		if kind == "a" and self:MercerBallPress("a", self:GetPossessor()) then return end
		if self:IsOnGround() and not self:GetNW2Bool("MercerWall") then
			local mv = self:MercerChord(kind)
			if mv and self:MercerChordStart(mv) then return end
		elseif self:MercerAirChordOk() then
			local mv = self:MercerChord(kind)
			local air = mv and self.MercerAirChords[mv]
			if air and self:MercerChordStart(air) then return end
		end
		if kind == "s" and not self:IsOnGround() then return end -- in the air RMB is the elbow drop (CustomThink)
		self:MercerFightPress(kind)
	end
	function ENT:MercerCoPress()
		local k = self.MercerCoQueued
		if not k then return end
		self.MercerCoQueued = nil
		if k == "a" then self:MercerCombo() else self:MercerSpecial() end
	end

	-- Ground spikes (claws / spines special): a line of the game's own spike models bursting out ahead.
	function ENT:MercerSpinesBurst()
		local c = self:WorldSpaceCenter()
		self:MercerSound(SND.spikes, 80)
		self:MercerVFX("hit", c, Vector(0, 0, 1), 1.4)
		self:MercerVFX("crush_concrete", self:GetPos() + Vector(0, 0, 4), Vector(0, 0, 1), 0.6)
		for _, e in ipairs(ents.FindInSphere(c, 1.5 * M2U)) do
			if e ~= self and IsValid(e) and DrGBase.CanAttack(e) and (e:IsPlayer() or e:IsNPC() or e:IsNextBot()) then
				local di = DamageInfo()
				di:SetAttacker(self)
				di:SetInflictor(self)
				di:SetDamage(10)
				di:SetDamageType(DMG_SLASH)
				di:SetDamagePosition(e:WorldSpaceCenter())
				e:TakeDamageInfo(di)
				if IsValid(e) then
					local d = e:GetPos() - self:GetPos()
					d.z = 0
					d = (d:LengthSqr() > 1 and d:GetNormalized() or self:GetForward()) * 450 + Vector(0, 0, 180)
					if e:IsNPC() or e:IsPlayer() then
						e:SetGroundEntity(NULL)
						e:SetVelocity(d)
					elseif e.loco and not e.ProtoNoLaunch then
						e.loco:Jump()
						e.loco:SetVelocity(d)
					end
				end
			end
		end
	end

	local SPIKES = {"models/mercer/groundspike_single_mid.mdl", "models/mercer/groundspike_single_small.mdl",
		"models/mercer/groundspike_small.mdl"}
	function ENT:MercerSpikes(f)
		local fwd = self:GetForward()
		fwd.z = 0
		fwd:Normalize()
		self:MercerSound(SND.spikes, 85)
		for i = 1, 7 do
			self:Timer(i * 0.06, function(self)
				local start = self:GetPos() + fwd * (60 + i * 70) + Vector(0, 0, 60)
				local tr = util.TraceLine({start = start, endpos = start - Vector(0, 0, 200), mask = MASK_SOLID_BRUSHONLY})
				if not tr.Hit then return end
				local spike = ents.Create("prop_dynamic")
				spike:SetModel(SPIKES[math.random(#SPIKES)])
				spike:SetPos(tr.HitPos - Vector(0, 0, 120))
				spike:SetAngles(Angle(math.random(-15, 15), math.random(360), math.random(-15, 15)))
				spike:SetModelScale(0.35 + math.random() * 0.25)
				spike:Spawn()
				spike:SetSolid(SOLID_NONE)
				local t0 = CurTime()
				local id = "alex_mercer_spike" .. spike:EntIndex()
				timer.Create(id, 0, 0, function()
					if not IsValid(spike) then timer.Remove(id) return end
					local k = math.Clamp((CurTime() - t0) / 0.12, 0, 1)
					spike:SetPos(tr.HitPos - Vector(0, 0, 120 * (1 - k)))
				end)
				timer.Simple(2.5, function() if IsValid(spike) then spike:Remove() end end)
				self:MercerEffect("alex_mercer_slam", tr.HitPos, 0.5)
				for _, ent in ipairs(ents.FindInSphere(tr.HitPos, 90)) do
					if ent ~= self and DrGBase.CanAttack(ent) and (ent:IsPlayer() or ent:IsNPC() or ent:IsNextBot()) then
						local dmg = DamageInfo()
						dmg:SetAttacker(self)
						dmg:SetInflictor(self)
						dmg:SetDamage(f.damage)
						dmg:SetDamageType(DMG_SLASH)
						ent:TakeDamageInfo(dmg)
						ent:SetVelocity(Vector(0, 0, 450))
					end
				end
			end)
		end
	end

	-- Space: hold to charge (crouch), release to jump - the longer the hold, the higher (like the game).
	-- From the game's prototype_jump graph ("jump" items, unlocks Jump1..Jump4): standing charge 0.333 → 1.333 s
	-- gives 2 → 40 m; running 0.5 → 1.4 s gives 5 → 25 m; the running hop ("run/tactical") is 2 m. Game
	-- gravity ~25 m/s² ≈ our 1000 u/s², so the launch speed is sqrt(2 g h).
	-- Tap vs charged: the release bank picks "tactical" while the charge meter is below 0.1; the meter
	-- (jump_charging store) fills 0 → 1 in 2 s ("slow") or 4 s when moving faster than 10 m/s ("fast").
	local JUMP_STAND = {tmin = 0.3333, tmax = 1.3333, hmin = 2, hmax = 40}
	local JUMP_RUN = {tmin = 0.5, tmax = 1.4, hmin = 5, hmax = 25}
	local HOP_HEIGHT = 2
	-- (MP fix 7, user 2026-10-28: in multiplayer the auto jump fell short) the engine moves a nextbot in steps of its
	-- update interval there - nb_update_frequency in whole ticks (0.1 -> 7 x 0.015 = 0.105 s, the log's controls step):
	-- each gravity step costs height (apex vz^2 / 2g - vz h / 2: 30 u short on a 2 m hop, the user's log). A launch's
	-- upward speed raised to give its planned apex with that step; g = the gravity he flies under. Single player: as is
	local function mpVz(vz, g)
		if game.SinglePlayer() or vz <= 0 then return vz end
		local cv = GetConVar("nb_update_frequency")
		local tick = engine.TickInterval()
		local h = math.ceil((cv and cv:GetFloat() or 0.1) / tick - 0.001) * tick
		if h <= 0.02 then return vz end
		local a = (g or 1000) * h / 2
		return a + math.sqrt(a * a + vz * vz)
	end
	local function launchSpeed(cfg, held)
		local k = math.Clamp((held - cfg.tmin) / (cfg.tmax - cfg.tmin), 0, 1)
		-- (the jump upgrades: the full charge's height from 7 m at level 0 to the game's own at 4)
		local hmax = Lerp(ALEX_MERCER_JUMP_LEVEL:GetInt() / 4, math.min(7, cfg.hmax), cfg.hmax)
		local h = Lerp(k, cfg.hmin, math.max(hmax, cfg.hmin)) * M2U
		return mpVz(math.sqrt(2 * 1000 * h)), k
	end

	-- When a jump node ends in the air, hand over to the air pose in the same tick (no frozen frame).
	local function toAir(self)
		if self:IsOnGround() then self:UpdateAnimation() else self:MercerAirPose() end
	end

	-- prototype_air → fall/pose: "default" while rising or slow, "down" once falling faster than 2 m/s.
	-- Jump nodes (tap, release, launch, run jump) keep priority until they end (the game's priorities).
	function ENT:MercerAirPose()
		local st = self.MercerNode
		if self:GetNW2Bool("MercerObjHold") then
			if not st then GP.Start(self, "mercer/obj/air", {air = true, hold = true}) end
			return
		end
		if self:GetNW2Bool("MercerHolding") then
			-- (prototype_air fall/pose/holding/grapple: jump_B 74-98 cyclic)
			if not st then GP.Start(self, "mercer/grab/fall", {air = true, loop = true}) end
			return
		end
		if st and not st.opts.air then
			-- (2026-11-04, alex_mercer_air_grab) a jump's own node keeps its pose: graph_jump 1194's reach on its upper body (upper_body2), the catch.
			-- (user: "захват в воздухе тоже не заметил": it had no reach of its own, only the catch)
			if (st.opts.onDone == toAir or (st.opts.nextOpts and st.opts.nextOpts.onDone == toAir)) and not st.opts.block then self:MercerAirGrabThink(st, true) end
			return
		end
		-- (2026-11-04, alex_mercer_air_grab) E held, the hands free: the reach
		if self:MercerAirGrabThink(st) then return end
		-- (2026-11-04) firing a gun in the air: air/firearm's alex_weap_rifle_aim_air, cyclic at 2
		if self.MercerGun and not self.MercerGun.missile and self:MercerGunAiming() then
			if not (st and st.path == "mercer/gun/air") then GP.Start(self, "mercer/gun/air", {air = true}) end
			return
		end
		-- (2026-10-28: an automatic head-first dive on a fast fall was tried - removed: the user's "leap of faith" is the
		-- game's Bullet Dive, on a key from the glide - MercerBulletStart)
		local falling = self:GetVelocity().z < -AIR_FALL_SPEED or (st ~= nil and st.path == NODE_AIR_DOWN)
		if falling then
			if not (st and st.path == NODE_AIR_DOWN) then GP.Start(self, NODE_AIR_DOWN, {air = true}) end
		elseif not (st and st.path == BLEND_AIR) then
			GP.StartBlend(self, BLEND_AIR, {air = true, full = 2.5})
		end
	end

	-- the jump_charging meter (0 -> 1 in 2 s, 4 s above 10 m/s) with what it brought from the air
	function ENT:MercerChargeMeter(held)
		return math.Clamp(held / (self.MercerChargeFast and 4 or 2) + (self.MercerChargeAirM or 0), 0, 1)
	end
	-- (alex_mercer_jump_graph) the meter at 1, jump_charging/effects/cycle/full_start = effects/charge/bare/jump/full_start: alex_warp at 1, 0.2 s on transform_short at 0.5088, pitch 1.5 - 1.6; the wave and the biomass on the
	-- client (MercerChargeFullT). Standing and running alike
	function ENT:MercerChargeFull()
		self.MercerChargeFullDone = true
		self:SetNW2Float("MercerChargeFullT", CurTime())
		self:MercerCue("alex_warp")
		self:Timer(0.2, function(ent) ent:MercerCue("transform_short", 0.5088, 1.55) end)
	end
	-- (alex_mercer_jump_graph) jump_charging's bank air (graph_jump 1095-1128), which the plain fall and the air dash spawn: Jump down: the meter 0 -> 1 in 1.5 s; let go: it stays 0.2 s (0.3 s falling over 20 m/s), then chargeClear. No
	-- jump in the air, only the meter and its effects. The landing's banks take it (graph_air 2971-3104, MercerChargeLanded): still down: he goes on, the release is the jump with all of it; let go in that window: the jump at once
	function ENT:MercerAirChargeFree()
		return not (self.MercerFight or self.MercerFKick or self.MercerStomp or self.MercerElbow or self.MercerGrab or self.MercerGrind or self.MercerBullet
			or self.MercerHToss or self.MercerAirSlam or self.MercerObj or self.MercerGun or self:GetNW2Bool("MercerWall") or self:GetNW2Bool("MercerGlide"))
	end
	function ENT:MercerAirChargeDown()
		if not self:MercerAirChargeFree() then return end
		local ac, now = self.MercerAirCharge, CurTime()
		if not (ac and ac.rel and now - ac.rel < (self:GetVelocity().z < -20 * M2U and 0.3 or 0.2)) then
			ac = {sec = 0, m = 0}
			self.MercerAirCharge = ac
			self.MercerChargeFullDone = nil
			self:SetNW2Float("MercerChargeFullT", 0)
		end
		ac.down, ac.rel, ac.t = true, nil, now
		self:SetNW2Float("MercerChargeStart", now - ac.sec)
		self:SetNW2Bool("MercerChargeAnimDone", false)
		self:SetNW2Bool("MercerCharging", true)
		self:MercerSound(SND.powerup_jump, 62)
	end
	function ENT:MercerAirChargeThink()
		local ac = self.MercerAirCharge
		if not ac then return end
		local now = CurTime()
		if not self:MercerAirChargeFree() then
			self.MercerAirCharge = nil
			self:SetNW2Bool("MercerCharging", false)
		elseif ac.down then
			local dt = now - ac.t
			ac.t, ac.sec, ac.m = now, ac.sec + dt, math.min(1, ac.m + dt / 1.5)
			if ac.m >= 1 and not self.MercerChargeFullDone then self:MercerChargeFull() end
		elseif now - ac.rel >= 0.3 then
			self.MercerAirCharge = nil
		end
	end
	-- what the landing does with it: the time held is the time held, the meter what it was. True: still down
	function ENT:MercerChargeLanded(ac, fallV)
		local now = CurTime()
		if not ac.down and now - ac.rel >= (fallV > 20 * M2U and 0.3 or 0.2) then return end
		local fast = self:GetVelocity():Length2D() > 10 * M2U
		self.MercerChargeFast = fast
		self.MercerChargeStart = now - ac.sec
		self.MercerChargeAirM = ac.m - ac.sec / (fast and 4 or 2)
		if ac.down then
			self.MercerChargeLandT = now
			self:SetNW2Bool("MercerCharging", true)
			return true
		end
		self.MercerLandJump = true -- (next tick: the engine's own landing still sets his velocity after this callback)
	end
	-- (standing, Space still down: the landing's exit_passive, from 0.3 s, the huge one's from 1 s, takes him into the crouch)
	function ENT:MercerChargeLandOver()
		local lt = self.MercerChargeLandT
		if not lt then return false end
		local over = CurTime() - lt >= (self.MercerNode.path == NODE_LAND_HUGE and 1 or 0.3)
		if over then self.MercerChargeLandT = nil end
		return over
	end

	function ENT:MercerJumpCharge()
		if self.MercerBullet then return false end -- (user 2026-10-28: nothing cuts the Bullet Dive)
		if self.MercerGrab and self.MercerGrab.phase == "sseized" then return end -- (the pack's Super Soldier has him)
		if self.MercerGrind then return end -- riding a body: man_grind has no jump
		if self.MercerHitCancel then self:MercerHitCancel() end -- (user 2026-10-23: a jump cuts a hit reaction too)
		if self:GetNW2Bool("MercerWall") then
			-- a NEW Space press while on the wall: tap = wallJump (off the wall), hold = wallJumpUp (charged leap up it)
			if CurTime() - (self.MercerWallStart or 0) > 0.2 then
				self.MercerWallCharge = CurTime()
				self.MercerChargeFullDone = nil
				self:SetNW2Float("MercerChargeFullT", 0)
				self:SetNW2Float("MercerChargeStart", CurTime())
				self:SetNW2Bool("MercerCharging", true)
			end
			return
		end
		if self.MercerChargeStart then dbg("charge pressed again while charging (ignored)") return end
		-- the heavy landing's Jump opportunity while moving (JumpMulti)
		if self.MercerNode and self.MercerNode.path == NODE_LAND_HEAVY and self:IsOnGround()
			and not self:GetNW2Bool("MercerHolding") and self.MercerMoveDir and not self.MercerMoveDir:IsZero() then
			return self:MercerHeavyJump()
		end
		if not self:IsOnGround() and self.MercerJumpGraph:GetBool() then return self:MercerAirChargeDown() end
		if not self:IsOnGround() or self:IsPlayingAnimation() then return end
		self.MercerChargeStart = CurTime()
		self.MercerChargeFast = self:GetVelocity():Length2D() > 10 * M2U
		self.MercerChargeAirM, self.MercerChargeFullDone, self.MercerAirCharge, self.MercerChargeLandT = nil, nil, nil, nil
		self:SetNW2Float("MercerChargeFullT", 0)
		self:SetNW2Float("MercerChargeStart", CurTime())
		self:SetNW2Bool("MercerChargeAnimDone", false)
		self:SetNW2Bool("MercerCharging", true)
		self:MercerSound(SND.powerup_jump, 62)
		dbg("charge start speed2d=%.0f", self:GetVelocity():Length2D())
		if self:GetNW2Bool("MercerHolding") then
			-- (prototype_jump grapple: the human in hand - the game crouches on the spot; user 2026-10-23: on the run he
			-- keeps running while it charges, the release takes the running grapple jump)
			if self:GetVelocity():Length2D() < 100 then GP.Start(self, "mercer/grab/charge", {block = true}) end
		elseif self:GetNW2Bool("MercerObjHold") then
			-- (user 2026-10-29) carrying: the game's crouch with the object (prototype_jump pose/holding/object), its hands
			-- on it; on the move the carry loco goes on (as with a human)
			if self:GetVelocity():Length2D() < 100 then
				GP.Start(self, "mercer/obj/charge", {block = true, next = "mercer/obj/charge_hold", nextOpts = {loop = true, block = true}})
			end
		elseif self:GetVelocity():Length2D() < 100 then
			GP.Start(self, NODE_CHARGE, {block = true, next = NODE_CHARGE_HOLD, nextOpts = {loop = true, block = true}})
		end
	end

	-- prototype_wall → actions/input/jump (Jump released, charge counts):
	--  running UP the wall (run direction within 90° of up) -> wall_jump_up: wallJumpUp item, charge 0.667 -> 1.333 s
	--   = 10 -> 40 m straight up along the wall, pose wall_run_jump_up 2-25 (0.5 s) then jump_off_ledge_2 10-20; the fall
	--   after it re-grabs the wall (wall_test) only once he comes down
	--  otherwise (sideways / down, or pulling back) -> wallJump: from 0.1667 s, 25 -> 35 m/s (charge), at least 45° up,
	--   within 20° of straight off the wall, carrying the run's momentum (arc 30°), gravity 35 m/s² while rising,
	--   drift 5; pose by input: forward = jump_dive, back = jump_long_back
	-- the climb anims and wall_run_jump_up are upright with hands / balls of the feet on a plane 0.93 m in front of the
	-- root (fingertips 1.07 m): the root hangs that far off the wall (at the wall run's 16 u he was half inside it)
	local CLIMB_DIST, WALL_DIST = 0.95 * M2U, 16
	-- move the root out to the upright anims' wall distance before leaving the wall (hull-traced)
	function ENT:MercerWallStepOut(n)
		local pos = self:GetPos()
		local eye = pos + Vector(0, 0, 36)
		local wall = util.TraceLine({start = eye, endpos = eye - n * (CLIMB_DIST + 24), filter = self, mask = MASK_SOLID_BRUSHONLY})
		if not wall.Hit then return end
		local want = wall.HitPos + n * CLIMB_DIST
		want.z = pos.z
		local tr = util.TraceHull({start = pos, endpos = want, mins = Vector(-13, -13, 0), maxs = Vector(13, 13, 72),
			filter = self, mask = MASK_SOLID})
		self:SetPos(tr.HitPos)
	end
	-- exit_edge (the stick released 0.1667 s on the wall run) → backflip: alex_wall_run_flip 15-52 over 1 s, fall from
	-- 0.9333 s. Rendered (tools/stickfig.py): upright, facing the wall, the root rises 2.1 m from frame 15 and ends 2 m
	-- back off the wall -> launch 10 m/s up, 2 m/s away (the anim is pinned, physics carries him).
	ALEX_MERCER_GRAPH["mercer/wall_backflip"] = {{start = 0, stop = 1, anim = "alex_wall_run_flip", rate = 1, f0 = 15,
		f1 = 52, cyclic = false, part = "", blendin = 0.1, blendout = 0.3}}
	function ENT:MercerWallBackflip()
		local n = self.MercerWallNormal
		if not n then return end
		self:MercerWallStepOut(n)
		self:MercerStopWall(n * 2 * M2U + Vector(0, 0, 10 * M2U))
		self:SetAngles(Angle(0, (-n):Angle().y, 0))
		GP.Start(self, self:GetNW2Bool("MercerHolding") and "mercer/wall_grap_fall" or "mercer/wall_backflip", {onDone = toAir})
		self:MercerTrail("backflip")
		self:Timer(0.5, function(ent) ent:MercerCue("backflip_whoosh") end)
		self:MercerSound(SND.jump, 65)
		self:MercerSound(SND.jump_wind, 70)
	end
