	function ENT:MercerWallJump(held)
		local n = self.MercerWallNormal
		self:SetNW2Bool("MercerCharging", false)
		if not n or self.MercerWallUsd then return end
		local p = self:GetPossessor()
		local back = IsValid(p) and p:KeyDown(IN_BACK)
		local a = self:GetNW2Float("MercerWallDir", 0)
		if math.cos(math.rad(a)) > 0.3 and not back then
			local k = math.Clamp((held - 0.6667) / (1.333 - 0.6667), 0, 1)
			local h = Lerp(k, 10, 40) * M2U
			-- the jump starts from the anim's wall distance (from the wall run he hugs it at 16 u): otherwise his feet
			-- and the hull scrape up through the wall ("застревает в текстурке")
			self:MercerWallStepOut(n)
			-- (2026-11-04, alex_mercer_wall_jump_graph) why it "даже не ускоряют": those 0.6667, 1.333 are wallJumpUp's flight times, not seconds held (fig_schema: flightTimeMin, Max, heightMin, Max; by the meter, 1 s on the wall,
			-- graph_wall 1041), and we flew the height under his plain gravity and hung at the top: a tap made 10 m in 0.89 s, stopping, slower than running on. The game: h in T: 2h / T up, 45 m/s^2 (a tap 30 m/s, in full 60), the wall
			-- taken again from 15 m/s up (node wall_test, graph_wall 887-891), at that speed
			local graph = self.MercerWallJumpGraph:GetBool()
			if graph then
				local m = math.Clamp(held, 0, 1)
				local T = Lerp(m, 0.6667, 1.333)
				local hm = Lerp(m, 10, Lerp(ALEX_MERCER_JUMP_LEVEL:GetInt() / 4, 20, 40)) * M2U
				self:MercerStopWall(Vector(0, 0, mpVz(2 * hm / T, 2 * hm / (T * T))))
				self.loco:SetGravity(2 * hm / (T * T))
				self.MercerWallJumpGrav = true
				self.MercerWallUp15 = true
			else
			self:MercerStopWall(Vector(0, 0, mpVz(math.sqrt(2 * 1000 * h))))
			end
			self.MercerWallRegrabAtApex = true
			self.MercerWallUpN, self.MercerWallUpT = n, CurTime() -- resume on this wall at the apex
			GP.Start(self, "mercer/wall_jump_up", {onDone = toAir})
			self:MercerTrail("jump_charged")
		else
			local away = Vector(n.x, n.y, 0):GetNormalized()
			local left = Vector(0, 0, 1):Cross(-away)
			local side = math.sin(math.rad(a))
			local dir
			if math.abs(side) > 0.3 then
				-- momentum: lean the launch toward the run direction, at most 30° off the wall
				dir = (away + left * (side > 0 and 1 or -1) * math.tan(math.rad(30))):GetNormalized()
			else
				dir = away
				if IsValid(p) then
					local f = p:EyeAngles():Forward()
					f.z = 0
					if f:Length() > 0.1 then
						local d = math.Clamp(math.AngleDifference(f:Angle().y, away:Angle().y), -20, 20)
						dir = Angle(0, away:Angle().y + d, 0):Forward()
					end
				end
			end
			local v = Lerp(math.Clamp(held / 1.333, 0, 1), 25, 35) * M2U
			local hv = math.min(v * math.cos(math.rad(45)), 25 * M2U)
			local launchH = dir * hv
			-- (players 2026-10-28: "the jump while wall running fails to provide the speed boost of the original") the
			-- wall graph's jump off a run along the wall is a reference to prototype_sprint's jump - the sprint jump keeps
			-- the run's speed x 1.2 (MercerJumpRelease); so here: his speed along the wall x 1.2, plus the push off it
			-- (the away part of the launch above). Running up the wall: as before
			if math.abs(side) > 0.3 then
				local wv = self.loco:GetVelocity()
				local flat = Vector(wv.x, wv.y, 0)
				local along = flat - away * flat:Dot(away)
				local runDir = left * (side > 0 and 1 or -1)
				local push = away * math.max(dir:Dot(away), 0) * hv
				-- (never slower along the wall than the launch above gave)
				if along:Length() * 1.2 > hv * math.max(dir:Dot(runDir), 0) then launchH = along * 1.2 + push end
				dbg("wall jumpout: run along %.1f m/s -> launch %.1f m/s (was %.1f)", along:Length() / M2U,
					launchH:Length() / M2U, hv / M2U)
			end
			self:MercerStopWall(launchH + Vector(0, 0, mpVz(v * math.sin(math.rad(45)), 35 * M2U)))
			self.loco:SetGravity(35 * M2U)
			self.MercerWallJumpGrav = true
			-- pose bank: running along the wall (Locomotion within 60° of left / right) -> wall_run_jumpout_l / _r, the
			-- flip variant with the stick pulled against the run (axisDirection -110 / 110), stick back -> jump_long_back;
			-- running up -> jump_dive (stick back -> jump_long_back)
			local node = back and "mercer/wall_jump_back" or "mercer/wall_jump_dive"
			local runSide = math.abs(math.sin(math.rad(a))) > 0.5 and (a > 0 and 1 or -1) or 0
			if runSide ~= 0 and not back then
				local against = IsValid(p) and ((runSide > 0 and p:KeyDown(IN_MOVERIGHT)) or (runSide < 0 and p:KeyDown(IN_MOVELEFT)))
				node = "mercer/wall_jumpout_" .. (runSide > 0 and "l" or "r") .. (against and "_flip" or "")
				-- the jumpout anims start in the wall run's space: face the run direction along the wall and let the
				-- client straighten the model from the wall tilt (the game's surface switch to Ground)
				self:SetAngles(Angle(0, (self.MercerWallYaw or dir:Angle().y) + runSide * 90, 0))
				self:SetNW2Float("MercerWallExitT", CurTime())
				self:SetNW2Int("MercerWallExitSide", runSide)
				self.MercerJumpoutT = CurTime()
				self:MercerTrail(against and "backflip" or "jump")
			else
				self:SetAngles(Angle(0, dir:Angle().y, 0))
				self:MercerTrail("jump")
			end
			GP.Start(self, node, {onDone = toAir})
		end
		self:MercerSound(SND.jump, 70)
		self:MercerSound(SND.jump_wind, 65)
	end

	-- a pose from one of the JP lists (weights, never the last one twice, some only above a charge)
	function ENT:MercerJumpPosePick(list, charge)
		local pool, sum = {}, 0
		for _, e in ipairs(list) do
			if e[1] ~= self.MercerLastJumpPose and (not e[4] or charge > e[4]) then
				pool[#pool + 1] = e
				sum = sum + e[2]
			end
		end
		if #pool == 0 then pool, sum = {list[1]}, list[1][2] end
		local r = math.random() * sum
		local pick = pool[#pool]
		for _, e in ipairs(pool) do
			r = r - e[2]
			if r <= 0 then pick = e break end
		end
		self.MercerLastJumpPose = pick[1]
		return pick
	end

	-- the run jump's release pose (directional blend over its window), after the enter pose (jump_long_D 0-2 in
	-- 0.133 s) for a charged run jump; opens the back_flip opportunity from w0 to 0.5 s
	function ENT:MercerRunJumpPose(list, charge, enter, w0)
		local e = self:MercerJumpPosePick(list, charge)
		local opts = {duration = e[3], full = 3, onDone = toAir}
		if enter then
			GP.Start(self, NODE_RUN_ENTER, {next = e[1], nextOpts = opts})
		else
			GP.StartBlend(self, e[1], opts)
		end
		self.MercerBackFlipWin = {t0 = CurTime(), w0 = w0, path = e[1]}
	end

	-- air/fall/land heavy -> Jump while moving: land_heavy_jump_fwd 14-21 in 0.1333 s, then the running charged jump's
	-- release at no charge (jump_simulation/forward: 5 m) with its pose bank
	function ENT:MercerHeavyJump()
		self:MercerCombatEvent()
		local md = self.MercerMoveDir
		if md and not md:IsZero() then self:SetAngles(Angle(0, md:Angle().y, 0)) end
		GP.Start(self, JP.heavyJump, {block = true, onDone = function(ent)
			if not ent:IsOnGround() then return toAir(ent) end
			local vel = ent:GetVelocity()
			vel.z = 0
			local fwd = ent:GetForward() * math.max(vel:Length() * 1.2, 4 * M2U)
			local p = ent:GetPossessor()
			if IsValid(p) and p:KeyDown(IN_BACK) and not p:KeyDown(IN_FORWARD) and p:KeyDown(IN_SPEED) then
				GP.Start(ent, JP.backflip, {onDone = toAir})
				ent:MercerTrail("backflip")
			else
				ent:MercerRunJumpPose(JP.run, 0, false, 0.3)
				ent:MercerTrail("jump")
			end
			ent.MercerFallSpeed = 0
			ent:LeaveGround()
			ent:SetVelocity(fwd + Vector(0, 0, (launchSpeed(JUMP_RUN, 0))))
			ent:MercerSound(SND.sprint, 70)
			ent:MercerSound(SND.jump_wind, 62)
		end})
	end

	function ENT:MercerJumpRelease()
		if self.MercerBullet then return false end -- (user 2026-10-28: nothing cuts the Bullet Dive)
		local ac = self.MercerAirCharge
		if ac and ac.down then
			ac.down, ac.rel = false, CurTime()
			self:SetNW2Bool("MercerCharging", false)
			return
		end
		if self.MercerWallCharge then
			local held = CurTime() - self.MercerWallCharge
			self.MercerWallCharge = nil
			if self:GetNW2Bool("MercerWall") then self:MercerWallJump(held) else self:SetNW2Bool("MercerCharging", false) end
			return
		end
		if not self.MercerChargeStart then return end
		local held = CurTime() - self.MercerChargeStart
		local charge = self:MercerChargeMeter(held)
		self.MercerChargeStart, self.MercerChargeAirM, self.MercerChargeLandT = nil, nil, nil
		self:SetNW2Bool("MercerCharging", false)
		if not self:IsOnGround() then GP.Stop(self) return end
		-- (the huge landing has no jump bank in the graph: let go in its second it was all for nothing)
		if self.MercerNode and self.MercerNode.path == NODE_LAND_HUGE and self.MercerJumpGraph:GetBool() then return end
		local vel = self:GetVelocity()
		vel.z = 0
		local running = vel:Length() > 100
		-- charge meter < 0.1 = the game's tactical (tap) jump
		local tap = held < (running and self.MercerChargeFast and 0.4 or 0.2)
		local sprint = running and self:GetMercerSprint() > 0
		local up, t
		if sprint then
			-- (prototype_sprint's jump: common/jump_simulation/sprint for a tap too)
			up, t = launchSpeed(JP.sprintJump, held)
		elseif running and tap then
			up, t = mpVz(math.sqrt(2 * 1000 * HOP_HEIGHT * M2U)), 0
		else
			up, t = launchSpeed(running and JUMP_RUN or JUMP_STAND, held)
		end
		local trail = tap and "jump" or "jump_charged"
		if running or not tap then self:MercerVO("alex_jump_sml_start", 1) end
		dbg("release held=%.2f running=%s tap=%s up=%.0f", held, tostring(running), tostring(tap), up)
		-- start the jump's own node BEFORE leaving the ground, so DrGBase's leave-ground animation update
		-- already sees it (otherwise it would flash another anim for a tick)
		self.MercerTapJump = nil
		if self:GetNW2Bool("MercerHolding") then
			GP.Start(self, running and "mercer/grab/jump_run" or "mercer/grab/jump", {onDone = toAir})
		elseif self:GetNW2Bool("MercerObjHold") then
			GP.Start(self, "mercer/obj/jump", {onDone = toAir})
		elseif running then
			local p = self:GetPossessor()
			local back = IsValid(p) and p:KeyDown(IN_BACK) and not p:KeyDown(IN_FORWARD)
			if tap and not sprint then
				if vel:Length() < 7 * M2U then
					-- run/tactical: the small front flip (its brake node spawns the frontflip trail)
					GP.Start(self, JP.hop, {onDone = toAir})
					trail = "frontflip"
					self.MercerTapJump = true -- (its variableNameSet: the soft landing is land_soft)
				else
					self:MercerRunJumpPose(JP.new, charge, false, 0)
				end
			elseif back and IsValid(p) and p:KeyDown(IN_SPEED) and not (sprint and charge >= 1) then
				-- Run held + the stick pulled back: the backflip (after the enter pose for a charged run jump)
				if sprint then
					GP.Start(self, JP.backflip, {onDone = toAir})
				else
					GP.Start(self, NODE_RUN_ENTER, {next = JP.backflip, nextOpts = {onDone = toAir}})
				end
				trail = "backflip"
			elseif sprint then
				self:MercerRunJumpPose(charge >= 1 and JP.sprint or JP.run, charge, false, 0.3)
				trail = "jump_charged"
			else
				self:MercerRunJumpPose(JP.run, charge, true, 0.3)
			end
		elseif tap then
			self.MercerTapJump = true -- the game marks the tactical jump: its soft landing is land_soft
			GP.Start(self, NODE_TAP, {onDone = toAir})
		else
			GP.Start(self, NODE_RELEASE, {next = NODE_CHARGED_AIR, nextOpts = {onDone = toAir}})
		end
		self.MercerFallSpeed = 0
		self.MercerJumpN = (self.MercerJumpN or 0) + 1 -- (only for alex_mercer_disguise_rates)
		self:LeaveGround()
		self:SetVelocity(vel * 1.2 + Vector(0, 0, up))
		self:MercerSound(SND.sprint, 70)
		self:MercerSound(SND.jump_wind, 62)
		self:MercerTrail(trail)
		if t > 0.6 then
			self:MercerVFX("boost", self:GetPos() + Vector(0, 0, 8), Vector(0, 0, 1)) -- loco/speed_boost
			-- (user 2026-10-30) the node's shockWave001 distortion ring + radialBlur (client alex_mercer_vfx.lua)
			self:MercerVFX("boost_wave", self:GetPos() + Vector(0, 0, 8), Vector(0, 0, 1), 1, self)
			self:MercerVFX("pound", self:GetPos() + Vector(0, 0, 2), nil, 0.4 + t * 0.4) -- ground_pound/charged
			self:MercerCue("jumpwind_gust")
		end
	end

	-- Bare-hand combat = prototype_bare/attacks/basic, node for node (build/graph_bare.txt). Every attack:
	--  windup (autoTarget turn) -> hold while the key is held (charge 0 -> 1 over 0.4 s) -> release when it is let go
	--  or fully charged -> transition_to_idle. Release: hit item (a sphere of radius r on a joint swept over its
	--  window; damageMin..Max and impulseMin..Max lerped by the charge), moveCharged lunge (distanceMin..Max by
	--  charge), the anim's own root motion (pinned in the model, rootspeed.lua drives the entity).
	--  Combo store: Attack pressed during the attack (taken from the release's window time on, or in the transition)
	--  -> the next punch, Special -> the kicks. Full charge: punch 1 / 2 -> uppercut (connect: Mercer follows the
	--  launched target up with 3 hits), punch 3 -> superman punch.
	-- at = {t0, t1 (-1 = whole node), turning °/s, arc °, maxDistance m, useInput}
	-- hit = {t0, t1, joint, radius m, arcRange ° (0 = all round), damageMin, damageMax, impulseMin, impulseMax (game
	--  axes: y up, -z forward)}; lunge = {t0, t1, distanceMin m, distanceMax m, min charge}
	local function seg(t0, t1, anim, f0, f1)
		return {start = t0, stop = t1, anim = anim, rate = 1, f0 = f0, f1 = f1, cyclic = false, part = "",
			blendin = 0, blendout = 0}
	end
