	function ENT:MercerStompStart()
		if self.MercerBullet then return false end -- (user 2026-10-28: nothing cuts the Bullet Dive)
		self:MercerCombatEvent()
		self.MercerStomp = {t0 = CurTime(), phase = "windup", charge = 0}
		GP.Start(self, "mercer/stomp_windup", {hold = true})
		self:SetNW2String("MercerHoldJoint", "Ankle_L") -- charge/bare/kick/l_foot
	end

	function ENT:MercerStompThink(p, dt)
		local st = self.MercerStomp
		if st.phase == "windup" or st.phase == "hold" then self:MercerClocksAhead(st, dt, self:MercerFormSpeed()) end
		local t = CurTime() - st.t0
		local vel = self.loco:GetVelocity()
		local hv = Vector(vel.x, vel.y, 0)
		local held = IsValid(p) and p:KeyDown(IN_ATTACK2)
		if st.phase == "windup" then
			-- flyingBrake: velocityXZ 8, gravity 5, gravityUp 30
			if hv:Length() > 0 then hv = hv:GetNormalized() * math.Approach(hv:Length(), 8 * M2U, 30 * M2U * dt) end
			vel.z = vel.z > 0 and math.Approach(vel.z, 0, 30 * M2U * dt) or vel.z - 5 * M2U * dt
			self.loco:SetGravity(0)
			if t >= 0.2 then
				st.phase, st.t1 = "hold", CurTime()
				vel.z = 15 * M2U -- fall initialVelocity (0, 15, 0)
				GP.Start(self, "mercer/stomp_hold", {hold = true})
			end
		elseif st.phase == "hold" then
			if self.MercerLockOn then hv = self:MercerLockHome(hv, dt, 50, 20) or hv end
			self.loco:SetGravity(30 * M2U)
			st.charge = math.min(1, (CurTime() - st.t1) / 0.6667)
			if not held or st.charge >= 1 then
				st.phase = "dive"
				hv = Vector()
				vel.z = -15 * M2U
				GP.Start(self, "mercer/stomp_release", {hold = true})
				self:SetNW2String("MercerHoldJoint", "")
				self:MercerCue("power_whoosh", 1, 0.75)
				self:MercerTrail("fall")
			end
		else
			self.loco:SetGravity(50 * M2U)
			hv = self.MercerLockOn and self:MercerLockHome(hv, dt) or Vector()
		end
		self.loco:SetVelocity(Vector(hv.x, hv.y, vel.z))
	end

	function ENT:MercerStompLand(speed)
		local st = self.MercerStomp
		self.MercerStomp = nil
		self.loco:SetGravity(1000)
		self:SetNW2String("MercerHoldJoint", "")
		if not st or st.phase ~= "dive" then return false end
		local v = speed / M2U
		local tier = STOMP_LAND[3]
		for _, x in ipairs(STOMP_LAND) do if v >= x[1] then tier = x break end end
		local pos = self:GetPos()
		local done = {}
		for _, h in ipairs({STOMP_FOOT, tier[2]}) do
			local r = h[4] * M2U
			for _, e in ipairs(ents.FindInSphere(pos, r + 64)) do
				if not done[e] and fightable(self, e) and nearestOn(e, pos):DistToSqr(pos) <= r * r then
					done[e] = true
					self:MercerFightDamage(e, h, st.charge, nearestOn(e, pos), false, false, false)
				end
			end
		end
		self:MercerShake("medium", "large")
		-- (user 2026-10-27: "a narrow crack, not a crater") every tier: the slam crater (was the line crack below 80 m/s)
		self:MercerDecal("AlexMercerCrack", pos + Vector(0, 0, 10), pos - Vector(0, 0, 30), self)
		self:MercerVFX("pound", pos + Vector(0, 0, 2), nil, tier[3])
		if tier[5] then self:MercerVFX("land_huge", pos + Vector(0, 0, 2)) end
		self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, tier[3] * 1.4)
		self:MercerCue(tier[5] and "deep_impact" or "explosion_med")
		self:MercerCue("jumpwind_gust")
		self:MercerSound(SND.land_heavy, 90)
		GP.Start(self, "mercer/stomp_land", {block = true, exitAfter = 0.6667, pressAfter = 0.3333, -- (hit_ground exit_passive 0.6667 s)
			onDone = function(ent) ent:UpdateAnimation() end})
		return true
	end

