					nodes[#nodes + 1] = seg(t, t + dur, sg[1], sg[3], sg[4])
					t = t + dur
				end
				c.dur = t
				ALEX_MERCER_GRAPH["mercer/consume_" .. set .. "_" .. c.name] = nodes
			end
		end

		local function grabbable(self, e)
			if not IsValid(e) or e == self then return false end
			-- (user 2026-10-28: grabbing players) a living player he may fight (not his possessor, not one in a vehicle or
			-- possessing a nextbot - their body is hidden), then the same human test as the NPCs
			if e:IsPlayer() then
				if not e:Alive() or e:InVehicle() or not fightable(self, e)
					or (e.DrG_IsPossessing and e:DrG_IsPossessing()) then return false end
			elseif not (e:IsNPC() or e:IsNextBot()) then
				return false
			end
			if e:GetClass() == "drg_alex_mercer" or (e.Health and e:Health() <= 0) or e.MercerGone or e.MercerHeldBy then
				return false
			end
			-- (2026-10-30, the pack's Hunter session) the game names the grapple joints alike on every rig: the pack's Hunters
			-- (drg_proto_hunter and the bosses built on it - all have HunterNode) passed the human test below, and he played
			-- his human grab on them - they have no receive anims; not grabbed as a human
			if e.HunterNode then return false end
			-- (2026-11-03, the pack's Super Soldier: its own scene, MercerHunterGrabStart - he can't hold it as a human)
			if e.ProtoSuperSoldier then return false end
			-- humans: a Valve biped of human height - or (user 2026-10-29, the Prototype NPC pack) the game's own human
			-- rig (Head + R_Wrist_Grapple: his victims' anims play on it as they are)
			if not (e:LookupBone("ValveBiped.Bip01_Head1") or (e:LookupBone("Head") and e:LookupBone("R_Wrist_Grapple"))) then
				return false
			end
			return e:OBBMaxs().z - e:OBBMins().z < 100
		end

		function ENT:MercerGrabTarget()
			local pos, fwd = self:GetPos(), self:GetForward()
			local best, bd
			for _, e in ipairs(ents.FindInSphere(pos, GRAB_RANGE + 40)) do
				if grabbable(self, e) then
					local to = e:GetPos() - pos
					to.z = 0
					local d = to:Length()
					if d < GRAB_RANGE and (d < 24 or to:GetNormalized():Dot(fwd) > GRAB_COS) and (not bd or d < bd) then
						best, bd = e, d
					end
				end
			end
			return best
		end

		-- The victim stays the NPC itself: frozen (SCHED_NPC_FREEZE), not solid, set by its neck into his hand every
		-- tick. No entity is ever created for a grab (2026-10-04: a ragdoll copy per grab spawned endless copies and broke
		-- the user's server). Consumed = faded out, then removed; thrown = killed with the throw's force (its own death
		-- ragdoll flies, made by the engine like any death).
		-- (server: no Entity:SetupBones - it is client-only; GetBonePosition sets the bones up itself)
		local function holdVictim(e)
			if e.MercerHeldBy then return nil end
			-- the neck's height first, before anything about it changes
			local b = e:LookupBone("ValveBiped.Bip01_Neck1") or e:LookupBone("ValveBiped.Bip01_Head1") or e:LookupBone("Neck")
				or e:LookupBone("Head")
			local bp = b and e:GetBonePosition(b)
			local h = bp and (bp.z - e:GetPos().z) or 60
			e.MercerHeldBy = true
			if e:IsNPC() then
				e:SetSchedule(SCHED_NPC_FREEZE)
				e:SetNPCState(NPC_STATE_SCRIPT)
				e:SetMoveType(MOVETYPE_NONE)
				-- VJ Base runs its own AI past the engine's freeze: its own frozen state
				if e.IsVJBaseSNPC and e.SetState and VJ_STATE_FREEZE then e:SetState(VJ_STATE_FREEZE) end
				for _, n in ipairs({"barnaclepull", "barnaclelift", "barnaclehit"}) do
					local sq = e:LookupSequence(n)
					if sq and sq > 0 then
						e.MercerHeldSeq, e.MercerHeldT0 = sq, CurTime()
						e:ResetSequence(sq)
						break
					end
				end
			end
			if e:IsPlayer() then
				-- (players) frozen in his hand: no moving, shooting or using; the weapon hidden; the client shows him
				-- from outside (NW2 MercerHeld: alex_mercer_victim.lua)
				e:Freeze(true)
				e:SetMoveType(MOVETYPE_NONE)
				local w = e:GetActiveWeapon()
				if IsValid(w) then
					w:SetNoDraw(true)
					e.MercerHeldWep = w
				end
				e:SetNW2Bool("MercerHeld", true)
			end
			if e.loco then e.loco:SetVelocity(Vector(0, 0, 0)) end
			-- (a DrGBase nextbot - the NPC pack's soldiers: its AI off while in his hand, back on when let go)
			if e.IsDrGNextbot and e.DisableAI and not e:IsAIDisabled() then
				e:DisableAI()
				e.MercerAIOff = true
			end
			e:SetNotSolid(true)
			return Vector(0, 0, math.Clamp(h, 40, 75))
		end

		local function freeVictim(e)
			if not IsValid(e) or not e.MercerHeldBy then return end
			e.MercerHeldBy = nil
			e.MercerHeldSeq = nil
			e:SetNotSolid(false)
			if e.MercerAIOff and e.EnableAI then
				e.MercerAIOff = nil
				e:EnableAI()
			end
			if e:IsNPC() then
				e:SetMoveType(MOVETYPE_STEP)
				e:SetNPCState(NPC_STATE_ALERT)
				-- (players 2026-10-28: "bad argument #1 to 'SetCondition' (number expected, got nil)" on a whipfist grab +
				-- a power switch, then soft locked) the enum is missing in some GMod builds: the error cut the release
				-- short, the holder's state never cleared
				if COND_NPC_UNFREEZE then e:SetCondition(COND_NPC_UNFREEZE) end
				if e.IsVJBaseSNPC and e.SetState and VJ_STATE_NONE then e:SetState(VJ_STATE_NONE) end
			end
			if e:IsPlayer() then
				e:Freeze(false)
				e:SetMoveType(MOVETYPE_WALK)
				if IsValid(e.MercerHeldWep) then e.MercerHeldWep:SetNoDraw(false) end
				e.MercerHeldWep = nil
				e:SetNW2Bool("MercerHeld", false)
			end
		end
		-- (players can't be removed) where an NPC victim is removed - consumed, or turned into a body copy (throw, slam,
		-- grind) - a player is let go and dies silently: no corpse of his own (the copy / the consume is his body)
		local function removeVictim(e)
			if not IsValid(e) then return end
			if e:IsPlayer() then
				e.MercerHeldBy = true -- (freeVictim needs the mark)
				freeVictim(e)
				e.MercerGone = true -- (until he respawns: the hook below)
				if e:Alive() then e:KillSilent() end
				return
			end
			e:Remove()
		end
		ALEX_MERCER_REMOVE_VICTIM = removeVictim
		hook.Add("PlayerSpawn", "AlexMercerVictimReset", function(ply)
			ply.MercerGone, ply.MercerHeldBy, ply.MercerHeldWep = nil, nil, nil
			ply:SetNW2Bool("MercerHeld", false)
			-- (players 2026-10-28: "a consumed player respawns invisible") drawn again, with his shadow
			ply:SetNoDraw(false)
			ply:DrawShadow(true)
		end)
		-- a held player who dies some other way (shot by others, the server): let go
		hook.Add("PostPlayerDeath", "AlexMercerVictimDeath", function(ply)
			if ply.MercerHeldBy and not ply.MercerGone then
				ply.MercerHeldBy = true
				freeVictim(ply)
			end
		end)
		ENT.MercerFreeVictim = function(self, e) freeVictim(e) end
		local victimOk
		ENT.MercerGrabbable = function(self, e) return grabbable(self, e) end

		-- its neck at this point, facing him (back: its back to him - the stealth consumes take it from behind; the
		-- client poses it by the _rcv anyway, this is the entity's own way round)
		local function placeVictim(self, e, neck, at, back)
			local pos = at - neck
			-- lifted by the neck, never pushed into the floor under him
			if pos.z < self:GetPos().z then pos.z = self:GetPos().z end
			e:SetPos(pos)
			local sq = e.MercerHeldSeq
			if sq then
				-- (a frozen NPC doesn't advance its own cycle)
				if e:GetSequence() ~= sq then e:ResetSequence(sq) end
				e:SetPlaybackRate(0)
				e:SetCycle(((CurTime() - (e.MercerHeldT0 or 0)) / math.max(e:SequenceDuration(sq), 0.3)) % 1)
			end
			e:SetAngles(Angle(0, self:GetAngles().y + (back and 0 or 180), 0))
			if e.loco then e.loco:SetVelocity(Vector(0, 0, 0)) end
		end

		function victimOk(e)
			return IsValid(e) and not (e.Health and e:Health() <= 0) and not (e:IsPlayer() and not e:Alive())
		end

		-- the whip grab: the human the spike met hangs on the spike
	function ENT:MercerCatch(st, e)
		if self:MercerObjOk(e) then return self:MercerCatchObj(st, e) end
		if not grabbable(self, e) or e.MercerHeldBy then return false end
		local ok, neck = pcall(holdVictim, e)
		if not ok or not neck then
			if not ok then ErrorNoHalt("[alex_mercer] whip grab: " .. tostring(neck) .. "\n") end
			freeVictim(e)
			return false
		end
		st.caught = {e = e, neck = neck}
		if self.MercerViolence then self:MercerViolence(e, 0) end -- (the whip's grab: as any grab - user 2026-10-28)
		local dm = e:GetPos():Distance(self:GetPos()) / M2U
		st.catchPose = dm <= 15 and "onehand" or dm <= 25 and "short" or nil
		if st.catchPose then GP.Start(self, "mercer/whipcatch/" .. st.catchPose, {block = true, hold = true}) end
		self:CallOnRemove("MercerFreeVictim", function(ent) freeVictim(e) end)
		self:MercerCue("alex_grab")
		return true
	end

	-- the body rides the spike: held where it stopped (pull), then reeled in at the grab's 30 m/s (trans); at his
	-- hand it is his to hold
	function ENT:MercerWhipCaughtThink(st)
		local c, sh = st.caught, st.shot
		local e = c.e
		if c.obj then return self:MercerCaughtObjThink(st, c) end
		if not victimOk(e) then
			freeVictim(e)
			st.caught = nil
			return false
		end
		if not sh or not sh.stopT then return false end
		local tip = sh.tip
		if st.phase == "trans" then
			local L0 = sh.tip:Distance(sh.base)
			local L = L0 - (st.atk.reel or 30) * M2U * (CurTime() - st.t0)
			if L <= 30 then
				st.caught = nil
				self:MercerFightEnd()
				self.MercerGrab = {phase = "hold", t0 = CurTime(), target = e, neck = c.neck}
				self:SetNW2Bool("MercerHolding", true)
				self:SetNW2Entity("MercerVictim", e)
				self:MercerCue("bodyfall_generic", 0.6)
				GP.Stop(self)
				self:UpdateAnimation()
				return true
			end
			tip = LerpVector(1 - L / math.max(L0, 1), sh.tip, self:MercerWhipBase())
		end
		placeVictim(self, e, c.neck, tip)
		return false
	end

	-- the grip: his right wrist + the game's attachment offset (game axes (x, y, z) = bone-local (-z, x, y))
		function ENT:MercerGripPos()
			local b = self:LookupBone("Wrist_R")
			local m = b and self:GetBoneMatrix(b)
			if not m then return self:LocalToWorld(Vector(28, -6, 58)) end
			return m:GetTranslation() + m:GetForward() * (-0.048 * M2U) - m:GetRight() * (-0.146 * M2U)
				+ m:GetUp() * (-0.009 * M2U)
		end

		function ENT:MercerGrabStart(target)
			self:MercerCombatEvent()
			self:SetAngles(Angle(0, (target:GetPos() - self:GetPos()):Angle().y, 0))
			self.MercerGrab = {t0 = CurTime(), phase = "reach", target = target}
			GP.Start(self, "mercer/grab_reach", {block = true, hold = true})
			self:MercerCue("alex_grab")
		end

