		-- tools/add_drop_anims.py) his heller_human_release_gvr from frame 12 (user: from its start the hand went up
		-- over his head - Heller holds them higher - "as if by the leg"): the hand forward at his chest goes down to his
		-- side; let go at frame 15. (user: no lying get-up - "he just lets go and they walk off at once")
		MERCER_DROP_ANIM, MERCER_DROP_LET, MERCER_DROP_END = "heller_human_release_gvr", 3 / 30, 28 / 30
		ALEX_MERCER_GRAPH["mercer/grab_drop"] = {seg(0, MERCER_DROP_END, MERCER_DROP_ANIM, 12, 40)}
		-- let go: on its feet on the floor in front of him, facing him, free at once (an NPC back to its own AI, moving
		-- off; a player to his controls); the client blends its bones from his hand to its own pose (NW2 MercerLetGoT)
		function ENT:MercerVictimGetup(g)
			local e = g.target
			self.MercerGrab = g -- (the drop phase finishes his anim)
			g.target = nil
			self:SetNW2Bool("MercerHolding", false)
			self:SetNW2Entity("MercerVictim", NULL)
			self:RemoveCallOnRemove("MercerFreeVictim")
			if not IsValid(e) then return end
			if not victimOk(e) then return freeVictim(e) end
			local at = self:GetPos() + self:GetForward() * 44
			local tr = util.TraceHull({start = at + Vector(0, 0, 40), endpos = at - Vector(0, 0, 80),
				mins = Vector(-14, -14, 0), maxs = Vector(14, 14, 8), filter = {self, e}, mask = MASK_SOLID})
			e:SetPos(tr.Hit and not tr.StartSolid and tr.HitPos or self:GetPos() + self:GetForward() * 44)
			e:SetAngles(Angle(0, self:GetAngles().y + 180, 0))
			freeVictim(e)
			e:SetNW2Float("MercerLetGoT", CurTime())
			if e:IsNPC() then
				-- off away from him (the game's released human backs off): from its enemy if it has one
				e:SetSchedule(IsValid(e:GetEnemy()) and SCHED_RUN_FROM_ENEMY or SCHED_MOVE_AWAY)
			end
		end
