		-- a catch ends what was flying him
		function ENT:MercerAirGrabFlightEnd()
			if self.MercerAirDash then
				self.MercerAirDash = nil
				self.loco:SetGravity(1000)
				local v = self.loco:GetVelocity()
				self.MercerAirBase = Vector(v.x, v.y, 0)
			end
			if self.MercerFKick then self:MercerFKickEnd() end
		end
		-- E down, or BY EYE a tap's 0.3 s: the graph reads Action down only, and a tap was gone inside the pose's own 0.1 s blend, nothing to see (user 2026-11-05: "В воздухе нажимая на Е ничего не происходит")
		function ENT:MercerAirGrabDown(p)
			return p:KeyDown(IN_USE) or (self.MercerUsePressAir == true and CurTime() - (self.MercerUsePressT or -9) < 0.3)
		end
		-- returns true while the reach owns the pose
		function ENT:MercerAirGrabThink(st, noPose)
			local p = self:GetPossessor()
			local kick = self.MercerFKick
			local lunge = kick and kick.phase == "lunge"
			if not IsValid(p) or not (lunge or self:MercerAirGrabDown(p)) or self.MercerBallQueued then return false end
			-- (alex_mercer_debug 1, what the next try says: every 0.5 s while E is down)
			local say = CurTime() - (self.MercerAirGrabDbgT or 0) > 0.5
			if say then self.MercerAirGrabDbgT = CurTime() end
			if not self.MercerAirGrabOn:GetBool() then
				if say then dbg("air_grab: E down, off (alex_mercer_air_grab 0)") end
				return false
			end
			if self.MercerGrab or self.MercerObj or self.MercerGun or self.MercerFight or self.MercerBullet then
				if say then dbg("air_grab: E down, not now: body %s, object %s, gun %s, strike %s, bullet dive %s", tostring(self.MercerGrab ~= nil), tostring(self.MercerObj ~= nil), tostring(self.MercerGun ~= nil),
					tostring(self.MercerFight ~= nil), tostring(self.MercerBullet ~= nil)) end
				return false
			end
			-- the dash's and the kick's own (their pose is theirs, their give the human's node and the object's)
			local fly = self.MercerAirDash or kick
			local r = (lunge and 0.5 or (self.MercerAirDash or (kick and kick.phase == "release")) and 1.4 or 1.2) * M2U
			if say then dbg("air_grab: E down, node %s, %s, %.1f m", st and st.path or "-", fly and "its own pose" or noPose and "the upper body" or "the whole body", r / M2U) end
			-- (the client's bone overlay, alex_mercer_animscale.lua; let go by CustomThink when this stops coming)
			if noPose and not fly then
				self.MercerAirReachT = CurTime()
				self:SetNW2Bool("MercerAirReach", true)
			end
			if not noPose and not (st and st.path == "mercer/air_grab") then GP.Start(self, "mercer/air_grab", {air = true}) end
			-- (in the kick's flight, along the flight, BY EYE: the graph's offset is along him, his reach 2.1 m out and the hit's 1 m, so the reach comes first. Along his yaw, a down kick's strike, a
			-- sphere of 1 m at 1 m down the flight in this file, got to a man first and the kick stopped on him. This sphere holds that one. What he can't take is still struck)
			local c = self:GetPos() + (kick and (kick.phase == "release" or lunge) and kick.dir or self:GetForward()) * (0.7 * M2U) + Vector(0, 0, M2U)
			local near = ents.FindInSphere(c, r + 24)
			-- (MercerBallPress) a press of E in the air may be half of the cannonball: for its first 0.12 s the pose only
			local since = CurTime() - (self.MercerUsePressT or -9)
			local chordWait = self.MercerUsePressAir and since < self.MercerBallAfterE
			if chordWait and not fly then near = {} end
			for _, e in ipairs(near) do
				if grabbable(self, e) and not e.MercerHeldBy and e:NearestPoint(c):Distance(c) <= r then
					local g = {t0 = CurTime(), phase = "hold", target = e, rmbWas = p:KeyDown(IN_ATTACK2), lmbWas = p:KeyDown(IN_ATTACK), jmpWas = p:KeyDown(IN_JUMP)}
					if self:MercerGrabAttach(g) then
						dbg("air_grab: caught %s, %s", e:GetClass(), fly and "node {human}" or "the fall goes on")
						self.MercerGrab, self.MercerGrabUseWas = g, true
						self:MercerCombatEvent()
						self:MercerCue("alex_grab")
						self:MercerAirGrabFlightEnd()
						GP.Stop(self)
						if fly then
							-- (the flight's speed gone at once: the landing is graded from here)
							g.take = {t0 = CurTime(), v = self:GetForward() * (6 * M2U)}
							self.MercerAirBase = Vector(g.take.v.x, g.take.v.y, 0)
							self.MercerFallSpeed = 0
							self.loco:SetVelocity(g.take.v)
							GP.Start(self, "mercer/air_grab/take", {air = true})
						else
							self:UpdateAnimation()
						end
						return true
					end
				end
			end
			if fly and not lunge then
				for _, e in ipairs(near) do
					if self:MercerObjOk(e) and e:NearestPoint(c):Distance(c) <= r then
						dbg("air_grab: caught the object %s", e:GetClass())
						self:MercerAirGrabFlightEnd()
						GP.Stop(self)
						self:MercerObjPick(e)
						return true
					end
				end
			end
			-- the lock: MercerAirLunge. Once a press, a press in the air: one on the ground held into a jump is none; the kick has its own aim
			if not kick and self.MercerUsePressAir and not chordWait and since < self.MercerBallAfterE + 0.1 and self.MercerAirLungeT ~= self.MercerUsePressT then
				self.MercerAirLungeT = self.MercerUsePressT
				local lk = self:MercerLocked()
				if lk then
					local d = lk:WorldSpaceCenter():Distance(self:WorldSpaceCenter())
					local ok = grabbable(self, lk)
					dbg("air_grab: E pressed, locked %s, %.1f m, grabbable %s", lk:GetClass(), d / M2U, tostring(ok))
					if ok and d <= 50 * M2U then
						self:MercerAirGrabFlightEnd()
						self:MercerAirLunge(lk)
					end
				end
			end
			if say and DebugAnim:GetBool() then
				for _, e in ipairs(ents.FindInSphere(c, 5 * M2U)) do
					if e ~= self and (e:IsNPC() or e:IsNextBot() or e:IsPlayer()) then
						dbg("air_grab: near %s, %.0f u from the reach's centre (it takes %.0f), grabbable %s", e:GetClass(), e:NearestPoint(c):Distance(c), r, tostring(grabbable(self, e)))
					end
				end
			end
			return true
		end

		function ENT:MercerRunGrabThink(g, p, dt)
			local node = self.MercerNode
			if not node or node.path ~= "mercer/run_grab" then
				self.MercerGrab = nil
				return false
			end
			local t = CurTime() - g.t0
			local pos, fwd = self:GetPos(), self:GetForward()
			-- his own sprint speed on, along where he faces (the anim's root is not used)
			local sp = g.speed or 0
			local vz = self.loco:GetVelocity().z
			self.loco:SetDesiredSpeed(math.max(sp, 1))
			self.loco:SetVelocity(Vector(fwd.x * sp, fwd.y * sp, vz))
			-- (user 2026-10-22: still stopped him) a nextbot on the ground only keeps moving while it approaches a
			-- goal each tick - the velocity alone was eaten by its ground friction (as the sprint dash does)
			if self:IsOnGround() and sp > 1 then self:Approach(pos + fwd * 100) end
			if t < 0.4 then
				if not (g.aim and victimOk(g.aim)) then
					local best, bd
					for _, e in ipairs(ents.FindInSphere(pos, 9 * M2U)) do
						if grabbable(self, e) and not e.MercerHeldBy then
							local to = e:GetPos() - pos
							to.z = 0
							local d = to:Length()
							if d > 1 and to:GetNormalized():Dot(fwd) > math.cos(math.rad(22.5)) and (not bd or d < bd) then
								best, bd = e, d
							end
						end
					end
					g.aim = best
				end
				if g.aim then
					local want = (g.aim:GetPos() - pos):Angle().y
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, want, 720 * dt), 0))
				end
			end
			if t >= 0.05 and t <= 0.5333 then
				local c = pos + fwd * (RUN_GRAB_AHEAD * M2U) + Vector(0, 0, 40)
				local r = RUN_GRAB_R * M2U
				for _, e in ipairs(ents.FindInSphere(c, r + 24)) do
					if grabbable(self, e) and not e.MercerHeldBy and e:NearestPoint(c):Distance(c) <= r then
						g.target = e
						if self:MercerGrabAttach(g) then
							g.phase, g.t0 = "hold", CurTime()
							self:MercerCue("alex_grab")
							GP.Stop(self)
							self:UpdateAnimation()
							return false
						end
						g.target = nil
					end
				end
			end
			-- (alex_mercer_climb_catch) graph_sprint 672: from 0.2 s the running grab executes grab/climb_test (graph_prototype 1939: limb {Climb},
			-- 0.3 m, an arc of 60 deg) -> {attach}. Past a body in reach, as above. No slide on this way in, it takes hold where he stands
			if t >= 0.2 and self.MercerCatchOn:GetBool() and self:IsOnGround() and CurTime() > (self.MercerWallCooldown or 0) then
				local tr = self:MercerWallTrace(34)
				if tr.Hit and math.abs(tr.HitNormal.z) < 0.3 and tr.HitNormal:Dot(fwd) < -0.5 then
					dbg("climb_catch: the running grab takes hold of the wall at %.2f s", t)
					self.MercerGrab = nil
					GP.Stop(self)
					self:MercerStartWall(tr)
					self:MercerStartClimb()
					GP.Start(self, "mercer/climb_attach_run", {onDone = function(ent) ent:UpdateAnimation() end})
					return true
				end
			end
			if t >= 0.6333 then
				self.MercerGrab = nil
				GP.Stop(self)
				self:UpdateAnimation()
				return false
			end
			return true
		end

		function ENT:MercerGrabAttach(g)
			local e = g.target
			if not victimOk(e) or e.MercerHeldBy then return false end
			-- any failure puts it back the way it was (solid, moving)
			local ok, neck = pcall(holdVictim, e)
			if not ok or not neck then
				if not ok then ErrorNoHalt("[alex_mercer] grab: " .. tostring(neck) .. "\n") end
				freeVictim(e)
				return false
			end
			g.neck = neck
			-- (the graph's grab/give alex_pickup left out - user 2026-10-23: early and out of place)
			self:CallOnRemove("MercerFreeVictim", function(ent) freeVictim(e) end)
			self:SetNW2Bool("MercerHolding", true)
			-- the client plays the game's receiver anims on it (alex_mercer_victim.lua)
			self:SetNW2Entity("MercerVictim", e)
			-- (user 2026-10-28: "a grab is the same attack - red at once") seized in disguise in sight of its side (or the
			-- seized one is of it): the cover blown on the spot, like a strike
			if self.MercerViolence then self:MercerViolence(e, 0) end
			if not (self:GetNW2Bool("MercerDisguised") and not self.MercerCoverBlown) and self.MercerProvoke then
				self:MercerProvoke(e)
			end
			return true
		end

		function ENT:MercerGrabFollow(g)
			local e = g.target
			if not victimOk(e) or not g.neck then return false end
			placeVictim(self, e, g.neck, self:MercerGripPos(), g.back)
			return true
		end

		-- let it go (thrown: killed with the throw's force - the engine's own death ragdoll flies)
		function ENT:MercerGrabRelease(vel)
			local g = self.MercerGrab
			self.MercerGrab = nil
			self:SetNW2Bool("MercerHolding", false)
			self:SetNW2Entity("MercerVictim", NULL)
			self:RemoveCallOnRemove("MercerFreeVictim")
			local e = g and g.target
			if not IsValid(e) then return end
			freeVictim(e)
			if vel and victimOk(e) then
				local di = DamageInfo()
				di:SetDamage(math.max(e:Health(), 1) + 500)
				di:SetDamageType(DMG_CRUSH)
				di:SetAttacker(self)
				di:SetInflictor(self)
				di:SetDamagePosition(e:WorldSpaceCenter())
				di:SetDamageForce(vel * 40)
				e:TakeDamageInfo(di)
			end
		end

		-- the held one killed into a body that flies off (the slam's / powerbomb's Bounce): the throw's way - a ragdoll
		-- copy of it, the NPC itself removed (damage to the freed NPC left it alive and broken - user); vel in u/s
		function ENT:MercerKillHeld(vel, spin)
			local g = self.MercerGrab
			local e = g and g.target
			local rag
			if IsValid(e) and victimOk(e) and self.MercerBodyCopy then
				local ok, r = pcall(self.MercerBodyCopy, self, e)
				if ok and IsValid(r) then rag = r elseif not ok then ErrorNoHalt("[alex_mercer] slam: " .. tostring(r) .. "\n") end
			end
			if not rag then return self:MercerGrabRelease(vel) end
			self.MercerGrab = nil
			self:SetNW2Bool("MercerHolding", false)
			self:SetNW2Entity("MercerVictim", NULL)
			self:RemoveCallOnRemove("MercerFreeVictim")
			e.MercerGone, e.MercerHeldBy = true, nil
			ALEX_MERCER_REMOVE_VICTIM(e)
			for i = 0, rag:GetPhysicsObjectCount() - 1 do
				local ph = rag:GetPhysicsObjectNum(i)
				if IsValid(ph) then
					ph:SetVelocity(vel)
					ph:AddAngleVelocity(VectorRand() * (spin or 200))
				end
			end
			timer.Simple(0.25, function() if IsValid(rag) then rag:SetCollisionGroup(COLLISION_GROUP_NONE) end end)
			return rag
		end

		-- (user 2026-10-29: "a thrown human must deal damage") the graph's throw item damageMin / Max on whoever the
		-- body hits, once each, for 4 s of flight (as the thrown objects): the bare human throw 15-45 -> 30-60 by the
		-- charge (midpoints 30 -> 45), the muscle form's 50-80 (65)
		function ENT:MercerThrownBody(rag, dmg)
			if not IsValid(rag) then return end
			rag.MercerThrown = {by = self, t = CurTime() + 4, dmg = dmg, hit = {}}
			if rag.MercerThrowCb then return end
			rag.MercerThrowCb = rag:AddCallback("PhysicsCollide", function(ent, data)
				local th = ent.MercerThrown
				local hit = data.HitEntity
				if not th or CurTime() > th.t or not IsValid(hit) or th.hit[hit] or hit == th.by then return end
				if not (hit:IsNPC() or hit:IsNextBot() or hit:IsPlayer()) then return end
				th.hit[hit] = true
				local di = DamageInfo()
				di:SetDamage(th.dmg)
				di:SetDamageType(DMG_CRUSH)
				di:SetAttacker(IsValid(th.by) and th.by or ent)
				di:SetInflictor(ent)
				di:SetDamagePosition(data.HitPos)
				-- (user 2026-10-29: "they fly off with insane force") the force capped: a body at 2000 u/s x 50 flung the hit
				-- one across the map
				local f = data.OurOldVelocity * 10
				if f:Length() > 12000 then f = f:GetNormalized() * 12000 end
				di:SetDamageForce(f)
				hit:TakeDamageInfo(di)
			end)
		end
		-- the muscle form's throw multiplier (alex_mercer_muscle_throw), 1 in any other form
		function ENT:MercerMuscleK()
			if self:GetMercerForm().name ~= "Мускулы" then return 1 end
			local cv = GetConVar("alex_mercer_muscle_throw")
			return cv and cv:GetFloat() or 1
		end
		function ENT:MercerThrowDamage(charge)
			if self:GetMercerForm().name == "Мускулы" then return 65 * self:MercerMuscleK() end
			return Lerp(charge or 0, 30, 45)
		end

		-- input while holding (the game's PC keys, user): "a" (LMB) = the throw, "e" (E) = the slam, "s" = consume
		function ENT:MercerGrabInput(kind)
			if self.MercerBullet then return false end -- (user 2026-10-28: nothing cuts the Bullet Dive)
			local g = self.MercerGrab
			-- (a Hunter of the pack in his hands: its own moves)
			if g and g.hunter then return self:MercerHunterGrabInput(kind) end
			if not g or g.phase ~= "hold" then return end
			-- (user: RMB in the air consumed the body) airborne the grab think has the air's own moves: slam / powerbomb
			if not self:IsOnGround() then return end
			self:MercerCombatEvent()
			if kind == "a" then kind = "e" elseif kind == "e" then kind = "a" end
			if kind == "a" then
				g.phase, g.t1 = "slam", CurTime()
				self:MercerVO("alex_punchkickbig", 0.77)
				GP.Start(self, "mercer/grab_slam", {block = true, hold = true})
				self:MercerCue("whoosh_small")
			elseif kind == "e" then
				g.phase, g.t1 = "throw", CurTime()
				self:MercerVO("alex_throw", 1)
				local p = self:GetPossessor()
				if IsValid(p) then self:SetAngles(Angle(0, self:MercerAimVector(p):Angle().y, 0)) end
				if self.MercerThrowRunOn:GetBool() and self:GetMercerSprint() > 0 and self:IsOnGround() then
					local hv = self.loco:GetVelocity()
					hv.z = 0
					local R = self.MercerRunThrow
					g.run = {v = math.Clamp(hv:Length() / M2U, R.vmin, R.vmax), dir = hv:LengthSqr() > 1 and hv:GetNormalized() or self:GetForward()}
					dbg("throw_run: slide from %.1f m/s, he was at %.1f", g.run.v, hv:Length() / M2U)
					GP.Start(self, "mercer/grab_throw_run", {block = true, hold = true})
				else
					GP.Start(self, "mercer/grab_throw", {block = true, hold = true})
				end
				self:MercerCue("alex_sprint")
			elseif kind == "s" then
				local set = CONSUMES[POWER_CONSUME[self:GetMercerForm().name] or "bare"]
				local c = set[math.random(#set)]
				g.phase, g.t1, g.fin, g.done = "consume", CurTime(), c, {}
				-- the client plays the receiver's effects / the body flowing into him by the node's own times
				self:SetNW2String("MercerConsumeName", c.name)
				self:SetNW2Float("MercerConsumeT", CurTime())
				g.set = POWER_CONSUME[self:GetMercerForm().name] or "bare"
				GP.Start(self, "mercer/consume_" .. g.set .. "_" .. c.name, {block = true, hold = true})
				-- (the blow's stop: graph_consume's slowMotion items)
				if c.slow and self.MercerSlowGraph:GetBool() then
					for _, x in ipairs(c.slow) do
						self:Timer(x[1], function(ent) ent:MercerSlowMotion(x[2], x[3], x[4], x[5]) end)
					end
				end
				-- (players 2026-10-28: "consumed NPCs' weapons stay floating in mid-air; hide their corpses' shadows") the
				-- weapon goes with the body, the body casts no shadow while it flows into him
				local ce = g.target
				if IsValid(ce) then
					g.gunKind = self:MercerGunKindOf(ce) -- (into his hand as the consume ends: MercerConsumedGun)
					if ce:IsNPC() and IsValid(ce:GetActiveWeapon()) then ce:GetActiveWeapon():Remove() end
					ce:DrawShadow(false)
					-- (the NPC pack: the receiver's npc_scream as the finisher starts - its own voice)
					if ce.ProtoCryOn then pcall(ce.ProtoCryOn, ce, ce, "npc_scream") end
				end
				-- (user 2026-10-29: "the second whip consume - tossed, impaled, consumed - the whip arm hangs in the air") the
				-- whip on the anim's joints only over the graph's own window (come_here 0.8-1.4 s: the impale; lash from
				-- 0.1 s); outside it reeled in - the plain arm. It was on from the start: the come_here anim keys its
				-- Whip_Link joints only for the impale, so before and after it the whip stood in the air in their rest
				if c.whip then
					local t1 = g.t1
					local function still(ent)
						local gg = ent.MercerGrab
						return gg ~= nil and gg.phase == "consume" and gg.fin == c and gg.t1 == t1
					end
					self:MercerWhipMode(0, 30)
					self:Timer(c.whipOn or 0, function(ent) if still(ent) then ent:MercerWhipMode(1) end end)
					if c.whipOff then
						self:Timer(c.whipOff, function(ent) if still(ent) then ent:MercerWhipMode(0, 30) end end)
					end
				end
				for _, x in ipairs(c.sfx) do
					if x[1] <= 0 then self:MercerCue(x[2]) else self:Timer(x[1], function(ent) ent:MercerCue(x[2]) end) end
				end
				for _, x in ipairs(c.shakes or {}) do self:MercerShake(x[2], x[3], x[1]) end
			end
		end

		-- the consumed body: its blood, the dissolve (fades out), the gibs, its end
		local function bodyCenter(e)
			return IsValid(e) and e:WorldSpaceCenter() or nil
		end

		-- the consumed one's side (DrGBase factions): a DrGBase nextbot's own, else by class / Classify()
		local SIDE_CLASS = {npc_citizen = FACTION_REBELS, npc_alyx = FACTION_REBELS, npc_barney = FACTION_REBELS,
			npc_monk = FACTION_REBELS, npc_vortigaunt = FACTION_REBELS, npc_eli = FACTION_REBELS, npc_kleiner = FACTION_REBELS,
			npc_mossman = FACTION_REBELS, npc_magnusson = FACTION_REBELS, npc_odessa = FACTION_REBELS, npc_dog = FACTION_REBELS,
			npc_fisherman = FACTION_REBELS, npc_combine_s = FACTION_COMBINE, npc_metropolice = FACTION_COMBINE,
			npc_breen = FACTION_COMBINE, npc_stalker = FACTION_COMBINE, npc_hunter = FACTION_COMBINE,
			npc_zombie = FACTION_ZOMBIES, npc_fastzombie = FACTION_ZOMBIES, npc_poisonzombie = FACTION_ZOMBIES,
			npc_zombine = FACTION_ZOMBIES, npc_zombie_torso = FACTION_ZOMBIES, npc_fastzombie_torso = FACTION_ZOMBIES,
			npc_antlion = FACTION_ANTLIONS, npc_antlion_worker = FACTION_ANTLIONS, npc_antlionguard = FACTION_ANTLIONS}
		local SIDE_CLASSIFY = {}
		local function side(list, f)
			for _, k in ipairs(list) do if k then SIDE_CLASSIFY[k] = f end end
		end
		side({CLASS_PLAYER_ALLY, CLASS_PLAYER_ALLY_VITAL, CLASS_CITIZEN_REBEL, CLASS_CITIZEN_PASSIVE, CLASS_VORTIGAUNT},
			FACTION_REBELS)
		side({CLASS_COMBINE, CLASS_METROPOLICE, CLASS_MANHACK, CLASS_SCANNER, CLASS_COMBINE_GUNSHIP, CLASS_COMBINE_HUNTER,
			CLASS_STALKER, CLASS_PROTOSNIPER}, FACTION_COMBINE)
		side({CLASS_ZOMBIE, CLASS_HEADCRAB}, FACTION_ZOMBIES)
		side({CLASS_ANTLION}, FACTION_ANTLIONS)
		local function disguiseFactions(e)
			local out = {}
			if e.IsDrGNextbot and e.GetFactions then
				for _, f in ipairs(e:GetFactions() or {}) do out[#out + 1] = f end
			end
			local f = SIDE_CLASS[e:GetClass()] or (e:IsNPC() and e.Classify and SIDE_CLASSIFY[e:Classify()])
			if f then out[#out + 1] = f end
			if istable(e.VJ_NPC_Class) then
				for _, v in ipairs(e.VJ_NPC_Class) do if isstring(v) then out[#out + 1] = v end end
			end
			return out
		end
		-- in disguise he is in the consumed one's factions (DrGBase sets every NPC's / nextbot's feeling for him by them)
		-- (players 2026-10-27: "the disguise doesn't work on VJ Base SNPCs") VJ's NPCs pick enemies by their own
		-- VJ_NPC_Class, not DrGBase's factions (DrGBase leaves them alone): in disguise he carries the consumed one's VJ
		-- classes, or its side's class; the VJ NPCs on him drop him as their enemy
		-- (DrGBase's FACTION_* hold strings such as "FACTION_HL2_REBELS": keyed by their values)
		local VJ_OF = {}
		for f, c in pairs({[FACTION_REBELS or ""] = "CLASS_PLAYER_ALLY", [FACTION_COMBINE or ""] = "CLASS_COMBINE",
			[FACTION_ZOMBIES or ""] = "CLASS_ZOMBIE", [FACTION_ANTLIONS or ""] = "CLASS_ANTLION"}) do
			if f ~= "" then VJ_OF[string.upper(f)] = c end
		end
		function ENT:MercerDisguiseSide(on)
			local vj = {}
			for _, f in ipairs(self.MercerDisguiseFactions or {}) do
				if on then self:JoinFaction(f)
				elseif string.upper(f) ~= "FACTION_BLACKLIGHT" then self:LeaveFaction(f) end
				local u = string.upper(f)
				vj[#vj + 1] = string.sub(u, 1, 6) == "CLASS_" and u or VJ_OF[u]
			end
			self.VJ_NPC_Class = on and #vj > 0 and vj or nil
			if not on or #vj == 0 then return end
			for _, v in ipairs(ents.GetAll()) do
				if v.IsVJBaseSNPC and IsValid(v) and v.GetEnemy and v:GetEnemy() == self then
					local mate = false
					for _, c in ipairs(v.VJ_NPC_Class or {}) do
						for _, c2 in ipairs(vj) do if string.upper(c) == c2 then mate = true end end
					end
					if mate then
						v:AddEntityRelationship(self, D_LI, 99)
						if v.ResetEnemy then v:ResetEnemy(false) else v:SetEnemy(NULL) end
					end
				end
			end
		end

		-- (players / user 2026-10-28: "disguised, you attack the victim's team and they never attack back") the game's
		-- cover: violence in the disguise seen by its side blows it - he leaves the side and its people in reach hunt him
		-- (the hunters); the disguise put on again (F, a new look) hides him only while none of them sees him (behind a
		-- wall); the hunt ends when they are all dead or far. NW2 MercerAware for the awareness lens (0 safe, 1 hunted
		-- unseen - amber, 2 seen - red), NW2 MercerDisgSwapT its shutter on a change of look
		local HUNT_R = 3000
		local function sideSet(self)
			local set = {}
			for _, f in ipairs(self.MercerDisguiseFactions or {}) do set[string.upper(f)] = true end
			return set
		end
		local function inSide(set, e)
			for _, f in ipairs(disguiseFactions(e)) do if set[string.upper(f)] then return true end end
			return false
		end
		local function sees(e, me)
			local eye = e.EyePos and e:EyePos() or e:WorldSpaceCenter()
			for _, z in ipairs({me:WorldSpaceCenter(), me:EyePos()}) do
				local tr = util.TraceLine({start = eye, endpos = z, filter = {e, me}, mask = MASK_BLOCKLOS})
				if not tr.Hit then return true end
			end
			return false
		end
		local function alive(e) return IsValid(e) and (e.Health == nil or e:Health() > 0) end
		-- (user 2026-10-30, by the main session: "seen" by the game's numbers) a soldier's own sight of him, the engine's
		-- PerceptionBehaviour test (prototypeenginef.dll 0x103f4340, its cone 0x103f1340): the sight config of its state -
		-- idleSight, combatSight while it fights (the engine: its combat / alert reactions; here: it has an enemy) - sees
		-- him within its radius (3D) or, idle, inside its cone: in front, within sightDistance flat and sightHeight up /
		-- down, half-width nearConeWidth at its feet growing to farConeWidth where the slant reaches sightDistance (forward
		-- sqrt(sightDistance^2 - farConeWidth^2)); then the line of sight (checkLoS) from 0.7 m over its feet to 0.7 m over
		-- his (sourceLoSOffset / destLoSOffset). Per class, the template named in its pack file's head: {idle radius, combat
		-- radius, the idle cone, checkLoS} (Soldier_tod.p3d, SuperSoldier_tod.p3d, specialist_tod.p3d); the cone is every
		-- soldier template's: nearConeWidth 8, farConeWidth 12, sightDistance 20, sightHeight 20 m
		ENT.MercerSight = {
			default = {1, 30, true, true}, -- (RifleLOD, the game's plain soldier: HL2 / VJ / other nextbots)
			drg_proto_bw_trooper = {1, 30, true, true}, -- BWRifleLOD
			drg_proto_marine = {1, 30, true, true}, -- RifleLOD
			drg_proto_bw_saw = {1, 30, true, true}, -- BWSawLOD
			drg_proto_bw_grenadier = {1, 40, true, true}, -- GrenadeLOD
			drg_proto_bw_rocket = {1, 50, true, true}, -- BWRocketLOD
			drg_proto_marine_rocket = {1, 50, true, true}, -- RocketLOD
			drg_proto_bw_officer = {1, 20, true, true}, -- BwOfficerNoGun
			drg_proto_commander = {1, 35, true, true}, -- Commander
			drg_proto_supersoldier = {20, 60, false, true}, -- SuperSoldier
			drg_proto_specialist = {100, 200, false, false}, -- Specialist (no checkLoS)
		}
		ENT.MercerSightCone = {near = 8, far = 12, dist = 20, height = 20}
		-- (alex_mercer_disguise_sight 0: the old way - any line of sight within HUNT_R, all round)
		function ENT:MercerSees(e)
			if not GetConVar("alex_mercer_disguise_sight"):GetBool() then return sees(e, self) end
			local s = self.MercerSight[e:GetClass()] or self.MercerSight.default
			local fights = e.GetEnemy and IsValid(e:GetEnemy())
			local p, q = e:GetPos(), self:GetPos()
			local d = (q - p) / M2U
			local r = fights and s[2] or s[1]
			local inside = d:LengthSqr() < r * r
			if not inside and s[3] and not fights then
				local c = self.MercerSightCone
				local fw = e:GetForward()
				local fx, fy = fw.x, fw.y
				local fl = math.sqrt(fx * fx + fy * fy)
				if math.abs(d.z) < c.height and fl > 1e-5 then
					fx, fy = fx / fl, fy / fl
					local f = d.x * fx + d.y * fy
					if f > 0 and d.x * d.x + d.y * d.y < c.dist * c.dist then
						local lat = math.abs(d.y * fx - d.x * fy)
						inside = f * (c.far - c.near) > math.sqrt(c.dist * c.dist - c.far * c.far) * (lat - c.near)
					end
				end
			end
			if not inside then return false end
			if not s[4] then return true end
			local up = Vector(0, 0, 0.7 * M2U)
			return not util.TraceLine({start = p + up, endpos = q + up, filter = {e, self}, mask = MASK_BLOCKLOS}).Hit
		end
		-- violence by him in disguise: blown when the victim lives on to tell, or one of the side sees it - or, by the
		-- game's perception (alex_mercer_disguise_sight), hears it: soundRadius attack / grabScream 15 m
		function ENT:MercerViolence(victim, dmg)
			if self.MercerCoverBlown or not self:GetNW2Bool("MercerDisguised") then return end
			local set = sideSet(self)
			local witness = inSide(set, victim) and dmg < victim:Health()
			local near = ents.FindInSphere(self:GetPos(), HUNT_R)
			local hear = GetConVar("alex_mercer_disguise_sight"):GetBool() and (15 * M2U) ^ 2 or -1
			if not witness then
				for _, e in ipairs(near) do
					if e ~= self and e ~= victim and (e:IsNPC() or e:IsNextBot()) and alive(e) and inSide(set, e)
						and (e:GetPos():DistToSqr(self:GetPos()) < hear or self:MercerSees(e)) then
						witness = true
						break
					end
				end
			end
			if not witness then return end
			self:MercerBlowCover(set, near)
		end
		-- blown: out of the side, its people in reach hunt him
		function ENT:MercerBlowCover(set, near)
			set = set or sideSet(self)
			near = near or ents.FindInSphere(self:GetPos(), HUNT_R)
			self.MercerCoverBlown = true
			self.MercerBlownSeenT = CurTime() -- (seen in it now: its 10 s start - MercerAwareThink)
			self.MercerSusp = 100
			self:SetNW2Bool("MercerBlown", true) -- (the perception HUD's ALERT)
			local hunters = {}
			for _, e in ipairs(near) do
				if e ~= self and (e:IsNPC() or e:IsNextBot()) and alive(e) and inSide(set, e) then hunters[e] = true end
			end
			self.MercerHunters = hunters
			self:MercerDisguiseSide(false)
			self:MercerHunt(true)
			self:SetNW2Int("MercerAware", 2)
			self:SetNW2Int("MercerAwarePct", 100) -- (the meter full and red this very moment, not at the next 0.25 s)
		end
		-- (user 2026-10-28: "the aggro on the disguise - as Mercer, as the NPCs feel about Mercer") the hunters go for the
		-- blown look: on while he wears it, off when he is Mercer again (then their usual feeling for him - DrGBase's,
		-- the friendly mode's - recomputed); wearing it again before them = on again
		function ENT:MercerHunt(on)
			for e in pairs(self.MercerHunters or {}) do
				if alive(e) then
					if on then
						if e:IsNPC() then
							e:AddEntityRelationship(self, D_HT, 99)
							if not IsValid(e:GetEnemy()) then
								e:SetEnemy(self)
								e:UpdateEnemyMemory(self, self:GetPos())
							end
						end
						if e.UpdateRelationshipWith then e:UpdateRelationshipWith(self) end -- (a DrGBase nextbot: by the sides)
					else
						if e:IsNPC() then
							if e:GetEnemy() == self then e:SetEnemy(NULL) end
							e:ClearEnemyMemory(self)
							if e.IsVJBaseSNPC and e.ResetEnemy then e:ResetEnemy(false) end
						end
						self:UpdateRelationshipWith(e) -- (his own feeling for it, mirrored onto an NPC by DrGBase)
						if e.UpdateRelationshipWith then e:UpdateRelationshipWith(self) end
					end
				end
			end
		end
		-- every NPC / nextbot that sees him now (HUNT_R)
		function ENT:MercerWitnesses()
			local out = {}
			for _, e in ipairs(ents.FindInSphere(self:GetPos(), HUNT_R)) do
				if e ~= self and (e:IsNPC() or e:IsNextBot()) and alive(e) and sees(e, self) then out[#out + 1] = e end
			end
			return out
		end
		-- the change seen: wearing (on) - the look blown, they hunt it; off - they fight Mercer himself
		function ENT:MercerSeenChange(witnesses, on)
			self.MercerHunters = self.MercerHunters or {}
			for _, e in ipairs(witnesses) do self.MercerHunters[e] = true end
			self.MercerCoverBlown, self.MercerSusp = true, 100
			self.MercerBlownSeenT = CurTime()
			self:SetNW2Bool("MercerBlown", true)
			self:SetNW2Int("MercerAware", 2)
			self:SetNW2Int("MercerAwarePct", 100)
			if on then
				self:MercerDisguiseSide(false)
				self:MercerHunt(true)
				return
			end
			self.MercerAggro = self.MercerAggro or {}
			for _, e in ipairs(witnesses) do
				self.MercerAggro[e] = true
				self:UpdateRelationshipWith(e)
				if e:IsNPC() then
					e:AddEntityRelationship(self, D_HT, 99)
					if not IsValid(e:GetEnemy()) then
						e:SetEnemy(self)
						e:UpdateEnemyMemory(self, self:GetPos())
					end
				elseif e.UpdateRelationshipWith then
					e:UpdateRelationshipWith(self)
				end
			end
		end
		function ENT:MercerHuntersSee()
			for e in pairs(self.MercerHunters or {}) do
				if alive(e) and e:GetPos():DistToSqr(self:GetPos()) < HUNT_R * HUNT_R and self:MercerSees(e) then return true end
			end
			return false
		end
		-- one of the disguise's side sees him now (HUNT_R; near: a FindInSphere already made there); another Mercer (MP: a
		-- player's, disguised in the same side) is no soldier of it
		function ENT:MercerWatched(set, near)
			set = set or sideSet(self)
			for _, e in ipairs(near or ents.FindInSphere(self:GetPos(), HUNT_R)) do
				if e ~= self and (e:IsNPC() or e:IsNextBot()) and e:GetClass() ~= "drg_alex_mercer" and alive(e) and inSide(set, e)
					and self:MercerSees(e) then return true end
			end
			return false
		end
		-- the disguise going on (again): hidden unless a hunter sees him now
		function ENT:MercerCoverTry()
			self:SetNW2Float("MercerDisgSwapT", CurTime())
			if not self.MercerCoverBlown then return true end
			if self:MercerHuntersSee() then
				self:MercerHunt(true) -- (the blown look on again before them)
				return false
			end
			self.MercerCoverBlown = nil
			self:MercerHunt(false)
			self.MercerHunters, self.MercerSusp = nil, 0
			self:SetNW2Bool("MercerBlown", false)
			self:SetNW2Int("MercerAware", 0)
			return true
		end
		-- (user 2026-10-28: the lens always on, as in the game - awarenessHUD's SetAwarenessWatched(IDLE / WATCHED /
		-- BLOWN) and SetAwarenessPercent(0-100), the game's suspicion) every 0.25 s:
		--  no disguise: BLOWN while an enemy of his sees him, else IDLE (the lens shut);
		--  disguised: WATCHED while one of its side sees him; seen doing what no soldier does (the sprint, the wall,
		--   the glide, a strike, a power or the armour out) the suspicion climbs (SUSP_UP / s), unseen it ebbs
		--   (SUSP_DOWN / s); full = the cover blown;
		--  blown: BLOWN while a hunter (or one of its side) sees him, WATCHED when none does (the moment to change looks);
		--   the hunt over once its hunters are dead / far, or after 10 s unseen in it
		-- (user 2026-10-28: "let the yellow bar ebb slowly") 8 % a second: full to empty in ~12 s
		local SUSP_UP, SUSP_DOWN, DT_AWARE = 40, 8, 0.25
		-- (user 2026-10-28: walking / a plain run = nothing odd; the sprint, a strike, an air strike... = odd) the power
		-- he has selected isn't odd by itself (the disguise covers it) - only using it is (a strike: MercerFight)
		local function suspicious(self)
			return self.MercerSprintOn or self:GetNW2Bool("MercerWall") or self:GetNW2Bool("MercerGlide")
				or self.MercerFight ~= nil or self.MercerElbow ~= nil or self.MercerStomp ~= nil or self.MercerFKick ~= nil
				or self.MercerAirDash ~= nil or self.MercerDive ~= nil or self:MercerArmour()
				or (not self:IsOnGround() and self:GetVelocity().z > 600)
		end
		-- a mutation out over the disguise (the game's disguise type "powered"): an attack power but the bare fists, or the
		-- shield (the armour takes the disguise off)
		function ENT:MercerPowerOut()
			local f = FORMS[self:GetNW2Int("MercerForm", 1)]
			return f ~= nil and f ~= FORMS[1] and f.kind ~= "disguise"
		end
		-- (2026-11-04, alex_mercer_disguise_rates, off by default) how fast the cover goes, as the game has it. alex_tod.p3d AlexDisguiseConfig (tools/disguise_config.py),
		-- prototypeenginef.dll 0x103ced50, 0x103ce020, 0x103ca160, 0x103ce4a0, the //disguise graph's thresholds. NOT startup_fig.p3d's factions.perSecond: no chunk of art.rcf or
		-- cells.rcf and nothing in the DLL reads those. The Faction variable: each who sees him gives a rate by (look, its type), the largest counts: a soldier look -5, a civilian
		-- one -2, a power out 1000, the Super Soldier (Faction "uav") +20 whatever the look; near his sight's edge it tends to 0.5 (a rise) or the full value (a fall), f below;
		-- x (1 + suspicionFactor), Super Soldier -0.2. None sees him: -10 / s. Above 20 with a power out: blown at once; else Recognition: 2 s more in sight, 1 s out of it lets him go.
		-- Each odd act has its own variable: {increase, decrease, the graph's threshold}: over it blown (Angry and BeginCombat both blow it), the rise x (1 - f).
		-- BY EYE: f for an idle soldier by the way to the cone's end (the engine goes along the cone); what a soldier only hears: f by the way to its soundRadius; which landing is
		-- which (the engine's message isn't read: under 5 m/s none, under 15 Landing, over Landing2); the meter = the nearest of the thresholds. Not here: FriendlyFire, CivilianFire,
		-- ShoveSoldier, Inside*, chameleon, decreaseDelay, the voices of Curious / Admiring. The glide, the air dash and the dive roll have no incident of their own
		do
			local GA = {Sprinting = {15, 5, 100}, Wallrunning = {100, 5, 100}, Climbing = {20, 5, 20}, Holding = {50, 5, 20}}
			local function smooth(x) return x <= 0 and 0 or x >= 1 and 1 or (3 - 2 * x) * x * x end
			function ENT:MercerDisgRatesThink(set, near, dt)
				local g = self.MercerGA
				if not g then
					g = {Faction = 0, Attack = 0, SmallJump = 0, Landing = 0, Sprinting = 0, Wallrunning = 0, Climbing = 0, Holding = 0, landT = self.MercerLandTime, jumps = self.MercerJumpN or 0}
					self.MercerGA = g
				end
				local powered, mil = self:MercerPowerOut(), self:GetNW2String("MercerDisguiseKind", "") == "MILITARY"
				local rate, f, fa, fj, fl, pos = nil, 1, 1, 1, 1, self:GetPos()
				for _, e in ipairs(near) do
					local cls = e ~= self and (e:IsNPC() or e:IsNextBot()) and e:GetClass()
					if cls and cls ~= "drg_alex_mercer" and alive(e) and (self.MercerSight[cls] or inSide(set, e)) then
						local d = e:GetPos():Distance(pos) / M2U
						if self:MercerSees(e) then
							local sg = self.MercerSight[cls] or self.MercerSight.default
							local r = e.GetEnemy and IsValid(e:GetEnemy()) and sg[2] or sg[1]
							local x = smooth(d < r and d / r or (sg[3] and d / self.MercerSightCone.dist) or 1)
							local ss = cls == "drg_proto_supersoldier"
							local v = powered and 1000 or ss and 20 or mil and -5 or -2
							v = (v > 0 and Lerp(x, v, 0.5) or Lerp(x, -0.5, v)) * (ss and 0.8 or 1)
							rate = math.max(rate or v, v)
							f = math.min(f, x)
							fa, fj, fl = math.min(fa, x), math.min(fj, x), math.min(fl, x)
						end
						-- (heard: soundRadius attack 15, smallJump 5, landing 30)
						if d < 15 then fa = math.min(fa, smooth(d / 15)) end
						if d < 5 then fj = math.min(fj, smooth(d / 5)) end
						if d < 30 then fl = math.min(fl, smooth(d / 30)) end
					end
				end
				local seen = rate ~= nil
				local function add(k, v, m) g[k] = math.Clamp(g[k] + v, 0, m or 100) end
				add("Faction", (rate or -10) * dt)
				for k, r in pairs(GA) do
					local on
					if k == "Sprinting" then on = self.MercerSprintOn
					elseif k == "Climbing" then on = self:GetNW2Bool("MercerClimb")
					elseif k == "Wallrunning" then on = self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerClimb")
					else on = self:GetNW2Bool("MercerHolding") or (self.MercerObj and (self.MercerObj.mass or 0) >= 200) end
					add(k, (on and seen) and r[1] * dt * (1 - f) or -r[2] * dt)
				end
				add("Attack", -5 * dt)
				if (self.MercerFight or self.MercerElbow or self.MercerStomp or self.MercerFKick or self.MercerClawSpike) and fa < 1 then add("Attack", 100 * (1 - fa)) end
				add("Landing", -5 * dt)
				add("SmallJump", -8 * dt)
				if (self.MercerJumpN or 0) ~= g.jumps then
					g.jumps = self.MercerJumpN
					if fj < 1 then add("SmallJump", 25 * (1 - fj)) end
				end
				if self.MercerLandTime ~= g.landT then
					g.landT = self.MercerLandTime
					local mps = (self.MercerLandSpeed or 0) / M2U
					if fl < 1 and mps >= 15 then add("Landing", 100 * (1 - fl))
					elseif fl < 1 and mps >= 5 then add("SmallJump", 50 * (1 - fl)) end
				end
				local blow = g.Attack > 10 or g.Holding > 20 or g.Climbing > 20 or g.Sprinting >= 100 or g.Wallrunning >= 100 or g.SmallJump >= 100 or (powered and g.Faction > 20)
				-- //disguise: Recognition, node 32: 2 s; unseen over 1 s lets him go. Startled, node 33: 1.4 s, then Angry
				if not blow and g.Faction > 20 then
					g.recT, g.recOut = (g.recT or 0) + dt, seen and 0 or (g.recOut or 0) + dt
					if g.recT >= 2 then blow = true elseif g.recOut > 1 then g.recT = nil end
				else
					g.recT = nil
				end
				if g.Landing > 40 and not g.startT then g.startT = CurTime() end
				if g.startT and CurTime() - g.startT >= 1.4 then blow = true end
				if blow then
					self.MercerGA = nil
					self:MercerBlowCover(set, near)
					return 100
				end
				local pct = math.max(g.Faction / 20, g.Attack / 10, g.Holding / 20, g.Climbing / 20, g.Sprinting / 100, g.Wallrunning / 100, g.SmallJump / 100, g.Landing / 40)
				return math.min(pct, 1) * 100
			end
		end
		function ENT:MercerAwareThink()
			if CurTime() < (self.MercerAwareT or 0) then return end
			self.MercerAwareT = CurTime() + DT_AWARE
			local st, susp = 0, self.MercerSusp or 0
			local disg = self:GetNW2Bool("MercerDisguised")
			local near = ents.FindInSphere(self:GetPos(), HUNT_R)
			local seen
			if self.MercerCoverBlown then
				local any = false
				for e in pairs(self.MercerHunters or {}) do
					if alive(e) and e:GetPos():DistToSqr(self:GetPos()) < (HUNT_R * 1.5) ^ 2 then any = true break end
				end
				-- (player 2026-10-30: "staying out of sight does not recover the blown disguise") the game's blown look
				-- clears by itself: alex_tod DisguiseBehaviour maxBlownTime 10 s, counted down every frame and set full
				-- again by the //disguise alert graph while he is seen in it (blowDisguise on "seen") - 10 s unseen in it
				-- (or not worn) and it is clean; the hunt off as with the F toggle (MercerCoverTry)
				seen = disg and (self:MercerHuntersSee() or self:MercerWatched(nil, near))
				if seen then self.MercerBlownSeenT = CurTime() end
				local clean = any and CurTime() - (self.MercerBlownSeenT or 0) >= 10
				if not any or clean then
					-- (the flag off first: the hunters' feelings re-read in MercerHunt see the cover back - the pack's
					-- disguisedAsUs reads it - as in MercerCoverTry)
					self.MercerCoverBlown = nil
					if clean and disg then self:MercerHunt(false) end
					self.MercerHunters, susp = nil, 0
					self:SetNW2Bool("MercerBlown", false)
					if disg then self:MercerDisguiseSide(true) end
				end
			end
			if self.MercerCoverBlown and disg then
				-- (user 2026-10-28: "blown in disguise = red", the bar too - the game's meter is red only full) full while
				-- he wears the blown look; red seen, amber unseen (the moment to change)
				st, susp = seen and 2 or 1, 100
			elseif disg then
				local set = sideSet(self)
				local watched = self:MercerWatched(set, near)
				-- (user 2026-10-28: standing among soldiers who look at him the lens stayed amber and the bar never ebbed -
				-- "it must go to rest, light only when he sprints, strikes in the air... - arouses suspicion") the suspicion
				-- climbs only while one of them sees him doing something odd; otherwise it ebbs, looked at or not; the
				-- lens is amber while there is any, at rest (shut) once it is gone
				-- (player 2026-10-30: "creating weapons do not blow the disguise") but a mutation out is no disguise:
				-- alex_tod AlexDisguiseConfig suspicionIncreases "powered" (a power out) seen by any soldier type = +1000 a
				-- second - the cover blown at the first look
				if self.MercerDisgRates:GetBool() then
					susp = self:MercerDisgRatesThink(set, near, DT_AWARE)
					st = self.MercerCoverBlown and 2 or (susp > 0.5 and 1 or 0)
				else
				if watched and self:MercerPowerOut() then
					susp = susp + 1000 * DT_AWARE
				elseif watched and suspicious(self) then
					susp = susp + SUSP_UP * DT_AWARE
				else
					susp = susp - SUSP_DOWN * DT_AWARE
				end
				susp = math.Clamp(susp, 0, 100)
				st = susp > 0.5 and 1 or 0
				if susp >= 100 then
					self:MercerBlowCover(set, near)
					st = 2
				end
				end
			else
				self.MercerGA = nil
				local seen = false
				for _, e in ipairs(near) do
					if e ~= self and (e:IsNPC() or e:IsNextBot()) and alive(e) and e.GetEnemy and e:GetEnemy() == self
						and sees(e, self) then
						seen = true
						break
					end
				end
				st, susp = seen and 2 or 0, seen and 100 or math.max(susp - SUSP_DOWN * DT_AWARE, 0)
			end
			self.MercerSusp = susp
			if self:GetNW2Int("MercerAware", 0) ~= st then self:SetNW2Int("MercerAware", st) end
			local pct = math.floor(susp + 0.5)
			if self:GetNW2Int("MercerAwarePct", 0) ~= pct then self:SetNW2Int("MercerAwarePct", pct) end
		end
		hook.Add("EntityTakeDamage", "AlexMercerCoverBlow", function(target, dmg)
			local att = dmg:GetAttacker()
			if not IsValid(att) or att:GetClass() ~= "drg_alex_mercer" or target == att then return end
			if not (target:IsNPC() or target:IsNextBot() or target:IsPlayer()) or not alive(target) then return end
			if att:GetNW2Bool("MercerDisguised") and not att.MercerCoverBlown then att:MercerViolence(target, dmg:GetDamage()) end
			-- (the friendly ones answer: unless an intact disguise still hides him)
			if not (att:GetNW2Bool("MercerDisguised") and not att.MercerCoverBlown) and att.MercerProvoke then
				att:MercerProvoke(target)
			end
		end)

		-- the consumed one's look for the disguise slot: model, skin, bodygroups; soldiers / police = MILITARY
		-- a consume's biomass into him: health (overflow = critical mass) and the transform wave (fx at most every 0.3 s)
		-- noCrit: health only, the overflow is lost (user 2026-10-23: the explosion devastator's pulled-in dead heal him
		-- but give no critical mass)
		function ENT:MercerAbsorbHeal(noCrit)
			local maxhp = self:GetMaxHealth()
			local hp = self:Health() + maxhp * GRAB_HEAL
			if hp > maxhp and noCrit then
				hp = maxhp
			elseif hp > maxhp then
				local crit = math.min(1, self:GetNW2Float("MercerCrit", 0) + (hp - maxhp) / (maxhp * CRIT_CAP))
				self:SetNW2Float("MercerCrit", crit)
				hp = maxhp
			end
			self:SetHealth(hp)
			self:SetNW2Int("DrGBaseHealth", hp)
			if CurTime() >= (self.MercerAbsorbFxT or 0) then
				self.MercerAbsorbFxT = CurTime() + 0.3
				self:MercerFxProg({{"transform_chest_out", 0}})
			end
		end

		-- in disguise, the new look after the absorb: the body's swirl into him takes ~1.2 s more (the consume's end)
		local DISGUISE_SWAP_DELAY = 1.5
		-- (delay: a finisher's own time from its absorb to the look - the stealth consumes swap at once)
		function ENT:MercerRememberDisguise(e, delay)
			local mdl = e:GetModel()
			if not mdl or mdl == "" or not util.IsValidModel(mdl) then return end
			local bg = {}
			for _, b in ipairs(e:GetBodyGroups() or {}) do bg[#bg + 1] = b.id .. "=" .. e:GetBodygroup(b.id) end
			local cls, low = e:GetClass(), string.lower(mdl)
			local military = cls:find("combine", 1, true) or cls:find("metropolice", 1, true) or low:find("combine", 1, true)
				or low:find("police", 1, true) or low:find("soldier", 1, true)
			-- (user screenshot 2026-10-28: a soldier nextbot whose model / class names none of these showed the civilian
			-- icon) or its side is a military one (Combine, the military, police, soldiers by faction name)
			if not military then
				for _, f in ipairs(disguiseFactions(e)) do
					local u = string.upper(f)
					if u:find("COMBINE", 1, true) or u:find("MILITARY", 1, true) or u:find("SOLDIER", 1, true)
						or u:find("POLICE", 1, true) or u:find("ARMY", 1, true) or u:find("BLACKWATCH", 1, true)
						or u:find("BLACKLIGHT", 1, true) or u:find("MARINE", 1, true) then
						military = true
						break
					end
				end
			end
			local d = {mdl = mdl, skin = e:GetSkin() or 0, bg = table.concat(bg, ","),
				kind = military and "MILITARY" or "PEDESTRIAN", factions = disguiseFactions(e)}
			-- (player 2026-10-29: "after consuming an NPC in disguise, wait a while before switching to the new model";
			-- user: and not a bare swap) in disguise the new look waits for the consume to be over, then comes in with
			-- the disguise's own transformation (its fx / sfx, the client's sweep from the old look to the new one)
			if self:GetNW2Bool("MercerDisguised") then
				self.MercerDisgPending = d
				self:Timer(delay or DISGUISE_SWAP_DELAY, function(ent)
					if ent.MercerDisgPending ~= d then return end
					ent.MercerDisgPending = nil
					ent:MercerApplyDisguise(d, ent:GetNW2Bool("MercerDisguised"))
				end)
				return
			end
			self.MercerDisgPending = nil
			self:MercerApplyDisguise(d, false)
		end

		function ENT:MercerApplyDisguise(d, swap)
			self:SetNW2String("MercerDisguiseModel", d.mdl)
			self:SetNW2Int("MercerDisguiseSkin", d.skin)
			self:SetNW2String("MercerDisguiseBG", d.bg)
			self:SetNW2String("MercerDisguiseKind", d.kind)
			-- (user 2026-10-22) whose side it was on: in its look, its side takes him for one of their own
			local was = self:GetNW2Bool("MercerDisguised")
			if was then self:MercerDisguiseSide(false) end
			self.MercerDisguiseFactions = d.factions
			-- (a new look while hunted: hidden again only unseen - MercerCoverTry)
			if was and self:MercerCoverTry() then self:MercerDisguiseSide(true) end
			if swap then
				-- the client sweeps from the old look to this one (NW2 MercerDisgLookT); the HUD icon's shutter
				self:SetNW2Float("MercerDisgLookT", CurTime())
				self:SetNW2Float("MercerDisgSwapT", CurTime())
				local f = ALEX_MERCER_DISGUISE and FORMS[ALEX_MERCER_DISGUISE]
				if f then
					self:MercerTransformFx(f.name, false)
					self:MercerTransformSfx(f.name, false)
				end
			end
		end

		-- (user 2026-10-30: "add the stealth consume") prototype common/button_hints/input_check/special_actions/
		-- stealthConsume: Action (E) on a human, not an infected, its back to him (detectedObjectFacing 0-170 deg), in a
		-- disguise not blown (not disguise_IsInRed) and nobody seeing it (detectedObjectIsSeen: seen 0, maxAngle 120,
		-- onlyMilitary 1, excludeIfCantReport 1, maxDistance 10 m - a soldier's view within 10 m) -> one of the game's
		-- quiet kills (CONSUMES.stealth), the body consumed into him, his look its own. No cover blown (none saw it) and
		-- no grab of the body first: the finisher is the grab
		-- (onlyMilitary - the night re-check against the graph: any NPC counted before, a civilian too) a soldier by the
		-- disguise look's own test (MercerRememberDisguise: Combine / police / soldier by class or model, a military side
		-- by faction) - without Blacklight (the infected side)
		function ENT:MercerIsMilitary(w)
			local cls, low = w:GetClass(), string.lower(w:GetModel() or "")
			if cls:find("combine", 1, true) or cls:find("metropolice", 1, true) or low:find("combine", 1, true)
				or low:find("police", 1, true) or low:find("soldier", 1, true) then return true end
			for _, f in ipairs(disguiseFactions(w)) do
				local u = string.upper(f)
				if u:find("COMBINE", 1, true) or u:find("MILITARY", 1, true) or u:find("SOLDIER", 1, true)
					or u:find("POLICE", 1, true) or u:find("ARMY", 1, true) or u:find("BLACKWATCH", 1, true)
					or u:find("MARINE", 1, true) then return true end
			end
			return false
		end
		function ENT:MercerStealthOk(e)
			local look = self:GetNW2Bool("MercerDisguised")
			if self.MercerCoverBlown or not grabbable(self, e) then return false end
			-- (user 2026-11-05: "если мерсер не в disguise то он не может сзади скрытно поглотить") the graph asks for no look, only "not disguise_IsInRed": without one that's the HUD's red of MercerAwareThink (one who has him for its enemy sees him), and it mustn't be after him itself, its back turned or not. A player's mind isn't known: only in a look, as before
			if not look and (not self.MercerStealthNoLook:GetBool() or self:GetNW2Int("MercerAware", 0) == 2 or e:IsPlayer() or (e.GetEnemy and e:GetEnemy() == self)) then return false end
			for _, f in ipairs(disguiseFactions(e)) do
				if FACTION_ZOMBIES and string.upper(f) == string.upper(FACTION_ZOMBIES) then return false end
			end
			local to, fw = e:GetPos() - self:GetPos(), e:GetForward()
			to.z, fw.z = 0, 0
			if to:LengthSqr() < 1 or fw:LengthSqr() < 0.01 then return false end
			-- its facing against the way from him to it (0 = its back to him, 180 = face to face). The engine's own test (prototypeenginef.dll 0x100b1a90, DetectedObjectFacingCondition): the angle within angle +- arc * 0.5, so the graph's 170 is +-85, his side of its shoulders: so without a look. In a look the +-170 it's had since 2026-10-30, not changed unasked: his way there is a kill, not a grab that blows the cover
			if math.deg(math.acos(math.Clamp(fw:GetNormalized():Dot(to:GetNormalized()), -1, 1))) > (look and 170 or 85) then return false end
			local at = e:WorldSpaceCenter()
			for _, w in ipairs(ents.FindInSphere(at, 10 * M2U)) do
				-- (excludeIfCantReport: none held by him / being consumed)
				if w ~= self and w ~= e and (w:IsNPC() or w:IsNextBot()) and alive(w) and not w.MercerHeldBy
					and not w.MercerGone and self:MercerIsMilitary(w) then
					local eye = w.EyePos and w:EyePos() or w:WorldSpaceCenter()
					if w:GetForward():Dot((at - eye):GetNormalized()) >= 0.5 then
						local tr = util.TraceLine({start = eye, endpos = at, filter = {w, e, self}, mask = MASK_BLOCKLOS})
						if not tr.Hit then return false end
					end
				end
			end
			return true
		end
		function ENT:MercerStealthConsume(e)
			local ok, neck = pcall(holdVictim, e)
			if not ok or not neck then
				if not ok then ErrorNoHalt("[alex_mercer] stealth consume: " .. tostring(neck) .. "\n") end
				freeVictim(e)
				return false
			end
			self:SetAngles(Angle(0, (e:GetPos() - self:GetPos()):Angle().y, 0))
			local set, total = CONSUMES.stealth, 0
			for _, x in ipairs(set) do total = total + x.weight end
			local r, c = math.random() * total, set[#set]
			for _, x in ipairs(set) do
				r = r - x.weight
				if r <= 0 then c = x break end
			end
			self:CallOnRemove("MercerFreeVictim", function(ent) freeVictim(e) end)
			self:SetNW2Bool("MercerHolding", true)
			self:SetNW2Entity("MercerVictim", e)
			self.MercerGrab = {phase = "consume", t0 = CurTime(), t1 = CurTime(), target = e, neck = neck, fin = c, done = {},
				set = "stealth", back = true}
			-- the client plays the receiver's _rcv, its effects and its way into him by the name (alex_mercer_victim.lua)
			self:SetNW2String("MercerConsumeName", c.name)
			self:SetNW2Float("MercerConsumeT", CurTime())
			GP.Start(self, "mercer/consume_stealth_" .. c.name, {block = true, hold = true})
			self.MercerGrab.gunKind = self:MercerGunKindOf(e)
			if e:IsNPC() and IsValid(e:GetActiveWeapon()) then e:GetActiveWeapon():Remove() end
			e:DrawShadow(false)
			for _, x in ipairs(c.sfx) do
				if x[1] <= 0 then self:MercerCue(x[2], x[3]) else self:Timer(x[1], function(ent) ent:MercerCue(x[2], x[3]) end) end
			end
			return true
		end

		-- when the receiver's consumeByParent is over (its time + 1.8 m / |boneSweepConstant| + 0.25 s + a margin)
		local SWEEP_END = {chest_punch = 2.6, head_stomp = 2.5, knee_head = 2.1, smash_throw = 3.45, beatdown = 4.6,
			crush_head = 3.3, headsmush = 2.9, headdrop = 3.15, heart_to_head = 2.3, lash = 2.6, readjust = 1.95,
			-- (the consumeMe finishers: the same swirl from their consumeMe time)
			foot_sweep = 2.3, arm_rip = 1.65, come_here = 2.1, readjust_b = 1.6, spin_and_slice = 2.15,
			-- (the stealth consumes: into him at once at the receiver's death - user 2026-10-30, "instant, as in the game";
			-- the client's sweep takes ~0.25 s there: death + 0.3, was death + 0.8 for the old swirl)
			break_neck = 2.67, rip_jugular = 2.67, guillotine = 2.8, full_nelson = 2.8, shiv = 3.93, bearhug = 3.3}
		-- (user 2026-10-08: in the game he may run off as soon as the finisher allows, the body flowing into him on the
		-- way) each giver node's "execute 79" = stuff/opportunity_to_opening: from then movement / an action leaves it
		-- (the beatdown has none: its end)
		local OPEN = {foot_sweep = 1.833, crush_head = 2, headsmush = 2.167, headdrop = 2.133, heart_to_head = 2,
			arm_rip = 2.167, lash = 1.967, come_here = 1.833, readjust = 1.667, readjust_b = 1.933, spin_and_slice = 1.833,
			head_stomp = 1.833, knee_head = 1.5, smash_throw = 1.667, chest_punch = 1.833}
			-- (the stealth consumes have none: their grab node is uninterruptible to the end - user 2026-10-30, left early
			-- the body fell back into the held stand's pose, facing him)
		-- the consume's rest after he left: the dissolve, the absorb (health) and the body's end at their own times
		-- (2026-11-05, the pack's Mother's body: graph_mother_core S105-S106) her scene hands him what it held, in his hand: his own consume of it, grapple/bare/beat_down whatever form he's in, from where his root stands.
		-- false: not taken, the scene ends without it. e: a body of the game's rig with health. The game's WOI bank: no way out of it (not in OPEN); no look of hers for a disguise, no gun; her personality has only npc_oof, no scream
		function ENT:MercerConsumeGiven(e, name)
			local g0 = self.MercerGrab
			if not g0 or g0.phase ~= "sseized" or g0.let or not IsValid(e) then return false end
			local c
			for _, x in ipairs(CONSUMES.bare) do
				if x.name == name then c = x end
			end
			if not c then return false end
			local g = {t0 = CurTime(), phase = "consume", t1 = CurTime(), target = e, fin = c, done = {}, set = "bare", given = true}
			if not self:MercerGrabAttach(g) then return false end
			-- on his feet where his root is, as a let go (alex_mercer/ssgrip.lua)
			self:MercerSeizedSettle(nil)
			self.MercerGrab = g
			self:MercerSeizedRestore(g0)
			if PROTO_PairFree then PROTO_PairFree(self) end
			GP.Stop(self)
			self:SetNW2String("MercerConsumeName", c.name)
			self:SetNW2Float("MercerConsumeT", CurTime())
			GP.Start(self, "mercer/consume_bare_" .. c.name, {block = true, hold = true})
			e:DrawShadow(false)
			for _, x in ipairs(c.sfx) do
				if x[1] <= 0 then self:MercerCue(x[2]) else self:Timer(x[1], function(ent) ent:MercerCue(x[2]) end) end
			end
			for _, x in ipairs(c.shakes or {}) do self:MercerShake(x[2], x[3], x[1]) end
			return true
		end
		function ENT:MercerConsumeTailThink()
			local g = self.MercerConsumeTail
			local t = CurTime() - g.t1
			self:MercerConsumeThink(g, t)
			if t > (g.goneAt or 0) - g.t1 + 0.1 or not IsValid(g.target) then self.MercerConsumeTail = nil end
		end
		function ENT:MercerConsumeThink(g, t)
			local c, e = g.fin, g.target
			if t >= c.dissolve and not g.done.dissolve then
				g.done.dissolve = true
				-- effectConsume: the body comes apart into him
				if IsValid(e) then
					g.fade0 = CurTime()
					local pos = bodyCenter(e)
					local dir = (pos - self:WorldSpaceCenter()):GetNormalized()
					self:MercerVFX("blood_gush", pos, dir, 1.2)
					self:MercerVFX("blood_mist", pos, dir, 1)
				end
			end
			if g.fade0 and IsValid(e) then
				local k = math.Clamp((CurTime() - g.fade0) / 1.2, 0, 1)
				e:SetColor(Color(255 - 125 * k, 255 - 240 * k, 255 - 235 * k, 255))
			end
			if c.gib and t >= c.gib and not g.done.gib then
				g.done.gib = true
				local pos = bodyCenter(e)
				if pos then
					self:MercerVFX("blood_squib", pos, Vector(0, 0, 1), 1.4)
					self:MercerVFX("blood_gush", pos, Vector(0, 0, 1), 1.4)
					self:MercerDecal("AlexMercerBlood", pos, pos - Vector(0, 0, 120), {self, e})
				end
			end
			if t >= c.absorb and not g.done.absorb then
				g.done.absorb = true
				-- the biomass into him: health (overflow = critical mass) and the transform wave over his body
				local maxhp = self:GetMaxHealth()
				local hp = self:Health() + maxhp * GRAB_HEAL
				if hp > maxhp then
					local crit = math.min(1, self:GetNW2Float("MercerCrit", 0) + (hp - maxhp) / (maxhp * CRIT_CAP))
					self:SetNW2Float("MercerCrit", crit)
					hp = maxhp
				end
				self:SetHealth(hp)
				self:SetNW2Int("DrGBaseHealth", hp)
				self:MercerFxProg({{"transform_chest_out", 0}})
				if IsValid(e) and not g.given then self:MercerRememberDisguise(e, c.swap) end
				local pos = bodyCenter(e)
				if pos then self:MercerDecal("AlexMercerBlood", pos, pos - Vector(0, 0, 120), {self, e}) end
			end
			-- (+0.75: the client's swirl into him takes 1 s a joint now, was 0.25)
			local gone = math.max(c.death or 0, c.absorb + 1.2, (SWEEP_END[c.name] or 0) + 0.75)
			if t >= gone and IsValid(e) and not e.MercerGone then
				e.MercerGone = true
				e.MercerHeldBy = nil
				ALEX_MERCER_REMOVE_VICTIM(e)
			end
		end

