		-- a Hunter he may take: within 2 m of its hull ahead of him (its own say: HunterCanBeGrabbed)
		function ENT:MercerHunterTarget()
			local cv = GetConVar("alex_mercer_hunter_grab")
			if not (cv and cv:GetBool()) then return end
			local pos, fwd = self:GetPos(), self:GetForward()
			local best, bd
			for _, e in ipairs(ents.FindInSphere(pos, 4 * M2U)) do
				local nodes = e.HunterGrabNodes
				if e ~= self and isfunction(e.HunterCanBeGrabbed) and e:HunterCanBeGrabbed(self)
					and (not nodes or self:LookupSequence(ALEX_MERCER_GRAPH[nodes.grab][1].anim) >= 0) then
					local to = e:GetPos() - pos
					to.z = 0
					local d = math.max(to:Length() - e:OBBMaxs().x, 0)
					if d < 2 * M2U and (d < 24 or to:GetNormalized():Dot(fwd) > 0.5) and (not bd or d < bd) then best, bd = e, d end
				end
			end
			return best
		end
		function ENT:MercerHunterGrabStart(e)
			-- (the pack's Supreme Hunter: the scene is its. Its true not handed on: this is CustomThink's return value, and DrGBase adds that to CurTime)
			if e.HunterRideStart then e:HunterRideStart(self) return end
			self:MercerCombatEvent()
			self:SetAngles(Angle(0, (e:GetPos() - self:GetPos()):Angle().y, 0))
			local nodes = e.HunterGrabNodes
			local node = e.ProtoSuperSoldier and "mercer/supersol_grab" or nodes and nodes.grab or "mercer/hunter_grab"
			self.MercerGrab = {hunter = e, phase = e.ProtoSuperSoldier and "ssgrab" or nodes and "hhold" or "hgrab", t0 = CurTime(),
				d = GP.Duration(node), node = node}
			-- (it stands: he closes on it, to where his half's hand takes it - over 0.1 s, BY EYE: the game's reach is tighter)
			local to = e:GetPos() - self:GetPos()
			to.z = 0
			local hand = ALEX_MERCER_GRABWRIST(self, ALEX_MERCER_GRAPH[node][1].anim, 0)
			if hand then
				self.MercerGrab.slide = to - self:GetForward() * (hand - self:GetPos()):Dot(self:GetForward())
				self.MercerGrab.slideLeft = 0.1
			end
			e:HunterGrabbed(self)
			GP.Start(self, node, {block = true, hold = true})
			self:MercerCue("alex_grab")
			if self.MercerViolence then self:MercerViolence(e, 0) end
			self:MercerHunterAttach(self.MercerGrab)
		end
		-- its _rcv at his _gv's frame, its Motion_Root on his R_Wrist_Grapple
		function ENT:MercerHunterAttach(g)
			local anim, cycle = GP.Sample(self)
			anim = anim and string.lower(anim)
			local rcv = anim and self.MercerHunterRcv[anim]
			if not rcv then return end
			-- (his hand off the anim's table, not his bones: on the server they are a cache up to 0.1 s old)
			local own = cycle * ((ALEX_MERCER_FRAMES[anim] or 2) - 1)
			local pos, ang = ALEX_MERCER_GRABWRIST(self, anim, own)
			if not pos then return end
			local R = self.MercerHunterRoot[g.node]
			g.hunter:HunterHeldPose(rcv, R and R.rcvAt and R.rcvAt(CurTime() - g.t0) or own, pos, ang)
		end
		-- this tick's stretch of his node's straight line
		function ENT:MercerHunterRootMove(g)
			local R = self.MercerHunterRoot[g.node]
			local dt = FrameTime()
			if g.slide then
				local k = math.min(dt / g.slideLeft, 1)
				self:MercerShove(g.slide * k)
				g.slide, g.slideLeft = g.slide * (1 - k), g.slideLeft - dt
				if k >= 1 then g.slide = nil end
			end
			if R and R.line then
				-- (by the frames: where they jump, over the client's fade)
				local anim, cycle = GP.Sample(self)
				local f = anim and cycle * ((ALEX_MERCER_FRAMES[string.lower(anim)] or 2) - 1) or 0
				local step = (self:GetForward() * -R.line[2] - self:GetRight() * R.line[1]) * (M2U * (f - (g.lineF or 0)))
				if f - (g.lineF or 0) > 2.5 then g.slide, g.slideLeft = step, 0.2 else self:MercerShove(step) end
				g.lineF = f
			elseif R then
				self:MercerShove((self:GetForward() * -R.v[2] - self:GetRight() * R.v[1]) * (M2U * dt))
			end
		end
		-- S53-S58: off the consumed body: up 4-5 m, back 2-4 m (the mid of each), his gravity's flight
		function ENT:MercerHunterFlip()
			local grav = self.loco:GetGravity()
			local vz = math.sqrt(2 * grav * 4.5 * M2U)
			self:LeaveGround()
			self.loco:SetVelocity(self:GetForward() * (-3 * M2U * grav / (2 * vz)) + Vector(0, 0, vz))
			GP.Start(self, "mercer/leader_flip", {air = true, onDone = function(ent) ent:UpdateAnimation() end})
		end
		-- the node ahead goes on from where his root is now: the entity under it, less that node's r0; a turn on the entity, a
		-- cut then. Without a turn over 0.2 s: the client's fade from his last pose, at the entity moving back under the root.
		-- (2026-11-04, user: "Вообще при всех захватах, там по любому все ровнять надо будет") A turn here is the forward pull's end now, 180 deg: no glide follows that, a blend of poses half a turn apart goes either way
		-- round. PROTO_PairTrack, on while that step is ahead: the client keeps his root where it was drawn over the fade. EF_NOINTERP, with no such file: the pose snaps (tools/hstep_client.py's model: a hand 52 u in a
		-- tick; a flag of one server frame, missed, and he stands turned 180 deg for 0.2 s). The side pulls and the throw go over the fade: ssgrip.lua's MercerSeizedSettle
		function ENT:MercerHunterStep(node, turn)
			local anim, cycle = GP.Sample(self)
			anim = anim and string.lower(anim)
			local bp = anim and ALEX_MERCER_GRABROOT(self, anim, cycle * ((ALEX_MERCER_FRAMES[anim] or 2) - 1))
			if PROTO_PairTrack then PROTO_PairTrack(self, node == "mercer/hunter_pull_fwd", "Motion_Root") end
			if turn then
				self:SetAngles(Angle(0, self:GetAngles().y + turn, 0))
				if not PROTO_PairTrack then self:AddEffects(EF_NOINTERP) end
			end
			if not bp then return end
