			local g = self.MercerGrab
			if turn or not g then return self:MercerShove(to) end
			g.slide, g.slideLeft = to, 0.2
		end
		-- Attack (LMB / "a", "e"): the throw; Special (RMB / "s"): the consume, stunned or at 15.1 % or under - in its node's
		-- window (a press in the grab's first frames: held for it)
		function ENT:MercerHunterGrabInput(kind)
			local g = self.MercerGrab
			if g.phase == "ssgrab" then return self:MercerSSSuplexInput(g, kind) end
			if g.phase == "hgrab" then g.pend = kind return end
			local R = self.MercerHunterRoot[g.node]
			if g.phase ~= "hhold" or not (R and R.input) or CurTime() - g.t0 > R.input then return end
			if CurTime() - g.t0 < (R.hook or 0) then g.pend = kind return end
			if kind == "s" and not (isfunction(g.hunter.HunterConsumable) and g.hunter:HunterConsumable()) then return end
			if kind ~= "s" and R.noThrow then return end
			self:MercerCombatEvent()
			if kind == "a" or kind == "e" then
				self:MercerHunterStep("mercer/hunter_throw")
				g.phase, g.t0, g.d, g.node = "hthrow", CurTime(), GP.Duration("mercer/hunter_throw"), "mercer/hunter_throw"
				self:MercerVO("alex_throw", 1)
				GP.Start(self, "mercer/hunter_throw", {block = true, hold = true})
				self:MercerCue("alex_sprint")
			elseif kind == "s" then
				local nodes = g.hunter.HunterGrabNodes
				local node = nodes and nodes.consume or "mercer/hunter_consume"
				self:MercerHunterStep(node)
				g.phase, g.t0, g.d, g.node, g.lineF = "hconsume", CurTime(), GP.Duration(node), node, nil
				GP.Start(self, node, {block = true, hold = true})
				-- (its items: S37-S39, S50-S51: shake, camera, cues; his effects from 0.6667 s)
				local C = self.MercerHunterRoot[node]
				if C.shake then self:MercerShake(C.shake[1], C.shake[2], C.shake[3]) end
				for _, c in ipairs(C.camera) do
					self:Timer(c[1], function(ent) ent:MercerPunchIn(c[2], c[3], c[4], c[5], c[6], c[7], c[8], c[9], c[10]) end)
				end
				for _, c in ipairs(C.cues) do
					self:Timer(c[1], function(ent) ent:MercerCue(c[2]) end)
				end
				self:MercerFxProg({{"consume_giver", 0.6667}, {"consume_giver", 1.2667}, {"consume_giver", 1.8667}})
				-- (user 2026-11-05: "чтоб эффекты были, и нормально щупальца работали, по графам все") his tendrils S38 / S51, the body's effectConsume and biomass, his
				-- worldDamage {Blood}: the client's, alex_mercer_victim.lua, from these (the body stays in MercerHConsume, then its ragdoll: the Hunter's OnRagdoll)
				self:SetNW2Entity("MercerHConsume", g.hunter)
				self:SetNW2String("MercerHConsumeK", C.fx or "hunter")
				self:SetNW2Float("MercerHConsumeT", CurTime())
			end
		end
		-- the grab's think (from MercerGrabThink): true while it owns his body
		function ENT:MercerHunterGrabThink()
			local g = self.MercerGrab
			local e = g.hunter
			local t = CurTime() - g.t0
			-- (it gone or dead while in his hands: let go - not once thrown / consumed: his move plays on)
			if not g.let and not g.got and (not IsValid(e) or (e:Health() <= 0 and g.phase ~= "hconsume")) then
				return self:MercerHunterGrabEnd()
			end
			if g.phase == "hgrab" then
				self:MercerHunterAttach(g)
				self:MercerHunterRootMove(g)
				if t < g.d then return true end
				-- the move stick: the pull that way (forward / right / left), else the hold
				local md, node = self.MercerMoveDir, "mercer/hunter_hold"
				if md and not md:IsZero() then
					local a = math.AngleDifference(md:Angle().y, self:GetAngles().y)
					if math.abs(a) <= 45 then
						node = "mercer/hunter_pull_fwd"
					elseif a < -45 and a >= -135 then
						node = "mercer/hunter_pull_r"
					elseif a > 45 and a <= 135 then
						node = "mercer/hunter_pull_l"
					end
				end
				-- (the hold is the same anim on: its root where it is)
				if node ~= "mercer/hunter_hold" then self:MercerHunterStep(node) end
				g.phase, g.t0, g.d, g.node = "hhold", CurTime(), GP.Duration(node), node
				GP.Start(self, node, {block = true, hold = true})
				return true
			elseif g.phase == "hhold" then
				if g.outT then return self:MercerSSOut(g) end
				local R = self.MercerHunterRoot[g.node]
				if g.pend and t >= (R.hook or 0) then
					local k = g.pend
					g.pend = nil
					self:MercerHunterGrabInput(k)
					if g.phase ~= "hhold" then return true end
				end
				if g.glide then
					-- (ssgrip.lua's, his hull stopped by a wall on the way as a shove is)
					local from = self:GetPos()
					self:MercerSeizedGlideStep(g)
					local by = self:GetPos() - from
					self:SetPos(from)
					self:MercerShove(by)
				end
				if not g.let then self:MercerHunterAttach(g) end
				self:MercerHunterRootMove(g)
				-- (no throw / consume by then: it is out of his hands, its half goes on)
				if R.let and not g.let and t >= R.let[1] then
					g.let = true
					e:HunterLetGo(R.let[2], R.let[3])
				end
				if t < g.d then return true end
				if R.next then
					self:MercerSeizedSettle(R.next, true)
					g.t0, g.d, g.node = CurTime(), GP.Duration(R.next), R.next
					GP.Start(self, R.next, {block = true, hold = true})
					return true
				end
				if R.turn and not R.push then return self:MercerSSOut(g) end
				if R.turn then self:MercerHunterStep(nil, R.turn) end
				self:MercerHunterGrabEnd()
				if R.push then self:MercerHitPushback() end
				return false
			elseif g.phase == "hthrow" then
				if g.outT then return self:MercerSSOut(g) end
				-- (2026-11-04: he throws where he looks, over the Super Soldier's S67: 1200 deg/s for 0.4 s, before the let go. S21 has no turn; at once at the press he and the body in his hands popped)
				local p = self:GetPossessor()
				if t < 0.4 and IsValid(p) then
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, self:MercerAimVector(p):Angle().y, 1200 * FrameTime()), 0))
				end
				if not g.let then
					self:MercerHunterAttach(g)
					if t >= 0.7667 then
						g.let = true
						e:HunterReleased(self, "thrown", self:GetForward() * 20 * M2U + Vector(0, 0, 6 * M2U))
					end
				end
				self:MercerHunterRootMove(g)
				if t >= g.d then return self:MercerSSOut(g) end
				return true
			elseif g.phase == "ssgrab" or g.phase == "ssthrow" then
				return self:MercerSSGrabThink(g, e, t)
			elseif g.phase == "sssuplex" then
				return self:MercerSSSuplexThink(g, e, t)
			elseif g.phase == "sseized" then
				return self:MercerSeizedThink(g, e, t)
			elseif g.phase == "hconsume" then
				self:MercerHunterRootMove(g)
				local R = self.MercerHunterRoot[g.node]
				if not g.got then
					self:MercerHunterAttach(g)
					if t >= R.got then
						g.got = true
						self:MercerHunterAbsorb(e)
					end
				end
				if t < g.d then return true end
				if not R.flip then return self:MercerHunterGrabEnd() end
				self:MercerHunterStep(nil, 0)
				self:MercerHunterGrabEnd()
				self:MercerHunterFlip()
				return false
			end
			return self:MercerHunterGrabEnd()
		end
		-- the Super Soldier's two (above)
		function ENT:MercerSSGrabThink(g, e, t)
			if g.outT then return self:MercerSSOut(g) end
			local dt, p = FrameTime(), self:GetPossessor()
			if g.phase == "ssgrab" then
				local use = IsValid(p) and p:KeyDown(IN_USE)
				-- (S287 buttonHintShow {Action} {TAP} "$M_THROW" while the throw is to be had: the pack's button hint, lua/autorun/client/prototype_buttonhint.lua)
				if not g.hint and t >= 0.1667 and t <= 0.6667 and e.SSGrabBlock then
					g.hint = true
					self:SetNW2String("ProtoCounterText", "THROW")
					self:SetNW2Float("ProtoCounterEnd", CurTime() + 0.6667 - t)
					self:SetNW2String("ProtoCounterKey", "action")
				end
				if use and g.useWas == false and not g.let and t >= 0.1667 and t <= 0.6667 and e.SSGrabBlock then
					self:SetNW2String("ProtoCounterKey", "")
					g.phase, g.t0, g.d = "ssthrow", CurTime(), GP.Duration("mercer/supersol_throw")
					self:MercerCombatEvent()
					self:MercerVO("alex_jump_sml_start", 1, 0.1)
					GP.Start(self, "mercer/supersol_throw", {block = true, hold = true})
					self:Timer(0.3333, function(ent) ent:MercerCue("whoosh_small") end)
					self:Timer(0.5, function(ent) ent:MercerCue("power_whoosh") end)
					return true
				end
				g.useWas = use
				self:MercerShove(self:GetForward() * (-3.291 / (46 / 30) * M2U * dt))
			else
				if t < 0.4 and IsValid(p) then
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, self:MercerAimVector(p):Angle().y, 1200 * dt), 0))
				end
				self:MercerShove((self:GetRight() * 0.743 + self:GetForward() * 0.086) * (30 / 53 * M2U * dt))
			end
			if not g.let then
				self:MercerHunterAttach(g)
				if t >= (g.phase == "ssgrab" and 1.5 or 0.8) then
					g.let = true
					e:HunterReleased(self, g.phase == "ssthrow" and "thrown" or "free")
				end
			end
			if t < g.d then return true end
			if g.phase == "ssthrow" then return self:MercerSSOut(g) end
			return self:MercerHunterGrabEnd()
		end
		-- the body his (the consume at 2.5 s): health as his other consumes, the transform wave, the body gone. (Its blood: the graph's, the
		-- client's, HunterFx and alex_mercer_victim.lua: this node has none at 2.5 s, and V's gush threw flakes 5 m off - user 2026-11-05)
		function ENT:MercerHunterAbsorb(e)
			e:HunterReleased(self, "consumed")
			local maxhp = self:GetMaxHealth()
			local hp = self:Health() + maxhp * GRAB_HEAL
			if hp > maxhp then
				self:SetNW2Float("MercerCrit", math.min(1, self:GetNW2Float("MercerCrit", 0) + (hp - maxhp) / (maxhp * CRIT_CAP)))
				hp = maxhp
			end
			self:SetHealth(hp)
			self:SetNW2Int("DrGBaseHealth", hp)
			self:MercerFxProg({{"transform_chest_out", 0}})
			e.MercerGone = true
			-- (its half plays on and it falls as a body: S39, the pack's HunterConsumedFall)
			if isfunction(e.HunterConsumedFall) then e:HunterConsumedFall(self) else e:Remove() end
		end
		function ENT:MercerHunterGrabEnd()
			local g = self.MercerGrab
			self.MercerGrab = nil
			-- (cut off before the body is his: the client's effects stop with it)
			if g and g.phase == "hconsume" and not g.got then self:SetNW2Float("MercerHConsumeT", 0) end
			if PROTO_PairTrack then PROTO_PairTrack(self, false) end
			-- (let go by the node: its half is playing on by itself)
			if g and IsValid(g.hunter) and g.hunter.HunterHeld == self and not g.let then g.hunter:HunterReleased(self, "free") end
			if g and g.phase == "sseized" then self:MercerSeizedRestore(g) end
			GP.Stop(self)
			self:UpdateAnimation()
			return false
		end

		-- returns true while the grab owns the body (reach, beating, throw, consume); holding lets him move
		function ENT:MercerGrabThink(p, dt)
			local g = self.MercerGrab
			if g.hunter then return self:MercerHunterGrabThink() end
			local t = CurTime() - g.t0
			local use = IsValid(p) and p:KeyDown(IN_USE)
			local usePressed = use and not self.MercerGrabUseWas
			self.MercerGrabUseWas = use
			if g.phase == "dash" then return self:MercerRunGrabThink(g, p, dt) end
			if g.phase == "reach" then
				if t >= 0.27 and not g.neck then
					-- alex_grap_hmn_gv frame 8: the hand closes on the neck
					if not self:MercerGrabAttach(g) then
						self.MercerGrab = nil
						GP.Start(self, self:GetMercerForm().name == "Клинок" and "mercer/grab_miss_blade" or "mercer/grab_miss", {block = true, exitAfter = 0.3, onDone = function(ent) ent:UpdateAnimation() end})
						return true
					end
				end
				if g.neck then self:MercerGrabFollow(g) end
				if t >= 0.4 then
					g.phase = "hold"
					GP.Stop(self)
					self:UpdateAnimation()
				end
				return true
			end
			if not victimOk(g.target) and g.phase ~= "consume" and g.phase ~= "after" and not g.slammed then
				-- the body is gone (removed, broken): let go, and out of any held grab pose
				self:MercerGrabRelease()
				if self.MercerNode and string.find(self.MercerNode.path, "mercer/grab_", 1, true) then
					GP.Stop(self)
					self:UpdateAnimation()
				end
				return false
			end
			if g.phase == "hold" then
				-- nobody at the controls (dispossessed): let it go - unless the AI took it
				if not IsValid(p) and not g.ai then self:MercerGrabRelease() return false end
				if not self:IsOnGround() then
					self:MercerGrabFollow(g)
					-- air/actions/attack/grapple: Special = the slam, Action = the powerbomb, Attack = the throw; Jump = the
					-- springboard (alex_grap_air_float)
					local rmb = IsValid(p) and p:KeyDown(IN_ATTACK2)
					local lmb = IsValid(p) and p:KeyDown(IN_ATTACK)
					local jmp = IsValid(p) and p:KeyDown(IN_JUMP)
					if not self.MercerAirSlam and not self.MercerAirThrow then
						if usePressed then self:MercerAirSlamStart("bomb")
						elseif rmb and not g.rmbWas then self:MercerAirSlamStart("slam")
						elseif lmb and not g.lmbWas then self:MercerAirThrowStart()
						elseif jmp and g.jmpWas == false then
							g.rmbWas, g.lmbWas, g.jmpWas = rmb, lmb, jmp
							self:MercerAirFloat()
							return false
						end
					end
					g.rmbWas, g.lmbWas, g.jmpWas = rmb, lmb, jmp
					-- (node {human}, MercerAirGrabThink) its 0.2 s, what he presses next goes first
					if g.take then
						if CurTime() - g.take.t0 >= 0.2 or self.MercerAirSlam or self.MercerAirThrow or self.MercerAirDash then g.take = nil
						else self.loco:SetVelocity(g.take.v) end
					end
					if self.MercerAirSlam then self:MercerAirSlamThink(FrameTime()) end
					if self.MercerAirThrow and not self.MercerAirThrow.rel then self:MercerAirThrowThink(lmb) end
					return false
				end
				-- (players 2026-10-27: after the air slam he sometimes stood holding the body, then spun on and on) the
				-- landing missed it (OnLandOnGround leaves early on a wall touch, a hit reaction...): on the ground the
				-- slam lands here
				-- (0.15 s on the ground first: the landing's own call goes first)
				local as = self.MercerAirSlam
				if as then
					as.groundT = as.groundT or CurTime()
					if CurTime() - as.groundT > 0.15 then
						self:MercerAirSlamLand(self:GetVelocity():Length())
						return true
					end
					return false
				end
				self.MercerAirThrow = nil
				g.jmpWas = nil
				self:MercerGrabFollow(g)
				if usePressed then self:MercerGrabInput("e") return true end
				-- (user 2026-10-28: "let the victim go") P1's human holding has no drop (attack / throw / consume only);
				-- P2's has it (holding/grabbing/human/action/dpad_ditch/drop_human: heller_human_release_gvr). Ctrl on
				-- the ground (free there - the air dash is the air's) puts it down: the "drop" phase below
				local ctrl = IsValid(p) and p:KeyDown(IN_DUCK)
				if ctrl and g.ctrlWas == false then
					g.phase, g.t0 = "drop", CurTime()
					ALEX_MERCER_FRAMES[MERCER_DROP_ANIM] = ALEX_MERCER_FRAMES[MERCER_DROP_ANIM] or 41
					GP.Start(self, "mercer/grab_drop", {block = true, hold = true})
					self:MercerCue("whoosh_small")
					return true
				end
				g.ctrlWas = ctrl
				return false
			end
			if g.phase == "drop" then
				local t = CurTime() - g.t0
				if not g.dropped then
					-- in his hand while it comes down (the client: heller_human_release_gvr_rcv), let go in front of him
					-- at MERCER_DROP_LET (his hand forward and down at frame 14)
					self:MercerGrabFollow(g)
					if t >= MERCER_DROP_LET then
						g.dropped = true
						self:MercerVictimGetup(g)
					end
					return true
				end
				-- (his arm back to the stance by frame 21: movement may cut the rest)
				if t >= MERCER_DROP_END or (t >= 0.4 and self.MercerMoveDir and not self.MercerMoveDir:IsZero()) then
					self.MercerGrab = nil
					GP.Stop(self)
					self:UpdateAnimation()
					return false
				end
				return true
			end
			local t1 = CurTime() - g.t1
			if g.phase == "slam" then
				self:MercerGrabFollow(g)
				if not g.rel then
					-- windup 0.4 s, then the hold charges 0.4 s while Attack is down
					local held = IsValid(p) and p:KeyDown(IN_USE)
					if t1 >= 0.4 and (not held or t1 >= 0.8) then
						g.rel, g.charge = CurTime(), math.Clamp((t1 - 0.4) / 0.4, 0, 1)
						GP.Start(self, "mercer/grab_slam_rel", {block = true, hold = true})
					end
					return true
				end
				local tr = CurTime() - g.rel
				if tr >= 0.2333 and not g.slammed then
					-- the body hits the ground: 50-75 (by the charge) to it, let go (Bounce); 15-25 to anyone within
					-- 3 m round him
					g.slammed = true
					local e = g.target
					local pos = bodyCenter(e)
					if pos then
						self:MercerVFX("hit", pos, Vector(0, 0, 1), 0.8)
						self:MercerVFX("blood_squib", pos, Vector(0, 0, 1), 1)
						self:MercerDecal("AlexMercerBlood", pos, pos - Vector(0, 0, 120), {self, e})
					end
					self:MercerCue("alex_punch_human")
					self:MercerCue("bonebreak", 0.7)
					self:MercerShake("small", "small")
					-- (the game's humans have less health than the slam's 50: it always kills them - a quick tap left a
					-- GMod NPC alive in a broken state, user) killed with the Bounce's force: its death ragdoll bounces
					-- (into the ground: the Bounce's impulse is out and down - user, the bodies flew up)
					self:MercerKillHeld(self:GetForward() * Lerp(g.charge or 0, 150, 250) - Vector(0, 0, 200), 80)
					self.MercerGrab = g
					local H = {0, 0, "", 3, 0, 15, 25, Vector(0, 1000, -1500), Vector(0, 3000, -6000)}
					for _, v in ipairs(ents.FindInSphere(self:GetPos(), 3 * M2U)) do
						if v ~= e and fightable(self, v) then self:MercerFightDamage(v, H, g.charge, v:WorldSpaceCenter()) end
					end
				elseif not g.slammed then
					self:MercerGrabFollow(g)
				end
				if tr >= 0.9667 then
					self.MercerGrab = nil
					GP.Stop(self)
					self:UpdateAnimation()
				end
				return true
			elseif g.phase == "throw" then
				local run = g.run
				if run then
					local R = self.MercerRunThrow
					run.v = math.max(0, run.v - R.brake * dt)
					self.loco:SetVelocity(Vector(0, 0, self.loco:GetVelocity().z))
					if run.v > R.stop and self:IsOnGround() then self:MercerShove(run.dir * (run.v * M2U * dt)) end
				end
				if not g.rel then
					self:MercerGrabFollow(g)
					local held = IsValid(p) and p:KeyDown(IN_ATTACK)
					-- (holding/human throw: the release's opportunity runs from the windup's 0 s: a tap throws at once; it waited 0.2 s)
					if not held or t1 >= (run and 0.5333 or 0.7) then
						g.rel, g.charge = CurTime(), run and math.Clamp(t1 / 0.5333, 0, 1) or math.Clamp((t1 - 0.2) / 0.5, 0, 1)
						GP.Start(self, "mercer/grab_throw_rel", run and {block = true, exitAfter = 0.23, onDone = function(ent) ent:UpdateAnimation() end}
							or {block = true, hold = true})
					end
					return true
				end
				if CurTime() - g.rel < (run and 0.2 or 0.1667) then
					self:MercerGrabFollow(g)
				elseif not g.thrown then
					g.thrown = true
					local p = self:GetPossessor()
					local aim = IsValid(p) and self:MercerAimVector(p) or self:GetForward()
					local lk = self:MercerLocked(80 * M2U)
					if lk then aim = (self:MercerLockPoint(lk) - self:WorldSpaceCenter()):GetNormalized() end
					aim = (aim + Vector(0, 0, 0.15)):GetNormalized()
					local e = g.target
					local rag
					if IsValid(e) and victimOk(e) and self.MercerBodyCopy then
						local ok, r = pcall(self.MercerBodyCopy, self, e)
						if ok and IsValid(r) then rag = r elseif not ok then ErrorNoHalt("[alex_mercer] throw: " .. tostring(r) .. "\n") end
					end
					if rag then
						-- the game's thrown human: 28 m/s along the aim, tumbling; the NPC itself is gone into the body
						self.MercerGrab = nil
						self:SetNW2Bool("MercerHolding", false)
						self:SetNW2Entity("MercerVictim", NULL)
						self:RemoveCallOnRemove("MercerFreeVictim")
						e.MercerGone, e.MercerHeldBy = true, nil
						ALEX_MERCER_REMOVE_VICTIM(e)
						-- (a charged throw - ThrowCharged - flies the farthest)
						-- (player 2026-10-29: the muscle form's throw) prototype_musclemass throw/variations/human: distance
						-- 100 -> 150 m against the bare human throw's 65 -> 110 (same 30-35 m/s field): the 40 -> 65 here
						-- scaled by that - 61 -> 89
						local muscle = self:GetMercerForm().name == "Мускулы"
						local v = aim * (Lerp(g.charge or 0, muscle and 61 or 40, muscle and 89 or 65) * M2U * self:MercerMuscleK())
						for i = 0, rag:GetPhysicsObjectCount() - 1 do
							local ph = rag:GetPhysicsObjectNum(i)
							if IsValid(ph) then
								ph:SetVelocity(v)
								ph:AddAngleVelocity(VectorRand() * 300)
							end
						end
						timer.Simple(0.25, function() if IsValid(rag) then rag:SetCollisionGroup(COLLISION_GROUP_NONE) end end)
						self:MercerThrownBody(rag, self:MercerThrowDamage(g.charge))
					else
						self:MercerGrabRelease(aim * Lerp(g.charge or 0, 2200, 3600) + Vector(0, 0, 350))
					end
					self.MercerGrab = {phase = "after", t0 = g.t0, t1 = g.t1, rel = g.rel}
					-- (on the run: nothing holds him after it, the slide's rest goes on until the run does)
					if run then
						self.MercerGrab = nil
						self.MercerThrowSlide = {v = run.v, dir = run.dir, node = self.MercerNode, R = self.MercerRunThrow}
					end
					self:MercerCue("lethal_whoosh")
					self:MercerShake("small", "small")
				end
				return true
			elseif g.phase == "after" then
				if CurTime() - (g.rel or g.t1) >= 1.3333 then
					self.MercerGrab = nil
					GP.Stop(self)
					self:UpdateAnimation()
				end
				return true
			elseif g.phase == "consume" then
				if IsValid(g.target) then self:MercerGrabFollow(g) end
				self:MercerConsumeThink(g, t1)
				-- the opening: movement or an action after it lets him go, the body staying to flow into him
				local open = OPEN[g.fin.name]
				local out = false
				if open and t1 >= open and IsValid(p) then
					local md = self.MercerMoveDir
					out = (md ~= nil and not md:IsZero()) or p:KeyDown(IN_ATTACK) or p:KeyDown(IN_ATTACK2)
						or p:KeyDown(IN_JUMP) or p:KeyDown(IN_USE) or p:KeyDown(IN_DUCK)
				end
				if t1 >= g.fin.dur or out then
					if g.fin.whip then self:MercerWhipMode(0, 30) end
					local e, goneAt = g.target, g.t1 + math.max(g.fin.death or 0, g.fin.absorb + 1.2, (SWEEP_END[g.fin.name] or 0) + 0.75)
					-- (the dissolve / the absorb / the end go on without him: the tail; the whip lash's absorb runs past
					-- his 1.56 s anim too)
					g.goneAt = goneAt
					self.MercerConsumeTail = g
					local function gone(ent)
						if IsValid(e) and not e.MercerGone then
							e.MercerGone, e.MercerHeldBy = true, nil
							ALEX_MERCER_REMOVE_VICTIM(e)
						end
						if IsValid(ent) and ent:GetNW2Entity("MercerVictim") == e then ent:SetNW2Entity("MercerVictim", NULL) end
					end
					if CurTime() < goneAt and IsValid(e) and not e.MercerGone then
						local me = self
						timer.Simple(goneAt - CurTime(), function() gone(me) end)
					else
						gone(self)
					end
					self:RemoveCallOnRemove("MercerFreeVictim")
					self.MercerGrab = nil
					self:SetNW2Bool("MercerHolding", false)
					GP.Stop(self)
					self:UpdateAnimation()
					-- (user 2026-10-30) the consumed one's gun, his hands free now
					if g.gunKind then self:MercerConsumedGun(g.gunKind, self:MercerGripPos()) end
				end
				return true
			end
			return false
		end
	end

	do -- man_grind = body surfing (a block of its own: the file's main chunk is near Lua's 200 locals).
		-- prototype_air air/actions/attack/bare/flying_kick/windup/release/release/give/man_grind (build/graph_air.txt),
		-- (groundSlide's minVelocity ENDS the slide - prototype_sprint's store slide is a node with nothing but a groundSlide
		-- of timeEnd -1 - and man_grind lasts while its motion branch runs (spawn flag 0): the ride ends at 4 m/s,
		-- ~1 s / 12 m from 20 m/s; user: "до бесконечности серфить можно")
		-- referenced by the sprint kick's contact store. A fully charged kick on a human with Attack / Special still
		-- down (unlockable GrappleGrind, reactionHitCharge >= 1): the human is grabbed onto Root_Grapple lying under him
		-- (alex_kick_air_straight_enemy_grind_rcv, causeDamage 100 = dead) and Mercer rides it. motion/grind =
		-- groundSlide (starts at 15..20 m/s, -15 m/s², ends under 4 m/s, max 20) + orient 30 °/s toward the input;
		-- pose gv 0-15 (0.3333 s), then 15-25-15 ping-pong; every 0.1 s worldDamage {Blood} + squibBlood001 +
		-- goreBloodGush001 + alex_slide (Retrigger), alex_manslide looping, head_crunch at the start, the receiver
		-- blood_splat_mono + skullcrusher. Attack / Special pressed again = its kick bank (FlyingKickComboSpecial):
		-- windup gv 35-45-54 over 0.5 s (charge Throw 0.5 s, groundSlide -5 m/s², alex_manslide stops); both buttons up
		-- or the charge full -> release gv 54-86: groundSlide -5 and autoTarget 180 °/s (90°, 50 m) until 0.3 s, then the
		-- fall (5 m/s up, 5 m/s forward, gravity 9.8 m/s²) with the backflip trail and the throw (direction (0, 0.1, -1),
		-- 25..30 m/s by the charge, spin 270..500 °/s); hammer_whoosh 0.51 + lethal_whoosh 0.13, whoosh_small 0.5 s at
		-- 0.33. The slide ending, both buttons up while riding (the node's Down conditions) or leaving the ground (node
		-- #8b16cec4) = exit: alex_loco_jump_land_bounce_fwd 0-20 with moveAtVelocity 6 -> 3 m/s 0.1333-0.5667 s, orient
		-- 180 °/s, exit_passive 0.5667 s, alex_feet 0.25 s; the body is left behind.
		-- GMod: an NPC can't lie down under him, so the human becomes ONE prop_ragdoll of its own model in its pose (made
		-- once per ride inside pcall - never per tick, the grab lesson) and the NPC goes like a consumed one; the ragdoll
		-- (debris: world collisions only) is dragged under his feet by its chest / head / pelvis, and removed after 30 s.
		local GV = "alex_kick_air_straight_enemy_grind_gv"
		local function rseg(t0, t1, anim, f0, f1)
			local x = seg(t0, t1, anim, f0, f1)
			x.rate = -1
			return x
		end
		ALEX_MERCER_GRAPH["mercer/grind/start"] = {seg(0, 0.3333, GV, 0, 15)}
		ALEX_MERCER_GRAPH["mercer/grind/loop"] = {seg(0, 0.3333, GV, 15, 25), rseg(0.3333, 0.6667, GV, 15, 25)}
		ALEX_MERCER_GRAPH["mercer/grind/kick"] = {seg(0, 0.1667, GV, 35, 45), seg(0.1667, 0.5, GV, 45, 54)}
		ALEX_MERCER_GRAPH["mercer/grind/throw"] = {seg(0, 32 / 30, GV, 54, 86)}
		ALEX_MERCER_GRAPH["mercer/grind/exit"] = {seg(0, 0.6667, "alex_loco_jump_land_bounce_fwd", 0, 20)}
		local SLIDE = {decel = 15, minInit = 15, min = 4, max = 20, turn = 30}
		local THROW_AT = {0, 0.3, 180, 90, 50, false}
		-- the body lies head first under his feet: chest under him, head ahead, pelvis behind (u along his facing)
		local BODY = {{"ValveBiped.Bip01_Spine2", 4, "Spine_2"}, {"ValveBiped.Bip01_Head1", 26, "Head"},
			{"ValveBiped.Bip01_Pelvis", -16, "Pelvis"}}

		local function grindBody(e)
			local mdl = e:GetModel()
			if not mdl or not util.IsValidRagdoll(mdl) then return nil end
			local rag = ents.Create("prop_ragdoll")
			if not IsValid(rag) then return nil end
			rag:SetModel(mdl)
			rag:SetPos(e:GetPos())
			rag:SetAngles(e:GetAngles())
			rag:SetSkin(e:GetSkin() or 0)
			for _, bg in ipairs(e:GetBodyGroups() or {}) do rag:SetBodygroup(bg.id, e:GetBodygroup(bg.id)) end
			rag:SetColor(e:GetColor())
			rag:SetMaterial(e:GetMaterial())
			rag:Spawn()
			rag:Activate()
			rag:SetCollisionGroup(COLLISION_GROUP_DEBRIS)
			for i = 0, rag:GetPhysicsObjectCount() - 1 do
				local ph = rag:GetPhysicsObjectNum(i)
				local pos, ang = e:GetBonePosition(rag:TranslatePhysBoneToBone(i))
				if IsValid(ph) and pos then
					ph:SetPos(pos)
					ph:SetAngles(ang)
					ph:Wake()
				end
			end
			SafeRemoveEntityDelayed(rag, 30)
			-- (user 2026-10-29, the Prototype NPC pack: "the screams on the finishers") a victim with its own voice cries
			-- from its body copy (thrown, slammed, ground along - the NPC itself is removed, its own sound would stop)
			if e.ProtoCryOn then pcall(e.ProtoCryOn, e, rag, "npc_scream") end
			return rag
		end

		ENT.MercerBodyCopy = function(self, e) return grindBody(e) end

		-- the anchors pull the body under his feet; the rest of it follows his speed
		local function dragBody(self, g, t)
			local rag = g.rag
			local fwd, base = self:GetForward(), self:GetPos()
			local vel = fwd * (g.v * M2U)
			local k = 10 * math.Clamp(t / 0.3333, 0.2, 1) -- the receiver falls flat over its first 0.3333 s
			for i = 0, rag:GetPhysicsObjectCount() - 1 do
				local ph = rag:GetPhysicsObjectNum(i)
				if IsValid(ph) then
					local cur = ph:GetVelocity()
					local want = g.anchor[i]
					if want then
						local d = base + fwd * want + Vector(0, 0, 6) - ph:GetPos()
						local corr = d * k
						if corr:Length() > 600 then corr = corr:GetNormalized() * 600 end
						ph:SetVelocity(vel + corr)
					else
						ph:SetVelocity(LerpVector(0.3, cur, Vector(vel.x, vel.y, cur.z)))
					end
				end
			end
		end

		local function throwBody(self, g)
			local dir = (self:GetForward() + Vector(0, 0, 0.1)):GetNormalized()
			local v = dir * (Lerp(g.charge or 0, 25, 30) * M2U)
			local spin = math.Rand(270, 500)
			for i = 0, g.rag:GetPhysicsObjectCount() - 1 do
				local ph = g.rag:GetPhysicsObjectNum(i)
				if IsValid(ph) then
					ph:SetVelocity(v)
					ph:AddAngleVelocity(Vector(spin, 0, 0))
				end
			end
		end

		local function slideMove(self, g, dt, turn)
			local md = self.MercerMoveDir
			if turn and md and not md:IsZero() then
				self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, md:Angle().y, turn * dt), 0))
			end
			self.loco:SetVelocity(Vector(0, 0, self.loco:GetVelocity().z))
			if g.v > 0.01 then self:MercerShove(self:GetForward() * (g.v * M2U * dt)) end
		end

		function ENT:MercerGrindStart(st, e)
			if self.MercerGrind or not self:MercerGrabbable(e) then return false end
			local ok, rag = pcall(grindBody, e)
			if not ok or not IsValid(rag) then
				if not ok then ErrorNoHalt("[alex_mercer] man_grind: " .. tostring(rag) .. "\n") end
				return false
			end
			e.MercerGone = true
			ALEX_MERCER_REMOVE_VICTIM(e)
			self:MercerFightEnd()
			local g = {rag = rag, t0 = CurTime(), pt0 = CurTime(), phase = "ride", next = 0, anchor = {},
				v = math.Clamp(st.moveV or 0, SLIDE.minInit, SLIDE.max)}
			for _, b in ipairs(BODY) do
				-- (the game's own rig - the NPC pack: Spine_2 / Head / Pelvis)
				local bone = rag:LookupBone(b[1]) or rag:LookupBone(b[3])
				local i = bone and rag:TranslateBoneToPhysBone(bone)
				if i and i >= 0 then g.anchor[i] = b[2] end
			end
			self.MercerGrind = g
			GP.Start(self, "mercer/grind/start", {block = true, next = "mercer/grind/loop",
				nextOpts = {block = true, loop = true}})
			local c = ALEX_MERCER_CUES and ALEX_MERCER_CUES.alex_manslide
			if c then
				g.loop = CreateSound(self, c.files[1])
				g.loop:SetSoundLevel(c.level)
				g.loop:PlayEx(c.vol, 100)
			end
			self:MercerCue("head_crunch")
			self:MercerCue("blood_splat_mono")
			self:MercerCue("skullcrusher")
			self:MercerCombatEvent()
			return true
		end

		function ENT:MercerGrindEnd()
			local g = self.MercerGrind
			if not g then return end
			if g.loop then g.loop:Stop() end
			self.MercerGrind = nil
			self:SetNW2String("MercerHoldJoint", "")
			self:SetNW2String("MercerHoldFx", "")
			self.loco:SetGravity(1000)
		end

		-- the kick bank: Attack / Special pressed while riding
		function ENT:MercerGrindPress()
			local g = self.MercerGrind
			if not g or g.phase ~= "ride" then return end
			g.phase, g.pt0, g.charge = "kick", CurTime(), 0
			if g.loop then g.loop:Stop() g.loop = nil end
			GP.Start(self, "mercer/grind/kick", {block = true, hold = true})
			self:SetNW2String("MercerHoldJoint", "Ankle_R")
			self:SetNW2String("MercerHoldFx", "charge_bare_r_foot") -- charge/bare/kick/r_foot
		end

		local function grindExit(self, g)
			if g.loop then g.loop:Stop() g.loop = nil end
			g.phase, g.pt0 = "exit", CurTime()
			self:SetNW2String("MercerHoldJoint", "")
			self:SetNW2String("MercerHoldFx", "")
			GP.Start(self, "mercer/grind/exit", {block = true, exitAfter = 0.5667, onDone = function(ent)
				ent:MercerGrindEnd()
				ent:UpdateAnimation()
			end})
			self:Timer(0.25, function(ent) ent:MercerCue("alex_feet") end)
		end

		function ENT:MercerGrindThink(p, dt)
			local g = self.MercerGrind
			local node = self.MercerNode
			if not node or string.sub(node.path, 1, 13) ~= "mercer/grind/" then return self:MercerGrindEnd() end
			local t = CurTime() - g.pt0
			local rag = g.rag
			local down = IsValid(p) and (p:KeyDown(IN_ATTACK) or p:KeyDown(IN_ATTACK2))
			if g.phase == "ride" or g.phase == "kick" then
				if not IsValid(rag) then return grindExit(self, g) end
				if self:IsOnGround() then g.grounded = true elseif g.grounded then return grindExit(self, g) end
				if g.phase == "ride" then
					if not IsValid(p) then
						-- (the AI rides a moment, then kicks the body off)
						if CurTime() - g.t0 > 1.2 then self:MercerGrindPress() end
					elseif not down then
						return grindExit(self, g)
					end
					g.v = g.v - SLIDE.decel * dt
					if g.v < SLIDE.min then return grindExit(self, g) end -- the slide is over
				else
					g.v = math.max(0, g.v - 5 * dt)
					g.charge = math.min(1, t / 0.5)
					if not down or g.charge >= 1 then
						-- the kick's release
						g.phase, g.pt0 = "throw", CurTime()
						self:SetNW2String("MercerHoldJoint", "")
						self:SetNW2String("MercerHoldFx", "")
						GP.Start(self, "mercer/grind/throw", {block = true, hold = true})
						self:MercerTrail("backflip")
						self:MercerCue("hammer_whoosh", 0.5128)
						self:MercerCue("lethal_whoosh", 0.1282)
						self:Timer(0.5, function(ent) ent:MercerCue("whoosh_small", 0.3333) end)
						return
					end
				end
				slideMove(self, g, dt, SLIDE.turn)
				if CurTime() >= g.next then
					-- the blood node, every 0.1 s
					g.next = CurTime() + 0.1
					local at = self:GetPos() + Vector(0, 0, 4)
					self:MercerDecal("AlexMercerBlood", at + Vector(0, 0, 8), at - Vector(0, 0, 24), {self, rag})
					self:MercerVFX("blood_squib", at, Vector(0, 0, 1))
					self:MercerVFX("blood_gush", at, -self:GetForward())
					-- alex_slide on one channel: the game's Retrigger restarts it
					local c = ALEX_MERCER_CUES and ALEX_MERCER_CUES.alex_slide
					if c then
						self:EmitSound(c.files[math.random(#c.files)], c.level, math.random(c.pmin, c.pmax), c.vol, CHAN_ITEM)
					end
				end
				dragBody(self, g, CurTime() - g.t0)
			elseif g.phase == "throw" then
				if t < 0.3 then
					g.v = math.max(0, g.v - 5 * dt)
					self:MercerAutoTarget(THROW_AT, t)
					slideMove(self, g, dt)
					if IsValid(rag) then dragBody(self, g, 1) end
				elseif not g.thrown then
					g.thrown = true
					if IsValid(rag) then throwBody(self, g) end
					self:LeaveGround()
					self.loco:SetGravity(9.8 * M2U)
					self.loco:SetVelocity(self:GetForward() * (5 * M2U) + Vector(0, 0, 5 * M2U))
				end
				if t >= GP.Duration("mercer/grind/throw") then
					self:MercerGrindEnd()
					GP.Stop(self)
					return toAir(self) -- sequence //prototype_air/air/fall
				end
			elseif g.phase == "exit" then
				-- the soft landing bounce off the body: moveAtVelocity 6 -> 3 m/s, orient 180 °/s
				if t >= 0.1333 and t <= 0.5667 then
					g.v = Lerp((t - 0.1333) / 0.4333, 6, 3)
					slideMove(self, g, dt, 180)
				end
			end
		end
	end

	do -- the flying kick (a block of its own: the main chunk is near Lua's 200 locals) = prototype_air air/actions/
		-- attack/bare/flying_kick (build/graph_air.txt): Attack in the air, once per flight (variable flying_kick, cleared on
		-- landing). windup 0.6667 s (charge Attack): the vertical aim blend alex_kick_air_straight_up / _straight / _down
		-- (+85 / 0 / -85°) 0-6 by the aim - at the auto target, else -45° (down and forward); flyingBrake (horizontal kept
		-- under 3 m/s, rising braked 30 m/s², falling 5 m/s² to at most 2 m/s); autoTarget 900 °/s, 120°, 30 m. release
		-- (Attack let go or the charge full) = flyingAttack, FlyingKickLong (all unlocked): 30 -> 60 m/s for 0.5 -> 0.8333 s
		-- by the charge along the aim, tracking the target at 90 °/s; pose 6-16 / 6-23 then held; the hit 1 m ahead of the
		-- root (1 m, 180°) 35-75 {Crush}, impulse forward 3000 -> 9000, the receiver knocked back 10 m in 0.6667 s, 2 m up;
		-- power_whoosh + alex_sprint + big_ricochet 0.75 + hammer_whoosh 0.36 (pitch 0.6-0.7) and the kick trail. The
		-- ground on the way down: hit_ground - alex_kick_air_straight_ground_impact 5-end, a crush mark, camera shake
		-- fast/heavy, the opening from 0.3333 s. A character: give - a fully charged kick still held on a human near the
		-- floor = man_grind, else alex_kick_air_straight_enemy_impact 1-9 / 8-27 and he drops back off it.
		-- A wall met in the flight / the fall = hit_wall (the foot on it, then he drops).
		-- User override, alex_mercer_fkick_graph 0 and the cannonball's: after the flight (the game: exit 23-42, then the fall) he falls on in the kick pose, the hit still
		-- on, until he lands = hit_ground (user: from high up the kick pose "dropped off"); Ctrl / Alt leave it (air dash /
		-- glide). hit_ground lets movement out from 0.6667 s (the game's opening: 0.3333 s) like the stomp's knee.
		-- (2026-11-04, alex_mercer_fkick_graph 1) as the game: the flight ends by its time (0.5 - 0.8333 s by the charge; a wall, the ground or a hit sooner); exit: flyingBrake 0.3333 s (the horizontal evenly down to 3 m/s,
		-- gravity 10, up 50), no hit, whoosh_small; then the plain fall, in which he can do all he can in a fall. So at most 50 m (35 along, 35 down) + 7.5 m of braking. A landing in the exit: the plain landing by its speed.
		-- Where it goes (the DLL: AutoTargetAction 0x1009a530, FlyingAttackAction 0x100bda10): the target within 120 deg round the CAMERA, 30 m, looked for every tick of the windup and kept; he turns to it at 900 deg/s, led by the
		-- flight's time; none: he turns to where the keys were at the press, and flies 45 deg down that way (the track's 0, -1, -1), the keys steering its yaw at 90 deg/s all through the flight. A wall or the ground clears the kick's
		-- once-per-flight mark and the air dashes (clear_variables), so kick - wall - kick works as in the game.
		local FK = {"alex_kick_air_straight_up", "alex_kick_air_straight", "alex_kick_air_straight_down"}
		-- (user 2026-10-27, clip nOmSGjJf6roSkHfuN, the frame he circled: 0.35 s into the release = the down kick's frame 19)
		-- the down kick plays 6 -> 19 at its own speed (0.357 s) and holds 19 to the landing
		local FK_END = {16, 23, 19}
		local FK_T = {0.4667, 0.4667, 0.4667 * 13 / 17}
		for i, a in ipairs(FK) do
			ALEX_MERCER_GRAPH["mercer/fkick/windup" .. i] = {seg(0, 0.6667, a, 0, 6)}
			ALEX_MERCER_GRAPH["mercer/fkick/release" .. i] = {seg(0, FK_T[i], a, 6, FK_END[i]), seg(FK_T[i], 30, a, FK_END[i], FK_END[i])}
		end
		ALEX_MERCER_GRAPH["mercer/fkick/impact"] = {seg(0, 0.1, "alex_kick_air_straight_enemy_impact", 1, 9),
			seg(0.1, 0.6, "alex_kick_air_straight_enemy_impact", 8, 27)}
		ALEX_MERCER_GRAPH["mercer/fkick/ground"] = {seg(0, 43 / 30, "alex_kick_air_straight_ground_impact", 5, 48)}
		-- (list item 7) give/#026a0fed combo/special (unlockable FlyingKickComboSpecial): Attack during the impact with a
		-- character -> alex_kick_air_straight_enemy_secondary windup 12-20 / 0.6667 s (charge Attack, flyingAutoTarget:
		-- flies at the target at 40 m/s, 720 deg/s, stopping 2 m short), release (Attack let go or the charge full) 20-end:
		-- still homing 0-0.2 s, the hit 0.2-0.2667 s on Ankle_L (0, 0, -0.25) 1 m, 20-50 {Crush}, impulse 1250 -> 5000 up
		-- / 6000 -> 10000 forward; the fall from 0.8333 s
		local SEC = "alex_kick_air_straight_enemy_secondary"
		ALEX_MERCER_GRAPH["mercer/fkick/sec_windup"] = {seg(0, 0.6667, SEC, 12, 20)}
		ALEX_MERCER_GRAPH["mercer/fkick/sec_release"] = {seg(0, 29 / 30, SEC, 20, 49)}
		local SEC_HIT = {0.2, 0.2667, "Ankle_L:0,0,-0.25", 1, 180, 20, 50, Vector(0, 1250, -6000), Vector(0, 5000, -10000),
			cue = "alex_punch_human"}
		-- hit_wall: alex_kick_air_straight_wall_impact 0-29 (the opening to the fall at 0.9 s)
		ALEX_MERCER_GRAPH["mercer/fkick/wall"] = {seg(0, 29 / 30, "alex_kick_air_straight_wall_impact", 0, 29)}
		ALEX_MERCER_GRAPH["mercer/fkick/exit"] = {seg(0, 0.5, "alex_kick_air_straight", 23, 42)}
		-- The cannonball (prototype_devastator air/cannonball: Attack + Action in the air) runs on the same machinery:
		-- windup alex_dev_critical_pain 0-10 over 1 s (charge 1 s, flyingBrake 10 / 5 / 35 / 20, autoTarget 900 °/s, 120°,
		-- 30 m), then cannonball_trans 0-12 (0.1333 s) and the ball alex_dev_critical_pain_cannonball at rate 4, cyclic,
		-- flyingAttack 35 -> 70 m/s for 0.6667 -> 1.167 s by the charge, turning 45 °/s; its hit 1 m ahead of the root, 1 m,
		-- 60-140 {Crush}, impulse 3000 -> 9000 forward; a wall = the kick's hit_wall; a character = the hit, then the
		-- transition alex_dev_critical_pain 65-85 and the fall; the ground = the plain landing. Its full charge with
		-- critical mass = the air Critical Pain (acp). (Its sound -2.768f #5de317d7 doesn't resolve: big_heavy_whoosh.)
		local CP, CB = "alex_dev_critical_pain", "alex_dev_critical_pain_cannonball"
		ALEX_MERCER_GRAPH["mercer/fkick/cannon_windup"] = {seg(0, 1, CP, 0, 10)}
		ALEX_MERCER_GRAPH["mercer/fkick/cannon_release"] = {seg(0, 0.1333, "alex_dev_critical_pain_cannonball_trans", 0, 12),
			{start = 0.1333, stop = -1, anim = CB, rate = 4, f0 = 0, f1 = 30, cyclic = true, part = "", blendin = 0.0333, blendout = 0}}
		ALEX_MERCER_GRAPH["mercer/fkick/cannon_impact"] = {seg(0, 0.6667, CP, 65, 85)}
		-- (2026-11-05, alex_mercer_fkick_graph, as the kick's: "заканчивается как в графе", it went on in its pose down to the ground) graph_devastator 1351, what its sequence goes to from the flight: flyingBrake 0.5 s (3 m/s, gravity 10, up 50), alex_loco_aerial_dash 17-33, the same whoosh at 0.7 - 0.8; no hit; then the plain fall
		ALEX_MERCER_GRAPH["mercer/fkick/cannon_exit"] = {{start = 0, stop = 0.5, anim = "alex_loco_aerial_dash", rate = 1, f0 = 17, f1 = 33, cyclic = false, part = "", blendin = 0.3333, blendout = 0.1333}}
		local CANNON_HIT = {0, 0, "", 1, 180, 60, 140, Vector(0, 0, -3000), Vector(0, 0, -9000), cue = "alex_punch_human"}
		local FK_HIT = {0, 0, "", 1, 180, 35, 75, Vector(0, 0, -3000), Vector(0, 0, -9000), cue = "alex_punch_human",
			react = {human = {t = {0.6667, 0.6667}, d = {10, 10}, h = {2, 2}}, brawler = {t = {0.6667, 0.6667}, d = {10, 10}, h = {2, 2}}}}

		local function fkTarget(self)
			-- autoTarget (air ranged): the nearest character within 120° of his facing and 30 m (the locked one first)
			local lk = self:MercerLocked(60 * M2U)
			if lk then return lk end
			local best, bd
			local pos, fwd = self:WorldSpaceCenter(), self:GetForward()
			local p = self:GetPossessor()
			if IsValid(p) and self.MercerFKickGraph:GetBool() then
				local a = self:MercerAimVector(p)
				a.z = 0
				if a:LengthSqr() > 0.01 then fwd = a:GetNormalized() end
			end
			for _, e in ipairs(ents.FindInSphere(pos, 30 * M2U)) do
				if (e:IsNPC() or e:IsPlayer() or e:IsNextBot()) and fightable(self, e) and not self.MercerNoTarget[e:GetClass()] then
					local to = e:WorldSpaceCenter() - pos
					local flat = Vector(to.x, to.y, 0)
					local d = to:Length()
					if d > 1 and flat:LengthSqr() > 1 and flat:GetNormalized():Dot(fwd) >= 0.5 and (not bd or d < bd) then
						best, bd = e, d
					end
				end
			end
			return best
		end

		function ENT:MercerFKickStart(cannon)
			if self.MercerBullet then return false end -- (user 2026-10-28: nothing cuts the Bullet Dive)
			if self.MercerFKick or (self.MercerFKickUsed and not cannon) then return false end
			if not cannon then self.MercerFKickUsed = true end -- (the flying_kick variable: the kick only)
			self.MercerAirDash = nil -- (the kick cuts the air dash short)
			local st = {phase = "windup", t0 = CurTime(), charge = 0, target = fkTarget(self), aim = -45, cannon = cannon}
			if IsValid(st.target) then
				local to = st.target:WorldSpaceCenter() - self:WorldSpaceCenter()
				st.aim = math.Clamp(math.deg(math.atan2(to.z, to:Length2D())), -85, 45)
			end
			st.k = (st.aim > 42.5 and 1) or (st.aim < -42.5 and 3) or 2
			st.gk = not cannon and self.MercerFKickGraph:GetBool()
			local md = self.MercerMoveDir
			if st.gk and md and not md:IsZero() then st.faceYaw = md:Angle().y end
			self.MercerFKick = st
			self:MercerVO("alex_throw", 1) -- (air/actions/attack/bare/flying_kick)
			self.MercerFallSpeed = 0 -- (the brake: the landing is graded from here)
			self:MercerCombatEvent()
			if cannon then
				GP.Start(self, "mercer/fkick/cannon_windup", {block = true, hold = true})
				self:SetNW2String("MercerHoldJoint", "Wrist_L")
				self:SetNW2String("MercerHoldFx", "charge_bare_l_hand") -- charge/bare/punch/l_hand
				return true
			end
			GP.Start(self, "mercer/fkick/windup" .. st.k, {block = true, hold = true})
			self:SetNW2String("MercerHoldJoint", "Ankle_R")
			self:SetNW2String("MercerHoldFx", "charge_bare_r_foot") -- charge/bare/kick/r_foot
			return true
		end

		function ENT:MercerFKickEnd()
			if not self.MercerFKick then return end
			self.MercerFKick = nil
			self:SetNW2Bool("MercerFKickOn", false)
			self.loco:SetGravity(1000)
			self:SetNW2String("MercerHoldJoint", "")
			self:SetNW2String("MercerHoldFx", "")
			-- (the air drift measures from what he has now, not the jump's take-off: that would bring its speed back)
			if self.MercerFKickGraph:GetBool() then self.MercerAirBase = nil end
		end

		local function release(self, st)
			st.phase, st.t0, st.hit = "release", CurTime(), {}
			st.speed = (st.cannon and Lerp(st.charge, 35, 70) or Lerp(st.charge, 30, 60)) * M2U
			st.dur = st.cannon and Lerp(st.charge, 0.6667, 1.167) or Lerp(st.charge, 0.5, 0.8333)
			local yaw, pitch = math.rad(self:GetAngles().y), math.rad(st.aim)
			-- (player 2026-10-28: moving targets) at the locked one: launched at where it will be when he gets there (the kick by the graph: any target, the DLL leads it by the flight's speed)
			if IsValid(st.target) and ((st.gk and fightable(self, st.target)) or (self.MercerLockOn and st.target == self:MercerLocked())) then
				local me = self:WorldSpaceCenter()
				local _, c = self:MercerLead(st.target, st.target:WorldSpaceCenter():Distance(me) / st.speed)
				local to = c - me
				if to:Length2D() > 1 then
					local up = math.deg(math.atan2(to.z, to:Length2D()))
					yaw = math.rad(to:Angle().y)
					pitch = math.rad(st.gk and up or math.Clamp(up, -85, 45))
					self:SetAngles(Angle(0, math.deg(yaw), 0))
					if st.gk then
						-- (a target found in the windup: the pose by its angle)
						st.aim = math.Clamp(up, -85, 45)
						st.k = (st.aim > 42.5 and 1) or (st.aim < -42.5 and 3) or 2
					end
				end
			end
			st.dir = Vector(math.cos(yaw) * math.cos(pitch), math.sin(yaw) * math.cos(pitch), math.sin(pitch))
			self:SetNW2String("MercerHoldJoint", "")
			self:SetNW2String("MercerHoldFx", "")
			if st.cannon then
				GP.Start(self, "mercer/fkick/cannon_release", {block = true, hold = true})
				self:MercerTrail("fall") -- motiontrails/fall/ground_pound
				self:MercerCue("big_heavy_whoosh", 0.46, 0.45)
				self:MercerCue("power_whoosh")
				return
			end
			GP.Start(self, "mercer/fkick/release" .. st.k, {block = true, hold = true})
			self:MercerTrail("kick_r")
			self:MercerCue("power_whoosh")
			self:MercerCue("alex_sprint")
			self:MercerCue("big_ricochet", 0.75, 0.65)
			self:MercerCue("hammer_whoosh", 0.36, 0.65)
		end

		local contact
		-- hit_wall (supportingLimbTest during the release: a face 60-120° from up, met while moving into it within a
		-- 135° arc): world brushes only - characters are the hit's
		local COS_ARC = math.cos(math.rad(67.5))
		local function wallAhead(self, dir, dist)
			local hv = Vector(dir.x, dir.y, 0)
			if hv:LengthSqr() < 0.04 then return end
			hv:Normalize()
			local start = self:GetPos() + Vector(0, 0, 40)
			local tr = util.TraceHull({start = start, endpos = start + hv * (dist + 16), mins = Vector(-12, -12, -20),
				maxs = Vector(12, 12, 20), filter = self, mask = MASK_SOLID_BRUSHONLY})
			if tr.Hit and not tr.StartSolid and math.abs(tr.HitNormal.z) < 0.5 and hv:Dot(-tr.HitNormal) > COS_ARC then
				return tr
			end
		end
		-- the foot on the wall: the climb limb holds him there until 0.75 s, then the ground limb (he drops); camera
		-- shake fast/heavy, the impact sound at 0 and 0.5 s (#96ece48f: not resolved - alex_land_heavy), a crush mark
		local function hitWall(self, st, tr)
			st.phase, st.t0 = "wall", CurTime()
			self:SetAngles(Angle(0, (-tr.HitNormal):Angle().y, 0))
			self.loco:SetGravity(0)
			self.loco:SetVelocity(Vector(0, 0, 0))
			GP.Start(self, "mercer/fkick/wall", {block = true, hold = true})
			self:MercerDecal("AlexMercerCrush15", tr.HitPos + tr.HitNormal * 4, tr.HitPos - tr.HitNormal * 16, self)
			self:MercerVFX("land_heavy", tr.HitPos + tr.HitNormal * 2, tr.HitNormal)
			self:MercerShake("medium", "large")
			self:MercerCue("alex_land_heavy")
			self:Timer(0.5, function(ent) ent:MercerCue("alex_land_heavy", 0.7) end)
			if st.gk then self.MercerFKickUsed, self.MercerAirDashes = nil, nil end -- (hit_wall: execute clear_variables)
		end

		-- the hit item (the whole release node): 1 m ahead of the root (Motion_Root 1 m up), 1 m
		local function strike(self, st, p)
			local c = self:GetPos() + Vector(0, 0, M2U) + st.dir * M2U
			for _, e in ipairs(ents.FindInSphere(c, M2U + 40)) do
				if not st.hit[e] and fightable(self, e) and nearestOn(e, c):Distance(c) <= M2U then
					st.hit[e] = true
					if e:IsNPC() or e:IsPlayer() or e:IsNextBot() then
						contact(self, st, e, c, p)
						return true
					end
					self:MercerFightDamage(e, st.cannon and CANNON_HIT or FK_HIT, st.charge, c)
				end
			end
		end

		-- store give: man_grind (a full charge still held on a human, near the floor: the ride is on the ground) or the
		-- hit and the drop back off it
		function contact(self, st, e, c, p)
			if st.cannon then
				-- the cannonball's give: the hit, then its transition (critical_pain 65-85) off him
				self:MercerFightDamage(e, CANNON_HIT, st.charge, c)
				st.phase, st.t0 = "impact", CurTime()
				self.loco:SetGravity(1000)
				self.loco:SetVelocity(-st.dir * (3 * M2U) + Vector(0, 0, 4 * M2U))
				GP.Start(self, "mercer/fkick/cannon_impact", {block = true, hold = true})
				self:MercerShake("small", "medium")
				return
			end
			local held = IsValid(p) and (p:KeyDown(IN_ATTACK) or p:KeyDown(IN_ATTACK2))
			local floor = util.TraceLine({start = self:GetPos() + Vector(0, 0, 4), endpos = self:GetPos() - Vector(0, 0, 3 * M2U),
				filter = self, mask = MASK_SOLID_BRUSHONLY})
			if st.charge >= 1 and held and floor.Hit and self.MercerGrindStart then
				self:MercerFKickEnd()
				if self:MercerGrindStart({moveV = math.min(st.speed / M2U, 20)}, e) then return end
				self.MercerFKick = st
			end
			self:MercerFightDamage(e, FK_HIT, st.charge, c)
			st.phase, st.t0, st.victim = "impact", CurTime(), e
			self.loco:SetGravity(1000)
			self.loco:SetVelocity(-st.dir * (3 * M2U) + Vector(0, 0, 4 * M2U))
			GP.Start(self, "mercer/fkick/impact", {block = true, hold = true})
		end

		-- flyingBrake as the DLL has it (0x100be3f0, 0x100be700): at its start the horizontal's way down to velocityXZ is shared out evenly over its time, and a fall past the terminal the same; else gravity / gravityUp a tick
		local function brakeBegin(st, vel, xz, term, T)
			local hs = Vector(vel.x, vel.y, 0):Length()
			local k = hs > 0 and math.min(xz * M2U, hs) / hs or 1
			st.brX, st.brY = (vel.x * k - vel.x) / T, (vel.y * k - vel.y) / T
			st.brZ = (term >= 0 and vel.z < -term * M2U) and (-term * M2U - vel.z) / T or nil
		end
		local function brakeTick(self, st, dt, g, gUp, term)
			local vel = self.loco:GetVelocity()
			local z = st.brZ and vel.z + st.brZ * dt or vel.z - (vel.z > 0 and gUp or g) * M2U * dt
			if not st.brZ and term >= 0 then z = math.max(z, math.min(vel.z, -term * M2U)) end
			self.loco:SetGravity(0)
			self.loco:SetVelocity(Vector(vel.x + st.brX * dt, vel.y + st.brY * dt, z))
		end

		-- (user 2026-11-05: "Людей на которых таргетлок есть", "Ещё пусть по графам игры сделает все") E with a target: the game has it in one place, combo/grab after the kick's hit (graph_air 1336-1362): E pressed,
		-- the auto target a human, not the Super Soldier: alex_weap_2hnd_grab_car 0-18 in 0.4 s, flyingAutoTarget 40 m/s, 720 deg/s, at 0.75 m over its feet, up to 50 m, then node {human} (1386). There it is here too, the "impact" phase.
		-- The game has no pull for a plain E in a fall, a jump or a dash: there its only reach is the sphere. BY EYE, asked for: this same flight from any E pressed in the air with a man locked, up to the data's 50 m and for as long as that takes
		-- (1.25 s; in the game 0.1 s, it is next to him); its 0.5 m round a point along the flight, as in the kick's, for its 1 m ahead of him: from above that one can't touch a man under him.
		-- Missed (gone, dead, a wall, out of time): its 18-24 at 6 m/s (1349, 1351). The whoosh is by eye too, the node has no sound
		ALEX_MERCER_GRAPH["mercer/fkick/lunge"] = {seg(0, 0.4, "alex_weap_2hnd_grab_car", 0, 18), seg(0.4, 30, "alex_weap_2hnd_grab_car", 18, 18)}
		ALEX_MERCER_GRAPH["mercer/air_grab/miss"] = {seg(0, 0.2, "alex_weap_2hnd_grab_car", 18, 24)}
		function ENT:MercerAirLunge(e)
			local st = self.MercerFKick
			if not st then
				st = {hit = {}, charge = 0, gk = true}
				self.MercerFKick = st
			end
			st.phase, st.t0, st.target, st.dir, st.reach = "lunge", CurTime(), e, self:GetForward(), false
			self.MercerFallSpeed = 0
			self:MercerCombatEvent()
			self:MercerCue("whoosh_small")
			GP.Start(self, "mercer/fkick/lunge", {block = true, hold = true})
		end
		function ENT:MercerAirLungeMiss()
			dbg("air_grab: the flight missed")
			self:MercerFKickEnd()
			self.MercerFallSpeed = 0
			local v = self:GetForward() * (6 * M2U)
			self.MercerAirBase = Vector(v.x, v.y, 0)
			self.loco:SetVelocity(v)
			GP.Start(self, "mercer/air_grab/miss", {onDone = toAir})
		end
		-- (graph_air 928-941, 1496-1503) E down in the flight and the exit: the reach's pose, let go the kick's own again; true: taken, the kick is over (MercerAirGrabThink)
		function ENT:MercerFKickReach(st, p, reachNode, ownNode)
			local reach = st.gk and IsValid(p) and self:MercerAirGrabDown(p) and self.MercerAirGrabOn:GetBool()
			if reach ~= (st.reach or false) then
				st.reach = reach
				GP.Start(self, reach and reachNode or ownNode, {block = true, hold = true})
			end
			if reach then self:MercerAirGrabThink(self.MercerNode, true) end
			return not self.MercerFKick
		end

		function ENT:MercerFKickThink(p, dt)
			local st = self.MercerFKick
			local node = self.MercerNode
			if not node or string.sub(node.path, 1, 13) ~= "mercer/fkick/" then return self:MercerFKickEnd() end
			local t = CurTime() - st.t0
			local use = st.gk and IsValid(p) and p:KeyDown(IN_USE)
			local usePressed = use and st.useWas == false and self.MercerAirGrabOn:GetBool()
			st.useWas = use
			-- (the flying kick hunt, 2026-10-27) every 0.1 s: what the server sets (pairs with the client trace)
			self:SetNW2Bool("MercerFKickOn", true)
			if CurTime() - (st.dbgT or 0) >= 0.1 then
				st.dbgT = CurTime()
				local v = self.loco:GetVelocity()
				dbg("fkick %s t=%.2f node=%s seq=%s cyc=%.3f rate=%.2f vz=%.0f vh=%.0f ground=%s", st.phase, t, node.path,
					self:GetSequenceName(self:GetSequence()), self:GetCycle(), self:GetPlaybackRate(), v.z, v:Length2D(),
					tostring(self:IsOnGround()))
			end
			self.MercerFallSpeed = math.max(self.MercerFallSpeed or 0, -self.loco:GetVelocity().z)
			if st.phase == "windup" then
				if st.gk and not IsValid(st.target) then st.target = fkTarget(self) end
				if IsValid(st.target) then
					local to = st.target:GetPos() - self:GetPos()
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, to:Angle().y, 900 * dt), 0))
					if st.gk then self:MercerLead(st.target, 0) end -- (its speed measured from here, for the lead at the release)
				elseif st.faceYaw then
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, st.faceYaw, 900 * dt), 0))
				end
				if st.gk then
					-- its two flyingBrakes: 0 - 0.1667 s and to 0.6667 s, 3 m/s, gravity 5, up 30, terminal 2
					if not st.brStage or (st.brStage == 1 and t >= 0.1667) then
						st.brStage = (st.brStage or 0) + 1
						brakeBegin(st, self.loco:GetVelocity(), 3, 2, st.brStage == 1 and 0.1667 or 0.5)
					end
					brakeTick(self, st, dt, 5, 30, 2)
				else
					-- flyingBrake (the kick: 3 / 5 / 30 / 2; the cannonball: 10 / 5 / 35 / 20)
					local xz, up, term = 3, 30, 2
					if st.cannon then xz, up, term = 10, 35, 20 end
					local vel = self.loco:GetVelocity()
					local hv = Vector(vel.x, vel.y, 0)
					local hs = hv:Length()
					if hs > xz * M2U then hv = hv * (math.max(xz * M2U, hs - 60 * M2U * dt) / hs) end
					local vz = vel.z > 0 and math.max(0, vel.z - up * M2U * dt) or math.max(-term * M2U, vel.z - 5 * M2U * dt)
					self.loco:SetGravity(0)
					self.loco:SetVelocity(Vector(hv.x, hv.y, vz))
				end
				st.charge = math.min(1, t / (st.cannon and 1 or 0.6667))
				local held = IsValid(p) and p:KeyDown(IN_ATTACK) and (not st.cannon or p:KeyDown(IN_USE))
				if not IsValid(p) then held = t < 0.4 end
				-- (user 2026-11-05: "конфликты ... с девастатором", the user's alex_mercer_devastator_free 1, so a ball held for its full charge never left) the cannonball's devastator bank, the air Critical Pain: the graph at the full charge, BY EYE 0.5 s more, so a full ball can be let go from 1 to 1.5 s. No devastator to give: off at the full charge, as the graph
				local canDev = st.cannon and held and self:MercerCanDevastate()
				if canDev and t >= self.MercerBallDevT then
					self:MercerFKickEnd()
					return self:MercerFightStart("acp", 1)
				end
				-- (graph_air 882: Action pressed lets it go too)
				if (not held and t > 0.05) or (st.charge >= 1 and not canDev) or usePressed then release(self, st) end
			elseif st.phase == "release" then
				if self:MercerFKickReach(st, p, "mercer/fkick/reach", "mercer/fkick/release" .. st.k) then return end
				-- flyingAttack: along the aim, turning toward the target at 90 °/s
				local want, rate
				if IsValid(st.target) and fightable(self, st.target) then
					-- (player 2026-10-28: the Cannonball misses moving targets) at the locked one: where it will be when
					-- he gets there (his flight speed), and turning twice the graph's rate; unlocked: as the game
					local locked = self.MercerLockOn and st.target == self:MercerLocked()
					local aimAt = st.target:WorldSpaceCenter()
					if locked or st.gk then
						local _, c = self:MercerLead(st.target, aimAt:Distance(self:WorldSpaceCenter()) / math.max(st.speed, 1))
						aimAt = c
					end
					want = (aimAt - self:WorldSpaceCenter()):GetNormalized()
					rate = (st.cannon and 45 or 90) * (locked and 2 or 1)
				elseif st.gk then
					-- no target: the keys turn its yaw at the same rate, its angle down stays
					local md = self.MercerMoveDir
					local y = (md and not md:IsZero()) and md:Angle().y or Vector(st.dir.x, st.dir.y, 0):Angle().y
					want, rate = Angle(-st.aim, y, 0):Forward(), 90
				end
				if want then
					local ang = math.acos(math.Clamp(st.dir:Dot(want), -1, 1))
					if ang > 1e-3 then
						st.dir = (st.dir + (want - st.dir) * math.min(1, math.rad(rate) * dt / ang)):GetNormalized()
					end
					if math.abs(st.dir.x) + math.abs(st.dir.y) > 0.01 then
						self:SetAngles(Angle(0, Vector(st.dir.x, st.dir.y, 0):Angle().y, 0))
					end
				end
				-- (the graph: its wall test from 0.1 s, its hit from 0.0333 s)
				local wall = (not st.gk or t >= 0.1) and wallAhead(self, st.dir, st.speed * dt)
				if wall then return hitWall(self, st, wall) end
				self.loco:SetGravity(0)
				self.loco:SetVelocity(st.dir * st.speed)
				if (not st.gk or t >= 0.0333) and strike(self, st, p) then return end
				if t >= st.dur then
					if st.gk or (st.cannon and self.MercerFKickGraph:GetBool()) then
						st.phase, st.t0, st.reach = "exit", CurTime(), false
						st.exitT = st.cannon and 0.5 or 0.3333
						brakeBegin(st, st.dir * st.speed, 3, -1, st.exitT)
						GP.Start(self, st.cannon and "mercer/fkick/cannon_exit" or "mercer/fkick/exit", {block = true, hold = true})
						self:MercerCue("whoosh_small", 0.5686, 0.75)
					else
						-- the flight is over: on in the kick pose under gravity, the momentum kept (user override, above)
						st.phase, st.t0 = "fall", CurTime()
						self.loco:SetGravity(1000)
					end
				end
			elseif st.phase == "exit" then
				if self:MercerFKickReach(st, p, "mercer/fkick/exit_reach", "mercer/fkick/exit") then return end
				brakeTick(self, st, dt, 10, 50, -1)
				if self:IsOnGround() or t >= st.exitT then
					self:MercerFKickEnd()
					GP.Stop(self)
					return toAir(self)
				end
			elseif st.phase == "fall" then
				local game = ALEX_MERCER_GAME_AIR_KEYS:GetBool()
				-- (with the game's keys a fresh Shift press only: Shift held on from the sprint is no dash)
				if IsValid(p) and (game and self.MercerDashPressed
					or not game and (p:KeyDown(IN_DUCK) or p:KeyDown(IN_WALK))) then
					-- Ctrl = the air dash, Alt = the glide (the air logic takes over this same tick); the game's air keys:
					-- Shift = the dash (held on: the glide)
					self:MercerFKickEnd()
					GP.Stop(self)
					if game or p:KeyDown(IN_DUCK) then
						self:MercerAirDashStart()
						self.MercerDashPressed = nil -- (the air logic this same tick: no second dash)
					end
					return
				end
				local vel = self.loco:GetVelocity()
				if vel:Length2D() > 3 * M2U then
					local wall = wallAhead(self, vel, vel:Length2D() * dt)
					if wall then return hitWall(self, st, wall) end
				end
				if vel.z < -FALL_MAX then self.loco:SetVelocity(Vector(vel.x, vel.y, -FALL_MAX)) end -- fall maxVelocity
				if strike(self, st, p) then return end
				if self:IsOnGround() and t > 0.1 then
					-- (settled without a landing event)
					if not self:MercerFKickLand(self.MercerFallSpeed or 0) then
						GP.Stop(self)
						self:UpdateAnimation()
					end
				end
			elseif st.phase == "wall" then
				if t < 0.75 then
					self.loco:SetGravity(0)
					self.loco:SetVelocity(Vector(0, 0, 0))
				else
					self.loco:SetGravity(1000)
				end
				if t >= 0.9 then
					self:MercerFKickEnd()
					GP.Stop(self)
					return toAir(self)
				end
			elseif st.phase == "lunge" then
				local e = st.target
				local me = self:GetPos()
				local aim = IsValid(e) and self:MercerGrabbable(e) and t < 1.25 and self:MercerLead(e, e:GetPos():Distance(me) / (40 * M2U)) + Vector(0, 0, 0.75 * M2U)
				if not aim then return self:MercerAirLungeMiss() end
				st.dir = (aim - me):GetNormalized()
				if wallAhead(self, st.dir, 40 * M2U * dt) then return self:MercerAirLungeMiss() end
				if math.abs(st.dir.x) + math.abs(st.dir.y) > 0.01 then
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, st.dir:Angle().y, 720 * dt), 0))
				end
				self.loco:SetGravity(0)
				self.loco:SetVelocity(st.dir * (40 * M2U))
				self:MercerAirGrabThink(node, true)
			elseif st.phase == "impact" and usePressed and self:MercerGrabbable(self:MercerLocked(50 * M2U) or st.victim) then
				-- combo/grab: the auto target, here the lock's, else who the kick hit
				self:MercerAirLunge(self:MercerLocked(50 * M2U) or st.victim)
			elseif st.phase == "impact" and not st.cannon and IsValid(p) and IsValid(st.victim) and fightable(self, st.victim)
				and self:MercerKeyPressed(p, IN_ATTACK) then
				-- the combo's special: the secondary kick
				st.phase, st.t0, st.charge, st.hit = "sec_windup", CurTime(), 0, {}
				GP.Start(self, "mercer/fkick/sec_windup", {block = true, hold = true})
				self:SetNW2String("MercerHoldJoint", "Ankle_L")
				self:SetNW2String("MercerHoldFx", "charge_bare_l_foot")
				self:MercerCue("whoosh_small")
			elseif st.phase == "sec_windup" or st.phase == "sec_release" then
				local e = st.victim
				local homing = st.phase == "sec_windup" or t < 0.2
				if homing and IsValid(e) then
					local to = e:WorldSpaceCenter() - self:WorldSpaceCenter()
					local want = to:Angle().y
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, want, 720 * dt), 0))
					self.loco:SetGravity(0)
					self.loco:SetVelocity(to:Length() > 2 * M2U and to:GetNormalized() * (40 * M2U) or Vector(0, 0, 0))
				elseif st.phase == "sec_release" and t >= 0.8333 then
					self.loco:SetGravity(1000)
				else
					self.loco:SetGravity(0)
					self.loco:SetVelocity(Vector(0, 0, 0))
				end
				if st.phase == "sec_windup" then
					st.charge = math.min(1, t / 0.6667)
					if (not (IsValid(p) and p:KeyDown(IN_ATTACK)) and t > 0.05) or st.charge >= 1 then
						st.phase, st.t0 = "sec_release", CurTime()
						GP.Start(self, "mercer/fkick/sec_release", {block = true, hold = true})
						self:SetNW2String("MercerHoldJoint", "")
						self:SetNW2String("MercerHoldFx", "")
						self:MercerTrail("kick_r")
						self:MercerCue("power_whoosh")
					end
				else
					if t >= SEC_HIT[1] and t <= SEC_HIT[2] + FrameTime() then
						local anim, cycle = GP.Sample(self)
						if anim then
							local frame = cycle * ((ALEX_MERCER_FRAMES[string.lower(anim)] or 2) - 1)
							local c = self:LocalToWorld(jointLocal(string.lower(anim), SEC_HIT[3], frame))
							for _, e2 in ipairs(ents.FindInSphere(c, M2U + 40)) do
								if not st.hit[e2] and fightable(self, e2) and nearestOn(e2, c):Distance(c) <= M2U then
									st.hit[e2] = true
									self:MercerFightDamage(e2, SEC_HIT, st.charge, c)
								end
							end
						end
					end
					if t >= GP.Duration(node.path) then
						self:MercerFKickEnd()
						GP.Stop(self)
						return toAir(self)
					end
				end
			elseif t >= GP.Duration(node.path) then
				-- impact / ground: done
				self:MercerFKickEnd()
				GP.Stop(self)
				return toAir(self)
			end
		end

		-- landing during the kick: hit_ground on the way down (the release) or in the fall after it, else the plain landing
		function ENT:MercerFKickLand(speed)
			local st = self.MercerFKick
			-- (MercerBallLand) the ball's bank {land}: the flight's own speed down, the windup's the flight it lets go at the touch (its release: "or supportingSurface"), 45 deg by flyingAttack; under 5 m/s, or from its exit or a blow, the plain landing, as the graph's
			if st.cannon and self.MercerBallLand:GetBool() and (st.phase == "release" or st.phase == "windup" or st.phase == "fall") then
				local v = speed / M2U
				if st.phase == "release" then v = -st.dir.z * st.speed / M2U
				elseif st.phase == "windup" then v = 0.7071 * Lerp(st.charge or 0, 35, 70) end
				if v >= 5 then
					local charge = st.charge or 0
					self:MercerFKickEnd()
					local f = self:MercerFightStart("gpdl", charge)
					if f then
						f.landV, f.ball = v, true
						return true
					end
					return false
				end
			end
			if st.cannon or not (st.phase == "fall" or (st.phase == "release" and st.dir.z <= -0.05)) then
				self:MercerFKickEnd()
				return false
			end
			st.phase, st.t0 = "ground", CurTime()
			self.loco:SetGravity(1000)
			GP.Start(self, "mercer/fkick/ground", {block = true, hold = true, exitAfter = 0.3333})
			local pos = self:GetPos()
			self:MercerDecal("AlexMercerCrush15", pos + Vector(0, 0, 10), pos - Vector(0, 0, 30), self)
			self:MercerVFX("land_heavy", pos + Vector(0, 0, 2))
			self:MercerShake("medium", "large") -- camera_shake fast/heavy
			self:MercerCue("alex_land_heavy")
			return true
		end
	end

	do -- the shield (a block of its own: the main chunk is near Lua's 200 locals). The game (build/graph_prototype.txt
		-- loco / idles banks {shield}, store {shield}; graph_hitreaction.txt store {shield}): with the shield power the
		-- shield is deployed (shieldDeploy) whenever he stands or moves - not in attacks - and protects the front
		-- (shieldProtecting): a hit there = the shield reaction (alex_shield_impact 0-end at rate 1, pushback 10 m/s away
		-- from the attacker for 0.2 s, exits from 0.1 s, sparks), bullets bounce off (shieldReflect: running = back at the
		-- shooter, standing / walking = away), the shield takes the damage (shieldHealth: damage states at 0.6 / 0.3) and
		-- breaks (break: shieldSetState Healing, a knockback, the shield's damage effects) - then heals. The shield's
		-- health and healing numbers are not in the extracted data: ours - 1000 damage, healing 200 / s 2 s after the last
		-- hit (the graph's 2 s shield timer), broken for 6 s (the shield hidden: its own material alex_shield_c).
		local SHIELD_HP, SHIELD_WAIT, SHIELD_REGEN, SHIELD_BROKEN = 1000, 2, 200, 6
		ALEX_MERCER_GRAPH["mercer/shield_hit"] = {seg(0, 0.3333, "alex_shield_impact", 0, 10)}
		-- (2026-10-08 rework, the user: the shield's anims / the whole thing rough) the held poses from the graph:
		--  idles bank {shield} (shieldProtecting, the shield timer #352407b6 - set for 2 s by a hit on the shield): the guard
		--   alex_shield_impact 9-10 at 0.2 (held up), movement leaves it
		--  loco bank {shield} (the timer, not targeting): alex_shield_run_n 0-1 held, upper body over the run
		--  sprint {shield} (always with the shield): alex_shield_sprint_n cycling, upper body
		--  the shield reaction (hitreaction prototype shield): alex_shield_impact 0-end at rate 1 - on the move upper body
		ALEX_MERCER_GRAPH["mercer/shield_guard"] = {{start = 0, stop = -1, anim = "alex_shield_impact", rate = 0.2, f0 = 9,
			f1 = 10, cyclic = true, part = "", blendin = 0.1, blendout = 0.1667}}
		local GUARD_T = 2
		local INVISIBLE = "alex_mercer/fx/invisible"

		local function shieldState(self)
			local sh = self.MercerShieldSt
			if not sh then
				sh = {hp = SHIELD_HP, lastHit = 0}
				self.MercerShieldSt = sh
			end
			return sh
		end

		-- shieldDeploy runs in the stand / loco / shield reaction nodes only (not in attacks, grabs, the wall)
		local function protecting(self)
			if not self:MercerShieldOut() or self:GetNW2Bool("MercerShieldDown") then return false end
			if self.MercerFight or self.MercerFKick or self.MercerStomp or self.MercerElbow or self.MercerHToss
				or self.MercerGrab or self.MercerGrind or self.MercerClawSpike or self.MercerDive then return false end
			return not self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerGlide")
		end
		ENT.MercerShieldProtecting = protecting

		local function shieldMaterial(self)
			for i, m in ipairs(self:GetMaterials() or {}) do
				if string.find(m, "alex_shield_c", 1, true) then return i - 1 end
			end
		end

		local function setBroken(self, broken)
			self:SetNW2Bool("MercerShieldDown", broken)
			local i = shieldMaterial(self)
			if i then self:SetSubMaterial(i, broken and INVISIBLE or "") end
		end

		-- (user 2026-11-03: "a quick shield as in the game; the shield can be used with other mutations") the game's defence
		-- slot: transformationSlot Defense next to Attack (prototype_consume transform/defense: its key tapped = the quick
		-- transform, the wave and no anim; prototype long_transformation/defense/shield = the showcase), and its firearm
		-- bank: over a gun too. Worn over whatever is out: the client draws it (NW2 MercerShieldShown, ENT:MercerShieldDraw)

		-- out while deployed (shieldDeploy: the stand and the loco), back in for attacks, grabs, the wall: the game's
		-- shield/effects cover it - deploy (5 biomass bursts round the left shoulder, transform_short 0.427 at 1.5 - 1.7),
		-- retract (down the left arm). 0.12 s before it comes out: between two strikes it stays in
		local function slotThink(self, sh)
			local on = self:GetNW2Bool("MercerShieldOn")
			if on and not self.MercerShieldSlot:GetBool() then
				self:SetNW2Bool("MercerShieldOn", false)
				on = false
			end
			local now = CurTime()
			local want = on and protecting(self) and not self:GetNW2Bool("MercerDisguised")
			if not want then
				sh.upSince = nil
			elseif not sh.upSince then
				sh.upSince = now
			end
			local show = want and now >= math.max(sh.upSince + 0.12, sh.showT or 0) or false
			if show == (sh.shown or false) then return end
			sh.shown = show
			self:SetNW2Bool("MercerShieldShown", show)
			if on and not self:GetNW2Bool("MercerShieldDown") then
				self:MercerFxProg({{show and "shield_deploy" or "shield_retract", 0}})
				if show then self:MercerCue("transform_short", 0.427, 1.6) end
			end
		end

		function ENT:MercerSetShield(on, animate)
			if on == self:GetNW2Bool("MercerShieldOn") then return end
			if on then self:MercerDisguiseOffSeen() end
			self:SetNW2Bool("MercerShieldOn", on)
			local f = FORMS[ALEX_MERCER_SHIELD]
			local long = animate and on and coroutine.running() ~= nil
			self:MercerTransformFx(f.name, long)
			self:MercerTransformSfx(f.name, long)
			if not long then return end
			-- (the node's shieldDeploy at 3.167 s; the showcase anim starts at its 2.433 s)
			shieldState(self).showT = CurTime() + 0.734
			self:MercerVO("alex_strength", 1)
			self.MercerTransforming = true
			self:PlaySequenceAndWait(f.transform, 1)
			self.MercerTransforming = nil
		end

		-- the shield reaction may cut a hit reaction / another shield reaction short, not other blocking nodes
		local function canReact(self)
			local n = self.MercerNode
			return not (n and n.opts.block and not GP.CanExit(self)) or string.sub(n.path, 1, 11) == "mercer/hit/"
				or n.path == "mercer/shield_hit"
		end

		function ENT:MercerShieldBlock(dmg, amount, attacker)
			if not protecting(self) or not IsValid(attacker) or attacker == self then return amount end
			local fwd = self:GetForward()
			local to = attacker:WorldSpaceCenter() - self:WorldSpaceCenter()
			to.z = 0
			if to:IsZero() or to:GetNormalized():Dot(fwd) < 0.2 then return amount end -- not from the front
			local sh = shieldState(self)
			sh.hp, sh.lastHit = sh.hp - amount, CurTime()
			sh.guardUntil = CurTime() + GUARD_T -- (timerSet 2 s: the shield held up)
			local pos = self:WorldSpaceCenter() + fwd * 20 + Vector(0, 0, 10)
			self:MercerEffect("alex_mercer_block", pos, 1)
			if sh.hp <= 0 then
				-- break: the shield goes (healing), a knockback
				sh.brokenUntil = CurTime() + SHIELD_BROKEN
				setBroken(self, true)
				self:MercerCue("bonebreak")
				self:MercerCue("impact_thump")
				sh.push = {t0 = CurTime(), dur = 0.5, dir = -to:GetNormalized(), v = 6 / 0.5 * M2U}
				if self:IsOnGround() and canReact(self) then
					GP.Start(self, "mercer/shield_hit", {block = true, exitAfter = 0.1, onDone = function(ent) ent:UpdateAnimation() end})
				end
				return 0
			end
			if dmg:IsBulletDamage() then
				-- shieldReflect: the bullet bounces off; on the run it flies back at the shooter
				if CurTime() - (sh.ricT or 0) > 0.08 then
					sh.ricT = CurTime()
					self:MercerCue("ricochet_generic")
				end
				if self:GetVelocity():Length2D() > 4 * M2U and not self.MercerReflecting then
					self.MercerReflecting = true
					local aim = (attacker:WorldSpaceCenter() - pos):GetNormalized()
					self:FireBullets({Attacker = self, Inflictor = self, Damage = amount, Num = 1, Src = pos, Dir = aim,
						Spread = Vector(0.03, 0.03, 0), Tracer = 1, TracerName = "Tracer", Force = 2,
						IgnoreEntity = self})
					self.MercerReflecting = nil
				end
				return 0
			end
			-- a blow / blast on the shield: the reaction, pushed back (on the move: upper body over the run)
			self:MercerCue("impact_thump")
			sh.push = {t0 = CurTime(), dur = 0.2, dir = -to:GetNormalized(), v = 10 * M2U}
			local moving = self:GetVelocity():Length2D() > 2 * M2U
			if moving and self:IsOnGround() and not self.MercerNode then
				self:MercerUpperLayer("alex_shield_impact", 0, 1, nil, 0.1667)
			elseif self:IsOnGround() and canReact(self) then
				GP.Start(self, "mercer/shield_hit", {block = true, exitAfter = 0.1, onDone = function(ent) ent:UpdateAnimation() end})
			end
			return 0
		end

		-- the held pose as one persistent upper-body layer, faded in / out (0.1 s)
		local function poseWanted(self, sh)
			if not self:MercerShieldOut() or not protecting(self) or not self:IsOnGround() then return nil end
			if self.MercerSprintOn then return "alex_shield_sprint_n" end
			if self:GetVelocity():Length2D() > 2 * M2U and CurTime() < (sh.guardUntil or 0)
				and not IsValid(self:GetNW2Entity("MercerLock")) then return "alex_shield_run_n" end
		end
		local function poseLayer(self, sh, dt)
			local want = poseWanted(self, sh)
			local L = sh.layer
			if L and (not self:IsValidLayer(L.id) or self:GetLayerSequence(L.id) ~= L.seq) then
				sh.layer, L = nil, nil
			end
			if L and L.anim ~= want then
				L.w = L.w - dt / 0.1
				if L.w <= 0 then
					self:MercerKillLayer(L.id)
					sh.layer, L = nil, nil
				else
					self:SetLayerWeight(L.id, L.w)
				end
			end
			if not L and want then
				local seq = self:LookupSequence(want .. "_upper")
				if not seq or seq < 0 then return end
				local id = self:AddGestureSequence(seq, false)
				if not id or id < 0 then return end
				self:SetLayerLooping(id, true)
				self:SetLayerWeight(id, 0)
				L = {id = id, seq = seq, anim = want, w = 0}
				sh.layer = L
			end
			if L and L.anim == want then
				L.w = math.min(1, L.w + dt / 0.1)
				self:SetLayerWeight(L.id, L.w)
				if want == "alex_shield_run_n" then
					-- (0-1 held: the shield up in front)
					self:SetLayerPlaybackRate(L.id, 0)
					self:SetLayerCycle(L.id, 0.5 / 23)
				else
					self:SetLayerPlaybackRate(L.id, 1)
				end
			end
		end
		-- the guard standing under fire: the shield timer running, still, nothing else playing
		local function guard(self, sh)
			local nd = self.MercerNode and self.MercerNode.path
			local md = self.MercerMoveDir
			local still = (not md or md:IsZero()) and self:GetVelocity():Length2D() < 2 * M2U
			local want = self:MercerShieldOut() and protecting(self) and self:IsOnGround() and still
				and CurTime() < (sh.guardUntil or 0)
			if want and not nd and not self:IsPlayingAnimation() then
				GP.Start(self, "mercer/shield_guard", {exitAfter = 0, block = true, onDone = function(ent) ent:UpdateAnimation() end})
			elseif nd == "mercer/shield_guard" and not want then
				GP.Stop(self)
				self:UpdateAnimation()
			end
		end

		-- (user 2026-10-27: "the run with the blade isn't as in the game") prototype_sprint added_poses {blades}:
		-- alex_blades_amb_fight cyclic on the upper body over the sprint (blend 0.1 / 0.1) - the blade arm held ready.
		-- Not in a strike, a held body, a blocking node or the air
		function ENT:MercerBladeSprintThink(dt)
			local want = self.MercerSprintOn and self:IsOnGround() and self:GetMercerForm().name == "Клинок" and not self:MercerShieldOut()
				and not self.MercerFight and not self:GetNW2Bool("MercerHolding") and not self.MercerGun
				and not (self.MercerNode and self.MercerNode.opts.block)
			local L = self.MercerBladeLayer
			if L and (not self:IsValidLayer(L.id) or self:GetLayerSequence(L.id) ~= L.seq) then
				self.MercerBladeLayer, L = nil, nil
			end
			if not L then
				if not want then return end
				local seq = self:LookupSequence("alex_blades_amb_fight_upper")
				if not seq or seq < 0 then return end
				local id = self:AddGestureSequence(seq, false)
				if not id or id < 0 then return end
				self:SetLayerLooping(id, true)
				self:SetLayerWeight(id, 0)
				L = {id = id, seq = seq, w = 0}
				self.MercerBladeLayer = L
			end
			L.w = math.Clamp(L.w + (want and 1 or -1) * dt / 0.1, 0, 1)
			if L.w <= 0 and not want then
				self:MercerKillLayer(L.id)
				self.MercerBladeLayer = nil
				return
			end
			self:SetLayerWeight(L.id, L.w)
			self:SetLayerPlaybackRate(L.id, 1)
		end

		function ENT:MercerShieldThink(dt)
			local sh = shieldState(self)
			poseLayer(self, sh, dt)
			guard(self, sh)
			slotThink(self, sh)
			if not self:MercerShieldOut() then
				-- another power: the shield's state stays, its material back to normal on the other models
				if self:GetNW2Bool("MercerShieldDown") then setBroken(self, false) end
				sh.push = nil
				return
			end
			local now = CurTime()
			if sh.brokenUntil then
				if now >= sh.brokenUntil then
					sh.brokenUntil, sh.hp = nil, SHIELD_HP
					setBroken(self, false)
				elseif not self:GetNW2Bool("MercerShieldDown") or sh.brokenModel ~= self:GetModel() then
					setBroken(self, true) -- (the model changed under it: the armour on / off)
					sh.brokenModel = self:GetModel()
				end
			elseif now - sh.lastHit > SHIELD_WAIT and sh.hp < SHIELD_HP then
				sh.hp = math.min(SHIELD_HP, sh.hp + SHIELD_REGEN * dt)
			end
			local push = sh.push
			if push then
				if now - push.t0 > push.dur then
					sh.push = nil
				elseif self:IsOnGround() then
					self:MercerShove(push.dir * (push.v * dt))
				end
			end
		end
	end

	do -- the two-button moves' bursts and the devastators (a block of its own: the main chunk is near 200 locals)
		-- palm strike: critical_pain/effects (the shockwave ahead); ground pound: ground_pound generic / charged (the
		-- ring, cracks, shake small / medium by the charge); sonic clap: sonic_clap generic / charged. Sounds: their
		-- graph cues don't resolve (#6952fbc2 ...) - the game's hammer_pound / impact_rumble / lethal_punch instead.
		-- (MercerBallLand) graph_devastator 554-593, the land's bank {hit}: over 70 m/s down high_speed, else charged from 0.75, else over 20 m/s the air's, else the ground's. Their programs, graph_effects 1409-1491:
		-- main = worldDamage {Crush}, its size (20, in the air's 40) taken BY EYE to u; cones = worldConeDamage: rays from a point 6 m up, off the vertical by these angles, a mark where each comes down: {time, angle min, max, rays, size}, the size x u BY EYE. {Crush}'s effectType {ground_pound}, graph_hiteffects 9-15: a decal 2 : 1, so the line crack (the long ones over the road in the video), and an effect of chunks (hash unread): debrisConcrete001 here. {Fire}: the scorch. (The air's crush marks 8, the graph's 12: seven of them so near the middle drowned the round crack in black on the clip's frame.)
		-- (worldDamage is no metres: at 85.5 - 87.5 s of the user's video of the game a landing's round crack is two men wide, 224 u here, the texture's crack 2/3 of its square; 448 u for the air's 40 stood out of all proportion beside him on the clip's frame, 330 u.) BY EYE too: pound / wave / huge, the old pound's scales; the shake (the graph's store has one for the hammerfist only)
		-- ground_pound/critical's (graph_effects 1449-1475): what the air slam's and powerbomb's down spawn (graph_air 98, 273), its marks out to 13 m
		ENT.MercerBombMarks = {fire = {{0.0667, 5, 30, 5, 20}}, crush = {{0.0667, 10, 15, 5, 3}, {0.1667, 15, 25, 5, 6}, {0.2667, 25, 35, 5, 8}, {0.3667, 35, 45, 5, 8}, {0.4667, 40, 45, 5, 8},
			{0.5667, 45, 50, 5, 8}, {0.6667, 50, 55, 5, 8}, {0.7667, 55, 65, 5, 8}, {0.8667, 55, 65, 5, 8}}}
		ENT.MercerBallTiers = {u = 9,
			high = {main = 224, pound = 2.2, wave = 2.6, huge = 1, shake = {"large", "large"}, blur = true,
				fire = {{0.0667, 5, 30, 5, 20}}, crush = {{0.0667, 10, 15, 5, 3}, {0.1333, 15, 25, 5, 6}, {0.2, 25, 35, 5, 8}, {0.2667, 35, 45, 5, 8}, {0.3333, 40, 45, 5, 8}},
				cues = {{"explosion_med"}}},
			charged = {main = 224, pound = 1.6, wave = 1.8, huge = 1, shake = {"medium", "large"}, blur = true,
				fire = {{0.0667, 10, 20, 3, 20}}, crush = {{0.0667, 10, 15, 5, 3}, {0.1333, 15, 20, 5, 6}, {0.2, 20, 25, 5, 8}, {0.2667, 25, 30, 5, 8}},
				cues = {{"alex_devastator"}, {"alex_sonic_wave", 0.2}}},
			air = {main = 330, pound = 1.3, wave = 1.4, huge = 0.5, shake = {"medium", "medium"},
				fire = {{0, 10, 20, 5, 12}}, crush = {{0, 5, 10, 7, 8}},
				cues = {{"explosion_med", 0, 1, 0.75}}},
			ground = {main = 224, pound = 1, wave = 0.9, shake = {"small", "small"},
				fire = {{0, 10, 20, 5, 5}}, crush = {{0, 5, 10, 5, 5}},
				cues = {{"explosion_med", 0, 1, 0.75}}}}
		function ENT:MercerBallCone(pos, c, decal)
			local u, n = self.MercerBallTiers.u, c[4]
			local off = math.Rand(0, 6.2832)
			for i = 1, n do
				local a, yaw = math.rad(math.Rand(c[2], c[3])), off + (i + math.Rand(-0.3, 0.3)) / n * 6.2832
				local at = pos + Vector(math.cos(yaw), math.sin(yaw), 0) * (6 * M2U * math.tan(a))
				self:MercerDecal(decal, at + Vector(0, 0, 40), at - Vector(0, 0, 60), self, c[5] * u)
				if decal ~= "Scorch" then self:MercerVFX("concrete", at + Vector(0, 0, 4), nil, 0.8) end
			end
		end
		function ENT:MercerBallMarks(pos, T)
			local function cones(list, decal)
				for _, k in ipairs(list) do
					if k[1] <= 0 then self:MercerBallCone(pos, k, decal)
					else self:Timer(k[1], function(ent) ent:MercerBallCone(pos, k, decal) end) end
				end
			end
			cones(T.fire, "Scorch")
			cones(T.crush, "AlexMercerCrackSmall")
		end
		function ENT:MercerBallBurst(st)
			local c, v = st.charge or 0, st.landV or 0
			local name = (v >= 70 and "high") or (c >= 0.75 and "charged") or (v >= 20 and "air") or "ground"
			local T = self.MercerBallTiers[name]
			local pos = self:GetPos()
			dbg("cannonball: landed at %.0f m/s down, charge %.2f: the %s landing", v, c, name)
			self.loco:SetVelocity(Vector(0, 0, 0)) -- (the node has no slide: the flight's 25 m/s along the ground would carry him off the dent)
			self:MercerDecal("AlexMercerCrack", pos + Vector(0, 0, 10), pos - Vector(0, 0, 30), self, T.main)
			self:MercerVFX("pound", pos + Vector(0, 0, 2), nil, T.pound)
			self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, T.wave)
			if T.huge then self:MercerVFX("land_huge", pos + Vector(0, 0, 2), nil, T.huge) end
			self:MercerVFX("crush_concrete", pos + Vector(0, 0, 4))
			if T.blur then self:MercerVFX("bullet_land_wave", pos + Vector(0, 0, 2), nil, 1, self) end
			self:MercerShake(T.shake[1], T.shake[2])
			self:MercerBallMarks(pos, T)
			self:MercerCue("alex_land_heavy")
			self:MercerCue("alex_feet")
			self:MercerCue("hammer_pound", 0.8)
			self:MercerCue("impact_rumble")
			for _, q in ipairs(T.cues) do
				if (q[2] or 0) <= 0 then self:MercerCue(q[1], q[3], q[4])
				else self:Timer(q[2], function(ent) ent:MercerCue(q[1], q[3], q[4]) end) end
			end
		end
		function ENT:MercerChordBurst(st, kind)
			if st.ball and kind == "pound" then return self:MercerBallBurst(st) end
			local c = st.charge or 0
			local fwd = self:GetForward()
			local pos = self:GetPos()
			if kind == "palm" then
				self:MercerVFX("air_dash", pos + fwd * 60 + Vector(0, 0, 45), fwd)
				self:MercerShake("small", "small")
				self:MercerCue("big_heavy_whoosh", 0.7)
			elseif kind == "pound" then
				self:MercerVFX("pound", pos + Vector(0, 0, 2), nil, c >= 0.75 and 1.6 or 1)
				if c >= 0.75 then self:MercerVFX("land_huge", pos + Vector(0, 0, 2)) end
				self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, c >= 0.75 and 1.8 or 0.9)
				-- (user 2026-11-04: "там будет трещина какая то, а не вмятина") the small one was the whip's line crack. The graph's hit here is {Crush} (graph_devastator ground / charged): hiteffects crush_concrete, the round decal_fullcrack, 2 m
				self:MercerDecal(c >= 0.75 and "AlexMercerCrack" or "AlexMercerCrush2", pos + Vector(0, 0, 10), pos - Vector(0, 0, 30), self)
				self:MercerShake(c >= 0.75 and "medium" or "small", c >= 0.75 and "medium" or "small")
				self:MercerCue("hammer_pound", 0.8)
				self:MercerCue("impact_rumble")
			elseif kind == "clap" then
				self:MercerVFX("pound", pos + Vector(0, 0, 50) + fwd * 20, fwd, c >= 0.75 and 1.4 or 0.9)
				self:MercerShake("small", c >= 0.75 and "medium" or "small")
				self:MercerCue("lethal_punch", 0.8)
				self:MercerCue("big_heavy_whoosh", 0.6)
			end
		end

		-- the spike / tendril props are the claws' ground spike models (spikeProp: rise, stand, sink)
		local function lift(self, e)
			self:MercerFightDamage(e, {0, 0, "", 1, 0, 1, 1, Vector(0, 9000, 0), Vector(0, 9000, 0)}, 1, e:WorldSpaceCenter())
		end

		-- a devastator tendril (graph_devastator tendril items, drawn by the client: alex_mercer_tendrils.lua) from his joint
		-- into e - set "cp" (Critical Pain, 8) / "tb" (Tendril Barrage, 5), one at random; drawn back at tRev
		local TENDRIL_SETS = {cp = 8, tb = 5}
		function ENT:MercerTendrilAt(e, set, t1, tRev)
			net.Start("alex_mercer_tendril")
			net.WriteEntity(self)
			net.WriteEntity(e)
			net.WriteString(set)
			net.WriteUInt(math.random(TENDRIL_SETS[set]), 5)
			net.WriteFloat(t1)
			net.WriteFloat(tRev)
			net.SendPVS(self:GetPos())
		end

		-- the Tendril Barrage's devastator track (ground sonic_clap and the air one alike)
		function ENT:MercerBarrage(air)
			-- (user 2026-10-22: "many hits, a barrage") the graph's devastator track: radius 30 m, targetCount 50 - each
			-- target its own tendril (target/<class>/tendril), its attack beginning at random 0.666-1.5 s of the node
			-- (attackTimeBeginStart / Stop; this is 0.4 s into it), 400 +- 20 (attackDamage / randomDamage) as it
			-- strikes; minTargetCount 60 - the rest of the 60 random spokes (randomHeightArc 80, randomMinRadius 10 m,
			-- minHeightArcOnGround 5), drawn by the client
			local list = {}
			for _, e in ipairs(ents.FindInSphere(self:WorldSpaceCenter(), 30 * M2U)) do
				if fightable(self, e) then list[#list + 1] = {e, e:WorldSpaceCenter():Distance(self:WorldSpaceCenter())} end
			end
			table.sort(list, function(x, y) return x[2] < y[2] end)
			-- the locked target first (wherever it is): turned to, and its tendrils sure to go
			local lk = self:MercerLocked()
			if lk then
				self:SetAngles(Angle(0, (lk:GetPos() - self:GetPos()):Angle().y, 0))
				for i = #list, 1, -1 do if list[i][1] == lk then table.remove(list, i) end end
				table.insert(list, 1, {lk, lk:WorldSpaceCenter():Distance(self:WorldSpaceCenter())})
			end
			local nT = math.min(50, #list)
			-- (user 2026-10-22: "a barrage is a heap of hits - every tendril its own hit") the 60 tendrils shared out:
			-- each target 2-6 of them (more the fewer there are), each its own strike at its own time in the attack
			-- window; the rest (20 at least) the spokes
			-- (user 2026-10-22: the many hits were meant for the beam - FPS) one tendril a target, as in the graph
			local per = 1
			local now = CurTime()
			net.Start("alex_mercer_tendril_ring")
			net.WriteEntity(self)
			net.WriteFloat(now)
			net.WriteFloat(now + 1.9333)
			net.WriteBool(air)
			net.WriteUInt(math.max(0, 60 - nT), 7)
			net.SendPVS(self:GetPos())
			local H = {0, 0, "", 1, 0, 380, 420, Vector(0, 1500, 0), Vector(0, 1500, 0), kind = "DevastatorTendril"}
			-- (user 2026-10-22: the explosion's tendrils drag the caught back and he consumes them - not the beam, no
			-- disguise) at the draw-back (sonic_clap/retract, +1.9333 s) the client pulls their ragdolls in at the
			-- tendrils' 40 m/s; a server ragdoll (ai_serverragdolls) is pulled here; each one heals him as it arrives
			if not air then
				local kills = {}
				self.MercerTBKills = kills
				self:Timer(1.9333, function(ent)
					if ent.MercerTBKills == kills then ent.MercerTBKills = nil end
					-- (user: "to clear the bodies off the map") the server's own death ragdolls within 30 m as well
					local c0 = ent:WorldSpaceCenter()
					for _, rag in pairs(ALEX_MERCER_SV_RAGS) do
						if IsValid(rag) and rag:WorldSpaceCenter():Distance(c0) < 30 * M2U and not rag.MercerPulled then
							rag.MercerPulled = true
							ALEX_MERCER_SV_PULLS[#ALEX_MERCER_SV_PULLS + 1] = {m = ent, rag = rag, t0 = CurTime()}
						end
					end
					net.Start("alex_mercer_tb_pull")
					net.WriteEntity(ent)
					net.WriteUInt(#kills, 6)
					for _, kv in ipairs(kills) do net.WriteUInt(kv.idx, 16) end
					net.SendPVS(ent:GetPos())
					for _, kv in ipairs(kills) do
						local dist = kv.pos:Distance(ent:WorldSpaceCenter()) / M2U
						ent:Timer(math.min(dist / 40, 2.5) + 0.2, function(e2) e2:MercerAbsorbHeal(true) end)
					end
				end)
			end
			for k = 1, nT do
				local e, d = list[k][1], list[k][2]
				local times = {}
				for j = 1, per do times[j] = math.Rand(0.666, 1.5) - 0.4 end
				table.sort(times)
				for j, at in ipairs(times) do
					self:MercerTendrilAt(e, "tb", now + at, now + 1.9333)
					-- struck as it arrives (forwardVelocity 30 m/s): the graph's 400 +- 20 shared out over its tendrils,
					-- kept alive (1 hp) until the last so every one of them lands; the last one finishes it
					self:Timer(at + d / (30 * M2U), function(ent)
						if not (IsValid(e) and fightable(ent, e)) then return end
						local p = e:WorldSpaceCenter()
						sound.Play("mercer/fx/spike_impale_0" .. math.random(3) .. ".wav", p, 85, math.random(90, 110), 1)
						if j == per then
							local idx = e:EntIndex()
							-- (user 2026-10-22: whoever its tendrils catch is drawn in and consumed, like a grab - it kills
							-- an ordinary NPC outright) a human-sized one gets its whole health
							local small = (e:IsNPC() or e:IsPlayer() or e:IsNextBot()) and e:OBBMaxs().z - e:OBBMins().z < 110
							local hk = H
							if small and not air and e.Health and e:Health() > 0 then
								local all = e:Health() + 50
								hk = {H[1], H[2], H[3], H[4], H[5], all, all, H[8], H[9]}
							end
							ent:MercerFightDamage(e, hk, math.random(), p)
							if not air and (not IsValid(e) or (e.Health and e:Health() <= 0)) then
								local kl = ent.MercerTBKills
								if kl and #kl < 30 then kl[#kl + 1] = {idx = idx, pos = p} end
							end
						else
							local share = 400 / per
							local hp = e.Health and e:Health() or 0
							local h = {0, 0, "", 1, 0, share, share, Vector(0, 300, 0), Vector(0, 300, 0), kind = "DevastatorTendril"}
							if hp > 1 and share >= hp then h[6], h[7] = hp - 1, hp - 1 end
							if hp <= 1 or h[6] >= 1 then ent:MercerFightDamage(e, h, 1, p + VectorRand() * 8) end
						end
					end)
				end
			end
		end

		function ENT:MercerDevastate(st, kind)
			local pos = self:GetPos()
			-- the camera pull (MercerCamDistance): the barrage / the spikes far out, Critical Pain less
			self:SetNW2Float("MercerDevCamT", CurTime())
			self:SetNW2Float("MercerDevCamD", kind == "impale" and 220 or 480)
			if kind == "spikes" then
				-- ground_pound/critical: the slam, then spikes bursting out in rings (every 3 m out to 18 m, then the
				-- hit of the 25 m field at 2.8 s); those in a ring are thrown up as it breaks out
				self:MercerVFX("land_huge", pos + Vector(0, 0, 2))
				self:MercerVFX("pound", pos + Vector(0, 0, 2), nil, 2)
				self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, 4.2) -- (user: as big as the devastator's field)
				self:MercerDecal("AlexMercerCrack", pos + Vector(0, 0, 10), pos - Vector(0, 0, 30), self)
				self:MercerShake("large", "large", 0.1)
				self:MercerCue("explosion_med")
				self:MercerCueAt("rock_explode", pos)
				self:MercerCueAt("rock_debris", pos)
				-- (graph_devastator ground_pound devastator target/<class>: a devastatorTargetGroundSpike under each one - human /
				-- hunter the medium, tank / helicopter the large, anything else one of the three at random, within 5 m the large -
				-- holding it up (physics keyframed) until the fall. The game has no rings of spikes round him: the old port's.)
				local SZ = {small = "models/mercer/groundspike_single_small.mdl", medium = "models/mercer/groundspike_single_mid.mdl",
					large = "models/mercer/groundspike_single_large.mdl"}
				local DEPTH = {small = 260, medium = 320, large = 380}
				for _, e in ipairs(ents.FindInSphere(pos, 25 * M2U)) do
					if fightable(self, e) then
						local cls = e:GetClass()
						local d = (e:GetPos() - pos):Length2D() / M2U
						local size
						if e:IsVehicle() or cls == "npc_helicopter" or cls == "npc_combinegunship" or cls == "npc_strider"
							or cls == "npc_combinedropship" then size = "large"
						elseif e:IsNPC() or e:IsPlayer() or e:IsNextBot() then size = "medium"
						elseif d <= 5 then size = "large"
						else size = ({"large", "medium", "small"})[math.random(3)] end
						local gp = groundAt(e:GetPos())
						if gp then
							local delay = 0.05 + d * 0.01
							spikeProp(SZ[size], gp, Angle(math.random(-8, 8), math.random(360), 0), DEPTH[size], delay, 0.2, 2.75 - delay, 0.4)
							self:Timer(delay, function(ent)
								if IsValid(e) and fightable(ent, e) then
									lift(ent, e)
									ent:MercerCueAt("spike_emerge", e:GetPos())
								end
							end)
						end
					end
				end
				-- (user + the video: a field of spikes coming out further and further) ground_pound/critical's
				-- worldConeDamage {Crush} rings (type #304b2eee: the spike field), after the trackGroup's 0.2 s: 10-15 m at
				-- 0.0667, 15-25 at 0.1667, 25-35 at 0.2667, 35-45 at 0.3667, 40-45 at 0.4667 - size 3 / 6 / 8 = small /
				-- medium / large; every spike stands until the field's end (2.75 s) and sinks
				-- (user 2026-10-22: too far out, too sparse, too far from him - the nearest about 5 m, and hardly any
				-- effects) the rings brought in to 4-25 m, denser; each spike breaks the ground (crush_concrete), each
				-- ring sends its wave out to its own size
				local RINGS = {{0.2667, 4, 7, "small", 14}, {0.3667, 7, 11, "medium", 18}, {0.4667, 11, 15, "large", 20},
					{0.5667, 15, 20, "large", 20}, {0.6667, 20, 25, "large", 16}}
				for _, rg in ipairs(RINGS) do
					for _ = 1, rg[5] do
						local a, r = math.Rand(0, 2 * math.pi), math.Rand(rg[2], rg[3]) * M2U
						local gp = groundAt(pos + Vector(math.cos(a) * r, math.sin(a) * r, 0))
						if gp then
							local delay = rg[1] + math.Rand(0, 0.08)
							spikeProp(SZ[rg[4]], gp, Angle(math.random(-15, 15), math.random(360), math.random(-15, 15)),
								DEPTH[rg[4]], delay, 0.2, 2.75 - delay, 0.4)
							local sc = rg[4] == "small" and 0.5 or rg[4] == "medium" and 0.7 or 0.9
							self:Timer(delay, function(ent) ent:MercerVFX("crush_concrete", gp + Vector(0, 0, 4), Vector(0, 0, 1), sc) end)
						end
					end
					self:Timer(rg[1], function(ent)
						ent:MercerShake("small", "small")
						ent:MercerVFX("wave", pos + Vector(0, 0, 2), nil, rg[3] / 6)
					end)
				end
				self:Timer(3.1, function(ent) ent:MercerCueAt("rock_debris_tail", pos) end)
			elseif kind == "tendrils" then
				-- (graph_devastator sonic_clap devastator: sonic_clap/critical at 0.4 s - he bursts and his tendrils lash out of
				-- him into everyone around: target/<class>/tendril, one of the default store's 5 at random; sonic_clap/retract at
				-- 2.333 s draws them back. The old port's lines of ground spikes were not the game's.)
				-- (its ring / flare / debris: the graph's sonic_clap/critical program, atk.relFx)
				self:MercerShake("large", "medium")
				-- (user: "everything as in the game") sonic_clap/critical's biasDebrisConcrete001 (concrete chunks thrown
				-- out of the clap, 0.3333 s) and its worldConeDamage {Crush} ground_pound marks under him
				self:MercerVFX("crush_concrete", pos + Vector(0, 0, 4), Vector(0, 0, 1), 2)
				self:MercerDecal("AlexMercerCrack", pos + Vector(0, 0, 10), pos - Vector(0, 0, 30), self, 200)
				self:MercerBarrage(false)
				self:Timer(1.9333, function(ent) ent:MercerCue("spike_return") end)
			elseif kind == "impale" then
				self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, 2.2)
				-- critical_pain: the tendrils at the nearest targets ahead (up to 8, 120°, 30 m), striking at 0, 0.6667 and
				-- 1.333 s of the attack: 50 each, impulse 10000 up / 40000 forward (the first strike throws them)
				local fwd = self:GetForward()
				local list = {}
				for _, e in ipairs(ents.FindInSphere(self:WorldSpaceCenter(), 30 * M2U)) do
					if fightable(self, e) then
						local to = e:WorldSpaceCenter() - self:WorldSpaceCenter()
						local flat = Vector(to.x, to.y, 0)
						if flat:LengthSqr() > 1 and flat:GetNormalized():Dot(fwd) >= 0.5 then list[#list + 1] = {e, to:Length()} end
					end
				end
				table.sort(list, function(x, y) return x[2] < y[2] end)
				local lk = self:MercerLocked(30 * M2U)
				if lk then
					for i = #list, 1, -1 do if list[i][1] == lk then table.remove(list, i) end end
					table.insert(list, 1, {lk, 0})
				end
				-- (graph: his own 1.5 m strike spheres through 0.6667-2.5 s - a big one there takes the dash punch)
				self.MercerDevPunchDone = nil
				for k = 0, 18 do
					self:Timer(k * 0.1, function(ent)
						if ent.MercerDevPunchDone or not ent.MercerFight then return end
						local b = ent:MercerBigNear(1.5 * M2U)
						if b then ent:MercerDevPunch(b) end
					end)
				end
				-- (user + the video: as it fires, a burst of dust round his feet like a heavy landing, and the wave)
				self:MercerVFX("land_huge", pos + Vector(0, 0, 2))
				self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, 1.6)
				-- (user: in the game a whole pack of tendrils bursts out forward, always moving on, like a beam)
				-- tendrilDevastator: 10 tendrils out of his wrists along the aim, growing at the set's 30-35 m/s up to
				-- 200 m (the world stops them), drawn back at the item's end (node 3 s = now + 2.333)
				local aim = self:GetForward()
				local p = self:GetPossessor()
				if IsValid(p) then
					local a = self:MercerAimVector(p)
					aim = Vector(a.x, a.y, math.Clamp(a.z, 0, 0.7)):GetNormalized() -- (user: not down at the ground - the camera looks down at him)
				end
				-- (user 2026-10-22: he stood sideways, diagonal, as he fired) his hands kept on the locked one, else on the aim
				-- (MercerCPFace, every tick of the release)
				st.cpLock, st.cpDir = lk, Vector(aim.x, aim.y, 0):GetNormalized()
				net.Start("alex_mercer_tendril_beam")
				net.WriteEntity(self)
				net.WriteEntity(lk or NULL) -- (user 2026-10-22) the victim only when locked; else straight along his aim
				net.WriteVector(aim)
				net.WriteFloat(CurTime())
				net.WriteFloat(CurTime() + 2.333)
				net.SendPVS(pos)
				-- (user 2026-10-22: this beam is the barrage - a heap of hits, the tendrils in one bundle, not fanned out to
				-- every target) each 0.1333 s step (the client's three tendrils) strikes whatever is on the beam (1.2 m
				-- round it, 30 m out) as they get there at 30 m/s: tendrilDevastator's 1250 shared over the steps, the
				-- target kept at 1 hp until the last one, which throws it (impulse 10000 up / 40000 forward)
				local victim = lk
				local steps = {}
				for t = 0, 2.333 - 0.2, 0.1333 do steps[#steps + 1] = t end
				local share = 1250 / #steps
				local HLAST = {0, 0, "", 1.5, 0, 1250 / 3, 1250 / 3, Vector(0, 10000, -40000), Vector(0, 10000, -40000), kind = "DevastatorExplosion"}
				for si, t0 in ipairs(steps) do
					self:Timer(t0, function(ent)
						local o = ent:WorldSpaceCenter()
						local dir = aim
						if IsValid(victim) and fightable(ent, victim) then dir = (victim:WorldSpaceCenter() - o):GetNormalized() end
						local last = si == #steps
						for _, e in ipairs(ents.FindInSphere(o + dir * (15 * M2U), 15 * M2U + 60)) do
							if fightable(ent, e) then
								local cpos = e:WorldSpaceCenter()
								local along = (cpos - o):Dot(dir)
								if along > 0 and along < 30 * M2U
									and (o + dir * along):Distance(cpos) < 1.2 * M2U + e:BoundingRadius() * 0.5 then
									ent:Timer(along / (30 * M2U), function(ent2)
										if not (IsValid(e) and fightable(ent2, e)) then return end
										local hp0 = e:WorldSpaceCenter()
										sound.Play("mercer/fx/spike_impale_0" .. math.random(3) .. ".wav", hp0, 85, math.random(90, 110), 1)
										if last then
											ent2:MercerFightDamage(e, HLAST, 1, hp0)
										else
											local hp = e.Health and e:Health() or 0
											local h = {0, 0, "", 1, 0, share, share, Vector(0, 300, -600), Vector(0, 300, -600), kind = "DevastatorExplosion"}
											if hp > 1 and share >= hp then h[6], h[7] = hp - 1, hp - 1 end
											if hp <= 1 or h[6] >= 1 then ent2:MercerFightDamage(e, h, 1, hp0 + VectorRand() * 6) end
										end
									end)
								end
							end
						end
					end)
				end
				-- critical_pain/effects: worldConeDamage {Crush} along the ground ahead - 4 / 8 / 12 / 16 m at 0 /
				-- 0.1333 / 0.2667 / 0.4 s (the ground_pound marks), the fire one at 0.0667
				local flat = Vector(aim.x, aim.y, 0):GetNormalized()
				for k, d in ipairs({4, 8, 12, 16}) do
					self:Timer((k - 1) * 0.1333, function(ent)
						local c = ent:GetPos() + flat * (d * M2U)
						local tr = util.TraceLine({start = c + Vector(0, 0, 80), endpos = c - Vector(0, 0, 200),
							filter = ent, mask = MASK_SOLID_BRUSHONLY})
						if tr.Hit then
							ent:MercerDecal("AlexMercerCrack", tr.HitPos + tr.HitNormal * 4, tr.HitPos - tr.HitNormal * 8, ent, 90)
							ent:MercerVFX("crush_concrete", tr.HitPos + tr.HitNormal * 2, tr.HitNormal, 1.2)
						end
					end)
				end
				self:MercerShake("medium", "medium")
			elseif kind == "impale360" then
				self:MercerVFX("wave", pos + Vector(0, 0, 2), nil, 2.6)
				-- (the video: in the air the same burst of spokes; graph: the same devastator track as on the ground)
				self:MercerBarrage(true)
				self:MercerShake("medium", "medium", 0.1667)
			end
		end
	end

	do -- Mercer's hit reactions (list item 8, 2026-10-08 rewrite; a block of its own: the main chunk is near Lua's 200
		-- locals) = the hitreaction graph with Alex as the receiver (build/graph_hitreaction.txt; grabbableClass prototype):
		--  hit/Bullet/prototype: reactionHitPushbackAdd 0.01 - his locomotion's pushback banks react (MercerBulletReact)
		--  the standard hit (common/human #bea93d5e, node default, pose by the blow's impulse direction): pushed forward
		--   (from behind) alex_gethit_pushback_s 1-end, pushed to his right _e / to his left _w 1-end, otherwise (from the
		--   front) alex_gethit_pushback 3-end or _2 3-end at random, facing the blow; their root carries him
		--   (ALEX_MERCER_ROOTPATH, the anims pinned in the model). From 0.4 s an input may leave it (exit_active); from
		--   0.6667 s with movement held the exit bank's stumble out of it: alex_gethit_stagger / _2 / _3 1-17 at 0.8,
		--   turning to the stick at 600 deg/s, its own root forward, left from 0.5667 s (opening)
		--  the knockback (common/human/knockback, reactionHitExecute (time, distance, height)): he flies - the pose
		--   alex_gethit_fall_faceup cycling, facing the blow (reactionPushbackOrient 180); Jump in the air = AirRecover:
		--   alex_loco_jump_small_flip 24 -> 4 at 1.2 with the flying brake, then the plain fall; landing = the breakfall
		--   (common/prototype/breakfall): alex_breakfall_flip 0-30 / 0.8333 + 30-33 to 1.167 or
		--   alex_gethit_breakfall_front_backflip 0-end (equal weights), their root sliding him on, its hit by the fall's
		--   speed (>= 50 m/s 5 m 20, >= 30 m/s 4 m 15, else 2 m 5 {Crush}), the opening from 0.5 s
		-- GMod's attackers carry no hit types: a blast = MissileExplosion (0.4 s, 2.5 m, 0.5 m), a vehicle / a heavy crush
		-- = Weapon's car hit (1 s, 10 m, 0.5 m), a heavy blow (alex_mercer_heavy_hit % of his max health) = the Hunter's
		-- heavy hit (0.3 s, 5 m, 0.5 m), any
		-- other non-bullet blow = the standard hit. Not in a grab / consume / ride / wall run / devastator / jump charge
		-- (the graph's uninterruptible ones and ours). Setting: alex_mercer_hit_reactions.
		local G = ALEX_MERCER_GRAPH
		local function rseg(t0, t1, anim, f0, f1, bin, bout)
			return {start = t0, stop = t1, anim = anim, rate = 1, f0 = f0, f1 = f1, cyclic = false, part = "",
				blendin = bin or 0, blendout = bout or 0.1}
		end
		G["mercer/hit/north1"] = {rseg(0, 33 / 30, "alex_gethit_pushback", 3, 36, 0, 0.2)}
		G["mercer/hit/north2"] = {rseg(0, 36 / 30, "alex_gethit_pushback_2", 3, 39, 0, 0.2)}
		-- (2026-11-04) the plain Hunter's counter, by the blow's hit type (graph_hitreaction 6113-6200, tools/hunterhits.py: the type on his
		-- side, the same on the Hunter's hit item): the whole anim, blend out 0.2333, reactionPushbackOrient 180 deg/s, the same exits
		G["mercer/hit/lh2"] = {rseg(0, 35 / 30, "alex_gethit_left_hand_2", 0, 35, 0, 0.2333)}
		G["mercer/hit/rh2"] = {rseg(0, 32 / 30, "alex_gethit_right_hand_2", 0, 32, 0, 0.2333)}
		G["mercer/hit/lh1"] = {rseg(0, 34 / 30, "gethit_LeftHand", 0, 34, 0, 0.2333)}
		G["mercer/hit/rh1"] = {rseg(0, 34 / 30, "gethit_RighHand", 0, 34, 0, 0.2333)}
		-- (these two go 0.94 and 0.64 m: the straight line of it, which the model's LX LY took off the pose, is his, the rest stays in the pose)
		local function linePath(n, fw, lf)
			local t = {}
			for i = 0, n - 1 do
				local k = i / (n - 1)
				t[i * 3 + 1], t[i * 3 + 2], t[i * 3 + 3] = fw * k, lf * k, 0
			end
			return t
		end
		ALEX_MERCER_ROOTPATH.gethit_lefthand = ALEX_MERCER_ROOTPATH.gethit_lefthand or linePath(35, -0.747, 0.566)
		ALEX_MERCER_ROOTPATH.gethit_righhand = ALEX_MERCER_ROOTPATH.gethit_righhand or linePath(35, -0.597, -0.218)
		-- which node a blow plays, by the anim the Hunter is in and its time in that node's frames: {t end, node}; f0 its first frame. Their hit
		-- types: the claw counter #dd5c6932, the barrage #dd5c6931-35, the flurry run #0a438d16, 15. The run's other three, the plain flurry's,
		-- the swipe's have no bank there: the standing hit by the blow's way, as before
		local CLAW_TYPE = {
			brawler_pnch_claw_counter = {f0 = 0, {math.huge, "lh2"}},
			brawler_claw_barrage = {f0 = 3, {0.2667, "rh2"}, {0.5667, "lh2"}, {0.9667, "lh1"}, {1.233, "rh1"}, {1.8, "north1"}},
			brawler_flurry_run = {f0 = 0, {0.4, "rh2"}, {0.7667, "north2"}},
		}
		local function clawType(self)
			local a = self.MercerHitBy
			if not IsValid(a) or CurTime() - (self.MercerHitByT or 0) > 0.05 then return end
			local seq = a:GetSequence()
			local T = CLAW_TYPE[string.lower(a:GetSequenceName(seq) or "")]
			if not T then return end
			local t = (a:GetCycle() * a:SequenceDuration(seq) * 30 - T.f0) / 30
			for _, r in ipairs(T) do
				if t <= r[1] + 0.05 then return r[2] end
			end
		end
		G["mercer/hit/south"] = {rseg(0, 34 / 30, "alex_gethit_pushback_s", 1, 35, 0, 0.1)}
		G["mercer/hit/east"] = {rseg(0, 39 / 30, "alex_gethit_pushback_e", 1, 40, 0, 0.1)}
		G["mercer/hit/west"] = {rseg(0, 39 / 30, "alex_gethit_pushback_w", 1, 40, 0, 0.1)}
		G["mercer/hit/rec1"] = {rseg(0, 16 / 24, "alex_gethit_stagger", 1, 17, 0.2333, 0.2)}
		G["mercer/hit/rec2"] = {rseg(0, 16 / 24, "alex_gethit_stagger_2", 1, 17, 0.2333, 0.2)}
		G["mercer/hit/rec3"] = {rseg(0, 16 / 24, "alex_gethit_stagger_3", 1, 17, 0.2333, 0.2)}
		-- (hitType #0f307d52, graph_hitreaction.txt 3171-3192: alex_gethit_ground_stun x1.25; moving alex_gethit_stagger x0.62)
		G["mercer/hit/stun"] = {rseg(0, 33 / 37.5, "alex_gethit_ground_stun", 0, 33, 0.2, 0.2)}
		G["mercer/hit/stun_move"] = {rseg(0, 19 / 18.6, "alex_gethit_stagger", 0, 19, 0.5, 0.1)}
		G["mercer/hit/fly"] = {{start = 0, stop = -1, anim = "alex_gethit_fall_faceup", rate = 1, f0 = 0, f1 = 60, cyclic = true,
			part = "", blendin = 0.4, blendout = 0.2}}
		G["mercer/hit/recover"] = {rseg(0, 20 / 36, "alex_loco_jump_small_flip", 24, 4, 0.1, 0.1667)}
		G["mercer/hit/bf1"] = {rseg(0, 0.8333, "alex_breakfall_flip", 0, 30, 0.1667, 0),
			rseg(0.8333, 1.167, "alex_breakfall_flip", 30, 33, 0.1, 0.2)}
		G["mercer/hit/bf2"] = {rseg(0, 52 / 30, "alex_gethit_breakfall_front_backflip", 0, 52, 0.1, 0.2)}
		local KB_BLAST, KB_CAR, KB_HEAVY = {0.4, 2.5, 0.5}, {1, 10, 0.5}, {0.3, 5, 0.5}
		-- a heavy blow: alex_mercer_heavy_hit % of his health (the damage scale of GMod's NPCs varies wildly)
		-- (user 2026-11-04: "сильный удар когда его откидывает"; his alex_mercer_hp_scale 10) of his own, SpawnHealth: of the scaled one a blow had to be 4800 to be heavy, none is
		local function heavyBlow(self, amount)
			return amount >= (self.SpawnHealth or self:GetMaxHealth()) * GetConVar("alex_mercer_heavy_hit"):GetFloat() / 100
		end

		local function reacting(self)
			local n = self.MercerNode
			return n ~= nil and string.sub(n.path, 1, 11) == "mercer/hit/"
		end
		local function done(ent) ent:UpdateAnimation() end
		-- (user 2026-10-23: the reactions to fire / blows must give way to any action - a strike, a grab...) an action
		-- cuts a flinch / stagger / pushback / stumble / breakfall at once; the knockback's flight (and its air recover)
		-- are left to land
		-- the bullets' upper-body reactions (act_block / gethit_bullets_running) are gesture layers, not nodes: marked, so
		-- a cancel takes them off too (user 2026-10-23, again: they went on over his strikes / jumps / grabs)
		local function hitLayer(self, ...)
			local n = self.MercerLayers and #self.MercerLayers or 0
			self:MercerUpperLayer(...)
			local ls = self.MercerLayers
			if ls and #ls > n then ls[#ls].hit = true end
		end
		local function dropHitLayers(self)
			local ls, any = self.MercerLayers, false
			if not ls then return false end
			for i = #ls, 1, -1 do
				if ls[i].hit then
					if self:IsValidLayer(ls[i].id) then self:MercerKillLayer(ls[i].id) end
					table.remove(ls, i)
					any = true
				end
			end
			if any then self.MercerNudgeT = nil end
			return any
		end
		function ENT:MercerHitCancel()
			local layers = dropHitLayers(self)
			local hr = self.MercerHitSt
			if not hr or hr.down or not reacting(self) then return layers end
			local n = self.MercerNode.path
			if n == "mercer/hit/fly" or n == "mercer/hit/recover" then return false end
			hr.pathPrev = nil
			GP.Stop(self)
			self:UpdateAnimation()
			return true
		end
		-- (user 2026-10-08) no reaction at all while he attacks, rolls, flips, jumps, vaults... - and nothing kept for later:
		-- a blow landing then is simply ignored (he carries on), the next one after he is free reacts as usual
		local ACTS = {"MercerFight", "MercerFKick", "MercerElbow", "MercerStomp", "MercerAirDash", "MercerAirSlam",
			"MercerAirThrow", "MercerDevPunchSt", "MercerDive", "MercerEdge", "MercerLedge", "MercerSlide", "MercerSpikeRun",
			"MercerVault", "MercerWallHop", "MercerWallLip", "MercerWallRoll", "MercerWallUsd", "MercerHTossSlide", "MercerBackFlipWin"}
		-- (what he's at, for the log of the blows below)
		local function acting(self)
			if not self:IsOnGround() then return "in the air" end
			-- (user 2026-11-04, the same: "и на бегу") the sprint's dash in and the landing's pedal are the run, not an action
			if self.MercerNode and not reacting(self) and self.MercerNode.path ~= "mercer/pedal" and self.MercerNode.path ~= NODE_SPRINT_DASH then return self.MercerNode.path end
			if self:IsPlayingAnimation() then return "DrGBase's animation" end
			for _, k in ipairs(ACTS) do if self[k] then return k end end
			return false
		end
		-- a reaction node driven by its anim's own root; yaw = the facing its path is laid along (nil: his own, live)
		local function start(self, path, opts, yaw)
			local hr = self.MercerHitSt
			hr.t0, hr.pathPrev, hr.pathYaw, hr.orient = CurTime(), nil, yaw, nil
			if self.MercerSprintOn then self:MercerSprintEnd() end
			if self.MercerFight then self:MercerFightEnd() end
			opts.block = true
			GP.Start(self, path, opts)
			-- (with the move by the path, MercerShove: what the run or the flight left goes in a tick or two, or it slides on top of that, "double slide", MODLOG 2026-10-08)
			hr.braked = true
			self.loco:SetDeceleration(6000)
		end
		-- the step of the anim's root since the last tick (metres forward / left of its start), as his velocity
		local function pathStep(self, hr, dt)
			local anim, cycle = GP.Sample(self)
			anim = anim and string.lower(anim)
			local path = anim and ALEX_MERCER_ROOTPATH and ALEX_MERCER_ROOTPATH[anim]
			if not path or dt <= 0 then
				hr.pathPrev = nil
				return
			end
			local nf = #path / 3
			local f = cycle * ((ALEX_MERCER_FRAMES[anim] or nf) - 1)
			local i = math.Clamp(math.floor(f), 0, nf - 1)
			local j = math.min(i + 1, nf - 1)
			local k = math.Clamp(f - i, 0, 1)
			local fw = Lerp(k, path[i * 3 + 1], path[j * 3 + 1])
			local lf = Lerp(k, path[i * 3 + 2], path[j * 3 + 2])
			local prev = hr.pathPrev
			local key = self.MercerNode and self.MercerNode.t0
			hr.pathPrev = {key = key, anim = anim, fw = fw, lf = lf}
			if not prev or prev.key ~= key or prev.anim ~= anim then
				-- (from its first frame: a blow's first step is its quickest, and the pose has taken it by now)
				local tr = ALEX_MERCER_GRAPH[self.MercerNode.path]
				tr = tr and tr[1]
				if not tr or string.lower(tr.anim) ~= anim or not tr.f0 then return end
				local f0 = math.Clamp(math.floor(tr.f0), 0, nf - 1)
				prev = {fw = path[f0 * 3 + 1], lf = path[f0 * 3 + 2]}
			end
			local F = Angle(0, hr.pathYaw or self:GetAngles().y, 0):Forward()
			local L = Vector(-F.y, F.x, 0)
			local d = (F * (fw - prev.fw) + L * (lf - prev.lf)) * M2U
			local v = self.loco:GetVelocity()
			-- (user 2026-11-04: "проигрывается только анимация, но по факту назад он не отходит ... тупо на месте как столб стоит") a grounded NextBot ignores loco:SetVelocity (MODLOG 2026-10-03, MercerShove's own comment): this was his only move, so the
			-- pushbacks, the stumbles and the breakfalls' roll played in place, the anims' root pinned out of the model. The bench's loco took it, so the numbers said 2.7 m. By the path, as the strikes' lunges go; the velocity off for what the run left
			self.loco:SetVelocity(Vector(0, 0, v.z))
			self:MercerShove(d)
		end

		-- states that own the body (the graph's uninterruptible grab / consume, and ours)
		local function busy(self)
			return (self.MercerGrab and "a grab") or (self:GetNW2Bool("MercerHolding") and "a body in hand") or (self.MercerGrind and "the grind") or (self.MercerHToss and "the hammer toss")
				or (self.MercerClawSpike and "the spike")
				or (self:GetNW2Bool("MercerWall") and "the wall") or (self:GetNW2Bool("MercerCharging") and "the jump's charge") or (self.MercerSkid and "the skid")
				or (self.MercerFight and self.MercerFight.atk.devastator and "a devastator")
		end
		-- (user 2026-11-06, alex_mercer_hit_cuts) his strikes have no uninterruptible window in the graph: prototype_bare's windups and releases set motionState AttackWindup / AttackRelease with no flag,
		-- the other forms' and the air's attacks none either, so a hit's reaction takes over from them, in the windup, the hold, the release and the way out alike. Those that do have one: the air dash
		-- (air/actions/dash), the dive roll, the claws' ground spike, the transformations, grabs, consumes; the devastators are invulnerable (graph_devastator). Here: a strike (the fight, the flying kick,
		-- the elbow drop, the stomp), no other action of ACTS, nothing busy
		ENT.MercerCutActs = {MercerFight = true, MercerFKick = true, MercerElbow = true, MercerStomp = true}
		function ENT:MercerHitCuts()
			if not GetConVar("alex_mercer_hit_cuts"):GetBool() or busy(self) or self:IsPlayingAnimation() then return false end
			local f, any = self.MercerFight, false
			if f and (f.atk.devastator or f.caught) then return false end
			for _, k in ipairs(ACTS) do
				if self[k] then
					if not self.MercerCutActs[k] then return false end
					any = true
				end
			end
			-- and the after-attack poses he stands in after his strike (MercerAfterAttack: the graph's combat idle, Idling: any blow's reaction takes over there; here, as the user asked, the strong ones)
			local n = self.MercerNode
			return any or (n ~= nil and string.sub(n.path, 1, 20) == "mercer/after_attack_")
		end
		-- a strong blow, by the graph's attack types (graph_hitreaction.txt): {Hunter} (2870-3367: the Hunters), {Bare} (548-2791: the Super Soldier, the Supreme, another prototype), {Hydra} (5388-5504),
		-- a missile's blast (29-130), a car ({Weapon} 5326-5387) react in any state; {SoldierPush} (5275-5317), {Infected1} (2833-2869), {Infected2} (3368-3431) only standing, walking or already hit, {Bullet}
		-- a push only. And with GMod's attackers, whose types it doesn't know: any blow alex_mercer_heavy_hit makes a knockback
		ENT.MercerStrongBy = {drg_proto_hunter = true, drg_proto_leader_hunter = true, drg_proto_striped_leader_hunter = true, drg_proto_supreme_hunter = true,
			drg_proto_supreme_hunter_weak = true, drg_proto_supersoldier = true, drg_proto_hydra = true, drg_proto_mother_hydra = true, drg_proto_mother = true, drg_alex_mercer = true,
			drg_james_heller = true}
		function ENT:MercerStrongBlow(dmg, amount, attacker)
			if dmg:IsBulletDamage() then return false end
			if dmg:IsDamageType(DMG_BLAST) or dmg:IsDamageType(DMG_VEHICLE) or heavyBlow(self, amount) then return true end
			return IsValid(attacker) and self.MercerStrongBy[attacker:GetClass()] == true
		end
		-- the strike ended for the reaction that follows (start / MercerKnockback put their node over its own)
		function ENT:MercerHitCutAct()
			if self.MercerFight then self:MercerFightEnd() end
			if self.MercerFKick then self:MercerFKickEnd() end
			if self.MercerStomp or self.MercerElbow then
				self.MercerStomp, self.MercerElbow = nil, nil
				self.loco:SetGravity(1000)
				self:SetNW2String("MercerHoldJoint", "")
			end
		end

		-- Under fire (2026-10-08: the earlier "no reaction" was wrong - hit/Bullet/prototype only adds pushback, 0.01 a
		-- bullet, and his own graph reacts to it: prototype loco/default idles / loco / sprint, bank pushbackVelocity > 0):
		--  standing: shot from the front (pushbackDirection 180 +- 22.5) alex_gethit_bullets 54-74 or 78-98 at random;
		--   otherwise a cycle (variable 0 / 1 / 2): 24-50 (60) or alex_gethit_bullet_rshoulder (20) / _lshoulder (20) ->
		--   0-20 (0.4667 s) + 24-50 -> 0-20 -> ...; movement leaves it at once
		--  on the run: upper body over the run - alex_act_block 0-24 (0.8667 s) or 24-52 (0.8333 s), alex_gethit_bullets_
		--   running 0-18 or 22-40, equal weights; on the sprint alex_act_block whole, upper body
		-- (alex_act_block is the arm up against the fire - Prototype 1 has no block button)
		G["mercer/hit/bul_f1"] = {rseg(0, 20 / 30, "alex_gethit_bullets", 54, 74, 0.1, 0.1667)}
		G["mercer/hit/bul_f2"] = {rseg(0, 20 / 30, "alex_gethit_bullets", 78, 98, 0.1, 0.1667)}
		G["mercer/hit/bul_c"] = {rseg(0, 26 / 30, "alex_gethit_bullets", 24, 50, 0.1667, 0.2333)}
		G["mercer/hit/bul_rs"] = {rseg(0, 40 / 30, "alex_gethit_bullet_rshoulder", 0, 40, 0.2, 0.2333)}
		G["mercer/hit/bul_ls"] = {rseg(0, 40 / 30, "alex_gethit_bullet_lshoulder", 0, 40, 0.2, 0.2333)}
		G["mercer/hit/bul_a"] = {rseg(0, 0.4667, "alex_gethit_bullets", 0, 20, 0.1, 0), rseg(0.4667, 0.4667 + 26 / 30,
			"alex_gethit_bullets", 24, 50, 0, 0.0333)}
		G["mercer/hit/bul_b"] = {rseg(0, 20 / 30, "alex_gethit_bullets", 0, 20, 0.1, 0.1333)}
		local RUN_FIRE = {{"alex_act_block", 0, 24}, {"alex_act_block", 24, 52}, {"alex_gethit_bullets_running", 0, 18},
			{"alex_gethit_bullets_running", 22, 40}}
		function ENT:MercerBulletReact(attacker)
			local hr = self.MercerHitSt or {t0 = 0}
			self.MercerHitSt = hr
			if not self:IsOnGround() or hr.down then return end
			local md = self.MercerMoveDir
			local moving = (md ~= nil and not md:IsZero()) or self:GetVelocity():Length2D() > 2 * M2U
			if moving then
				-- (one upper-body track at a time - the shoves share it)
				if CurTime() < (self.MercerNudgeT or 0) or self.MercerNode then return end
				if self.MercerSprintOn then return hitLayer(self, "alex_act_block", 0, 1, nil, 0.3333) end
				local r = RUN_FIRE[math.random(#RUN_FIRE)]
				return hitLayer(self, r[1], r[2], 1, r[3], 0.3)
			end
			-- standing, in his idle: one reaction at a time, the next while still under fire
			if self.MercerNode or self.MercerFight or self:IsPlayingAnimation() then return end
			local to = attacker:WorldSpaceCenter() - self:WorldSpaceCenter()
			to.z = 0
			local front = not to:IsZero() and math.abs(math.AngleDifference(to:Angle().y, self:GetAngles().y)) <= 22.5
			local node
			if front then
				node = math.random(2) == 1 and "bul_f1" or "bul_f2"
			elseif (hr.bul or 0) == 1 then
				node, hr.bul = "bul_a", 2
			elseif hr.bul == 2 then
				node, hr.bul = "bul_b", 0
			else
				local x = math.random(100)
				node, hr.bul = (x <= 60 and "bul_c") or (x <= 80 and "bul_rs") or "bul_ls", 1
			end
			start(self, "mercer/hit/" .. node, {exitAfter = 0, onDone = done}, nil)
		end

		-- (user 2026-11-04: "почему ... не сделаны нормальные реакции на удары") alex_mercer_debug 1: every blow in garrysmod/data/alex_mercer_debug_sv.txt, what came of it and why
		local function blowLog(self, dmg, amount, attacker, what)
			dbg("blow %.1f type %d from %s: %s", amount, dmg:GetDamageType(), IsValid(attacker) and attacker:GetClass() or "nothing", what)
		end
		function ENT:MercerHitReact(dmg, amount, attacker)
			if amount <= 0 then return blowLog(self, dmg, amount, attacker, "no reaction: no damage left") end
			if not GetConVar("alex_mercer_hit_reactions"):GetBool() then return blowLog(self, dmg, amount, attacker, "no reaction: alex_mercer_hit_reactions 0") end
			if not IsValid(attacker) or attacker == self then return blowLog(self, dmg, amount, attacker, "no reaction: no attacker, or himself") end
			local at = busy(self) or acting(self)
			-- (user 2026-11-06) a strong blow through his strike: cut, its reaction below - a knockback anywhere, the standing hit on the ground (in the air without a knockback he goes on)
			local cut = at and self:MercerHitCuts() and self:MercerStrongBlow(dmg, amount, attacker)
				and (self:IsOnGround() or dmg:IsDamageType(DMG_BLAST) or dmg:IsDamageType(DMG_VEHICLE) or heavyBlow(self, amount))
			if at and not cut then return blowLog(self, dmg, amount, attacker, "no reaction: " .. at) end
			-- (user 2026-10-23: none in the landing either) not within 0.5 s of touching down (of a real landing: MercerHitHop)
			if CurTime() - (self.MercerHardLandT or 0) < 0.5 then return blowLog(self, dmg, amount, attacker, "no reaction: just landed") end
			local hr = self.MercerHitSt or {t0 = 0}
			self.MercerHitSt = hr
			-- (user 2026-10-08: spammed heavy blows kept him flying) none while knocked back, nor for alex_mercer_knockback_
			-- immunity s after he lands (the damage still counts) - our limit, the game's graph has none
			if hr.down or CurTime() < (hr.kbFree or 0) then return blowLog(self, dmg, amount, attacker, "no reaction: knocked back, or immune after it") end
			if dmg:IsBulletDamage() then -- (hit/Bullet/prototype: the pushback)
				blowLog(self, dmg, amount, attacker, "a bullet")
				return self:MercerBulletReact(attacker)
			end
			-- the blow's impulse: from the attacker through him (a blast: from where it went off)
			local from = attacker:WorldSpaceCenter()
			if dmg:IsDamageType(DMG_BLAST) and not dmg:GetDamagePosition():IsZero() then from = dmg:GetDamagePosition() end
			local imp = self:WorldSpaceCenter() - from
			imp.z = 0
			if imp:LengthSqr() < 1 then imp = -self:GetForward() end
			imp:Normalize()
			if cut then
				blowLog(self, dmg, amount, attacker, "cuts " .. at)
				self:MercerHitCutAct()
			end
			local kb
			if dmg:IsDamageType(DMG_BLAST) then kb = KB_BLAST
			elseif dmg:IsDamageType(DMG_VEHICLE) or (dmg:IsDamageType(DMG_CRUSH) and heavyBlow(self, amount)) then kb = KB_CAR
			elseif heavyBlow(self, amount) then kb = KB_HEAVY end
			if kb then
				blowLog(self, dmg, amount, attacker, "knockback")
				return self:MercerKnockback(imp, kb)
			end
			-- the standard hit: on the ground, not while flying off / landing from a knockback, not twice in 0.25 s
			if not self:IsOnGround() or hr.down or (reacting(self) and CurTime() - hr.t0 < 0.25) then return blowLog(self, dmg, amount, attacker, "no reaction: the last one under 0.25 s ago") end
			if self.MercerFight then self:MercerFightEnd() end
			self.MercerStomp, self.MercerElbow = nil, nil
			local a = math.AngleDifference(imp:Angle().y, self:GetAngles().y) -- (+ = toward his left)
			local yaw = self:GetAngles().y
			-- (user 2026-11-04: "назад шаг делает"; 2026-11-04, the graph: movement leaves south, east, west from 0.6667 s, north from 0.9 s, the "post_hit" stumble, graph_hitreaction 6390, 6411. Here it left at the 0.4 s of a press, W held: his log, 36 of 323 cut at 0.405 s)
			if math.abs(a) <= 45 then
				start(self, "mercer/hit/south", {exitAfter = 0.4, moveAfter = 0.6667, onDone = done}, yaw)
			elseif a > 45 and a < 135 then
				start(self, "mercer/hit/west", {exitAfter = 0.4, moveAfter = 0.6667, onDone = done}, yaw)
			elseif a < -45 and a > -135 then
				start(self, "mercer/hit/east", {exitAfter = 0.4, moveAfter = 0.6667, onDone = done}, yaw)
			else
				yaw = (-imp):Angle().y -- (facing the blow)
				self:SetAngles(Angle(0, yaw, 0))
				start(self, math.random(2) == 1 and "mercer/hit/north1" or "mercer/hit/north2", {exitAfter = 0.4, moveAfter = 0.9, onDone = done}, yaw)
			end
			blowLog(self, dmg, amount, attacker, self.MercerNode.path)
			self:MercerCue("alex_punch_human", 0.6)
		end
		-- (user 2026-11-04: "когда его бьют, есть анимация того как он назад шаг делает") a blow's push has him off the ground for a tick or two: DrGBase's PushEntity is loco:Jump() and a velocity. Landing again, fall 0 - 90 u/s, OnLandOnGround cut the
		-- reaction that same blow had just started, the kerb's "no landing anim" and MercerHitCancel; and the 0.5 s "just landed" took the next blow's too. His log of 2026-10-28: of 323 standing hits 156 cut so, median life 0.1 s, 19 played out.
		-- The bench had no such hop. Here a landing that soft goes on with the reaction
		function ENT:MercerHitHop()
			local hr = self.MercerHitSt
			return hr ~= nil and not hr.down and reacting(self)
		end
		-- (the NPC pack's Hunter, its forward pull's end, S271) the pushback on his own, driven by its root as after a blow
		function ENT:MercerHitPushback()
			self.MercerHitSt = self.MercerHitSt or {t0 = 0}
			start(self, "mercer/hit/north1", {exitAfter = 0.4, moveAfter = 0.9, onDone = done}, self:GetAngles().y)
		end
		-- (the NPC pack's Hunter, its claws: their hit types are a pushback for him, whatever alex_mercer_hit_reactions says) the standing hit by the blow's way, not twice in 0.25 s, on the ground
		function ENT:MercerHitClaw(imp)
			self.MercerHitSt = self.MercerHitSt or {t0 = 0}
			local hr = self.MercerHitSt
			-- (2026-11-04, the reactions on by default: its damage has just started the standing hit by the blow's way, in this very tick: the typed one takes over from that)
			local since = CurTime() - hr.t0
			if not self:IsOnGround() or hr.down or (reacting(self) and since < 0.25 and since > 0) then return end
			self.MercerStomp, self.MercerElbow = nil, nil
			local yaw = self:GetAngles().y
			local typed = clawType(self)
			if typed then
				start(self, "mercer/hit/" .. typed, {exitAfter = 0.4, moveAfter = 0.6667, onDone = done}, yaw)
				hr.orient = (-imp):Angle().y
				self:MercerCue("alex_punch_human", 0.6)
				return
			end
			local a = math.AngleDifference(imp:Angle().y, yaw) -- (+ = toward his left)
			local node = "mercer/hit/" .. (math.abs(a) <= 45 and "south" or (a > 45 and a < 135) and "west" or (a < -45 and a > -135) and "east" or "north1")
			if node == "mercer/hit/north1" then
				yaw = (-imp):Angle().y -- (facing the blow)
				self:SetAngles(Angle(0, yaw, 0))
			end
			start(self, node, {exitAfter = 0.4, moveAfter = node == "mercer/hit/north1" and 0.9 or 0.6667, onDone = done}, yaw)
			self:MercerCue("alex_punch_human", 0.6)
		end
		-- (the NPC pack's Leader Hunter, its stomps' wide hits) on the ground, dive-rolling or in the air nothing (graph_hitreaction.txt 3167, 3202); out of it from 0.5667 s
		function ENT:MercerHitStun()
			if not self:IsOnGround() or self.MercerDive then return end
			self.MercerHitSt = self.MercerHitSt or {t0 = 0}
			local p = self:GetPossessor()
			local move = IsValid(p) and (p:KeyDown(IN_FORWARD) or p:KeyDown(IN_BACK) or p:KeyDown(IN_MOVELEFT) or p:KeyDown(IN_MOVERIGHT))
			start(self, move and "mercer/hit/stun_move" or "mercer/hit/stun", {exitAfter = 0.5667, onDone = done}, self:GetAngles().y)
			self:MercerShake("large", "large")
			self:MercerVO("alex_jump_sml_start", 0.5)
		end

		function ENT:MercerKnockback(imp, kb)
			if self.MercerFight then self:MercerFightEnd() end
			if self.MercerFKick then self:MercerFKickEnd() end
			self.MercerStomp, self.MercerElbow, self.MercerAirDash = nil, nil, nil
			if self.MercerSprintOn then self:MercerSprintEnd() end
			local hr = self.MercerHitSt or {t0 = 0}
			self.MercerHitSt = hr
			hr.down, hr.recovered, hr.downT = true, nil, CurTime()
			self:SetAngles(Angle(0, (-imp):Angle().y, 0)) -- facing the blow
			-- reactionFloat: the distance over the time, up to the height. (user 2026-11-04: "пусть все будет по графам как в игре") The arc went by plain gravity, 0.42 s whatever the time said: a car's 10 m in 1 s flew 4.2, the Hunter's heavy 5 m flew 7, its strongest 11 m flew 26.
			-- Now the arc of the graph's own time, gravity back at its end. (A height of 0 in the graph: still off the ground, or the distance is lost at once)
			local t, dist, h = kb[1], kb[2], math.max(kb[3], 0.1)
			local hu = h * M2U
			self.loco:SetGravity(8 * hu / (t * t))
			hr.kbEnd = CurTime() + t
			self:LeaveGround()
			self.MercerFallSpeed = 0
			self.loco:SetVelocity(imp * (dist / t * M2U) + Vector(0, 0, mpVz(4 * hu / t)))
			start(self, "mercer/hit/fly", {}, nil)
			self:MercerCue("alex_punch_human", 0.8)
			self:MercerShake("small", "medium")
		end

		-- the knockback's landing: the breakfall (common/prototype/breakfall)
		function ENT:MercerHitLand(speed)
			local hr = self.MercerHitSt
			if not hr or not hr.down then return false end
			hr.down = nil
			if hr.kbEnd then
				hr.kbEnd = nil
				self.loco:SetGravity(1000)
			end
			hr.kbFree = CurTime() + 1 + GetConVar("alex_mercer_knockback_immunity"):GetFloat() -- (the breakfall ~1 s, then N s)
			if hr.recovered then return false end -- (AirRecover: the plain landing)
			local v = (speed or 0) / M2U -- (OnLandOnGround has already cleared MercerFallSpeed)
			local r, dmgv = 2, 5
			if v >= 50 then
				r, dmgv = 5, 20
			elseif v >= 30 then
				r, dmgv = 4, 15
			end
			self:Attack({damage = dmgv, range = r * M2U, angle = 360, type = DMG_CRUSH, force = Vector(150, 0, 120), push = true})
			self:MercerVFX("land_soft", self:GetPos() + Vector(0, 0, 2))
			self:MercerVFX("dash", self:GetPos() + Vector(0, 0, 2)) -- (breakfall/skid dust)
			self:MercerCue("alex_land", 0.8)
			start(self, math.random(2) == 1 and "mercer/hit/bf1" or "mercer/hit/bf2", {exitAfter = 0.5, onDone = done},
				self:GetAngles().y)
			return true
		end

		-- every tick, hit reactions on or off, hit or not: an action takes the upper layers off (before it was only in
		-- MercerHitThink - never run until he had been hit once, so the shove's layer froze over his strikes)
		function ENT:MercerLayersDrop()
			local action = acting(self) or busy(self) or self.MercerChargeStart or self.MercerGun
				or self:GetNW2Bool("MercerHolding") or not self:MercerPlainLoco()
			if self.MercerLayers and #self.MercerLayers > 0 and action then
				dropHitLayers(self)
			end
			-- (user 2026-10-29: the freeze over a roll, again) every layer slot, tracked or not: one of the upper-body
			-- copies (*_upper) still showing during an action, or showing untracked at any time (lost: nothing would
			-- step or end it), is taken off. The shield's own pose layer is left to the shield
			local mine = {}
			for _, l in ipairs(self.MercerLayers or {}) do mine[l.id] = true end
			local sh = self.MercerShieldSt
			if sh and sh.layer then mine[sh.layer.id] = true end
			if self.MercerBladeLayer then mine[self.MercerBladeLayer.id] = true end
			for i = 0, 14 do
				if self:IsValidLayer(i) and self:GetLayerWeight(i) > 0.001 and (action or not mine[i]) then
					local seq = self:GetLayerSequence(i)
					local name = seq and seq >= 0 and self:GetSequenceName(seq) or ""
					if string.sub(name, -6) == "_upper" and not (sh and sh.layer and sh.layer.id == i) then
						dbg("layer %d %s off: weight %.2f, %s", i, name, self:GetLayerWeight(i), mine[i] and "tracked" or "untracked")
						self:MercerKillLayer(i)
					end
				end
			end
		end
		function ENT:MercerHitThink(dt)
			local hr = self.MercerHitSt
			if hr.down and CurTime() - (hr.downT or 0) > 6 then -- (never came down)
				hr.down, hr.kbFree = nil, CurTime() + GetConVar("alex_mercer_knockback_immunity"):GetFloat()
			end
			if hr.kbEnd and CurTime() >= hr.kbEnd then -- (the float's over: he falls as anyone)
				hr.kbEnd = nil
				self.loco:SetGravity(1000)
			end
			if not reacting(self) then
				hr.pathPrev = nil
				if hr.braked then
					hr.braked = nil
					if not self.MercerSprintOn then self.loco:SetDeceleration(self.Deceleration) end
				end
				return
			end
			local node = self.MercerNode.path
			local p = self:GetPossessor()
			local md = self.MercerMoveDir
			local moving = md ~= nil and not md:IsZero()
			if node == "mercer/hit/fly" then
				-- AirRecover: Jump in the flight
				if IsValid(p) and CurTime() - hr.t0 > 0.1 and p:KeyDown(IN_JUMP) and not hr.jumpWas then
					hr.recovered = true
					start(self, "mercer/hit/recover", {onDone = function(ent)
						if ent:IsOnGround() then ent:UpdateAnimation() else ent:MercerAirPose() end
					end}, nil)
				end
				hr.jumpWas = IsValid(p) and p:KeyDown(IN_JUMP)
				return
			end
			hr.jumpWas = IsValid(p) and p:KeyDown(IN_JUMP)
			if node == "mercer/hit/recover" then
				-- flyingBrake: the flight's carry braked to 1 m/s across
				local v = self.loco:GetVelocity()
				local hv = Vector(v.x, v.y, 0)
				local hs = hv:Length()
				if hs > M2U then hv = hv * (math.max(M2U, hs - 10 * M2U * dt) / hs) end
				self.loco:SetVelocity(Vector(hv.x, hv.y, v.z))
				return
			end
			if string.sub(node, 1, 14) == "mercer/hit/rec" then
				-- the stumble turns to the stick (orient 600 deg/s) and runs along its own root
				if moving then
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, md:Angle().y, 600 * dt), 0))
				end
				pathStep(self, hr, dt)
				return
			end
			pathStep(self, hr, dt)
			if hr.orient then self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, hr.orient, 180 * dt), 0)) end
			-- the pushbacks: from 0.6667 s, movement held -> the exit bank's stumble out of it
			local push = node == "mercer/hit/north1" or node == "mercer/hit/north2" or node == "mercer/hit/south"
				or node == "mercer/hit/east" or node == "mercer/hit/west" or node == "mercer/hit/lh1" or node == "mercer/hit/lh2"
				or node == "mercer/hit/rh1" or node == "mercer/hit/rh2"
			if push and moving and CurTime() - hr.t0 >= (self.MercerNode.opts.moveAfter or 0.6667) then
				start(self, "mercer/hit/rec" .. math.random(3), {exitAfter = 0.5667, onDone = done}, nil)
			end
		end
	end

	local WALL_TURN = 80 -- wallRun turningRate (°/s)
	-- switch the wall run onto an adjacent face (normal within 90° of the current one, like the game's
	-- surfaceAngleThreshold); returns true when it wrapped
	function ENT:MercerWallWrap(normal, hitpos)
		local nn = Vector(normal.x, normal.y, 0)
		if math.abs(normal.z) > 0.3 or nn:Length() < 0.5 then return false end
		nn:Normalize()
		local n = self.MercerWallNormal
		local dot = nn:Dot(n)
		if dot > 0.94 or dot < -0.01 then return false end -- same face, or more than 90° round
		-- (user 2026-10-22: the change of face was abrupt - thrown off, stuck in the corner, fell) no snap: over 0.2 s
		-- he is carried along a smooth path onto the new face's hug point, turning to it, still going up / along
		-- (MercerWallThink's glide), nothing else checked meanwhile
		local pos = self:GetPos()
		local yaw0 = self.MercerWallYaw or self:GetAngles().y
		self.MercerWallNormal = nn
		self.MercerWallYaw = (-nn):Angle().y
		self.MercerWallPoint = Vector(hitpos.x, hitpos.y, 0) + nn * 16
		self:SetNW2Vector("MercerWallNormal", nn)
		self.MercerWallGlide = {t0 = CurTime(), p0 = Vector(pos.x, pos.y, 0), p1 = self.MercerWallPoint * 1, yaw0 = yaw0,
			yaw1 = self.MercerWallYaw}
		return true
	end

	-- the wall run's obstacleAvoid over a ledge: 0.4 s, 0.5 m clear of it (alex_wall_run_hop_up 12-18), out from the wall
	-- and 1.4 m up, back onto the wall above it
	ALEX_MERCER_GRAPH["mercer/wall_hop"] = {seg(0, 0.4, "alex_wall_run_hop_up", 12, 18)}
	local HOP_UP = 1.4 * M2U
	function ENT:MercerWallLedge(n, at)
		local pos = at or self:GetPos()
		local mins, maxs = Vector(-12, -12, 0), Vector(12, 12, 72)
		for _, d in ipairs({0.6, 1.0, 1.5, 2.1}) do
			local out = pos + n * (d * M2U)
			local free = util.TraceHull({start = out + Vector(0, 0, 4), endpos = out + Vector(0, 0, HOP_UP + 8), mins = mins,
				maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
			if not free.Hit and not free.StartSolid then
				-- the wall must go on above the ledge
				local hi = pos + Vector(0, 0, HOP_UP + 40) + n * (d * M2U)
				local wall = util.TraceLine({start = hi, endpos = hi - n * ((d + 0.6) * M2U), filter = self, mask = MASK_SOLID_BRUSHONLY})
				if wall.Hit and math.abs(wall.HitNormal.z) < 0.3 then return d end
				return nil
			end
		end
	end
	-- (2026-11-05, tools/overhang_map.py, gm_construct's own ledges: 1.4 m up and back in stood him inside the ledge at its end, 11 ticks; the bench had hidden it, SetPos colliding there) up until his hull is free at the wall again, up to 4 m. graph_wall's hop goes up at 10..16 m/s for its 0.4 s
	function ENT:MercerWallHopRise(pos)
		local mins, maxs = self:OBBMins(), self:OBBMaxs()
		for up = HOP_UP, 4 * M2U, 8 do
			local at = pos + Vector(0, 0, up)
			if not util.TraceHull({start = at, endpos = at, mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY}).StartSolid then return up end
		end
	end
	function ENT:MercerWallHopStart(n, d)
		local pos = self:GetPos()
		local rise = self:MercerWallHopRise(pos) or HOP_UP
		local mins, maxs = self:OBBMins(), self:OBBMaxs()
		local col = pos + n * ((d + 0.1) * M2U)
		local tr = util.TraceHull({start = col, endpos = col + Vector(0, 0, rise), mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
		if tr.Hit and not tr.StartSolid then rise = math.max(HOP_UP, rise * tr.Fraction - 1) end
		self.MercerWallHop = {t0 = CurTime(), from = pos, out = n * ((d + 0.1) * M2U), up = rise}
		GP.Start(self, self:MercerWallPosesOk() and "mercer/wall_usd_hop" or "mercer/wall_hop", {block = true, hold = true})
		self:MercerSound(SND.jump_wind, 65)
		self:MercerCue("alex_feet")
	end
	-- graph_wall obstacle/avoid/roll (Run + movement, an obstacle 0.5-2.1 m ahead on the wall within 0.3 s): obstacleAvoid
	-- 0.4 s, 0.5 m clear of it; the pose by the run's direction - up-right (-45 +-22.5 deg) alex_wall_roll_diagonal_r,
	-- right (beyond -67.5) alex_wall_roll_r, left (beyond 22.5) alex_wall_roll_l, 11-30 over 0.4 s (straight up: the hop)
	ALEX_MERCER_GRAPH["mercer/wall_roll_l"] = {seg(0, 0.4, "alex_wall_roll_l", 11, 30)}
	ALEX_MERCER_GRAPH["mercer/wall_roll_r"] = {seg(0, 0.4, "alex_wall_roll_r", 11, 30)}
	ALEX_MERCER_GRAPH["mercer/wall_roll_dr"] = {seg(0, 0.4, "alex_wall_roll_diagonal_r", 11, 30)}
	-- an obstacle on the wall across the run: its width (m) when it can be rolled over and the wall goes on past it
	function ENT:MercerWallSideObstacle(n, mdir)
		local pos = self:GetPos()
		local mins, maxs = Vector(-12, -12, 0), Vector(12, 12, 72)
		local out = pos + n * (0.5 * M2U) + Vector(0, 0, 4)
		for _, w in ipairs({0.6, 1.0, 1.5, 2.1}) do
			local past = out + mdir * ((w + 0.5) * M2U)
			local free = util.TraceHull({start = out, endpos = past, mins = mins, maxs = maxs, filter = self,
				mask = MASK_SOLID_BRUSHONLY})
			if free.Hit or free.StartSolid then return nil end
			local probe = past + Vector(0, 0, 32)
			local wall = util.TraceLine({start = probe, endpos = probe - n * (1.2 * M2U), filter = self, mask = MASK_SOLID_BRUSHONLY})
			if wall.Hit and wall.HitNormal:Dot(n) > 0.94 then
				-- clear of the obstacle there (not still on its face)
				local near = util.TraceHull({start = past - n * (0.3 * M2U), endpos = past - n * (0.3 * M2U), mins = mins,
					maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
				if not near.StartSolid then return w end
			end
		end
	end
	function ENT:MercerWallRollStart(n, mdir, w, a)
		local pose = (a <= -22.5 and a >= -67.5 and "dr") or (a < -67.5 and "r") or "l"
		local v = Vector(0, 0, math.cos(math.rad(a))) * (self.MercerWallSpeed or 10 * M2U)
		self.MercerWallRoll = {t0 = CurTime(), from = self:GetPos(), out = n * (0.5 * M2U), along = mdir * ((w + 0.5) * M2U),
			up = v * 0.4}
		GP.Start(self, "mercer/wall_roll_" .. pose, {block = true, hold = true})
		self:MercerSound(SND.jump_wind, 65)
		self:MercerCue("alex_feet")
	end
	local function wallRollThink(self, n)
		local r = self.MercerWallRoll
		local k = math.Clamp((CurTime() - r.t0) / 0.4, 0, 1)
		self.loco:SetGravity(0)
		self.loco:SetVelocity(Vector(0, 0, 0))
		self:SetPos(r.from + r.out * math.sin(math.pi * k) + r.along * k + r.up * k)
		if k < 1 then return end
		self.MercerWallRoll = nil
		GP.Stop(self)
		if self:MercerWallTrace(40, 36).Hit then
			self.MercerWallPoint = self:GetPos()
			self:UpdateAnimation()
		else
			self:MercerStopWall(Vector(0, 0, 2 * M2U))
			toAir(self)
		end
	end
	local wallTopExit
	local function wallHopThink(self, n)
		local h = self.MercerWallHop
		local k = math.Clamp((CurTime() - h.t0) / 0.4, 0, 1)
		self.loco:SetGravity(0)
		self.loco:SetVelocity(Vector(0, 0, 0))
		-- (out first, in its first 0.12 s, up from 0.06 s on, and out to its end: the run's own pull takes him back, MercerWallThink's fix, once he is over it)
		local ko, ku = math.Clamp(k / 0.3, 0, 1), math.Clamp((k - 0.15) / 0.85, 0, 1)
		self:SetPos(h.from + h.out * (ko * ko * (3 - 2 * ko)) + Vector(0, 0, (h.up or HOP_UP) * ku * ku * (3 - 2 * ku)))
		if k < 1 then return end
		self.MercerWallHop = nil
		GP.Stop(self)
		local pos = self:GetPos()
		local home = Vector(h.from.x, h.from.y, pos.z)
		local start = home + Vector(0, 0, 36)
		if util.TraceHull({start = start, endpos = start - n * 40, mins = Vector(-6, -6, -6), maxs = Vector(6, 6, 6), filter = self, mask = MASK_SOLID_BRUSHONLY}).Hit then
			-- back on the wall above the ledge: the run goes on
			self.MercerWallPoint = home
			self:UpdateAnimation()
		else
			-- (no wall above it: over the top as from any wall, along the wall's own normal, wherever the camera looks. It was 4 m/s up and the air's drift, along the camera)
			wallTopExit(self, n)
		end
	end

	-- up round a lip (MercerWallLipTop): out off the wall, up past it, in over the roof (0.4 s, the hop's pose), then
	-- the top exit
	local function wallLipThink(self, n)
		local l = self.MercerWallLip
		local k = math.Clamp((CurTime() - l.t0) / 0.4, 0, 1)
		local function ease(x) x = math.Clamp(x, 0, 1) return x * x * (3 - 2 * x) end
		local o = ease(k / 0.35)
		local u = ease((k - 0.15) / 0.55)
		local i = ease((k - 0.6) / 0.4)
		local out = Vector(l.out.x, l.out.y, l.from.z)
		local p = LerpVector(o, l.from, out)
		p.z = Lerp(u, l.from.z, l.top.z)
		p = LerpVector(i, p, l.top)
		self:SetPos(p)
		self.loco:SetGravity(0)
		self.loco:SetVelocity(Vector(0, 0, 0))
		if k < 1 then return end
		self.MercerWallLip = nil
		GP.Stop(self)
		return wallTopExit(self, n)
	end

	-- (user 2026-11-05: "Бег по навесу и перепрыгивание оттуда сможете? Пусть со второй части возьмут если в первой нет"; "он бежал по потолку типа... по этой крыше он вертикально пробегал верх ногами и анимация перепрыгивания там была")
	-- Prototype 2's wall_run/obstacle/avoid (heller/build/graphs/graph_prototype_wall.txt 327-565; obstacleAvoid's fields out of prototype2engine.dll: "up" is out of the wall, "forward" up it). Where the stuck pose stood, Run and a direction held, going up within 60 deg:
	-- {medium}, the edge under 3 m out, from under 2 m below it: heller_run_up_awning 0-17, 0.5 s: out at 2..8 m/s as far as the edge asks (exit on it cleared), up at 5; then 17-26, moveAtVelocity 14 to 6 m/s up in 0.3333 s, drift to 2 m/s, the air.
	-- {large}, the edge 3 to 6 m out (obstacleFaceHeightSlope's 6), with 7 m rays at 0 and +- 0.4 m free for 6 m out, else stuck: under it at 5 m/s, the feet on it, to 1.5 m short of the edge (obstacleClearance -1.5); the transition: 0.3333 s out at 5 m/s, up at 4.5 once clear; then as {medium}'s end.
	-- Run let go: off into the fall at any time (the graph's opportunity). Not with a human in hand: his _2hnd anims aren't ported.
	-- BY EYE: 30 deg either way for the slope of what's overhead; {medium} under 1.5 m too, where it was the stuck pose; the rays' height, under what's overhead; the hull touching the ceiling, the anims carry the feet up to it; he stays at the wall's turn 0 while under it (the game turns at 45 deg/s)
	-- (alex_mercer_debug 1) "навес: ..." what the check saw and why not: the same line at most every 0.5 s
	function ENT:MercerOverhangSay(fmt, ...)
		if not DebugAnim:GetBool() then return end
		local s = string.format(fmt, ...)
		if s == self.MercerOverhangSaid and CurTime() - (self.MercerOverhangSaidT or 0) < 0.5 then return end
		self.MercerOverhangSaid, self.MercerOverhangSaidT = s, CurTime()
		dbg("навес: %s", s)
	end
	-- A step along a ceiling over his hull: the place under it and true; or past its edge with room to rise, the place and false; or nil and why: a wall across, the ceiling too steep, a second one close above the edge
	function ENT:MercerUnderStep(from, n, dist, slack)
		local mins, maxs = self:OBBMins(), self:OBBMaxs()
		local t = {filter = self, mask = MASK_SOLID_BRUSHONLY, mins = Vector(mins.x + 0.5, mins.y + 0.5, mins.z), maxs = Vector(maxs.x - 0.5, maxs.y - 0.5, maxs.z)}
		slack = slack or dist * 0.6 + 1
		t.start, t.endpos = from, from - Vector(0, 0, slack)
		local tr = util.TraceHull(t)
		if tr.StartSolid then return nil, "он в геометрии у потолка" end
		t.start, t.endpos = tr.HitPos, tr.HitPos + n * dist
		tr = util.TraceHull(t)
		if tr.StartSolid then return nil, "он в геометрии у потолка" end
		if tr.Hit then return nil, math.abs(tr.HitNormal.z) < 0.3 and "стена поперёк" or "потолок идёт вниз круче 30 град" end
		local at = tr.HitPos
		t.start, t.endpos = at, Vector(at.x, at.y, from.z + slack)
		tr = util.TraceHull(t)
		if tr.StartSolid then return nil, "он в геометрии у потолка" end
		if tr.Hit then return Vector(at.x, at.y, tr.HitPos.z - 1), true end
		-- (past it with his whole hull, the engine's, a hair more than these traces': not caught on the corner going up)
		local past = Vector(at.x, at.y, from.z) + n
		t.mins, t.maxs, t.start, t.endpos = mins, maxs, past, past + Vector(0, 0, 1.5 * M2U)
		tr = util.TraceHull(t)
		if tr.StartSolid then return Vector(at.x, at.y, from.z), true end
		if tr.Hit then return Vector(past.x, past.y, tr.HitPos.z - 1), true end
		return past, false
	end
	-- how far out his hull clears what's over it (m), walked from just under it; nil and why when he can't, how far he got
	function ENT:MercerWallOverhang(n, under)
		local p, out, low = under, 0, under.z
		local steps = 0
		local trail = {under}
		for _ = 1, 25 do
			local nx, still = self:MercerUnderStep(p, n, 0.25 * M2U)
			if not nx then return nil, still, out end
			if still and nx.z - p.z > 0.25 * M2U * 0.6 + 1 then
				steps = steps + nx.z - p.z
				if steps > 1.5 * M2U then return nil, "потолок идёт вверх круче 30 град", out end
			end
			out = out + 0.25
			if not still then
				if out >= 3 then
					local side = n:Cross(Vector(0, 0, 1))
					for _, off in ipairs({0, 0.4, -0.4}) do
						-- (at his hull's middle at its lowest under it: from 40 u under his feet, as it was, they met a balcony's own parapet below him, gm_construct's stacked ones)
						local s = Vector(under.x, under.y, low + 36) + side * (off * M2U)
						local ray = util.TraceLine({start = s, endpos = s + n * (6 * M2U), filter = self, mask = MASK_SOLID_BRUSHONLY})
						if ray.Hit and not ray.StartSolid then return nil, string.format("луч наружу упёрся через %.1f м", ray.Fraction * 6), out end
					end
				end
				self.MercerOverhangTrail = trail
				return out
			end
			low = math.min(low, nx.z)
			p = nx
			trail[#trail + 1] = nx
		end
		return nil, "глубже 6 м, это потолок", out
	end
	-- (2026-11-05, the user's "его тупо нет", tools/overhang_map.py on gm_construct's brushes: of 277 places by a wall with an overhang 0.5 to 6 m deep over them, in 182 the wall run never began, the rule of 2026-10-29 "balcony/doorway = no run", 3.33 m clear asked for, and a floor there is 3.15 m. P2's wall test has no such rule: it takes the wall and {medium} takes what's over it.)
	-- What's overhead from the ground: he can run out from under it, 1 m deep at least by {medium}: a doorway's lintel stays no run, as the user asked. BY EYE: 12 u of room to lift off under it. A wall run begun here goes on in MercerWallThink. Its walk is up to 75 hull traces and he may stand at the wall running: the answer is kept 0.1 s
	-- (user 2026-11-05: "четвертый клип где мерсер теперь нормально балкон перепрыгнуть не может и цепляется боком за потолок") the plain wall run comes first: an overhang only over a real wall and a real awning. A wall is a face up his whole body: a parapet 44 u high with a slab over it took him upside down back into the room he came from.
	function ENT:MercerOverhangWallOk(pos, n, head)
		-- (head: from the ground. On the wall, by the ceiling, a recess at his head's height isn't an end of the wall: the long eave on gm_construct)
		for _, h in ipairs(head and {6, 36, 66} or {6, 36}) do
			local a = pos + Vector(0, 0, h)
			local tr = util.TraceLine({start = a, endpos = a - n * 46, filter = self, mask = MASK_SOLID_BRUSHONLY})
			if not tr.Hit or tr.StartSolid or math.abs(tr.HitNormal.z) > 0.3 then return false, h end
		end
		return true
	end
	-- (the same clip, from a brick column's side: a balcony's slab 64 u wide reaching 128 u away from him along the column, he ran along it on his side.) It's an awning when it's about as wide along the wall as it's deep; how wide, by rays up at half its depth, each way along the wall
	function ENT:MercerOverhangWideOk(n, out)
		-- (the walk's own place at half the depth, or nearer the wall if his middle is past the edge there, a sloping ceiling's height with it: his hull's top 1 u under it)
		local trail = self.MercerOverhangTrail
		if not trail then return true, 0 end
		local top = self:OBBMaxs().z + 1
		local mid
		for i = math.ceil(#trail / 2), 1, -1 do
			local q = trail[i]
			local tr = util.TraceLine({start = Vector(q.x, q.y, q.z + top - 8), endpos = Vector(q.x, q.y, q.z + top + 8), filter = self, mask = MASK_SOLID_BRUSHONLY})
			if tr.Hit and not tr.StartSolid then
				mid = q
				break
			end
		end
		if not mid then return true, 0 end
		local side = Vector(-n.y, n.x, 0)
		local c = mid.z + top
		local w = 0
		for _, sg in ipairs({1, -1}) do
			for d = 8, 256, 8 do
				local q = mid + side * (sg * d)
				local tr = util.TraceLine({start = Vector(q.x, q.y, c - 8), endpos = Vector(q.x, q.y, c + 8), filter = self, mask = MASK_SOLID_BRUSHONLY})
				if not tr.Hit or tr.StartSolid then break end
				w = w + 8
			end
		end
		return w >= 0.75 * out * M2U, w / M2U
	end
	function ENT:MercerWallLowOver()
		local pos, mins, maxs = self:GetPos(), self:OBBMins(), self:OBBMaxs()
		return util.TraceHull({start = pos + Vector(0, 0, 4), endpos = pos + Vector(0, 0, 24), mins = Vector(mins.x + 0.5, mins.y + 0.5, 0), maxs = Vector(maxs.x - 0.5, maxs.y - 0.5, maxs.z), filter = self, mask = MASK_SOLID_BRUSHONLY}).Hit
	end
	function ENT:MercerWallOverhangAhead(n, wp, at)
		local c = self.MercerOverhangAheadC
		if c and CurTime() < c.t and c.at:DistToSqr(at) < 16 and c.n:Dot(n) > 0.99 then
			self.MercerOverhangAheadOk = c.ok and CurTime() or nil
			return c.ok
		end
		local ok = false
		local p = self:GetPossessor()
		if IsValid(p) and self.MercerOverhangOn:GetBool() and not self:GetNW2Bool("MercerHolding") then
			local room = (at.z + 72 - wp.z) / M2U
			if self:LookupSequence("alex_loco_run_upsidedown_cycle") < 0 then
				self:MercerOverhangSay("с земли: над ним %.2f м: в модели нет анимаций навеса, нужна загрузка карты", room)
			elseif at.z - wp.z < 12 then
				self:MercerOverhangSay("с земли: над ним %.2f м: отказ, тесно", room)
			else
				local out, why, got = self:MercerWallOverhang(n, Vector(at.x, at.y, at.z - 1))
				if not out then
					self:MercerOverhangSay("с земли: над ним %.2f м, прошёл %.2f м: отказ: %s", room, got or 0, why)
				elseif out < 1 then
					self:MercerOverhangSay("с земли: над ним %.2f м, глубина %.2f м: отказ, меньше 1 м", room, out)
				else
					local wall, wh = self:MercerOverhangWallOk(wp, n, true)
					local wide, ww = self:MercerOverhangWideOk(n, out)
					if not wall then
						self:MercerOverhangSay("с земли: над ним %.2f м, глубина %.2f м: отказ, стены нет на высоте %d u", room, out, wh)
					elseif not wide then
						self:MercerOverhangSay("с земли: над ним %.2f м, глубина %.2f м: отказ, шириной %.2f м: не навес", room, out, ww)
					else
						self:MercerOverhangSay("с земли: над ним %.2f м, глубина %.2f м: на стену", room, out)
						ok = true
					end
				end
			end
		end
		self.MercerOverhangAheadC = {t = CurTime() + 0.1, at = at, n = n, ok = ok}
		self.MercerOverhangAheadOk = ok and CurTime() or nil
		return ok
	end
	-- started? blocked: his head at it now; otherwise {medium}'s from 2 m under it. By P2's numbers what's 1 m deep or more is {medium} or {large}: the hop (P1's, up to 2.1 m) only under that, any: whatever it is, the hop and the lip having said no
	function ENT:MercerWallOverhangTry(p, n, pos, blocked, any)
		if CurTime() < (self.MercerOverhangFailT or 0) then return false end
		if not IsValid(p) or not self.MercerOverhangOn:GetBool() or self:GetNW2Bool("MercerHolding") then
			if blocked then self:MercerOverhangSay("на стене: отказ: %s", self:GetNW2Bool("MercerHolding") and "человек в руках" or "выключен, alex_mercer_wall_overhang 0") end
			return false
		end
		local dir = self:GetNW2Float("MercerWallDir", 0)
		if math.abs(dir) > 60 then
			if blocked then self:MercerOverhangSay("на стене: направление %.0f град: отказ, больше 60", dir) end
			return false
		end
		-- (a game still on the model from before this: no such anims, the stuck pose as it was)
		if self:LookupSequence("alex_loco_run_upsidedown_cycle") < 0 then
			self:MercerOverhangSay("на стене: в модели нет анимаций навеса, нужна загрузка карты")
			return false
		end
		local mins, maxs = self:OBBMins(), self:OBBMaxs()
		-- (from his feet: from 4 u up it started solid with his head at a low ceiling, as he is the moment he takes a wall under one)
		local tr = util.TraceHull({start = pos, endpos = pos + Vector(0, 0, 4 + 2 * M2U), mins = Vector(mins.x + 0.5, mins.y + 0.5, mins.z),
			maxs = Vector(maxs.x - 0.5, maxs.y - 0.5, maxs.z), filter = self, mask = MASK_SOLID_BRUSHONLY})
		if tr.StartSolid or not tr.Hit then
			if blocked then self:MercerOverhangSay("на стене: упёрся, но над ним свободно: %s", tr.StartSolid and "он в геометрии" or "движение встало") end
			return false
		end
		local under = Vector(pos.x, pos.y, tr.HitPos.z - 1)
		local gap = (under.z - pos.z) / M2U
		local tilt = math.deg(math.acos(math.Clamp(-tr.HitNormal.z, -1, 1)))
		if not any and self:MercerWallLipTop(under, n) then
			self:MercerOverhangSay("на стене: до него %.2f м, угол %.0f: карниз и крыша за ним, через край", gap, tilt)
			return false
		end
		local out, why, got = self:MercerWallOverhang(n, under)
		if not out then
			self:MercerOverhangSay("на стене: до него %.2f м, угол %.0f, прошёл %.2f м: отказ: %s", gap, tilt, got or 0, why)
			return false
		end
		-- (in the first ticks off the ground he isn't at the wall yet: how deep it is from where the run goes)
		local depth = out + math.max(0, (pos - self.MercerWallPoint):Dot(n)) / M2U
		if not any and depth < 1 then
			self:MercerOverhangSay("на стене: до него %.2f м, угол %.0f, глубина %.2f м: меньше 1 м, прыжок", gap, tilt, depth)
			return false
		end
		if not blocked and depth >= 3 then return false end
		local wall, wh = self:MercerOverhangWallOk(pos, n)
		if not wall then
			self:MercerOverhangSay("на стене: до него %.2f м, глубина %.2f м: отказ, стены нет на высоте %d u", gap, depth, wh)
			return false
		end
		local wide, ww = self:MercerOverhangWideOk(n, out)
		if not wide then
			self:MercerOverhangSay("на стене: до него %.2f м, глубина %.2f м: отказ, шириной %.2f м: не навес", gap, depth, ww)
			return false
		end
		self:MercerOverhangSay("на стене: до него %.2f м, угол %.0f, глубина %.2f м: пошёл, %s", gap, tilt, depth, depth < 3 and "быстрый заброс" or "вверх ногами")
		local medium = depth < 3
		self.MercerWallUsd = {t0 = CurTime(), phase = medium and "awning" or "run", under = true, hug = under, gap = under.z - pos.z, left = out,
			out = medium and math.Clamp(out / 0.5, 2, 8) * M2U or 5 * M2U}
		self.MercerWallProg = nil
		self.loco:SetVelocity(Vector(0, 0, 0))
		GP.Start(self, medium and (self:MercerWallPosesOk() and "mercer/wall_usd_awningb" or "mercer/wall_usd_awning") or "mercer/wall_usd_run", {block = true, hold = true})
		self:MercerSound(SND.jump_wind, 65)
		self:MercerCue("alex_feet")
		dbg("wall overhang: %s, the edge %.2f m out, %.2f m under it", medium and "medium" or "large", out, (under.z - pos.z) / M2U)
		return true
	end
	function ENT:MercerWallUsdOff(vel, clean)
		GP.Stop(self)
		-- (the wall run's tilt out over the next pose's blend: these anims stand in its space, tools/build_all.py)
		self:SetNW2Float("MercerWallUsdExitT", CurTime())
		self:MercerStopWall(vel)
		-- (graph_air fall/mechanics: its wall test from 0.1333 s, not a wall's 0.6 s. Only past the edge: come off short of it, the same wall would take him and the same try throw him off again, on and on, stuck to it)
		if clean then self.MercerWallCooldown = CurTime() + 0.1333 else self.MercerOverhangFailT = CurTime() + 1.5 end
		toAir(self)
	end
	-- (user 2026-11-05: "он не бежит дальше, в смысле либо падает, или застревает в текстурке, ну как сказать застревает, просто липнет к ней, выбраться оттуда без труда можно")
	-- Past the edge. What it was: 0.3333 s up, then off the wall with no wall test for 0.6 s, whatever stood at the edge in his way: on gm_construct's stacked balconies a rail and the next one's edge, he fell beside them or came to stand on the rail. And nothing ever put him back on the wall above.
	-- P2's transition goes to the air, and its wall test takes the first wall he meets. Here he stays on the wall where there is one, with the keys held (W: the graph's drift is the keys'), so the tilt stays and the speed:
	-- a face all along his hull right here: the plain run goes on up it, at the speed he has, its own top exit at its end. The wall past what he has just cleared, up to 3.5 m (BY EYE), his hull above that and free all the way to it: over to it at 10 m/s (BY EYE), still rising, on the plain run from there. Nothing, or no W: off, into the air, at the graph's time
	function ENT:MercerWallUsdFace(pos, n, h, dist)
		local s = pos + Vector(0, 0, h)
		local tr = util.TraceHull({start = s, endpos = s - n * dist, mins = Vector(-6, -6, -6), maxs = Vector(6, 6, 6), filter = self, mask = MASK_SOLID_BRUSHONLY})
		if tr.Hit and not tr.StartSolid and math.abs(tr.HitNormal.z) < 0.3 and tr.HitNormal:Dot(n) > 0.9 then return tr end
	end
	function ENT:MercerWallUsdToRun(pos, v, why)
		self:MercerOverhangSay("край: %s, %.1f м/с", why, v / M2U)
		self.MercerWallUsd = nil
		self.MercerWallPoint = pos * 1
		self.MercerWallSpeed = math.max(10 * M2U, v)
		self.MercerWallInputT, self.MercerWallProg = CurTime(), nil
		GP.Stop(self)
		self.loco:SetVelocity(Vector(0, 0, self.MercerWallSpeed))
		self:UpdateAnimation()
	end
	function ENT:MercerWallUsdOnward(u, n, p, pos, v)
		if not p:KeyDown(IN_FORWARD) then return false end
		local mins, maxs = self:OBBMins(), self:OBBMaxs()
		if self:MercerWallUsdFace(pos, n, 6, 40) and self:MercerWallUsdFace(pos, n, 36, 40) and self:MercerWallUsdFace(pos, n, maxs.z + 8, 40) then
			self:MercerWallUsdToRun(pos, v, "стена прямо перед ним, бежит дальше")
			return true
		end
		if pos.z < (u.edgeZ or 1e9) then return false end
		local reach = 3.5 * M2U + 40
		local wall = self:MercerWallUsdFace(pos, n, 36, reach)
		if not wall or not self:MercerWallUsdFace(pos, n, 100, reach) then return false end
		local hug = wall.HitPos + n * 16
		hug = Vector(hug.x, hug.y, pos.z)
		if (pos - hug):Dot(n) < 8 then return false end
		local tr = util.TraceHull({start = pos, endpos = hug, mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
		if tr.Hit or tr.StartSolid then return false end
		u.phase, u.t0, u.back, u.v = "back", CurTime(), hug, v
		-- (the flight to the wall above in the wall run's own pose, nothing held)
		if self:MercerWallPosesOk() then
			GP.Stop(self)
			self:UpdateAnimation()
		end
		self:MercerOverhangSay("край: к стене над ним, %.2f м", (pos - hug):Dot(n) / M2U)
		return true
	end
	-- (up beside the edge, and something hanging further out over him there, a slanted fascia: pressed to it till his time ran out and off. Out from under it, at obstacleAvoid's 5 m/s)
	function ENT:MercerWallUsdRise(pos, n, dz)
		local t = {start = pos, endpos = pos + Vector(0, 0, dz), mins = self:OBBMins(), maxs = self:OBBMaxs(), filter = self, mask = MASK_SOLID_BRUSHONLY}
		local tr = util.TraceHull(t)
		if tr.StartSolid then return nil end
		if tr.Fraction < 1 then
			t.start, t.endpos = tr.HitPos, tr.HitPos + n * (5 * M2U * FrameTime())
			local o = util.TraceHull(t)
			if not o.StartSolid and not o.Hit then return o.HitPos end
		end
		return tr.HitPos
	end
	function ENT:MercerWallUsdThink(n, p)
		local u = self.MercerWallUsd
		local now, dt = CurTime(), FrameTime()
		self.loco:SetGravity(0)
		self.loco:SetVelocity(Vector(0, 0, 0))
		self:SetAngles(Angle(0, self.MercerWallYaw, 0))
		self:SetNW2Float("MercerWallDir", math.ApproachAngle(self:GetNW2Float("MercerWallDir", 0), 0, 300 * dt))
		if not IsValid(p) or not p:KeyDown(IN_SPEED) then return self:MercerWallUsdOff(Vector(0, 0, 0), true) end
		local age = now - u.t0
		if u.phase == "back" then
			-- over to the wall above: up at the speed he has, growing to the wall run's, and in; a ceiling only stops the rise
			u.v = math.Approach(u.v, self.MercerWallSpeed or 10 * M2U, 30 * M2U * dt)
			local mins, maxs = self:OBBMins(), self:OBBMaxs()
			local pos = self:GetPos()
			local tr = util.TraceHull({start = pos, endpos = pos + Vector(0, 0, u.v * dt), mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
			if tr.StartSolid then return self:MercerWallUsdOff(Vector(0, 0, u.v)) end
			local at = tr.HitPos
			local to = Vector(u.back.x - at.x, u.back.y - at.y, 0)
			local step = 10 * M2U * dt
			local arrive = to:Length() <= step
			if not arrive then to = to:GetNormalized() * step end
			tr = util.TraceHull({start = at, endpos = at + to, mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
			if tr.StartSolid then return self:MercerWallUsdOff(Vector(0, 0, u.v)) end
			self:SetPos(tr.HitPos)
			if arrive or tr.Hit then
				if self:MercerWallUsdFace(tr.HitPos, n, 36, 46) then
					self:MercerWallUsdToRun(tr.HitPos, u.v, "на стене над ним, бежит дальше")
				else
					self:MercerOverhangSay("край: стены не оказалось, сошёл")
					self:MercerWallUsdOff(Vector(0, 0, u.v), true)
				end
			end
			return
		end
		if u.phase == "up" then
			-- the transition's moveAtVelocity, its drift
			local v = Lerp(math.Clamp(age / 0.3333, 0, 1), 14, 6) * M2U
			local md = self.MercerMoveDir
			local drift = md and Vector(md.x, md.y, 0) or Vector(0, 0, 0)
			if drift:Length() > 0.01 then drift = drift:GetNormalized() * (2 * M2U) end
			-- (W on a wall is up it, over the edge it's on: in over what he has cleared, whatever the camera looks at. The first clip's camera ran along the wall and the graph's drift with it, off beside the edge)
			local w = p:KeyDown(IN_FORWARD)
			if w then drift = n * (-2 * M2U) end
			local pos = self:GetPos()
			if self:MercerWallUsdOnward(u, n, p, pos, v) then return end
			if age >= 0.3333 then
				if w and self:MercerWallUsdFace(pos, n, 6, 40) then return self:MercerWallUsdToRun(pos, v, "стена у ног, до её верха") end
				self:MercerOverhangSay("край: стены дальше нет%s, сошёл", w and ", наверх" or " или W отпущен")
				-- (BY EYE: the graph's 2 m/s and the air's 5 m/s of drift at once, in the air the camera has that drift)
				if w then drift = n * (-5 * M2U) end
				return self:MercerWallUsdOff(Vector(drift.x, drift.y, v), true)
			end
			local mins, maxs = self:OBBMins(), self:OBBMaxs()
			local at = self:MercerWallUsdRise(pos, n, v * dt)
			if not at then return end
			local tr = util.TraceHull({start = at, endpos = at + drift * dt, mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY})
			-- (not back under the edge he has just cleared: only where he can go on rising. BY EYE: a drift from the first tick put him under a lower edge)
			if not tr.StartSolid and not tr.Hit and not util.TraceHull({start = tr.HitPos, endpos = tr.HitPos + Vector(0, 0, M2U), mins = mins, maxs = maxs, filter = self, mask = MASK_SOLID_BRUSHONLY}).Hit then at = tr.HitPos end
			self:SetPos(at)
			return
		end
		if u.under then
			-- (the walk's own slack: a tick's short step read a small step up in a real ceiling as the edge, and the full hull past it hit the rest: on gm_construct he fell off 0.3 m short of the edge)
			local nx, still, whyStop = self:MercerUnderStep(u.hug, n, u.out * dt, 0.25 * M2U * 0.6 + 1)
			if not nx and u.left > -0.75 then
				-- (a slanted face at the edge, tools/overhang_map.py on gm_construct: the walk's 0.25 m stepped past it, a tick's step stands under it with nowhere to rise: on out at this height)
				whyStop = still
				local mins, maxs = self:OBBMins(), self:OBBMaxs()
				local tr = util.TraceHull({start = u.hug, endpos = u.hug + n * (u.out * dt), mins = Vector(mins.x + 0.5, mins.y + 0.5, mins.z), maxs = Vector(maxs.x - 0.5, maxs.y - 0.5, maxs.z), filter = self, mask = MASK_SOLID_BRUSHONLY})
				if not tr.Hit and not tr.StartSolid then nx, still = tr.HitPos, true end
			end
			if not nx then self:MercerOverhangSay("под ним: сошёл не дойдя, осталось %.2f м: %s", u.left, tostring(whyStop or still)) end
			if not nx then return self:MercerWallUsdOff(Vector(0, 0, 0)) end
			-- (MercerWallUsdOnward: he isn't over it till his feet are past what he went under)
			if not still then u.edgeZ = nx.z + self:OBBMaxs().z end
			-- (the ceiling going up: his hull after it at the gap's rate, no jump)
			if still and nx.z > u.hug.z then u.gap = u.gap + nx.z - u.hug.z end
			u.hug, u.under, u.left = nx, still, u.left - u.out * dt / M2U
			u.gap = math.max(0, u.gap - (u.phase == "awning" and 5 or 8) * M2U * dt)
			self:SetPos(Vector(nx.x, nx.y, nx.z - u.gap))
		else
			-- past the edge: up beside it
			local at = self:MercerWallUsdRise(self:GetPos(), n, (u.phase == "awning" and 5 or 4.5) * M2U * dt)
			if at then self:SetPos(at) end
		end
		if u.phase == "run" then
			if now > (self.MercerWallFX or 0) then
				self.MercerWallFX = now + 0.24
				self:MercerSound(SND.feet_run, 66)
			end
			if not u.under or u.left <= 1.5 then
				u.phase, u.t0 = "t1", now
				GP.Start(self, self:MercerWallPosesOk() and "mercer/wall_usd_t1b" or "mercer/wall_usd_t1", {block = true, hold = true})
			end
		elseif u.phase == "t1" then
			if not u.under and age >= 0.3333 then
				u.phase, u.t0 = "up", now
				GP.Start(self, self:MercerWallPosesOk() and "mercer/wall_usd_t2b" or "mercer/wall_usd_t2", {block = true, hold = true})
			elseif age > 0.8 then
				return self:MercerWallUsdOff(Vector(0, 0, 0))
			end
		elseif age >= 0.5 then
			-- ({medium}'s own second part plays on in its node)
			if not u.under then
				u.phase, u.t0 = "up", now
			elseif age > 0.9 then
				return self:MercerWallUsdOff(Vector(0, 0, 0))
			end
		end
	end

	function ENT:MercerWallThink(p)
		local n = self.MercerWallNormal
		if self:GetNW2Bool("MercerClimb") then return self:MercerClimbThink(p) end
		if self.MercerWallHop and n then return wallHopThink(self, n) end
		if self.MercerWallLip and n then return wallLipThink(self, n) end
		if self.MercerWallStuckSt then return self:MercerWallStuckThink() end
		if self.MercerWallRoll and n then return wallRollThink(self, n) end
		if self.MercerWallUsd and n then return self:MercerWallUsdThink(n, p) end
		-- (user 2026-11-04: "е на стену на скорости он просто бежал по стене как обычно") alex_mercer_climb_catch: graph_wall 431, the wall run's
		-- opportunity into prototype_air's wall_hit/climb (graph_air 2641): Action down, the hands free, 0.1667 s in, whatever Run does
		if n and self.MercerCatchOn:GetBool() and IsValid(p) and p:KeyDown(IN_USE) and CurTime() - (self.MercerWallStart or 0) >= 0.1667
			and not self:GetNW2Bool("MercerHolding") then
			local v = self.loco:GetVelocity()
			dbg("climb_catch: E on the wall run, %.2f s on it, %.1f m/s", CurTime() - (self.MercerWallStart or 0), v:Length() / M2U)
			return self:MercerClimbCatch(v)
		end
		-- wall_run actions/input (build/graph_wall.txt): Special (unlockable ElbowDrop) = the elbow drop off the wall with
		-- every power - its windup moves him off the wall at 3 m/s for 0.1 s, then the air elbow drop; Attack = the air
		-- attack bank (prototype_air air/actions/attack: the flying kick), turned away from the wall
		if n and self.MercerRMBPressed then
			self:SetAngles(Angle(0, n:Angle().y, 0))
			self:MercerStopWall(n * 3 * M2U)
			self:MercerCombatEvent()
			self.MercerElbow = {t0 = CurTime(), phase = "windup", blade = false, wall = true}
			GP.Start(self, elbowNode(self.MercerElbow, "windup"), {hold = true})
			self:MercerSound(SND.jump_wind, 70, 90)
			return
		end
		if n and self.MercerWallKick then
			self.MercerWallKick = nil
			if not self.MercerFKickUsed then
				self:SetAngles(Angle(0, n:Angle().y, 0))
				self:MercerStopWall(n * 3 * M2U)
				self:MercerFKickStart()
				return
			end
		end
		if IsValid(p) and not p:KeyDown(IN_SPEED) then
			-- Run let go on the wall run: E held = cling (climb), otherwise the backflip off the wall (user: clinging only
			-- on E)
			if p:KeyDown(IN_USE) then return self:MercerStartClimb() end
			-- graph_wall: Run let go while climbing up (within 45 deg) -> the backflip; any other way -> the wall slide
			if math.abs(self:GetNW2Float("MercerWallDir", 0)) > 45 then return self:MercerWallRunSlide(n) end
			return self:MercerWallBackflip()
		end
		-- exit_edge: no movement held for 0.1667 s -> the backflip off the wall
		if IsValid(p) then
			if p:KeyDown(IN_FORWARD) or p:KeyDown(IN_BACK) or p:KeyDown(IN_MOVELEFT) or p:KeyDown(IN_MOVERIGHT) then
				self.MercerWallInputT = CurTime()
			elseif CurTime() - (self.MercerWallInputT or 0) > 0.1667 then
				return self:MercerWallBackflip()
			end
		end
		local pos = self:GetPos()
		local gl = self.MercerWallGlide
		if gl and n then
			local k = math.Clamp((CurTime() - gl.t0) / 0.2, 0, 1)
			local s = k * k * (3 - 2 * k)
			local h = LerpVector(s, gl.p0, gl.p1)
			local a0 = self:GetNW2Float("MercerWallDir", 0)
			local up = math.cos(math.rad(a0)) * (self.MercerWallSpeed or 10 * M2U)
			self:SetPos(Vector(h.x, h.y, pos.z + up * FrameTime()))
			self.loco:SetVelocity(Vector(0, 0, up))
			self:SetAngles(Angle(0, gl.yaw0 + math.AngleDifference(gl.yaw1, gl.yaw0) * s, 0))
			if k >= 1 then self.MercerWallGlide = nil end
			return
		end
		-- (user: jumping onto a brush's corner left him stuck in it) inside the geometry: out to the nearest free spot -
		-- off the wall, diagonally, sideways, up - and the wall-hug point with him (its pull dragged him back in); stuck
		-- again and again (5 times within 0.5 s) or nowhere to go: off the wall (MercerUnstick takes over)
		local mins, maxs = self:OBBMins(), self:OBBMaxs()
		local function solid(at)
			return util.TraceHull({start = at, endpos = at, mins = mins, maxs = maxs, filter = self,
				mask = MASK_SOLID_BRUSHONLY}).StartSolid
		end
		if solid(pos) then
			local side = Vector(0, 0, 1):Cross(-n)
			local dirs = {n, (n + side):GetNormalized(), (n - side):GetNormalized(), side, -side,
				(n + Vector(0, 0, 1)):GetNormalized(), Vector(0, 0, 1)}
			local out
			for r = 4, 48, 4 do
				for _, d in ipairs(dirs) do
					if not solid(pos + d * r) then
						out = pos + d * r
						break
					end
				end
				if out then break end
			end
			if CurTime() - (self.MercerWallStuckLast or 0) > 0.5 then self.MercerWallStuckN = 0 end
			self.MercerWallStuckN = (self.MercerWallStuckN or 0) + 1
			self.MercerWallStuckLast = CurTime()
			if not out or self.MercerWallStuckN >= 5 then
				self.MercerWallStuckN = 0
				if out then self:SetPos(out) end
				return self:MercerStopWall(n * 150)
			end
			self:SetPos(out)
			self.MercerWallPoint = out * 1
			pos = out
		end
		-- (his own hull, a hair narrower: 12 u let a lip of 3-4 u past and wedged him under it)
		local up = util.TraceHull({start = pos + Vector(0, 0, 4), endpos = pos + Vector(0, 0, 24),
			mins = Vector(mins.x + 0.5, mins.y + 0.5, 0), maxs = Vector(maxs.x - 0.5, maxs.y - 0.5, maxs.z), filter = self,
			mask = MASK_SOLID_BRUSHONLY})
		-- (solid(pos) above says his own place is free: started solid 4 u up is his head at it, taking a wall under a low ceiling he's there at once. Going up only: along the wall he runs on as before)
		local blocked = up.Hit and (not up.StartSolid or math.cos(math.rad(self:GetNW2Float("MercerWallDir", 0))) > 0.3)
		-- (user 2026-10-29: "stuck right before the top") going up and not getting higher for 0.25 s = blocked too,
		-- whatever the traces say
		if not blocked and math.cos(math.rad(self:GetNW2Float("MercerWallDir", 0))) > 0.3 then
			local pr = self.MercerWallProg
			if not pr then
				self.MercerWallProg = {t = CurTime(), z = pos.z}
			elseif CurTime() - pr.t > 0.25 then
				blocked = pos.z - pr.z < 6
				self.MercerWallProg = {t = CurTime(), z = pos.z}
			end
		else
			self.MercerWallProg = nil
		end
		-- (the plain wall run first: running along a wall under a ceiling he has a way on, it's only up there's none. The stuck pose flipped him off a wall he ran along)
		if blocked and self.MercerAirStickOn:GetBool() and math.abs(self:GetNW2Float("MercerWallDir", 0)) >= 60 then
			-- (unless he isn't getting anywhere: 6 u in 0.25 s)
			local sp = self.MercerWallSide
			if not sp or pos:DistToSqr(sp.p) > 36 then
				sp = {p = pos, t = CurTime()}
				self.MercerWallSide = sp
			end
			if CurTime() - sp.t < 0.25 then
				blocked = false
				self.MercerWallProg = nil
			end
		end
		-- (alex_mercer_wall_overhang) {medium}: obstacleDistance under 2 m
		if not blocked and CurTime() >= (self.MercerOverhangNext or 0) then
			self.MercerOverhangNext = CurTime() + 0.1
			if self:MercerWallOverhangTry(p, n, pos, false) then return end
		end
		if blocked then
			self.MercerWallProg = nil
			if self:MercerWallOverhangTry(p, n, pos, true) then return end
			-- (user 2026-10-29) a lip on the wall's top (a coping, a cornice) with the roof past it: out round it and up
			-- onto the roof, then the top exit
			-- (user 2026-11-05, with a clip: "первый баг с тем что его не закидывает наверх после этого мини перепрыгивания из второй части": first now: the hop below, its ray 95 u up taking the band's own edge for the wall going on above, had this place: 1.4 m up beside the roof's edge, off the wall at 4 m/s, down again, the wall takes him, round and round for 14 s of the clip)
			local lip = math.cos(math.rad(self:GetNW2Float("MercerWallDir", 0))) > 0.3 and self:MercerWallLipTop(pos, n)
			if lip then
				self:MercerOverhangSay("на стене: карниз и крыша за ним, через край")
				self.MercerWallLip = {t0 = CurTime(), from = pos, out = lip.out, top = lip.top}
				GP.Start(self, self:MercerWallPosesOk() and "mercer/wall_usd_hop" or "mercer/wall_hop", {block = true, hold = true})
				self:MercerSound(SND.jump_wind, 65)
				self:MercerCue("alex_feet")
				return
			end
			-- wall_run obstacle/avoid (graph_wall): a ledge out of the wall within 2.1 m (obstacleFaceHeightSlope 0.5-2.1)
			-- with the wall going on above it = the hop over it
			local d = self:MercerWallLedge(n)
			if d and self:MercerWallHopRise(pos) then return self:MercerWallHopStart(n, d) end
			if self:MercerWallOverhangTry(p, n, pos, true, true) then return end
			return self:MercerWallStuckStart(n) -- (graph_wall stuck: no way on up - a ceiling, a balcony: flip off)
		end
		-- steer on the wall with WASD (W up, A/D sideways, S+A/D diagonal down); no keys = keep going up.
		-- wallRun turningRate: the run direction turns at 80 °/s
		local a = self:GetNW2Float("MercerWallDir", 0)
		local dt = FrameTime()
		if not IsValid(p) then
			-- (user 2026-10-23: the AI ran round the map along an invisible wall - nothing let it off) no player: the run
			-- turns straight up the wall, and if it hasn't topped it in 4 s, off it
			if CurTime() - (self.MercerWallStart or CurTime()) > 4 then return self:MercerWallBackflip() end
			a = math.ApproachAngle(a, 0, WALL_TURN * 2 * dt)
			self:SetNW2Float("MercerWallDir", a)
		end
		if IsValid(p) then
			local fwd = (p:KeyDown(IN_FORWARD) and 1 or 0) - (p:KeyDown(IN_BACK) and 1 or 0)
			local lft = (p:KeyDown(IN_MOVELEFT) and 1 or 0) - (p:KeyDown(IN_MOVERIGHT) and 1 or 0)
			if fwd < 0 and lft == 0 then
				-- (user / the game: no running down a wall) exit_edge: pulled down for 0.2 s -> off the wall
				self.MercerWallDownT = self.MercerWallDownT or CurTime()
				if CurTime() - self.MercerWallDownT > 0.2 then
					self.MercerWallDownT = nil
					return self:MercerWallBackflip()
				end
			else
				self.MercerWallDownT = nil
				if fwd ~= 0 or lft ~= 0 then
					local want = math.deg(math.atan2(lft, math.max(fwd, 0)))
					a = math.Clamp(math.ApproachAngle(a, want, WALL_TURN * WallTurn:GetFloat() * dt), -90, 90)
					self:SetNW2Float("MercerWallDir", a)
				end
			end
		end
		self.MercerWallSpeed = math.Approach(self.MercerWallSpeed or 10 * M2U, 16 * M2U, 3 * M2U * dt)
		-- (MercerWallTopOn) the edge ahead: eased by 40 m/s\xc2\xb2 to what the flight over it asks, 10 m/s, the graph's wallExit velocityMin; going by the rays he had the exit's own, it's found 104 u up
		local topPlan = self.MercerWallTopOn:GetBool() and math.cos(math.rad(a)) > 0.3 and self:MercerWallEdge(n, pos)
		if topPlan then
			local d = math.max(topPlan.z - pos.z - 22, 0)
			self.MercerWallSpeed = math.min(self.MercerWallSpeed, math.sqrt(topPlan.v * topPlan.v + 2 * 40 * M2U * d))
		end
		if CurTime() > (self.MercerWallFX or 0) then
			self.MercerWallFX = CurTime() + 0.12
			self.MercerWallStepN = (self.MercerWallStepN or 0) + 1
			if self.MercerWallStepN % 2 == 0 then self:MercerSound(SND.feet_run, 66) end
		end
		local left = Vector(0, 0, 1):Cross(-n)
		local side = math.sin(math.rad(a))
		-- wallRun surfaceAngleThreshold 90°: follow the surface round corners instead of running into / off them
		-- (user: on a building's corner / edge he got stuck in the wall)
		if math.abs(side) > 0.2 then
			local mdir = left * (side > 0 and 1 or -1)
			local mins, maxs = self:OBBMins(), self:OBBMaxs()
			-- inner corner: the next face is ahead along the run
			local inner = util.TraceHull({start = pos + Vector(0, 0, 8), endpos = pos + Vector(0, 0, 8) + mdir * 20,
				mins = mins, maxs = maxs - Vector(0, 0, 8), filter = self, mask = MASK_SOLID_BRUSHONLY})
			if inner.Hit and not inner.StartSolid then
				-- (graph_wall obstacle/avoid rolled over short obstacles - user: no auto-jumping on the wall, off; a real
				-- corner is followed round)
				if self:MercerWallWrap(inner.HitNormal, inner.HitPos) then return end
			end
			-- outer corner: the wall face ends; look round the edge for the adjacent face
			local ahead = pos + mdir * 24 + Vector(0, 0, 36)
			local still = util.TraceLine({start = ahead, endpos = ahead - n * 40, filter = self, mask = MASK_SOLID_BRUSHONLY})
			if not still.Hit then
				local probe = ahead - n * 36
				local round = util.TraceLine({start = probe, endpos = probe - mdir * 48, filter = self,
					mask = MASK_SOLID_BRUSHONLY})
				if round.Hit and not round.StartSolid and self:MercerWallWrap(round.HitNormal, round.HitPos) then return end
			end
		end
		local dir = Vector(0, 0, 1) * math.cos(math.rad(a)) + left * side
		-- move the wall-hug point sideways with us, pull the hull back onto it if it drifts
		self.MercerWallPoint = self.MercerWallPoint + left * (side * self.MercerWallSpeed * dt)
		local fix = self.MercerWallPoint - pos
		fix.z = 0
		self.loco:SetVelocity(fix * 10 + dir * self.MercerWallSpeed)
		self:SetAngles(Angle(0, self.MercerWallYaw, 0))
		self:MercerWallRunDents(n, dir)
		-- wall ended sideways / below: drop off
		if not self:MercerWallTrace(40, 36).Hit and math.cos(math.rad(a)) < 0.3 then
			return self:MercerStopWall(n * 150)
		end
		if self:IsOnGround() and math.cos(math.rad(a)) < 0 then return self:MercerStopWall() end
		-- Reached the top: keep climbing until the FEET are above the edge (checking at head height left
		-- him wedged under the lip), then pop up and forward onto the roof.
		if math.cos(math.rad(a)) > 0.3 and not self:MercerWallTrace(40, 6).Hit then return wallTopExit(self, n) end
		-- (MercerWallTopOn) off it with the feet he has drawn (his origin + 19 to 48 u on the wall) at the edge. The engine's hull in the air stands 24 u over his origin: he goes in over it from here
		if topPlan and pos.z >= topPlan.z - 22 then return wallTopExit(self, n) end
	end

	-- (MercerWallTopOn) {z = the edge, v = the launch up, vin = in over it, need = how far in from where he leaves}. The rays of the exit's own: a miss at height h is the edge at h - 6. What's past the edge, 2.5 m in: a step up (the tower's brick column has a ledge 64 u deep, then the roof 32 u up) asks more of the launch, and he's to come down on it: the arc reaches it.
	-- 10 m/s, from 22 u under the edge at 25.4 m/s\xc2\xb2 (wallExit's gravity 25): 1.4 m over it, 0.7 s in the air; 15 deg over the edge by the graph: 2.7 m/s in, he lands about 1.5 m past it
	function ENT:MercerWallEdge(n, pos, must)
		local e = self.MercerWallTopEdge
		if e and (CurTime() - e.t > 0.2 or math.abs(e.z - pos.z) > 130) then e = nil end
		if not e then
			local hi
			if not self:MercerWallTrace(40, 104).Hit then
				hi = 104
				if self:MercerWallTrace(40, 6).Hit then
					local lo = 6
					for _ = 1, 6 do
						local mid = (lo + hi) * 0.5
						if self:MercerWallTrace(40, mid).Hit then lo = mid else hi = mid end
					end
				else
					hi = 6
				end
			elseif must then
				hi = 6 -- (off a hop or a lip, wherever he stands)
			end
			if not hi then return end
			local z = pos.z + hi - 6
			local inward = Vector(-n.x, -n.y, 0):GetNormalized()
			local top, front = z, nil
			for d = 8, 100, 23 do
				local c = pos + inward * (16 + d)
				local tr = util.TraceLine({start = Vector(c.x, c.y, z + 120), endpos = Vector(c.x, c.y, z - 8), filter = self, mask = MASK_SOLID_BRUSHONLY})
				if tr.StartSolid then break end
				if tr.Hit and tr.HitNormal.z > 0.5 and tr.HitPos.z > top + 4 then
					top, front = tr.HitPos.z, d
				end
			end
			local v = 10 * M2U
			if top > z then v = math.max(v, math.sqrt(2 * 1000 * (top - z + 30))) end
			local apex = v * v / 2000 - 22
			local rise = v / 1000 + math.sqrt(2 * math.max(apex - (top - z), 1) / 1000)
			local need = 16 + (front or 0) + 21
			local vin = math.Clamp(need / rise, math.tan(math.rad(15)) * v, 6 * M2U)
			e = {t = CurTime(), z = z, v = v, vin = vin, need = need}
			self.MercerWallTopEdge = e
		end
		return e
	end
	function ENT:MercerWallTopEnd()
		local w = self.MercerWallTopSt
		if not w then return end
		self.MercerWallTopSt = nil
		if w.step then self.loco:SetStepHeight(w.step) end
	end
	-- from over the edge till he's as far in as the plan has him: the in-going on top of whatever else moves him
	function ENT:MercerWallTopThink()
		local w = self.MercerWallTopSt
		if not w then return end
		if self:IsOnGround() or self:GetNW2Bool("MercerWall") or CurTime() - w.t0 > 1.5 then return self:MercerWallTopEnd() end
		local pos, v = self:GetPos(), self.loco:GetVelocity()
		-- (coming down: 8 u, past what he falls in a tick till he's going fast, then the whole step: with 1 u the hull's feet reached the floor a tick before the ground test did, him 1 u in it)
		if v.z <= 0 and w.step then self.loco:SetStepHeight(v.z < -350 and w.step or 8) end
		if pos.z >= w.z + 2 and (pos - w.from):Dot(w.dir) < w.need then
			local along = v.x * w.dir.x + v.y * w.dir.y
			if along < w.vin then self.loco:SetVelocity(v + w.dir * (w.vin - along)) end
		end
	end

	-- (the top exit, also after getting up round a lip - wallLipThink)
	function wallTopExit(self, n)
		do
			-- wallExit over the top: the wall-run speed (10..25 m/s), 15° over the edge
			local v = math.Clamp(self.MercerWallSpeed or 10 * M2U, 10 * M2U, 25 * M2U)
			local soft = self.MercerWallTopOn:GetBool()
			if soft then
				local plan = self:MercerWallEdge(n, self:GetPos(), true)
				local inward = Vector(-n.x, -n.y, 0):GetNormalized()
				self:SetNW2Float("MercerWallTopT", self:GetNW2Bool("MercerHolding") and -10 or CurTime())
				self:MercerStopWall(Vector(0, 0, plan.v))
				-- (straight up till he's over the edge, the wall's step height of 1 u as he rises: the engine's ground test takes any surface within a step of his feet, the ledge he's rising past among them, and in the fall it would snap him down the last 24 u in a tick)
				local step = self.loco:GetStepHeight()
				self.loco:SetStepHeight(1)
				self.MercerWallTopSt = {t0 = CurTime(), dir = inward, vin = plan.vin, from = self:GetPos(), need = plan.need, z = plan.z, step = step}
				self:MercerWallTopThink()
			else
				self:MercerStopWall((Vector(0, 0, math.cos(math.rad(15))) - n * math.sin(math.rad(15))) * v)
			end
			self:MercerEffect("alex_mercer_slam", self:GetPos() - n * 20, 0.4)
			self:MercerSound(SND.jump_wind, 70)
			-- wall_run → exit → exit_edge → exit → parkour_exit: over the edge onto the roof with a pose of the parkour exit
			-- bank (sideflip / med_sideflip when no_parkour_flip_test finds room, step / tact otherwise)
			-- (user: the flips as before as well) one pool: the parkour exits (flips only with room, the sided ones by the
			-- input) + graph_wall's own top poses (the pull over the top, the flip over it); never the same one twice
			local onto = Vector(-n.x, -n.y, 0):GetNormalized()
			-- (user 2026-10-27: with a body in his arms he flipped over the top - jerky) holding: no flip / pull-over
			-- poses, the grab's own running jump (as the jump with a body)
			if self:GetNW2Bool("MercerHolding") then
				self:SetAngles(Angle(0, onto:Angle().y, 0))
				GP.Start(self, "mercer/grab/jump_run", {onDone = toAir})
				self:MercerTrail("jump")
				self:MercerSound(SND.jump, 68)
				return
			end
			if not self.MercerTopExits then
				local list = {}
				for _, e in ipairs(EXITS) do list[#list + 1] = e end
				list[#list + 1] = {w = 10, path = "mercer/wall_top_flip", trail = "frontflip"}
				list[#list + 1] = {w = 5, path = "mercer/wall_top", trail = "jump"}
				self.MercerTopExits = list
			end
			-- (MercerWallTopOn: he's still under the edge here: no_parkour_flip_test from over it)
			local room = flipRoom(self, onto, soft and self.MercerWallTopSt and self.MercerWallTopSt.z + 6)
			local pick = pickPose(self, self.MercerTopExits, function(e)
				return (not e.flip or room) and (not e.side or inputSide(self, e.side, e.arc))
			end)
			self.MercerLastVault = pick.path
			self:SetAngles(Angle(0, onto:Angle().y, 0))
			GP.Start(self, soft and ALEX_MERCER_GRAPH[pick.path .. "_top"] and pick.path .. "_top" or pick.path, {onDone = toAir})
			self:MercerTrail(pick.trail or (pick.flip and "backflip" or "frontflip"))
			self:MercerSound(SND.jump, 68) -- alex_fol_jump_b
		end
	end

	-- sequences that only make sense in the air (left over on the ground = clear them)
	local AIR_POSES = {alex_bullet_smash_glide_forward = true, alex_bullet_smash_glide_left = true,
		alex_bullet_smash_glide_right = true, alex_bullet_smash_glide_backward = true, alex_loco_amb_air = true,
		alex_loco_jump_long_all1_start = true, alex_loco_jump_long_all1_mid = true, alex_loco_jump_long_D = true,
		alex_loco_jump_long_D_fwd = true, alex_loco_jump_long_D_2 = true, alex_loco_jump_long_right = true,
		alex_loco_jump_long_left = true, alex_loco_jump_long_back = true, alex_loco_jump_tact_stand = true}

	-- (user 2026-10-28: "Alex should open doors") moving into a closed, unlocked door (him or the AI) opens it: a
	-- prop_door_rotating away from him, func_door / func_door_rotating with their Open input; locked ones stay shut
	local DOORS = {prop_door_rotating = true, func_door = true, func_door_rotating = true}
	-- (players / user 2026-10-28: "he can't break the map's glass") a strike in progress or the sprint shatters the
	-- breakables just ahead of him: windows (func_breakable_surf) shatter round the point, func_breakable breaks
	function ENT:MercerBreakGlass(c, r)
		for _, e in ipairs(ents.FindInSphere(c, r)) do
			local cls = e:GetClass()
			if cls == "func_breakable_surf" and not e.MercerShattered then
				e.MercerShattered = true
				e:Fire("Shatter", "0.5 0.5 512", 0, self, self)
			elseif cls == "func_breakable" and (e:Health() or 0) > 0 then
				e:Fire("Break", "", 0, self, self)
			end
		end
	end
	function ENT:MercerDoorThink()
		if CurTime() < (self.MercerDoorT or 0) then return end
		self.MercerDoorT = CurTime() + 0.15
		local fs = self.MercerFight
		if (fs and (fs.phase == "release" or fs.phase == "connect")) or (self.MercerSprintOn and self:IsOnGround()) then
			self:MercerBreakGlass(self:GetPos() + Vector(0, 0, 50) + self:GetForward() * 45, 75)
		end
		local dir = self.MercerMoveDir
		if not dir or dir:IsZero() then
			local v = self:GetVelocity()
			v.z = 0
			if v:LengthSqr() < 900 then return end
			dir = v
		end
		dir = Vector(dir.x, dir.y, 0):GetNormalized()
		local sprint = self.MercerSprintOn and self:IsOnGround()
		local speed = self:GetVelocity():Length2D()
		local start = self:GetPos() + Vector(0, 0, 40)
		-- (on the sprint: looked for farther ahead, a tick's run plus a margin)
		local tr = util.TraceHull({start = start, endpos = start + dir * (sprint and 48 + speed * 0.2 or 48),
			mins = Vector(-10, -10, -30), maxs = Vector(10, 10, 30), filter = {self, self:GetPossessor()}, mask = MASK_SOLID})
		local e = tr.Entity
		if not IsValid(e) or not DOORS[e:GetClass()] then return end
		if CurTime() < (e.MercerDoorT or 0) then return end
		-- (user 2026-10-28: "on the sprint he knocks doors out - hands forward like shoving a person, the door flies off,
		-- he isn't slowed") a hinged door, locked or not, becomes a physics prop of its own model thrown ahead faster
		-- than him (no collision with him for 0.6 s, no damage to him: MercerKnockBy), the centre nudge, wood crack
		-- + thump; brush doors (func_door*) can't fly: unlocked and opened
		if sprint then
			e.MercerDoorT = CurTime() + 1
			self:MercerNudge(1)
			self:MercerCue("impact_thump")
			if e:GetClass() == "prop_door_rotating" then
				local mdl, pos, ang, skin = e:GetModel(), e:GetPos(), e:GetAngles(), e:GetSkin()
				local d = ents.Create("prop_physics")
				if IsValid(d) and mdl and util.IsValidModel(mdl) then
					d:SetModel(mdl)
					d:SetPos(pos)
					d:SetAngles(ang)
					d:SetSkin(skin or 0)
					d:Spawn()
					d:SetCollisionGroup(COLLISION_GROUP_DEBRIS)
					d.MercerKnockT, d.MercerKnockBy = CurTime(), self
					local ph = d:GetPhysicsObject()
					if IsValid(ph) then
						ph:Wake()
						ph:SetVelocity(dir * math.max(speed * 1.5, 700) + Vector(0, 0, 150))
						ph:AddAngleVelocity(VectorRand() * 200)
					end
					timer.Simple(0.6, function() if IsValid(d) then d:SetCollisionGroup(COLLISION_GROUP_NONE) end end)
					e:EmitSound("physics/wood/wood_furniture_break" .. math.random(2) .. ".wav", 85, math.random(90, 105))
					e:Remove()
					return
				end
				if IsValid(d) then d:Remove() end
			end
			e:Fire("Unlock", "", 0, self, self)
			e:Fire("Open", "", 0, self, self)
			return
		end
		if e:GetInternalVariable("m_bLocked") then return end
		e.MercerDoorT = CurTime() + 1
		if e:GetClass() == "prop_door_rotating" then
			local st = e:GetInternalVariable("m_eDoorState")
			if st == 1 or st == 2 then return end -- (opening / open)
			e:Fire("OpenAwayFrom", "!activator", 0, self, self)
		else
			e:Fire("Open", "", 0, self, self)
		end
	end

	-- (MP fix 6) alex_mercer_mp_anim 0 = back to the engine's 10 Hz body updates in multiplayer (to compare)
	MercerMPAnim = MercerMPAnim or CreateConVar("alex_mercer_mp_anim", "1", {FCVAR_ARCHIVE},
		"Alex Mercer, multiplayer: update his animation every tick (1) or only when the engine does (0)")
	-- (user 2026-10-29: "the gun drags him; only the gun looks up") the gun blends' pose parameters (aim_pitch /
	-- move_yaw) - set in BOTH realms from here, in Think: the gun follows the R_Wrist_Grapple bone, and its place is
	-- worked out from his bones before he is drawn, with whatever values the bones had then. Set in Draw they came
	-- too late (the gun on one set of values, the body on another); unset on the server, the networked ones sat at
	-- the minimum (-180 = the back strafe, -67 = the gun down). The pitch eased 15 /s, the move yaw 12 /s
	function ENT:MercerGunPose(dt)
		local want = math.Clamp(-self:GetNW2Float("MercerGunPitch", 0), -67, 78) -- (Source pitch: down > 0; the blend: up > 0)
		local pcur = self.MercerGunPitchP or want
		pcur = pcur + (want - pcur) * math.min(1, dt * 15)
		self.MercerGunPitchP = pcur
		self:SetPoseParameter("aim_pitch", pcur)
		local md = SERVER and self:IsPossessed() and self.MercerMoveDir
		local dir = md and not md:IsZero() and md or self:GetVelocity()
		dir = Vector(dir.x, dir.y, 0)
		local a = dir:Length() > 1.5 * M2U and math.AngleDifference(dir:Angle().y, self:GetAngles().y) or 0
		local cur = self.MercerGunYawP or a
		cur = cur + math.AngleDifference(a, cur) * math.min(1, dt * 12)
		self.MercerGunYawP = cur
		self:SetPoseParameter("move_yaw", cur)
	end
	-- (a save value marks nothing changed, and single player's local network transfer copies only what is marked; a change of a layer marks the whole entity: one
	-- with no weight, gone at once). Returns what it knows, for mercer_trace
	function ENT:MercerEveryTickSet(on)
		local ok = self:SetSaveValue("m_bAnimatedEveryTick", on)
		local id = self:AddLayeredSequence(self:GetSequence(), 1)
		if id and id >= 0 then
			self:SetLayerWeight(id, 0)
			self:RemoveLayer(id)
		end
		return tostring(ok) .. ", reads " .. tostring((self:GetInternalVariable("m_bAnimatedEveryTick")))
	end
	-- (user 2026-11-04: "При прыжках и некоторых действиях как будто рванно двигается... там как будто фпс проседает"; his mercer_trace, 20 s) a frame that takes two server ticks (a long frame: the Lua collector's runs, most of them): the engine's
	-- NextBot update runs once a frame ("don't run multiple ticks in a frame", as remembered from the SDK; the trace: 29 such frames, 30 ticks with no update, each followed by a step of two). On the second tick his place and his node's pose stand, on the next he
	-- makes up: at his speed 15 u off his path, and what follows him sees it, the camera too. The engine's order in a tick: the Tick hook, the NextBot update, the thinks; what the client gets is the place at the tick's end. So here, in such a tick's think, his
	-- pose as the update would have it, his place on by the speed he has; taken back in the next tick's Tick hook, before the update makes its double step from where it left him: nothing the update sees changes. tools/trace_fill.py: his own 20 s through a model of the
	-- client that fits what his client drew (0.22 u): near a lost tick off a smooth path 10.4 u (95 %) -> 2.4. Not seen in game. alex_mercer_fill_ticks, 0 = as before
	do
		local FILLED = {}
		hook.Add("Tick", "AlexMercerFillTicks", function()
			for ent, f in pairs(FILLED) do
				FILLED[ent] = nil
				-- (moved by something else since, it's that one's place now)
				if IsValid(ent) and ent:GetPos():DistToSqr(f[2]) < 0.01 then ent:SetPos(ent:GetPos() - f[1]) end
			end
		end)
		function ENT:MercerFillTick()
			-- (no update since this long; the update of this tick came before this think. Not for an update that has stopped for some other reason)
			local since, ft = CurTime() - (self.MercerNBTime or -1000), FrameTime()
			if since < ft * 0.5 or since > ft * 4.5 then return end
			self.MercerBUOwn = true
			self:BodyUpdate()
			self.MercerBUOwn = nil
			local step = self.loco:GetVelocity() * since
			if step:LengthSqr() < 0.01 then return end
			local pos = self:GetPos() + step
			self:SetPos(pos)
			FILLED[self] = {step, pos}
			self.MercerFillSent = pos -- (for mercer_trace: the place the client gets)
		end
	end
	function ENT:CustomThink()
