			end
		elseif sprinting and (input or aiRun) and self:IsOnGround() and not self:GetNW2Bool("MercerWall")
			and not self.MercerChargeStart and not self:IsPlayingAnimation()
			and not (self.MercerNode and self.MercerNode.opts.moveAfter and CurTime() - self.MercerNode.t0 < self.MercerNode.opts.moveAfter)
			and (not self.MercerNode or self.MercerNode.opts.root or GP.CanExit(self)
				-- (exit_active's input bank: Run + movement down, one of them just pressed)
				or (GP.CanPress(self) and (shiftPressed or not self.MercerHadInput))) then
			self:MercerSprintBegin()
		end
		-- run stop (Mercer's own graph): movement released above 2 m/s; over 8 m/s the sprint stop from frame 6
		if IsValid(p) and not input and self.MercerHadInput and self:IsOnGround() and not self.MercerSprintOn
			and not self.MercerNode and not self.MercerChargeStart and not self:IsPlayingAnimation()
			and not self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerHolding") and not self.MercerGun
			and not self:GetNW2Bool("MercerObjHold") then
			local v = self:GetVelocity():Length2D() / M2U
			if v > 2 then
				local fast = v > 8
				GP.Start(self, fast and NODE_RUN_STOP_FAST or NODE_RUN_STOP, {block = true, exitAfter = 0,
					root = fast and 0.1 or 0.35, onDone = function(ent) ent:UpdateAnimation() end})
				-- (user 2026-11-04: the same) the stop's {default} node, under 8 m/s: alex_sprint and alex_feet_scuff at 0.8182 (graph_prototype); the other node has none
				if not fast then
					self:MercerCue("alex_sprint", 0.8182)
					self:MercerCue("alex_feet_scuff", 0.8182)
				end
			end
		end
		self.MercerHadInput = input
		if input then self.MercerChain = nil end
		-- (user 2026-11-03: "резче") DrGBase picks the anim and the speed from it only every 0.1 s, and the run only once he
		-- moves: movement pressed, or held as a strike / a landing ends, he stood in the stance up to 0.2 s at a desired speed
		-- of 1 u/s. At once now
		if IsValid(p) and self.MercerSharp:GetBool() then
			local free = input and self:IsOnGround() and not self.MercerNode and not self.MercerFight and not self.MercerSprintOn
				and not self.MercerChargeStart and not self:IsPlayingAnimation() and not self:GetNW2Bool("MercerWall")
			if free and not self.MercerFreeWas then
				self.MercerStartT = CurTime()
				self:UpdateAnimation()
			end
			self.MercerFreeWas = free
			local seq = self:GetSequence()
			if seq ~= self.MercerSpeedSeq then
				self.MercerSpeedSeq = seq
				self:UpdateSpeed()
			end
		end
		-- prototype_sprint sprint_idle (list item 6): Run held standing, nothing in hand -> alex_loco_sprint_idle 0-10, then
		-- 10-40 cycling while Run is down; Run let go -> 40-50; movement leaves it at once (into the sprint / the run)
		do
			local nd = self.MercerNode and self.MercerNode.path
			local sIdle = nd == "mercer/sprint_idle" or nd == "mercer/sprint_idle_cycle"
			local runDown = IsValid(p) and p:KeyDown(IN_SPEED)
			if (sIdle or nd == "mercer/sprint_idle_exit") and (input or not self:IsOnGround()) then
				GP.Stop(self)
				self:UpdateAnimation()
			elseif sIdle and not runDown then
				GP.Start(self, "mercer/sprint_idle_exit", {exitAfter = 0, onDone = function(ent) ent:UpdateAnimation() end})
			elseif not nd and runDown and not input and self:IsOnGround() and not self.MercerSprintOn and not self.MercerSkid
				and not self.MercerGrab and not self:GetNW2Bool("MercerHolding") and not self.MercerGun and not self.MercerChargeStart
				and not self:IsPlayingAnimation() and not self:GetNW2Bool("MercerWall") and not self.MercerFight
				and self:GetVelocity():Length2D() < 2 * M2U then
				GP.Start(self, "mercer/sprint_idle", {exitAfter = 0, next = "mercer/sprint_idle_cycle",
					nextOpts = {exitAfter = 0}})
			end
		end
		if self.MercerRunTurn then self:MercerRunTurnThink(dt) end
		if self.MercerNode and self.MercerNode.opts.root then self:MercerRootMotion(dt) end
		-- (alex_mercer_land_huge: the huge node, no Shift) its pose has no root of its own and the game's motion goes Idling with it; W held from a long flight he went on at the plain 15 m/s^2, 5.5 m over its second with the feet planted.
		-- 60 m/s^2 is by eye: 12 m/s over 0.2 s, about the anim's 0.2333 s blend
		if self.MercerNode and self.MercerNode.opts.brake and self:IsOnGround() then
			local v = self.loco:GetVelocity()
			local sp = v:Length2D()
			if sp > 0 then
				local k = math.max(0, sp - self.MercerNode.opts.brake * M2U * dt) / sp
				self.loco:SetVelocity(Vector(v.x * k, v.y * k, v.z))
			end
		end
		-- the run jump's back_flip opportunity: the stick pulled back (within 60 deg) inside its window
		local bf = self.MercerBackFlipWin
		if bf then
			local t = CurTime() - bf.t0
			local nd = self.MercerNode and self.MercerNode.path
			if t > 0.5 or (t >= bf.w0 and nd ~= bf.path) then
				self.MercerBackFlipWin = nil
			elseif t >= bf.w0 and IsValid(p) and p:KeyDown(IN_BACK) and not p:KeyDown(IN_FORWARD)
				and not p:KeyDown(IN_MOVELEFT) and not p:KeyDown(IN_MOVERIGHT) then
				self.MercerBackFlipWin = nil
				GP.Start(self, JP.backFlip, {onDone = toAir})
				self:MercerTrail("backflip")
			end
		end
		-- the running touch keeps his landing speed (the walkframes speed of the pinned anim is 0)
		if input and self.MercerNode and self.MercerNode.path == JP.touchRun and self.MercerNode.opts.keepSpeed then
			self.loco:SetDesiredSpeed(self.MercerNode.opts.keepSpeed)
		end
		-- land_touch_fwd with the stick let go -> land_stop (the node's onEvent)
		if not input and self.MercerNode and (self.MercerNode.path == JP.touchFwd or self.MercerNode.path == JP.touchRun) then
			GP.Start(self, NODE_LAND_STOP, {block = true, exitAfter = 0, onDone = function(ent) ent:UpdateAnimation() end})
		end
		-- 0..1 sprint intensity for effects and the camera (0.3 at 10 m/s .. 1 at 20 m/s)
		local sprint = self.MercerSprintOn and 0.3 + 0.7 * math.Clamp(((self.MercerSprintSpeed or SPR.vMin) - SPR.vMin)
			/ (SPR.vMax - SPR.vMin), 0, 1) or 0
		self:SetNW2Float("MercerSprint", sprint)
		if self:GetNW2Bool("MercerCharging") and not self:GetNW2Bool("MercerChargeAnimDone")
			and self:GetSequence() == self:LookupSequence("alex_loco_pedal_straight") and self:GetCycle() > 0.9 then
			self:SetNW2Bool("MercerChargeAnimDone", true)
		end
		-- airborne time (filters ground flicker)
		if self:IsOnGround() then
			self.MercerAirStart = nil
		else
			self.MercerAirStart = self.MercerAirStart or CurTime()
		end
		self:MercerAirChargeThink()
		if self.MercerLandJump then
			self.MercerLandJump = nil
			if self.MercerChargeStart then self:MercerJumpRelease() end
		end
		if self.MercerWallCharge and not self.MercerChargeFullDone and CurTime() - self.MercerWallCharge >= 1 and self.MercerJumpGraph:GetBool() then self:MercerChargeFull() end
		if self.MercerChargeStart then
			if not self:IsOnGround() and CurTime() - self.MercerAirStart > 0.1 then
				if self.MercerJumpGraph:GetBool() and self:MercerAirChargeFree() then
					-- (off a ledge with Space held: the meter goes on in the air)
					local held = CurTime() - self.MercerChargeStart
					self.MercerAirCharge = {sec = held, m = self:MercerChargeMeter(held), down = true, t = CurTime()}
					self.MercerChargeStart, self.MercerChargeAirM = nil, nil
					local nd = self.MercerNode and self.MercerNode.path
					if nd == NODE_CHARGE or nd == NODE_CHARGE_HOLD then GP.Stop(self) end
				else
				-- really left the ground while charging (pushed off a ledge...): the charge is lost
				dbg("charge cancelled: airborne for %.2f s", CurTime() - self.MercerAirStart)
				GP.Stop(self)
				self.MercerChargeStart = nil
				self:SetNW2Bool("MercerCharging", false)
				end
			elseif self.MercerJumpGraph:GetBool() and not self.MercerChargeFullDone and self:MercerChargeMeter(CurTime() - self.MercerChargeStart) >= 1 then
				self:MercerChargeFull()
			elseif self:GetVelocity():Length2D() < 100 and self:IsOnGround() and (not self.MercerNode or self:MercerChargeLandOver()) then
				-- standing charge without its node (stopped running while charging, or lost): play the crouch
				-- on the charge's own timeline, so it continues where the hold time says instead of the idle pose
				local held = CurTime() - self.MercerChargeStart
				dbg("charge node missing -> resume crouch at %.2f s", held)
				if held < 1.5 then
					GP.Start(self, NODE_CHARGE, {block = true, next = NODE_CHARGE_HOLD, nextOpts = {loop = true, block = true}})
					self.MercerNode.t0 = self.MercerChargeStart
				else
					GP.Start(self, NODE_CHARGE_HOLD, {loop = true, block = true})
					self.MercerNode.t0 = CurTime() - ((held - 1.5) % 4)
				end
			end
			if DebugAnim:GetBool() then
				dbg("charging seq=%s cyc=%.3f rate=%.2f node=%s ground=%s", self:GetSequenceName(self:GetSequence()),
					self:GetCycle(), self:GetPlaybackRate(), self.MercerNode and self.MercerNode.path or "-", tostring(self:IsOnGround()))
			end
		end
		-- (user 2026-11-04: "на мерсере не оставалась херня от взрывов, рядом что то взорвется, и он черный бывает") anything burning that lights him: the engine's flame takes 8 off his render colour every think, down to 50 of 255, and
		-- nothing ever brings it back (CEntityFlame, CBaseAnimating::Scorch). The decals: client, alex_mercer_vfx.lua
		if self:IsOnFire() then
			self:Extinguish()
			local c = self:GetColor()
			self:SetColor(Color(255, 255, 255, c.a))
		end
		-- footsteps (the anims carry no events), glide wind loop
		local speed2d = self:GetVelocity():Length2D()
		local stepSeq = self:GetSequenceName(self:GetSequence())
		if not self.MercerNode and (stepSeq == "mercer_sprint" or stepSeq == "mercer_run" or stepSeq == "mercer_run_claw") then
			-- (user 2026-11-04: the same) the graph's footstep items: the cycle's 0.451 and 0.922, the run's and the sprint's (graph_prototype 3918, graph_sprint 1437). His feet come down there, by the anims: n2 0.438, 0.938, n1 0.446, 0.893,
			-- the run 0.417, 0.944. On the feet, not on a clock
			local cyc, pc = self:GetCycle(), self.MercerFootCyc
			self.MercerFootCyc = cyc
			if pc and self:IsOnGround() and speed2d > 40 then
				for i = 1, 2 do
					local ph = i == 1 and 0.451 or 0.922
					if (pc < ph and cyc >= ph) or (cyc < pc and (ph > pc or ph <= cyc)) then
						self.MercerNextStep = CurTime() + 0.15
						self:MercerFootstep()
					end
				end
			end
		else
			self.MercerFootCyc = nil
			if self:IsOnGround() and speed2d > 40 and CurTime() > (self.MercerNextStep or 0) then
				self.MercerNextStep = CurTime() + math.Clamp(28 / speed2d + 0.18, 0.18, 0.75)
				self:MercerFootstep()
			end
		end
		-- jumpwind_sustain: air fall (from 0.1 s, 0.63) / down / wall run (from 0.5 s): the wind loop, by speed
		local vel3 = self:GetVelocity()
		local windK = 0
		if self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerClimb") then
			windK = 0.6
		elseif not self:IsOnGround() then
			windK = math.Clamp((math.abs(vel3.z) / M2U - 6) / 30, 0, 1)
		end
		if windK > 0.02 then
			if not self.MercerWind then
				self.MercerWind = CreateSound(self, FX .. "wind_gust_01.wav")
				self.MercerWind:PlayEx(0, 100)
			end
			self.MercerWind:ChangeVolume(0.25 + 0.75 * windK, 0.15)
			self.MercerWind:ChangePitch(90 + 25 * windK, 0.15)
		elseif self.MercerWind then
			self.MercerWind:FadeOut(0.3)
			self.MercerWind = nil
		end
		local gliding = self:GetNW2Bool("MercerGlide")
		if gliding and not self.MercerGlideLoop then
			self.MercerGlideLoop = self:StartLoopingSound(FX .. "alex_glide_loop.wav")
		elseif not gliding and self.MercerGlideLoop then
			self:StopLoopingSound(self.MercerGlideLoop)
			self.MercerGlideLoop = nil
		end
		-- skydive pose ONLY while gliding (user: on fast falls it looked like a slide before landing)
		local wantDive = not self:IsOnGround() and not self:GetNW2Bool("MercerWall") and self:GetNW2Bool("MercerGlide")
		local dive = self:GetNW2Float("MercerDive", 0)
		dive = wantDive and math.min(1, dive + FrameTime() * 3) or (self:IsOnGround() and 0 or math.max(0, dive - FrameTime() * 4))
		self:SetNW2Float("MercerDive", dive)
		if self.MercerNode and (self:GetNW2Bool("MercerGlide") or self:GetNW2Bool("MercerWall"))
			and string.sub(self.MercerNode.path, 1, 18) ~= "mercer/wall_enter/" and string.sub(self.MercerNode.path, 1, 15) ~= "mercer/wall_usd"
			and string.sub(self.MercerNode.path, 1, 13) ~= "mercer/climb_" then GP.Stop(self) end -- (climb nodes play on the wall: ledge up, edges, charge)
		if self:IsOnGround() then self.MercerGroundT = CurTime() end
		-- airborne poses from the game's air graph (default / down); jump nodes keep priority
		if not self:IsOnGround() and not self:GetNW2Bool("MercerGlide") and not self:GetNW2Bool("MercerWall") then
			self:MercerOffEdgeNode()
			self:MercerOffLedge()
			self:MercerAirPose()
		end
		if self:GetNW2Bool("MercerWall") then return self:MercerWallThink(p) end
		-- in the air: flying into a wall while pushing toward it grabs it (not right after leaving a wall)
		if self.MercerWallRegrabAtApex and (self:IsOnGround() or self:GetVelocity().z < 0) then
			self.MercerWallRegrabAtApex = nil
		end
		-- (alex_mercer_wall_jump_graph) the wall again from 15 m/s up, not at the top
		local wallUp15 = self.MercerWallUp15 and self:GetVelocity().z <= 15 * M2U
		if wallUp15 or self:IsOnGround() then self.MercerWallUp15 = nil end
		-- after a wall jump up: at the apex (or standing on a facade ledge) with the wall still in front he takes it
		-- again at once - Shift = the wall run goes on, otherwise he clings (user: he stopped on the ledges)
		if self.MercerWallUpN then
			local up = CurTime() - self.MercerWallUpT
			if up > 3 or self:GetNW2Bool("MercerWall") then
				self.MercerWallUpN = nil
			elseif (up > 0.2 or wallUp15) and (self:GetVelocity().z <= 0 or wallUp15 or self:IsOnGround()) then
				local n = self.MercerWallUpN
				self.MercerWallUpN = nil
				local start = self:GetPos() + Vector(0, 0, 40)
				local tr = util.TraceHull({start = start, endpos = start - n * (CLIMB_DIST + 30), mins = Vector(-6, -6, -6),
					maxs = Vector(6, 6, 6), filter = self, mask = MASK_SOLID_BRUSHONLY})
				if tr.Hit and not tr.StartSolid and math.abs(tr.HitNormal.z) < 0.3 then
					self.MercerWallRegrabAtApex = nil
					self.MercerWallCooldown = 0
					self:MercerStartWall(tr, nil, true)
					if not (IsValid(p) and p:KeyDown(IN_SPEED)) then self:MercerStartClimb() end
					return
				end
			end
		end
		-- (user: grabbing only on E - he stuck to things by himself)
		if not self:IsOnGround() and CurTime() > (self.MercerWallCooldown or 0) and not self.MercerWallRegrabAtApex
			and IsValid(p) and p:KeyDown(IN_USE) and not self.MercerAirDash and not self.MercerGrab then
			local md = self.MercerMoveDir
			local dir = (md and not md:IsZero()) and md or self:GetForward()
			local tr = self:MercerWallTrace(36)
			if tr.Hit and math.abs(tr.HitNormal.z) < 0.3 and tr.HitNormal:Dot(dir) < -0.5 then
				local v = self.loco:GetVelocity()
				self:MercerStartWall(tr)
				if self.MercerCatchOn:GetBool() then
					self:MercerClimbCatch(v)
				else
					self:MercerStartClimb() -- E = climb (the wall run is on Space)
				end
				return
			end
		end
		-- running into an obstacle vaults it (prototype_sprint parkour)
		if self:IsOnGround() and input and not self.MercerChargeStart and not self:IsPlayingAnimation()
			and not (self.MercerNode and self.MercerNode.opts.block) then
			self:MercerVaultCheck()
		end
		if self:IsOnGround() and input then self:MercerShoveThink() end
		-- prototype_sprint wall_test (user: wall run on Shift, as in the game): Run + movement held and a wall within
		-- 0.3 m, within 45° of the facing, taller than a vault (the vault test above takes anything up to 2.1 m first)
		if sprinting and not self.MercerChargeStart and not self:IsPlayingAnimation()
			and CurTime() > (self.MercerWallCooldown or 0) and not self.MercerWallRegrabAtApex
			and not (self.MercerVault and CurTime() - self.MercerVault.t0 < 0.6) -- just vaulted it
			and not (self.MercerNode and self.MercerNode.opts.block) then
			local ground = self:IsOnGround()
			local md = self.MercerMoveDir
			if not md or md:IsZero() then
				-- (the AI has no input: its flight's own direction - "bad argument to Dot (got nil)", user 2026-10-23)
				local hv = self:GetVelocity()
				hv.z = 0
				md = hv:LengthSqr() > 1 and hv:GetNormalized() or self:GetForward()
			end
