		-- fixed carry spot (smooth, in multiplayer too) and drawn between his CLIENT hands (alex_mercer_guns.lua)
		local OBJECTS_ON = true
		function ENT:MercerObjTarget()
			if not OBJECTS_ON then return end
			local pos, fwd = self:GetPos() + Vector(0, 0, 40), self:GetForward()
			local best, bd
			for _, e in ipairs(ents.FindInSphere(pos + fwd * 40, 90)) do
				if objOk(self, e) then
					local d = e:NearestPoint(pos):Distance(pos)
					if d <= 2.2 * M2U and (not bd or d < bd) then best, bd = e, d end
				end
			end
			return best
		end
