		-- as it arrives (2hnd/specific); pose {catch} within 15 m alex_whip_grab_twohand, its last frame held, the same short and long pulls
		-- farther. On the spike as a body is: frozen, not solid (not the game's: its grabSlotEnableStuckTest), reeled in at the grab's 30 m/s,
		-- arriving when its near side would (half its bounding radius, BY EYE)
		ALEX_MERCER_GRAPH["mercer/whipcatch/twohand"] = {seg(0, 39 / 30, "alex_whip_grab_twohand", 0, 39), seg(39 / 30, 9, "alex_whip_grab_twohand", 39, 39)}
		function ENT:MercerObjOk(e)
			return OBJECTS_ON and not self.MercerObj and objOk(self, e)
		end
		function ENT:MercerCatchObj(st, e)
			local ph = e:GetPhysicsObject()
			st.caught = {e = e, obj = true, group = e:GetCollisionGroup()}
			e.MercerHeldBy = self
			e:SetCollisionGroup(COLLISION_GROUP_WORLD)
			e:SetNotSolid(true)
			ph:EnableMotion(false)
			ph:EnableCollisions(false)
			local dm = e:GetPos():Distance(self:GetPos()) / M2U
			st.catchPose = dm <= 15 and "twohand" or dm <= 25 and "short" or nil
			if st.catchPose then GP.Start(self, "mercer/whipcatch/" .. st.catchPose, {block = true, hold = true}) end
			self:MercerCue("alex_grab")
			-- (removed with it on the spike, his player gone with him: it isn't left frozen in the air)
			local c = st.caught
			self:CallOnRemove("MercerCaughtObj", function(ent) ent:MercerCaughtObjFree(c) end)
			return true
		end
		-- let go: the fight ended before it reached him, or it did
		function ENT:MercerCaughtObjFree(c)
			self:RemoveCallOnRemove("MercerCaughtObj")
			local e = c.e
			if not IsValid(e) then return end
			e.MercerHeldBy = nil
			e:SetCollisionGroup(c.group or COLLISION_GROUP_NONE)
			e:SetNotSolid(false)
			local ph = e:GetPhysicsObject()
			if IsValid(ph) then
				ph:EnableCollisions(true)
				ph:EnableMotion(true)
				ph:Wake()
			end
		end
		function ENT:MercerCaughtObjThink(st, c)
			local e, sh = c.e, st.shot
			if not IsValid(e) or not IsValid(e:GetPhysicsObject()) then
				st.caught = nil
				return false
			end
			if not sh or not sh.stopT then return false end
			c.off = c.off or (e:GetPos() - sh.tip)
			local tip = sh.tip
			if st.phase == "trans" then
				local L0 = sh.tip:Distance(sh.base)
				local L = L0 - (st.atk.reel or 30) * M2U * (CurTime() - st.t0)
				if L <= 30 + e:BoundingRadius() * 0.5 then
					st.caught = nil
					self:MercerFightEnd()
					self:MercerCaughtObjFree(c)
					GP.Stop(self)
					self:MercerObjPick(e)
					return true
				end
				tip = LerpVector(1 - L / math.max(L0, 1), sh.tip, self:MercerWhipBase())
			end
			e:SetPos(tip + c.off)
			return false
		end
		local function handsPos(self)
			local bl, br = self:LookupBone("Wrist_L"), self:LookupBone("Wrist_R")
			if not (bl and br) then return self:WorldSpaceCenter() + self:GetForward() * 30 end
			return (self:GetBonePosition(bl) + self:GetBonePosition(br)) * 0.5
		end
		function ENT:MercerObjPick(e)
			local ph = e:GetPhysicsObject()
			self:MercerCombatEvent()
			self:SetAngles(Angle(0, (e:WorldSpaceCenter() - self:GetPos()):Angle().y, 0))
			local mins, maxs = e:OBBMins(), e:OBBMaxs()
			-- (user 2026-10-28: "the car isn't centred - the prop in the middle of his hands") its long side across him
			-- (a car held side-on), its depth half out in front
			local lx, ly = maxs.x - mins.x, maxs.y - mins.y
			self.MercerObj = {e = e, t0 = CurTime(), phase = "pick", mass = ph:GetMass(), group = e:GetCollisionGroup(),
				yaw = lx > ly and 90 or 0, r = math.min(lx, ly) * 0.5, h = maxs.z - mins.z}
			e.MercerHeldBy = self
			e:SetCollisionGroup(COLLISION_GROUP_WORLD)
			ph:EnableMotion(false)
			GP.Start(self, "mercer/obj/pickup", {block = true})
			self:MercerSound(SND.jump_wind, 65, 90)
		end
		-- where the object is held: parented to him, its centre in front of his chest (the carry pose's hands: ~22 u out,
		-- 50 u up), half its size further out, turned as it was picked up (the client draws it at his real hands)
		local function holdAt(self, o)
			local e = o.e
			if e:GetParent() ~= self then
				-- (user 2026-10-28: "the car sticks into the floor and Mercer is flung across the map") held, it is not
				-- solid at all on the server (a frozen car overlapping him pushed him out): only the client draws it
				e:SetNotSolid(true)
				local ph = e:GetPhysicsObject()
				if IsValid(ph) then ph:EnableCollisions(false) end
				e:SetParent(self)
				self:SetNW2Entity("MercerObjEnt", e)
				e:SetNW2Entity("MercerCarrier", self)
			end
			local oc = e:OBBCenter()
			oc:Rotate(Angle(0, o.yaw, 0))
			-- (user 2026-10-28: "on the hands, centred") the carry pose (alex_weap_2hnd_sml_amb) holds it OVER his head:
			-- the wrists ~69 u up, 21 u either side, 1 u forward - its bottom on the palms (+4 u), its centre over him
			-- (the server's spot clear over his head, out of his box; what is seen is the client's, on his hands)
			e:SetLocalPos(Vector(1, 0, 80 + o.h * 0.5) - oc)
			self:SetNW2Float("MercerObjYaw", o.yaw)
			e:SetLocalAngles(Angle(0, o.yaw, 0))
		end
		local function letGo(self, o, vel, spin)
			self.MercerObj = nil
			self:SetNW2Bool("MercerObjHold", false)
			local e = o.e
			if not IsValid(e) then return end
			e.MercerHeldBy = nil
			self:SetNW2Entity("MercerObjEnt", NULL)
			e:SetNW2Entity("MercerCarrier", NULL)
			if e:GetParent() == self then
				local wp, wa = e:GetPos(), e:GetAngles()
				e:SetParent(nil)
				e:SetPos(wp)
				e:SetAngles(wa)
			end
			e:SetCollisionGroup(o.group or COLLISION_GROUP_NONE)
			e:SetNotSolid(false)
			local ph = e:GetPhysicsObject()
			if IsValid(ph) then
				ph:EnableCollisions(true)
				ph:EnableMotion(true)
				ph:Wake()
				if vel then ph:SetVelocity(vel) end
				if spin then ph:AddAngleVelocity(spin) end
			end
		end
		function ENT:MercerObjDrop()
			local o = self.MercerObj
			if not o then return end
			if self.MercerNode and string.sub(self.MercerNode.path, 1, 11) == "mercer/obj/" then GP.Stop(self) end
			letGo(self, o, self:GetVelocity() + self:GetForward() * 60)
			self:UpdateAnimation()
		end
		-- the throw's autoTarget (30 m, 45 deg; the locked one first; the AI: its enemy)
		local function throwTarget(self)
			if not self:IsPossessed() and IsValid(self:GetEnemy()) then return self:GetEnemy() end
			return self:MercerAutoTargetFind({0, -1, 900, 45, 30, false})
		end
		local function throwIt(self, o)
			local e = o.e
			if not IsValid(e) then self.MercerObj = nil return end
			local tab = self:GetMercerForm().name == "Мускулы" and OBJ_MASS_MUSCLE or OBJ_MASS
			local cls = tab[#tab]
			for _, k in ipairs(tab) do if o.mass <= k[1] then cls = k break end end
			local speed = Lerp(o.charge or 0.5, cls[4], cls[5]) * M2U * self:MercerMuscleK()
			local from = e:WorldSpaceCenter()
			local dir
			local tgt = throwTarget(self)
			if IsValid(tgt) then
				-- at the target, lofted for its fall (gravity 600 u/s^2) over the flight
				local to = tgt:WorldSpaceCenter() - from
				local tflight = to:Length() / speed
				dir = (to + Vector(0, 0, 0.5 * 600 * tflight * tflight)):GetNormalized()
			else
				local p = self:GetPossessor()
				dir = IsValid(p) and self:MercerAimVector(p) or self:GetForward()
				dir = (dir + Vector(0, 0, 0.1)):GetNormalized()
			end
			e.MercerThrown = {by = self, t = CurTime() + 4, dmg = Lerp(o.charge or 0.5, cls[2], cls[3]) * self:MercerMuscleK(), hit = {}}
			if not e.MercerThrowCb then
				e.MercerThrowCb = e:AddCallback("PhysicsCollide", function(ent, data)
					local th = ent.MercerThrown
					local hit = data.HitEntity
					if not th or CurTime() > th.t or not IsValid(hit) or th.hit[hit] or hit == th.by then return end
					if not (hit:IsNPC() or hit:IsNextBot() or hit:IsPlayer() or IsValid(hit:GetPhysicsObject())) then return end
					th.hit[hit] = true
					local di = DamageInfo()
					di:SetDamage(th.dmg * (IsValid(th.by) and th.by:MercerVehicleScale(hit, nil, nil, nil, "Throw") or 1))
					di:SetDamageType(DMG_CRUSH)
					di:SetAttacker(IsValid(th.by) and th.by or ent)
					di:SetInflictor(ent)
					di:SetDamagePosition(data.HitPos)
					-- (user 2026-10-29: "they fly off with insane force") the force capped: a body at 2000 u/s x 50 flung the hit
				-- one across the map
				local f = data.OurOldVelocity * 10
				if f:Length() > 12000 then f = f:GetNormalized() * 12000 end
				di:SetDamageForce(f)
					hit:TakeDamageInfo(di)
				end)
			end
			local sp = math.rad(math.Rand(270, 500)) * (math.random(2) == 1 and 1 or -1)
			letGo(self, o, dir * speed, Vector(0, math.deg(sp), math.Rand(-90, 90)))
			self:MercerVO("alex_throw", 1)
			self:MercerSound(SND.jump_wind, 75, 80)
			-- (the graph's on_all_throws: the throw's whoosh, his push off the ground)
			self:MercerCue("big_heavy_whoosh", 0.6, 0.5)
			self:MercerCue("power_whoosh")
			self:MercerTrail("punch_r")
			self:MercerVFX("dash", self:GetPos() + Vector(0, 0, 2))
			if o.mass > 750 then self:MercerShake("small", "medium") end
		end
		-- returns true while the object's anims own the body (the pickup, the throw)
		function ENT:MercerObjThink(p, dt)
			local o = self.MercerObj
			if not IsValid(o.e) or o.e:GetPhysicsObject() == nil then self.MercerObj = nil self:SetNW2Bool("MercerObjHold", false) return false end
			local t = CurTime() - o.t0
			if o.phase == "pick" then
				-- the pickup: the object into his hands over its first half
				if t >= 0.15 then holdAt(self, o) end
				if t >= 29 / 60 then
					o.phase = "hold"
					self:SetNW2Bool("MercerObjHold", true)
					GP.Stop(self)
					self:UpdateAnimation()
					return false
				end
				return true
			end
			holdAt(self, o)
			-- (user 2026-10-28: "the step forward is only in the anim") the throw's root: 1.3 m over the windup (0-15),
			-- 0.5 m in the release's first 0.3 s, 0.35 m over the rest (alex_weap_2hnd_throw's Motion_Root)
			local function step(v)
				local fwd = self:GetForward()
				self.loco:SetVelocity(Vector(fwd.x * v * M2U, fwd.y * v * M2U, self.loco:GetVelocity().z))
				if v > 0.05 and self:IsOnGround() then self:Approach(self:GetPos() + fwd * 100) end
			end
			local function moveOn()
				if o.air then
					if self:IsOnGround() then
						o.air = false
						self.loco:SetGravity(1000)
						return
					end
					local vel = self.loco:GetVelocity()
					local hv = Vector(vel.x, vel.y, 0)
					if hv:Length() > 15 * M2U then hv = hv:GetNormalized() * math.Approach(hv:Length(), 15 * M2U, 60 * M2U * dt) end
					local vz = vel.z > 0 and math.Approach(vel.z, 0, 50 * M2U * dt) or vel.z - 10 * M2U * dt
					self.loco:SetGravity(0)
					self.loco:SetVelocity(Vector(hv.x, hv.y, vz))
				elseif o.slideV then
					local R = o.slideR
					o.slideV = math.max(0, o.slideV - (R and R.brake or OBJ_SLIDE_BRAKE) * dt)
					self.loco:SetVelocity(Vector(0, 0, self.loco:GetVelocity().z))
					if o.slideV > (R and R.stop or 0) then self:MercerShove(o.slideDir * (o.slideV * M2U * dt)) end
				else
					return true
				end
			end
			if o.phase == "windup" then
				-- (user 2026-10-28: "he doesn't turn to where he throws") through the windup he turns (900 deg/s, the
				-- autoTarget's rate) to where it will fly: the target (locked / in the arc / the AI's enemy), else the
				-- camera's aim - the throw took the aim while he kept facing his own way
				local tgt = throwTarget(self)
				local want = IsValid(tgt) and (tgt:GetPos() - self:GetPos()):Angle().y
					or (IsValid(p) and self:MercerAimVector(p):Angle().y) or nil
				if want then
					self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, want, 900 * FrameTime()), 0))
				end
				if moveOn() then step(t < 0.5 and 2.6 or 0) end
				-- (user 2026-10-28: "I don't like how he charges the throw, it looks off") no pose of its own for the charge: the windup's
				-- frames 0-15, the release when the key is let go; the AI's whole
				o.charge = math.min(1, t / 0.5)
				local up = IsValid(p) and not p:KeyDown(o.key)
				if t >= (o.air and 0.6667 or o.slideV and 0.5333 or 0.5) or up then
					o.phase, o.t0 = "release", CurTime()
					GP.Start(self, "mercer/obj/release", {block = true, exitAfter = o.slideV and 0.13 or 0.6667,
						onDone = function(ent) ent:UpdateAnimation() end})
				end
				return true
			elseif o.phase == "release" then
				if moveOn() then step(t < 0.3 and 1.65 or (t < 1.1 and 0.4 or 0)) end
				if t >= 0.0333 then
					if o.air then self.loco:SetGravity(1000) end
					if o.slideV then self.MercerThrowSlide = {v = o.slideV, dir = o.slideDir, node = self.MercerNode, R = o.slideR} end
					throwIt(self, o)
				end
				return true
			end
			return false
		end
		-- what is left of the run's slide after the object has gone, until the run goes on
		function ENT:MercerThrowSlideThink(dt)
			local s = self.MercerThrowSlide
			local R = s.R
			s.v = s.v - (R and R.brake or OBJ_SLIDE_BRAKE) * dt
			if s.v <= (R and R.stop or 0) or self.MercerNode ~= s.node or not self:IsOnGround() then
				self.MercerThrowSlide = nil
				-- (alex_mercer_throw_run) what is left of it is his own speed: the sprint's locoSprint takes it up, at least velocityMin
				if R and s.v > 0 then
					self.loco:SetVelocity(s.dir * (s.v * M2U) + Vector(0, 0, self.loco:GetVelocity().z))
					if self.MercerSprintOn then self.MercerSprintSpeed = math.Clamp(s.v, SPR.vMin, SPR.vMax) end
				end
				return
			end
			self.loco:SetVelocity(Vector(0, 0, self.loco:GetVelocity().z))
			self:MercerShove(s.dir * (s.v * M2U * dt))
		end
		function ENT:MercerObjInput(kind)
			local o = self.MercerObj
			if not o or o.phase ~= "hold" then return end
			if kind == "e" then return self:MercerObjDrop() end
			if kind == "a" or kind == "s" then
				o.phase, o.t0 = "windup", CurTime()
				o.key = kind == "s" and IN_ATTACK2 or IN_ATTACK
				self:MercerCombatEvent()
				o.air = not self:IsOnGround()
				if self.MercerSprintOn and not o.air then
					local hv = self:GetVelocity()
					hv.z = 0
					o.slideV, o.slideDir = math.Clamp(hv:Length() / M2U, 10, 15), hv:LengthSqr() > 1 and hv:GetNormalized() or self:GetForward()
					if self.MercerThrowRunOn:GetBool() then
						o.slideR = self.MercerRunThrow
						o.slideV = math.Clamp(hv:Length() / M2U, o.slideR.vmin, o.slideR.vmax)
						dbg("throw_run: an object, slide from %.1f m/s, he was at %.1f", o.slideV, hv:Length() / M2U)
					end
					self.MercerSprintOn = false
					self.loco:SetAcceleration(self.Acceleration)
					self.loco:SetDeceleration(self.Deceleration)
					self:SetNW2Float("MercerSprint", 0)
				end
				GP.Start(self, "mercer/obj/windup", {block = true, hold = true})
				self:MercerSound(SND.jump_wind, 65, 110)
			end
		end
		hook.Add("EntityRemoved", "AlexMercerObjRemoved", function(e)
			if e.MercerObj then
				local o = e.MercerObj
				if IsValid(o.e) then letGo(e, o) end
			end
		end)
	end

	do -- (user 2026-10-23) firearms (a block of its own: the main chunk is near 200 locals) = the prototype_firearm
		-- graph (build/graph_firearm.txt) with the soldiers' guns (lua/autorun/alex_mercer_guns.lua: models, the
		-- GunAmmoProfile numbers). E near a gun: holding/firearm - alex_weap_rifle_pickup 9-20, the gun in
		-- R_Wrist_Grapple; loco: alex_weap_rifle_stand idle; aiming (Attack down / a lock / 0.6 s after a shot - the
		-- "aiming" node's timer): locoStrafe 720 deg/s facing the aim (strafe_fwd / back / left / right; standing
		-- aim_up / neutral / down), else alex_weap_rifle_run_fwd. Attack: rifle / saw fire while held, the others per
		-- press, at fireRate, the clip empty -> the "pose" node's drop. E: drop (alex_weap_rifle_drop, grabSlotDetachThrow
		-- at 0.35 s, spin 270). RMB does nothing with a gun (the graph's bare kicks are left out).
		ALEX_MERCER_GRAPH["mercer/gun/pickup"] = {seg(0, 11 / 30, "alex_weap_rifle_pickup", 9, 20)}
		ALEX_MERCER_GRAPH["mercer/gun/drop"] = {seg(0, -1, "alex_weap_rifle_drop", 0, -1)}
		ALEX_MERCER_GRAPH["mercer/gun/air"] = {{start = 0, stop = -1, anim = "alex_weap_rifle_aim_air", rate = 2, f0 = 0, f1 = -1, cyclic = true,
			part = "", blendin = 0.2, blendout = 0.2}}
		local GUNS_ON = true
		local AIM_HOLD = 0.15 -- (user 2026-10-29: "the gun must come down as soon as you let go"; was 0.6)
		-- (the carry anims got their loop flag in alex_mercer_anims.qc 2026-10-23: wrapping the cycle by hand ran the
		-- client's interpolation backwards through the anim at every wrap - "he gets thrown back" running)
		local function gunData(e)
			return IsValid(e) and e.MercerGunKind and ALEX_MERCER_GUNS and ALEX_MERCER_GUNS[e.MercerGunKind]
		end
		function ENT:MercerGunTarget()
			if not GUNS_ON then return end
			local pos = self:GetPos() + Vector(0, 0, 20)
			local best, bd
			local from = ALEX_MERCER_GUN_FROM or {}
			for _, e in ipairs(ents.FindInSphere(pos, 2.5 * M2U)) do
				local ok = gunData(e) and not IsValid(e:GetParent()) and e:GetNW2Int("MercerGunAmmo", 1) > 0
					and CurTime() > (e.MercerGunNoPick or 0)
				-- a GMod gun on the ground (no owner)
				ok = ok or (from[e:GetClass()] and e:IsWeapon() and not IsValid(e:GetOwner()))
				if ok then
					local d = e:GetPos():Distance(pos)
					if not bd or d < bd then best, bd = e, d end
				end
			end
			return best
		end
		local function attach(self, e)
			local ph = e:GetPhysicsObject()
			if IsValid(ph) then ph:EnableMotion(false) end
			e:SetNotSolid(true)
			local b = self:LookupBone("R_Wrist_Grapple")
			if b then e:FollowBone(self, b) else e:SetParent(self) end
			e:SetLocalPos(vector_origin)
			e:SetLocalAngles(angle_zero)
		end
		local function release(self, G)
			self.MercerGun = nil
			self:SetNW2String("MercerGun", "")
			if G.missile then
				self:SetNW2Bool("MercerMissileHold", false)
				if IsValid(G.e) then G.e:Remove() end
				return
			end
			local e = G.e
			if not IsValid(e) then return end
			local pos, ang = e:GetPos(), e:GetAngles()
			pcall(e.FollowBone, e, NULL, 0)
			e:SetParent(NULL)
			e:SetPos(pos)
			e:SetAngles(ang)
			e:SetNotSolid(false)
			e.MercerGunNoPick = CurTime() + 1
			local ph = e:GetPhysicsObject()
			if IsValid(ph) then
				ph:EnableMotion(true)
				ph:Wake()
				ph:SetVelocity(self:GetVelocity() + self:GetForward() * 60 + Vector(0, 0, 60))
				ph:AddAngleVelocity(Vector(0, 0, 270))
			end
			if e:GetNW2Int("MercerGunAmmo", 0) <= 0 then SafeRemoveEntityDelayed(e, 10) end -- (DiscardedFirearm: fades)
		end
		-- (2026-11-04, alex_mercer_missile_grab, off by default) a rocket taken out of the air and thrown back. Every shell of the game
		-- is GrabbableBehaviour class "missile" (Soldier_tod.p3d: shell_40mm001, shell_127mm001, shell_TOWMissile001). What keeps one, by
		-- all the graphs (build/chasecam/missile_paths.py), {t0, t1 s from the press, radius m, forward, up m of Motion_Root, 1 m over his
		-- feet}: standing, prototype_consume detect_from_loco/detected/in_front/not_holding/grab/missile: alex_weap_rifle_pickup 0-20 at 2, its
		-- sphere, the grab 0.15-0.21 s with the rocket in that sphere at the press already (at 20 m/s it is through in 0.12 s: the 0.1-0.4 s here
		-- BY EYE, the plain Action's); running, prototype_sprint actions/grab give/grabbed/missile. In the air none: the air's grabs let
		-- go of all but a helicopter. In the hand it is a state of the gun's, so all a gun excludes stays excluded, but no NW2 MercerGun:
		-- holding/grabbing/missile, on the PC only Attack throws, E nothing. The flying one goes, alex_mercer_missile_held is drawn in
		-- its place (alex_mercer_guns.lua), a new one of its class flies at the throw.
		local MISSILE_CLASS = {proto_rocket_127mm = true, proto_grenade_40mm = true, proto_grenade_milkor = true,
			rpg_missile = true, grenade_ar2 = true}
		local MISSILE_GRAB = {ground = {0.1, 0.4, 1.25, 0.5, -0.5}, sprint = {0.1667, 0.5333, 1.4, 1, 0.2}}
		-- the throw item's distance / velocity / tracking min, max by the charge, ThrowLongRange's (all he can do is unlocked) and the
		-- muscle form's; ThrowAction (0x1011ff50) reads velocity as the speed. Not ported: its damage 100-140 / 200-300 and its spin; the
		-- shell's own blast is what hits
		local MISSILE_THROW = {bare = {55, 110, 35, 40, 30, 40}, muscle = {70, 130, 40, 60, 50, 60}}
		-- (the pickup's second half: the catch comes at its middle)
		ALEX_MERCER_GRAPH["mercer/missile/pickup"] = {seg(0, 0.1667, "alex_weap_rifle_pickup", 10, 20)}
		ALEX_MERCER_GRAPH["mercer/missile/windup"] = {seg(0, 0.6667, "alex_weap_missile_throw", 0, 38)}
		ALEX_MERCER_GRAPH["mercer/missile/release"] = {seg(0, -1, "alex_weap_missile_throw", 39, -1)}
		function ENT:MercerMissileArm(t0, runV)
			if not self:IsOnGround() then return end
			self.MercerMissileWin = {t0 = t0, r = (self.MercerSprintOn or runV:Length() > 3 * M2U) and MISSILE_GRAB.sprint or MISSILE_GRAB.ground}
		end
		local function missileTake(self, e, p, row)
			local f = self:GetMercerForm()
			-- (as a gun: an attack power goes, the disguise / the armour stay)
			if self:GetNW2Int("MercerForm", 1) ~= 1 and f.kind ~= "disguise" then self:MercerSetForm(1, false) end
			local h = ents.Create("alex_mercer_missile_held")
			if not IsValid(h) then return end
			h:SetModel(e:GetModel())
			h:SetPos(self:GetPos())
			h:SetAngles(self:GetAngles())
			h:SetParent(self)
			h:Spawn()
			-- (the empty grab it interrupts: the running grab's dash, the miss pose)
			self.MercerGrab = nil
			if self.MercerNode and string.find(self.MercerNode.path, "grab", 1, true) then GP.Stop(self) end
			self.MercerGun = {e = h, missile = e:GetClass(), rings = e.ProtoRings, t0 = CurTime(), phase = "hold", next = 0,
				attached = true, attackWas = p:KeyDown(IN_ATTACK)}
			self:SetNW2Bool("MercerMissileHold", true)
			self:MercerCombatEvent()
			self:MercerSound(SND.jump_wind, 65, 90)
			e:Remove()
			if row == MISSILE_GRAB.ground and not self.MercerNode then
				GP.Start(self, "mercer/missile/pickup", {block = true, exitAfter = 0, onDone = function(ent) ent:UpdateAnimation() end})
			else
				self:UpdateAnimation()
			end
		end
		function ENT:MercerMissileCatch(p)
			local w = self.MercerMissileWin
			local r = w.r
			local t = CurTime() - w.t0
			local g = self.MercerGrab
			if t > r[2] or not IsValid(p) or self.MercerObj or self.MercerGun or (g and g.phase ~= "dash") then
				self.MercerMissileWin = nil
				return
			end
			if t < r[1] then return end
			local c = self:GetPos() + self:GetForward() * (r[4] * M2U) + Vector(0, 0, (1 + r[5]) * M2U)
			local R, ft = r[3] * M2U, FrameTime()
			for _, e in ipairs(ents.FindInSphere(c, R + 120 * M2U * ft)) do
				if MISSILE_CLASS[e:GetClass()] and not e.ProtoDone and e.ProtoAttacker ~= self and e:GetOwner() ~= self then
					-- its line over the last tick and the next: at 100 m/s it passes the sphere between two ticks, and its own trace
					-- would hit him the tick after
					local pos, v = e:GetPos(), e.ProtoVel or e:GetVelocity()
					local a, ab = pos - v * ft, v * (2 * ft)
					local len2 = ab:Dot(ab)
					local q = a + ab * (len2 > 0 and math.Clamp((c - a):Dot(ab) / len2, 0, 1) or 0)
					if q:Distance(c) <= R and not util.TraceLine({start = self:WorldSpaceCenter(), endpos = q, mask = MASK_SOLID_BRUSHONLY}).Hit then
						self.MercerMissileWin = nil
						return missileTake(self, e, p, r)
					end
				end
			end
		end
		local function missileLaunch(self, G, dir, charge, tgt)
			local T = self:GetMercerForm().name == "Мускулы" and MISSILE_THROW.muscle or MISSILE_THROW.bare
			local speed = Lerp(charge, T[3], T[4]) * M2U
			local m = ents.Create(G.missile)
			if not IsValid(m) then return end
			-- (from where a held gun's muzzle is: a nextbot's server bones are off in graph nodes)
			m:SetPos(self:GetPos() + Vector(0, 0, 52) + dir * 34 + self:GetRight() * 5)
			m:SetAngles(dir:Angle())
			if m.ProtoFly then
				m.ProtoVel, m.ProtoAttacker = dir * speed, self
				m.ProtoRings = G.rings or m.ProtoRings
				m.ProtoLife = Lerp(charge, T[1], T[2]) * M2U
				-- the throw's tracking: its speed kept, turning to the target at the item's deg/s (the rocket's burn and the grenade's
				-- drop are not used, by eye)
				local track = Lerp(charge, T[5], T[6])
				m.ProtoFly = function(s, v, dt)
					if not IsValid(tgt) then return end
					local sp = v:Length()
					local cur = v * (1 / sp)
					local to = (tgt:WorldSpaceCenter() - s:GetPos()):GetNormalized()
					local deg = math.deg(math.acos(math.Clamp(cur:Dot(to), -1, 1)))
					if deg < 0.01 or deg > 179.9 then return end
					local step = math.min(deg, track * dt)
					local n = (cur * math.sin(math.rad(deg - step)) + to * math.sin(math.rad(step))):GetNormalized() * sp
					v.x, v.y, v.z = n.x, n.y, n.z
				end
				m:Spawn()
			else
				m:SetOwner(self)
				m:Spawn()
				m:Activate()
				m:SetVelocity(dir * speed)
			end
		end
		-- the autoTarget's turn (windup 900 deg/s, 90 deg; release 1200, 45; 30 m), else to the camera's aim - as the object's throw
		local function missileTurn(self, p, rate, arc)
			local tgt = self:MercerAutoTargetFind({0, -1, rate, arc, 30, false})
			local want = IsValid(tgt) and (tgt:GetPos() - self:GetPos()):Angle().y or (IsValid(p) and self:MercerAimVector(p):Angle().y)
			if want then self:SetAngles(Angle(0, math.ApproachAngle(self:GetAngles().y, want, rate * FrameTime()), 0)) end
			return tgt
		end
		local function missileMove(self, G, dt)
			if G.air then
				if self:IsOnGround() then
					G.air = false
					self.loco:SetGravity(1000)
					return
				end
				-- flyingBrake: down to 15 m/s at 10 (windup) / 30 m/s^2 (release), the rise stopped at 50; the fall as the object's
				local vel = self.loco:GetVelocity()
				local hv = Vector(vel.x, vel.y, 0)
				if hv:Length() > 15 * M2U then
					hv = hv:GetNormalized() * math.Approach(hv:Length(), 15 * M2U, (G.phase == "windup" and 10 or 30) * M2U * dt)
				end
				self.loco:SetGravity(0)
				self.loco:SetVelocity(Vector(hv.x, hv.y, vel.z > 0 and math.Approach(vel.z, 0, 50 * M2U * dt) or vel.z - 10 * M2U * dt))
				return
			end
			-- on the sprint the windup's move, 5 m/s along where he faces; else he stands
			local fwd = self:GetForward()
			local v = G.run and G.phase == "windup" and 5 * M2U or 0
			self.loco:SetVelocity(Vector(fwd.x * v, fwd.y * v, self.loco:GetVelocity().z))
			if v > 0 then self:Approach(self:GetPos() + fwd * 100) end
		end
		-- returns true while the throw owns the body
		local function missileThink(self, G, p, dt)
			if G.phase == "hold" then
				if not IsValid(p) then self:MercerGunDrop() return false end
				local down = p:KeyDown(IN_ATTACK)
				local press = down and not G.attackWas
				G.attackWas = down
				if not press then return false end
				G.phase, G.t0 = "windup", CurTime()
				G.air = not self:IsOnGround()
				if self.MercerSprintOn and not G.air then
					G.run = true
					self.MercerSprintOn = false
					self.loco:SetAcceleration(self.Acceleration)
					self.loco:SetDeceleration(self.Deceleration)
					self:SetNW2Float("MercerSprint", 0)
				end
				self:MercerCombatEvent()
				G.e:SetNW2Int("MercerMissilePhase", G.air and 4 or 2)
				GP.Start(self, "mercer/missile/windup", {block = true, hold = true})
				self:MercerSound(SND.jump_wind, 65, 110)
				return true
			end
			missileMove(self, G, dt)
			local t = CurTime() - G.t0
			if G.phase == "windup" then
				missileTurn(self, p, 900, 90)
				-- the charge items: up to 1 over 0.5 s, down to 0.8 by the windup's end
				G.charge = t < 0.5 and t / 0.5 or Lerp((t - 0.5) / 0.1667, 1, 0.8)
				if t >= 0.6667 or not IsValid(p) or not p:KeyDown(IN_ATTACK) then
					G.phase, G.t0 = "release", CurTime()
					G.e:SetNW2Int("MercerMissilePhase", G.air and 5 or 3)
					GP.Start(self, "mercer/missile/release", {block = true, onDone = function(ent) ent:UpdateAnimation() end})
				end
				return true
			end
			local tgt = missileTurn(self, p, 1200, 45)
			if t >= 0.1 then
				local dir
				if IsValid(tgt) then
					dir = (tgt:WorldSpaceCenter() - (self:GetPos() + Vector(0, 0, 52))):GetNormalized()
				else
					-- (the item's direction 0, 0.1, -1: a little up)
					dir = ((IsValid(p) and self:MercerAimVector(p) or self:GetForward()) + Vector(0, 0, 0.1)):GetNormalized()
				end
				if G.air then self.loco:SetGravity(1000) end
				missileLaunch(self, G, dir, G.charge or 0, tgt)
				release(self, G)
				-- (the object's throw's: the graph's dialogue alex_throw, its whooshes by eye)
				self:MercerVO("alex_throw", 1)
				self:MercerSound(SND.jump_wind, 75, 80)
				self:MercerCue("power_whoosh")
				self:MercerTrail("punch_r")
			end
			return true
		end
		function ENT:MercerGunPick(e)
			local kind = ALEX_MERCER_GUN_FROM and ALEX_MERCER_GUN_FROM[e:GetClass()]
			if kind then
				-- a GMod gun: ours in its place
				local n = ents.Create("alex_mercer_gun_" .. kind)
				if not IsValid(n) then return end
				n:SetPos(e:GetPos())
				n:SetAngles(e:GetAngles())
				n:Spawn()
				e:Remove()
				e = n
			end
			local f = self:GetMercerForm()
			-- a gun in the bare hands: an attack power goes (the disguise / the armour stay)
			if self:GetNW2Int("MercerForm", 1) ~= 1 and f.kind ~= "disguise" then self:MercerSetForm(1, false) end
			self:MercerCombatEvent()
			self:SetAngles(Angle(0, (e:GetPos() - self:GetPos()):Angle().y, 0))
			self.MercerGun = {e = e, g = gunData(e), kind = e.MercerGunKind, t0 = CurTime(), phase = "pick", next = 0}
			GP.Start(self, "mercer/gun/pickup", {block = true, exitAfter = 0.2, onDone = function(ent) ent:UpdateAnimation() end})
		end
		-- (user 2026-10-30: "let him take the consumed one's weapon at once" - not the game's: there it falls to the
		-- ground, picked up with Action) the gun a consumed one held, as one of his kinds: a nextbot's by its GunModel
		-- (the Prototype pack's soldiers carry these very models), an NPC's / a player's weapon by ALEX_MERCER_GUN_FROM
		function ENT:MercerGunKindOf(e)
			if not IsValid(e) or not ALEX_MERCER_GUNS then return end
			if e.GunModel then
				for k, g in pairs(ALEX_MERCER_GUNS) do
					if g.model == e.GunModel then return k end
				end
			end
			local w
			if e:IsNPC() or e:IsPlayer() then
				w = e:GetActiveWeapon()
			elseif e.GetWeapon then
				local ok, x = pcall(e.GetWeapon, e)
				w = ok and x or nil
			end
			return IsValid(w) and ALEX_MERCER_GUN_FROM and ALEX_MERCER_GUN_FROM[w:GetClass()] or nil
		end
		-- as the consume ends: that gun in his hand at once (no pickup anim) - in the bare form or the disguise, played
		-- by a player, on the ground, the hands free; else it lies there (E picks it up), like the game's
		function ENT:MercerConsumedGun(kind, pos)
			if not GUNS_ON or not (ALEX_MERCER_GUNS and ALEX_MERCER_GUNS[kind]) then return end
			-- (the AI never takes up a gun: none left lying for it either - each consume of an armed one dropped another
			-- that stayed for good; before this the gun went with the body, as it still does for him)
			if not IsValid(self:GetPossessor()) then return end
			local e = ents.Create("alex_mercer_gun_" .. kind)
			if not IsValid(e) then return end
			e:SetPos(pos)
			e:SetAngles(Angle(0, self:GetAngles().y, 0))
			e:Spawn()
			local f = self:GetMercerForm()
			if self.MercerGun or self.MercerObj or self.MercerGrab
				or not self:IsOnGround() or (self:GetNW2Int("MercerForm", 1) ~= 1 and not (f and f.kind == "disguise")) then
				return
			end
			attach(self, e)
			e:EmitSound("mercer/weapons/guncock_01.wav", 70, 100, 0.8)
			self.MercerGun = {e = e, g = gunData(e), kind = kind, t0 = CurTime(), phase = "hold", next = 0, attached = true}
			self:SetNW2String("MercerGun", kind)
			-- (an E that left the finisher at its opening must not drop it at once: E with a gun puts it down)
			self.MercerUseHeld = nil
		end
		-- put down (E) / the clip empty: the drop anim standing, at once otherwise
		function ENT:MercerGunDrop()
			local G = self.MercerGun
			if not G then return end
			if G.missile then
				-- (a form change, a heavy hit, the death: it flies on where he faces, uncharged - by eye, the graph has no drop)
				if self.MercerNode and string.sub(self.MercerNode.path, 1, 15) == "mercer/missile/" then GP.Stop(self) end
				if G.air then self.loco:SetGravity(1000) end
				missileLaunch(self, G, self:GetForward(), 0)
				release(self, G)
				return self:UpdateAnimation()
			end
			if G.phase ~= "hold" or not self:IsOnGround() or self.MercerNode then
				if self.MercerNode and string.sub(self.MercerNode.path, 1, 11) == "mercer/gun/" then GP.Stop(self) end
				release(self, G)
				return self:UpdateAnimation()
			end
			G.phase, G.t0 = "drop", CurTime()
			self:SetNW2String("MercerGun", "")
			GP.Start(self, "mercer/gun/drop", {block = true, exitAfter = 0.35, onDone = function(ent) ent:UpdateAnimation() end})
		end
		local function aimPoint(self, p, G)
			local lk = self.MercerLocked and self:MercerLocked(G.g.range * M2U)
			if lk then return lk:WorldSpaceCenter(), true end
			if IsValid(p) and self.PossessorTrace then
				local tr = self:PossessorTrace()
				if tr and tr.HitPos then return tr.HitPos, false end
			end
			return self:WorldSpaceCenter() + self:GetForward() * 2000, false
		end
		-- (players 2026-10-27, user 2026-10-28: "the bullets come out of his legs") the server's bones of a nextbot in a graph node
		-- aren't to be trusted: the shot leaves from where a held gun's muzzle is - chest height, a gun's length out along
		-- the aim, a little to his right
		local function muzzlePos(self, aim)
			local base = self:GetPos() + Vector(0, 0, 52)
			local d = aim - base
			d:Normalize()
			return base + d * 34 + self:GetRight() * 5
		end
		local function shoot(self, G, aim)
			local e, g = G.e, G.g
			local src = muzzlePos(self, aim)
			local dir = aim - src
			dir:Normalize()
			self:SetNW2Float("MercerGunShot", CurTime())
			local dmg = ALEX_MERCER_GUN_DAMAGE(g)
			if g.projectile == "grenade" then
				local gr = ents.Create("grenade_ar2")
				if IsValid(gr) then
					gr:SetPos(src)
					gr:SetAngles(dir:Angle())
					gr:SetOwner(self)
					gr:Spawn()
					gr:SetVelocity(dir * 1500)
					pcall(gr.SetSaveValue, gr, "m_flDamage", dmg)
				end
			elseif g.projectile == "rocket" then
				local m = ents.Create("rpg_missile")
				if IsValid(m) then
					m:SetPos(src + dir * 16)
					m:SetAngles(dir:Angle())
					m:SetOwner(self)
					m:Spawn()
					m:Activate()
					m:SetVelocity(dir * 1500)
					pcall(m.SetSaveValue, m, "m_flDamage", dmg)
				end
			else
				-- (user 2026-10-28: the shots still came "from below" - the engine draws a nextbot's tracer from its model's
				-- first attachment, low on him) no engine tracer: our own from the muzzle to the hit
				self:FireBullets({Attacker = self, Inflictor = self, Damage = dmg, Num = 1, Src = src, Dir = dir,
					Spread = Vector(g.spread, g.spread, 0), Tracer = 0, Force = 2,
					Distance = g.range * M2U, IgnoreEntity = self, Callback = function(_, tr)
						local ed = EffectData()
						ed:SetStart(src)
						ed:SetOrigin(tr.HitPos)
						ed:SetScale(6000)
						util.Effect("Tracer", ed)
					end})
			end
			e:EmitSound(g.snd, g.projectile and 90 or 85, (g.pitch or 100) + math.random(-4, 4), 1, CHAN_WEAPON)
			e:SetNW2Float("MercerGunShot", CurTime())
			local ammo = e:GetNW2Int("MercerGunAmmo", g.clip) - 1
			e:SetNW2Int("MercerGunAmmo", ammo)
			G.shots = (G.shots or 0) + 1
			-- (user 2026-10-28: the game's sounds) the spent casings falling (the game's bullet_casings01-04), every few
			-- rounds of the bullet guns, a moment after the shot
			if not g.projectile and G.shots % 4 == 1 then
				local ge = e
				timer.Simple(0.25, function()
					if IsValid(ge) then ge:EmitSound("mercer/weapons/bullet_casings0" .. math.random(4) .. ".wav", 60, math.random(95, 110), 0.35) end
				end)
			end
			if ammo <= 0 then
				e:EmitSound("mercer/weapons/empty_clip.wav", 70)
				self:MercerGunDrop()
			end
		end
		-- returns true while the gun's own anims own the body (the pickup)
		function ENT:MercerGunThink(p, dt)
			local G = self.MercerGun
			if not IsValid(G.e) then
				self.MercerGun = nil
				self:SetNW2String("MercerGun", "")
				self:SetNW2Bool("MercerMissileHold", false)
				return false
			end
			if G.missile then return missileThink(self, G, p, dt) end
			local t = CurTime() - G.t0
			if G.phase == "pick" then
				if t >= 0.1 and not G.attached then
					attach(self, G.e)
					G.attached = true
					-- (user 2026-10-28) the game's own pickup: Alex cocking it (sounds/alex/guncock_01)
					G.e:EmitSound("mercer/weapons/guncock_01.wav", 70, 100, 0.8)
				end
				if t < 11 / 30 then return true end
				G.phase = "hold"
				self:SetNW2String("MercerGun", G.kind)
				return false
			elseif G.phase == "drop" then
				if t >= 0.35 then release(self, G) end
				return false
			end
			-- no player (the AI took over): the gun goes
			if not IsValid(p) then self:MercerGunDrop() return false end
			local aim, locked = aimPoint(self, p, G)
			local fire = p:KeyDown(IN_ATTACK)
			-- (user 2026-10-27) RMB toggles the aim: pressed, he raises the gun and aims (the aiming stance / strafe)
			-- without firing; pressed again, lowers it
			local rmb = p:KeyDown(IN_ATTACK2)
			if rmb and not G.rmbWas then G.aimOn = not G.aimOn end
			G.rmbWas = rmb
			if fire or locked or G.aimOn then self:SetNW2Float("MercerGunAim", CurTime()) end
			local to = aim - self:GetPos()
			self.MercerGunAimYaw = to:Angle().y
			self:SetNW2Float("MercerGunPitch", math.NormalizeAngle((aim - self:EyePos()):Angle().p))
			local g = G.g
			if fire and CurTime() >= G.next and (g.auto or not G.held) and not self:GetNW2Bool("MercerWall") then
				G.next = CurTime() + 1 / g.rate
				shoot(self, G, aim)
			elseif not fire and G.held and g.tail and (G.shots or 0) > 0 and IsValid(G.e) then
				G.e:EmitSound(g.tail, 75, 100, 0.6) -- (the burst's echo)
				G.shots = 0
			end
			if self.MercerGun then G.held = fire end
			return false
		end
		function ENT:MercerGunAiming()
			local G = self.MercerGun
			return G and G.phase == "hold" and CurTime() - self:GetNW2Float("MercerGunAim", -10) < AIM_HOLD
		end
		hook.Add("EntityRemoved", "AlexMercerGunRemoved", function(e)
			if e.MercerGun then release(e, e.MercerGun) end
		end)
	end

	-- AI -- (user 2026-10-22: "really dumb" - spammed leaps, only one strike, never changed powers) on his own he
	-- changes attack powers in a fight (12-20 s, with the transformation), puts the armour on when hurt, plays whole
	-- combos (the next press queued in time), charged strikes now and then, grabs humans (to consume when hurt, else
	-- slams / throws / consumes), the devastators with critical mass; leaps only at a far enemy, on a cooldown
	local AI_POWERS = {"Обычный", "Когти", "Клинок", "Молот", "Хлыст", "Мускулы"}
	local function aiWait(self, s)
		local t = CurTime() + s
		while CurTime() < t do coroutine.yield() end
	end
	local function aiFace(self, e)
		if IsValid(e) then self:SetAngles(Angle(0, (e:GetPos() - self:GetPos()):Angle().y, 0)) end
	end
	function ENT:MercerAIPowers()
		local hp, max = self:Health(), self:GetMaxHealth()
		if hp < max * 0.35 and not self:MercerArmour() and CurTime() > (self.MercerAIArmourT or 0) then
			self.MercerAIArmourT = CurTime() + 30
			self:MercerSetArmour(true, true)
			return true
		end
		if CurTime() < (self.MercerAIFormT or 0) then return false end
		self.MercerAIFormT = CurTime() + math.Rand(12, 20)
		local cur = self:GetMercerForm().name
		local pool = {}
		for i, f in ipairs(FORMS) do
			if f.name ~= cur and not f.hidden and table.HasValue(AI_POWERS, f.name) then pool[#pool + 1] = i end
		end
		if #pool == 0 then return false end
		self:MercerSetForm(pool[math.random(#pool)], true)
		return true
	end
	function ENT:MercerAIGrab(enemy)
		self:MercerGrabStart(enemy)
		local g = self.MercerGrab
		if not g then return end
		g.ai = true
		local t = CurTime() + 1.5
		while self.MercerGrab == g and g.phase ~= "hold" and CurTime() < t do coroutine.yield() end
		if self.MercerGrab ~= g or g.phase ~= "hold" then return end
		aiWait(self, math.Rand(0.3, 0.8))
		if self.MercerGrab ~= g then return end
		local hurt = self:Health() < self:GetMaxHealth() * 0.6
		local r = math.random()
		-- consume (RMB); the slam (E); the throw (LMB) at another enemy if there is one
		-- (user: as he likes - consume, throw, slam; hurt he consumes: it heals and fills the critical mass)
		self:MercerGrabInput((hurt or r < 0.45) and "s" or r < 0.75 and "a" or "e")
		t = CurTime() + 7
		while self.MercerGrab and CurTime() < t do coroutine.yield() end
	end
	-- (user 2026-10-22: he can't drop off a height - like many GMod NPCs - he should just jump down; jump high; air
	-- dashes) his own parkour over DrGBase's paths, no navmesh needed: an enemy 3 m+ below within 40 m - a hop off
	-- toward it; 3 m+ above within 30 m - the charged jump (its anims and sounds) on an arc topping 2 m over it; in
	-- the air past the top with the enemy still 8 m+ away - an air dash at it. 2.5 s between jumps
	local AI_G = 1000
	local function aiArc(self, to, top)
		local d = to - self:GetPos()
		local h = d.z
		d.z = 0
		local dist = d:Length()
		local H = math.max(h, 0) + top
		local vz = math.sqrt(2 * AI_G * H)
		local T = vz / AI_G + math.sqrt(2 * math.max(H - h, 1) / AI_G)
		local vh = math.min(dist / T, 25 * M2U)
		return (dist > 1 and d:GetNormalized() or self:GetForward()) * vh + Vector(0, 0, vz)
	end
	function ENT:MercerAIMove(dt)
		local e = self:GetEnemy()
		if not IsValid(e) or self.MercerFight or self.MercerGrab or self:GetNW2Bool("MercerWall") then return end
		local d = e:GetPos() - self:GetPos()
		local dz = d.z
		d.z = 0
		local dist = d:Length()
		-- (user 2026-10-27: "he stands in a corner and stares") chasing, more than 3 m off, on the ground, hardly moving
		-- for 1.2 s: unstick - a wall toward it is run up (as below), else a jump at it
		local stuck = false
		if self:IsOnGround() and dist > 3 * M2U and self:GetVelocity():Length2D() < 1 * M2U and not self.MercerChargeStart
			and not self:IsPlayingAnimation() and not (self.MercerNode and self.MercerNode.opts.block) then
			self.MercerAIStillT = self.MercerAIStillT or CurTime()
			stuck = CurTime() - self.MercerAIStillT > 1.2
		else
			self.MercerAIStillT = nil
		end
		if self:IsOnGround() then
			self.MercerAIAir = nil
			if stuck then self.MercerAIStillT, self.MercerAIJumpT = nil, 0 end
			if CurTime() < (self.MercerAIJumpT or 0) or self:IsPlayingAnimation() or self.MercerChargeStart
				or (self.MercerNode and self.MercerNode.opts.block) then return end
			local up = dz > 3 * M2U and dist < 30 * M2U or stuck
			local down = dz < -3 * M2U and dist < 40 * M2U
			if not (up or down) then return end
			if up then
				-- (user: he jumped onto buildings instead of running up them) a wall between: at it on the sprint - the
				-- wall test takes him up it
				local s0 = self:GetPos() + Vector(0, 0, 40)
				-- (user 2026-10-27: "he doesn't run up walls by himself any more, only jumps") the wall looked for along
				-- the whole way to it (up to 30 m), not just 10 m ahead - a target on a roof is mostly farther
				local w = util.TraceLine({start = s0, endpos = s0 + d:GetNormalized() * math.min(dist, 30 * M2U), filter = self,
					mask = MASK_SOLID_BRUSHONLY})
				-- (stuck twice in a row: the wall didn't take him - the jump this time)
				local tryWall = not (stuck and self.MercerAIStuckWall)
				if stuck then self.MercerAIStuckWall = tryWall end
				if w.Hit and math.abs(w.HitNormal.z) < 0.3 and tryWall then
					self.MercerAIRunT, self.MercerAIWallT = CurTime(), CurTime()
					self.loco:Approach(w.HitPos, 1)
					self.loco:FaceTowards(w.HitPos)
					return
				end
			end
			self.MercerAIJumpT = CurTime() + 2.5
			self:SetAngles(Angle(0, d:Angle().y, 0))
			local vel = aiArc(self, e:GetPos(), up and 2 * M2U or 1 * M2U)
			if up then
				-- the charged standing jump (as if Space was held 1.2 s), then his own arc
				self.MercerChargeStart, self.MercerChargeFast = CurTime() - 1.2, false
				self:MercerJumpRelease()
			else
				GP.Start(self, NODE_TAP, {onDone = toAir})
				self.MercerFallSpeed = 0
				self:LeaveGround()
				self:MercerSound(SND.jump_wind, 62)
				self:MercerTrail("jump")
			end
			self.loco:SetVelocity(vel)
			self.MercerAirBase = Vector(vel.x, vel.y, 0)
			self.MercerAIAir = true
		elseif self.MercerAIAir and not self.MercerFKick and not self.MercerFKickUsed and dist < 6 * M2U
			and math.abs(dz) < 4 * M2U then
			-- (user: kicks now and then) close in the air: the flying kick at it
			self:SetAngles(Angle(0, d:Angle().y, 0))
			self:MercerFKickStart()
		elseif self.MercerAIAir and not self.MercerAirDash and self.loco:GetVelocity().z < 0 and dist > 8 * M2U then
			-- past the top and still far: an air dash at it (as many as the menu allows)
			self:SetAngles(Angle(0, d:Angle().y, 0))
			self.MercerMoveDir = nil
			self:MercerAirDashStart()
		end
	end

	-- (user: he never sprints) chasing an enemy past 8 m he holds Run (the sprint: dash, speed, the wall run)
	-- (user 2026-10-22: off the sprint he slid in and didn't strike; zigzags on open ground) he keeps sprinting right
	-- in and strikes off the sprint from 4 m (the sprint's own attacks: the kick / the dash attacks); in the open, the
	-- enemy level with him and nothing in the way, straight at it instead of DrGBase's navmesh path
	function ENT:OnChaseEnemy(enemy)
		if not IsValid(enemy) then return end
		if CurTime() - (self.MercerAIWallT or -10) < 0.25 then return true end -- (MercerAIMove takes him at the wall)
		local d = enemy:GetPos() - self:GetPos()
		local dz = d.z
		d.z = 0
		local dist = d:Length()
		-- (user 2026-10-27: "the AI sprints when it's right by its victim") Run held from 8 m off (as meant above); already
		-- on the sprint it keeps it in to its 4 m strike
		if dist > 8 * M2U or (self.MercerSprintOn and dist > 4 * M2U) then self.MercerAIRunT = CurTime() end
		if self.MercerSprintOn and dist < 4 * M2U and math.abs(dz) < 1.5 * M2U and not self.MercerFight
			and self:IsOnGround() then
			-- (user 2026-10-27: "the AI spams the sprint kick, knocking the player far away") the sprint strike about a
			-- third of the time and 6 s apart at most; otherwise he drops the sprint and fights it out (combos, grabs)
			if CurTime() > (self.MercerAIKickT or 0) and math.random() < 0.35 then
				self.MercerAIKickT = CurTime() + 6
				self:SetAngles(Angle(0, d:Angle().y, 0))
				self:MercerFightPress(math.random() < 0.5 and "a" or "s")
				return true
			end
			self.MercerAIRunT = nil
			self:MercerSprintEnd()
		end
		if self:IsOnGround() and math.abs(dz) < 2 * M2U and not self.MercerFight then
			local tr = util.TraceHull({start = self:GetPos() + Vector(0, 0, 24), endpos = enemy:GetPos() + Vector(0, 0, 24),
				mins = Vector(-14, -14, 0), maxs = Vector(14, 14, 40), filter = {self, enemy}, mask = MASK_SOLID})
			if not tr.Hit then
				self.loco:Approach(enemy:GetPos(), 1)
				self.loco:FaceTowards(enemy:GetPos())
				return true
			end
		end
	end
	-- waiting out his own attack: once its transition may be left (the node's exit) he goes on (user: after a missed
	-- series he stood there staring)
	local function aiWaitFight(self, enemy, maxT)
		local t = CurTime() + maxT
		while (self.MercerFight or self.MercerClawSpike) and CurTime() < t do
			local st = self.MercerFight
			if st and st.phase == "trans" and CurTime() - st.t0 >= (st.atk.transExit or 0.3) then
				if not (IsValid(enemy) and self:IsInRange(enemy, self.MeleeAttackRange)) then
					self:MercerFightEnd()
					GP.Stop(self)
					self:UpdateAnimation()
				end
				break
			end
			coroutine.yield()
		end
	end
	function ENT:OnMeleeAttack(enemy)
		if self.MercerFight or self.MercerGrab then return end
		if self.MercerSprintOn and self:IsOnGround() then
			aiFace(self, enemy)
			self:MercerFightPress(math.random() < 0.5 and "a" or "s")
			return aiWaitFight(self, enemy, 3)
		end
		if self:MercerAIPowers() then return end
		aiFace(self, enemy)
		-- the devastators with critical mass (the two buttons held through the antic)
		-- (user: he never used them - the critical mass only comes from consuming) a third of it is enough, 15 s apart
		if self:GetNW2Float("MercerCrit", 0) >= 0.3 and self:IsOnGround() and CurTime() > (self.MercerAIDevT or 0)
			and math.random() < 0.5 then
			self.MercerAIDevT = CurTime() + 15
			self.MercerAIHoldUntil = CurTime() + 2.5
			if self:MercerChordStart(({"ps", "gpd", "scl"})[math.random(3)]) then
				local t = CurTime() + 5
				while self.MercerFight and CurTime() < t do coroutine.yield() end
				self.MercerAIHoldUntil = 0
				return
			end
			self.MercerAIHoldUntil = 0
		end
		-- a human: grab it (more often when hurt - consuming heals)
		local hurt = self:Health() < self:GetMaxHealth() * 0.5
		-- (user 2026-10-28: "the AI could take the player in a grab") any human he may grab - players too
		if self:IsOnGround() and self:MercerGrabbable(enemy) and CurTime() > (self.MercerAIGrabT or 0)
			and math.random() < (hurt and 0.7 or 0.35) then
			self.MercerAIGrabT = CurTime() + 6
			return self:MercerAIGrab(enemy)
		end
		-- (user: kicks now and then) a hop at it, the flying kick from the air (MercerAIMove)
		if self:IsOnGround() and math.random() < 0.15 and CurTime() > (self.MercerAIJumpT or 0) then
			self.MercerAIJumpT = CurTime() + 2.5
			GP.Start(self, NODE_TAP, {onDone = toAir})
			self.MercerFallSpeed = 0
			self.MercerFKickUsed = nil
			self:LeaveGround()
			local fwd = Vector(enemy:GetPos().x - self:GetPos().x, enemy:GetPos().y - self:GetPos().y, 0):GetNormalized()
			self.loco:SetVelocity(fwd * 200 + Vector(0, 0, 380))
			self.MercerAirBase = fwd * 200
			self.MercerAIAir = true
			self:MercerSound(SND.jump_wind, 62)
			return
		end
		local r = math.random()
		if r < 0.6 then
			-- a combo: 2-4 presses, each queued while the strike before it plays
			self:MercerFightPress("a")
			for _ = 2, math.random(2, 4) do
				aiWait(self, math.Rand(0.18, 0.3))
				if not self.MercerFight then break end
				self:MercerFightPress("a")
			end
		elseif r < 0.8 then
			self:MercerFightPress("s")
		else
			-- a charged strike
			self.MercerAIHoldUntil = CurTime() + math.Rand(0.5, 1)
			self:MercerFightPress(math.random(2) == 1 and "a" or "s")
		end
		aiWaitFight(self, enemy, 4)
		self.MercerAIHoldUntil = 0
	end

	function ENT:OnRangeAttack(enemy)
		if self.MercerFight or self.MercerGrab then return end
		local f = self:GetMercerForm()
		if f.name == "Хлыст" and self:IsInRange(enemy, 15 * M2U) and math.random() < 0.5 then
			aiFace(self, enemy)
			self:MercerFightPress("s") -- the longshot (15 m at no charge)
			local t = CurTime() + 3
			while self.MercerFight and CurTime() < t do coroutine.yield() end
		end
		-- (user: he still leapt for nothing) no leaps at all: he sprints to them (OnChaseEnemy)
	end

	function ENT:OnIdle()
		self:AddPatrolPos(self:RandomPos(1500))
	end

	function ENT:OnDeath()
		if self.MercerObj and self.MercerObjDrop then self:MercerObjDrop() end
		if self.MercerGun and self.MercerGunDrop then self:MercerGunDrop() end
		self:PlaySequenceAndWait("alex_act_death")
	end

	-- Power wheel / number keys (client → server). Only the possessor of a Mercer may change its form.
	util.AddNetworkString("alex_mercer_form")
	util.AddNetworkString("alex_mercer_senses") -- the Senses: client asks (mode, on) -> the node -> client told when it switches
	util.AddNetworkString("alex_mercer_shake")
	util.AddNetworkString("alex_mercer_punchin") -- the Bullet Dive's camera (ENT:MercerPunchIn, alex_mercer_fx_cl.lua)
	util.AddNetworkString("alex_mercer_tendril") -- the devastators' tendrils (alex_mercer_tendrils.lua)
	util.AddNetworkString("alex_mercer_tendril_beam") -- Critical Pain's tendril beam (tendrilDevastator)
	util.AddNetworkString("alex_mercer_tendril_cocoon") -- Critical Pain's antic: the tendrils wrapping him
	util.AddNetworkString("alex_mercer_tendril_ring") -- the Tendril Barrage's ring all round
	util.AddNetworkString("alex_mercer_tb_pull") -- the explosion's caught, drawn in at the draw-back
	-- server ragdolls (ai_serverragdolls 1) by their owner's index; pulled in, removed as they reach him (2.5 s at most)
	ALEX_MERCER_SV_RAGS = ALEX_MERCER_SV_RAGS or {}
	ALEX_MERCER_SV_PULLS = ALEX_MERCER_SV_PULLS or {}
	hook.Add("CreateEntityRagdoll", "AlexMercerTBRags", function(owner, rag)
		if IsValid(owner) then ALEX_MERCER_SV_RAGS[owner:EntIndex()] = rag end
	end)
	hook.Add("Think", "AlexMercerTBPull", function()
		local P = ALEX_MERCER_SV_PULLS
		for i = #P, 1, -1 do
			local q = P[i]
			local done = not (IsValid(q.m) and IsValid(q.rag)) or CurTime() - q.t0 > 2.5
			if not done then
				local tp = q.m:WorldSpaceCenter()
				local d = tp - q.rag:WorldSpaceCenter()
				if d:Length() < 50 then
					done = true
				else
					for b = 0, q.rag:GetPhysicsObjectCount() - 1 do
						local ph = q.rag:GetPhysicsObjectNum(b)
						if IsValid(ph) then
							ph:EnableGravity(false)
							ph:Wake()
							local to = tp - ph:GetPos()
							ph:SetVelocity(to:GetNormalized() * math.min(40 * 39.37, to:Length() * 6))
						end
					end
				end
			end
			if done then
				if IsValid(q.rag) then q.rag:Remove() end
				table.remove(P, i)
			end
		end
	end)
	net.Receive("alex_mercer_form", function(_, ply)
		local index = net.ReadUInt(8)
		local quick = net.ReadBool()
		local ent = ply:DrG_GetPossessing()
		if not IsValid(ent) or ent:GetClass() ~= "drg_alex_mercer" or not FORMS[index] or FORMS[index].hidden then return end
		-- (the shield's own key: the game's quick transform, never the showcase; from the wheel it plays standing still)
		quick = quick and FORMS[index].shield and ent.MercerShieldSlot:GetBool()
		ent:CallInCoroutine(function(self) self:MercerSetForm(index, not quick) end)
	end)
	net.Receive("alex_mercer_senses", function(_, ply)
		local mode, on = net.ReadString(), net.ReadBool()
		local ent = ply:DrG_GetPossessing()
		if not IsValid(ent) or ent:GetClass() ~= "drg_alex_mercer" or (mode ~= "thermal" and mode ~= "infected") then return end
		ent:CallInCoroutine(function(self) self:MercerSenses(mode, on) end)
	end)
end

if CLIENT then
	-- (MP fix 8, user 2026-10-28: in multiplayer the glide jerks, sideways most; client trace: his drawn position
	-- jumped 40-70 u every 0.1 s) the engine moves a nextbot only in its own updates there (~0.105 s - not
	-- nb_update_frequency: tried, even with sv_cheats), so the server's position stands, then leaps. The client
	-- keeps the positions as they arrive and draws him SMOOTH_DELAY behind, lerped between them (as the engine's own
	-- interpolation would with steady updates); model, bones, effects and the camera all take it (his client origin
	-- set before they use it). Single player: untouched. alex_mercer_mp_smooth 0 = off
	local MPSmooth = CreateClientConVar("alex_mercer_mp_smooth", "1", true, false,
		"Alex Mercer, multiplayer: draw his movement smoothed between the server's 10 Hz position updates (1 = on)")
	local SMOOTH_DELAY, SMOOTH_STEP, SMOOTH_SNAP = 0.12, 0.105, 400
	function ALEX_MERCER_MPSMOOTH(ent)
		if game.SinglePlayer() or not MPSmooth:GetBool() or not IsValid(ent) then return end
		local fn = FrameNumber()
		if ent.MercerSmFrame ~= fn then
			ent.MercerSmFrame = fn
			local now = UnPredictedCurTime()
			local s = ent.MercerSm
			if not s then s = {} ent.MercerSm = s end
			local np = ent:GetNetworkOrigin()
			local last = s[#s]
			if not last or np:DistToSqr(last.p) > 0.04 then
				-- (after a stop the first step starts one update back, not from the stop's old time)
				if last and now - last.t > SMOOTH_STEP * 2 then s[#s + 1] = {t = now - SMOOTH_STEP, p = last.p} end
				-- a teleport (a respawn, a SetPos): no sliding across
				if last and np:DistToSqr(last.p) > SMOOTH_SNAP * SMOOTH_SNAP then
					for i = #s, 1, -1 do s[i] = nil end
				end
				s[#s + 1] = {t = now, p = np}
				while #s > 2 and s[2].t < now - 1 do table.remove(s, 1) end
			end
			local tr = now - SMOOTH_DELAY
			local pos = s[#s].p
			local vel
			if tr < s[#s].t then
				pos = s[1].p
				for i = #s - 1, 1, -1 do
					if s[i].t <= tr then
						local a, b = s[i], s[i + 1]
						local span = math.max(b.t - a.t, 0.001)
						pos = LerpVector((tr - a.t) / span, a.p, b.p)
						vel = (b.p - a.p) / span
						break
					end
				end
			end
			-- (2026-11-04: MercerSmVel, the speed of what is drawn, for the game camera's leads: the engine's estimate is off the raw steps)
			ent.MercerSmPos, ent.MercerSmVel = pos, vel or vector_origin
			-- (user 2026-10-28, multiplayer: "the turns aren't smooth") his turning is stepped in the same ~0.105 s
			-- updates (PossessionControls), and drawn undelayed it ran ahead of the delayed position: the yaw kept
			-- the same way, SMOOTH_DELAY behind, lerped between its arrivals
			local sa = ent.MercerSmAng
			if not sa then sa = {} ent.MercerSmAng = sa end
			local na = ent:GetNetworkAngles()
			local la = sa[#sa]
			if not la or math.abs(math.AngleDifference(na.y, la.a.y)) > 0.05 or math.abs(math.AngleDifference(na.p, la.a.p)) > 0.05
				or math.abs(math.AngleDifference(na.r, la.a.r)) > 0.05 then
				if la and now - la.t > SMOOTH_STEP * 2 then sa[#sa + 1] = {t = now - SMOOTH_STEP, a = la.a} end
				sa[#sa + 1] = {t = now, a = na}
				while #sa > 2 and sa[2].t < now - 1 do table.remove(sa, 1) end
			end
			local ang = sa[#sa].a
			if tr < sa[#sa].t then
				ang = sa[1].a
				for i = #sa - 1, 1, -1 do
					if sa[i].t <= tr then
						local a, b = sa[i], sa[i + 1]
						ang = LerpAngle((tr - a.t) / math.max(b.t - a.t, 0.001), a.a, b.a)
						break
					end
				end
			end
			ent.MercerSmAngle = ang
		end
		local moved = false
		if ent.MercerSmPos and ent:GetPos() ~= ent.MercerSmPos then
			ent:SetPos(ent.MercerSmPos)
			moved = true
		end
		if ent.MercerSmAngle and ent:GetAngles() ~= ent.MercerSmAngle then
			ent:SetAngles(ent.MercerSmAngle)
			moved = true
		end
		if moved then ent:InvalidateBoneCache() end
	end
	hook.Add("PreRender", "AlexMercerMPSmooth", function()
		if game.SinglePlayer() then return end
		for _, m in ipairs(ents.FindByClass("drg_alex_mercer")) do ALEX_MERCER_MPSMOOTH(m) end
	end)

	-- the game's health bar instead of DrGBase's possession HUD (lua/autorun/client/alex_mercer_health.lua)
	function ENT:PossessionHUD()
		-- (the NPC pack's Mother's body: its scene has no HUD, as in a video of the game; hideHUD in graph_consume's beat-down. Only drg_proto_mother_corpse.lua sets it)
		if self:GetNW2Bool("MercerHideHUD") then return true end
		-- (user 2026-10-28) the game's minimap, bottom left (lua/autorun/client/alex_mercer_minimap.lua)
		if ALEX_MERCER_MINIMAP and ALEX_MERCER_MINIMAP.Draw then ALEX_MERCER_MINIMAP.Draw(self) end
		if ALEX_MERCER_HEALTH and ALEX_MERCER_HEALTH.Draw then
			ALEX_MERCER_HEALTH.Draw(self)
			return true
		end
	end

	-- While wall running, tilt the model so the anim's floor is the wall (nose up, back away from it).
	-- Pose tilts done with a model-space render matrix (SetRenderAngles gets overwritten on nextbots, which
	-- left the wall-run body lying "into" the wall). Entity yaw faces the wall / the travel direction.
	local EXIT_YAW = {
		["alex_loco_jump_tact_fwd_left"] = {0.1356, 0.6102, 41},
		["alex_loco_jump_tact_fwd_right"] = {0.2424, 1.0000, -57},
		["alex_loco_obstacle_jump_a"] = {0.1515, 1.0000, 55},
		["alex_loco_parkour_enter_tuck_jump"] = {0.1379, 1.0000, -143},
		["alex_loco_parkour_exit_sideflip_left"] = {0.0000, 1.0000, 76},
		["alex_loco_parkour_hoodslide"] = {0.5641, 0.9231, 41},
		["alex_loco_parkour_hoodslide_gv"] = {0.0000, 0.5217, -72},
		["alex_loco_parkour_small_basic_B"] = {0.0000, 0.8621, 152},
	}
	function ENT:MercerRenderMatrix()
		-- (alex_mercer_wall_overhang) off the run under an overhang: its anims stand in the wall run's space, tools/build_all.py OVERHANG_ANIMS; the tilt goes while Source blends to the next pose, 0.2 s,
		-- the one turning the other way: BY EYE, not seen in the game
		local ut = CurTime() - self:GetNW2Float("MercerWallUsdExitT", -10)
		if not self:GetNW2Bool("MercerWall") and ut < 0.2 then
			local k = 1 - math.Clamp(ut / 0.2, 0, 1)
			k = k * k * (3 - 2 * k)
			local m = Matrix()
			m:Translate(Vector(15, 0, 36) * k)
			m:Rotate(Angle(-90 * k, 0, 0))
			return m
		end
		-- (MercerWallTopOn) over the wall's top: from the wall run's own matrix to upright, while Source blends to the exit's pose, 0.2 s. It was gone from one frame to the next, the body turned 90 deg about his origin: the head 45 u, the feet 36 u down
		local wt = CurTime() - self:GetNW2Float("MercerWallTopT", -10)
		if not self:GetNW2Bool("MercerWall") and wt < 0.2 then
			local k = 1 - math.Clamp(wt / 0.2, 0, 1)
			k = k * k * (3 - 2 * k)
			local da = math.rad(self:GetNW2Float("MercerWallDir", 0))
			local f = LerpVector(k, Vector(1, 0, 0), Vector(0, math.sin(da), math.cos(da)))
			f:Normalize()
			local u = LerpVector(k, Vector(0, 0, 1), Vector(-1, 0, 0))
			local r = f:Cross(u)
			r:Normalize()
			u = r:Cross(f)
			local m = Matrix()
			m:Translate(Vector(15, 0, 36) * k)
			m:SetForward(f)
			m:SetUp(u)
			m:SetRight(r)
			return m
		end
		local et = CurTime() - self:GetNW2Float("MercerWallExitT", -10)
		if not self:GetNW2Bool("MercerWall") and et < 0.3 then
			-- jumpout: entity faces the run direction, the wall on its right (running left) / left (running right);
			-- tilt k: 1 = the wall run's (model up = out of the wall), 0 = upright
			local side = self:GetNW2Int("MercerWallExitSide", 1)
			local k = 1 - math.Clamp(et / 0.3, 0, 1)
			local u = LerpVector(k, Vector(0, 0, 1), Vector(0, side, 0))
			u:Normalize()
			local f = Vector(1, 0, 0)
			local m = Matrix()
			m:Translate(Vector(0, -side * 15, 36) * k)
			m:SetForward(f)
			m:SetUp(u)
			m:SetRight(f:Cross(u))
			return m
		end
		if self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerClimb") and self:GetNW2Bool("MercerHolding") then
			-- (a human in hand: the *_split anims are made upright on the wall - the body vertical, the wall 0.77 m in
			-- front of the root, the root climbing - unlike the plain wall run made on the floor; tilted, he and the
			-- body lay across the wall, user) no tilt, the root backed off to put the feet on the wall (16 u -> 30 u)
			local m = Matrix()
			m:Translate(Vector(-14, 0, 0))
			-- (user 2026-10-23: with a human he ran "up" even going sideways) the upright pose turned in the wall's plane,
			-- about the axis into the wall through his middle, to the run direction (0 up, +90 his left: roll -a)
			local a = self:GetNW2Float("MercerWallDir", 0)
			if math.abs(a) > 1 then
				m:Translate(Vector(0, 0, 36))
				m:Rotate(Angle(0, 0, -a))
				m:Translate(Vector(0, 0, -36))
			end
			return m
		end
		if self:GetNW2Bool("MercerWall") and not self:GetNW2Bool("MercerClimb") then
			-- wall-run enter: from upright to the wall tilt over the 0.2 s enter anim
			local k = math.Clamp((CurTime() - self:GetNW2Float("MercerWallEnterT", 0)) / 0.2, 0, 1)
			if k < 1 then
				local m = Matrix()
				m:Translate(Vector(15, 0, 36) * k)
				m:Rotate(Angle(-90 * k, 0, 0))
				return m
			end
			-- wall run: anim floor (model z=0) on the wall 15 units ahead; model forward = up the wall
			local m = Matrix()
			m:Translate(Vector(15, 0, 36))
			-- model forward = run direction on the wall (local: wall at +X, up +Z, Mercer's left +Y)
			local a = math.rad(self:GetNW2Float("MercerWallDir", 0))
			local f = Vector(0, math.sin(a), math.cos(a))
			local u = Vector(-1, 0, 0)
			m:SetForward(f)
			m:SetUp(u)
			m:SetRight(f:Cross(u))
			return m
		end
		-- (glide needs no tilt: the game's glide anims are already horizontal)
		-- (user 2026-10-22: after a side vault / flip he lands turned away from where he runs and snaps round) these
		-- vault / parkour-exit anims end with the hips turned (hip line, offline from build/anims, at the last frame
		-- each node plays): over the last 45 % of the played span the body is turned back by it - the flip stays, he
		-- lands facing the run. {cycle of the first played frame, of the last, the hips' yaw there}
		local ey = EXIT_YAW[self:GetSequenceName(self:GetSequence()) or ""]
		if ey then
			local span = (ey[2] - ey[1]) * 0.45
			local k = math.Clamp((self:GetCycle() - (ey[2] - span)) / math.max(span, 0.01), 0, 1)
			k = k * k * (3 - 2 * k)
			if k > 0 then
				local m = Matrix()
				m:Rotate(Angle(0, -ey[3] * k, 0))
				return m
			end
		end
	end

	-- Debug trace (temporary): what the client actually renders - sequence changes and cycle jumps -
	-- to garrysmod/data/alex_mercer_debug_cl.txt (pairs with the server trace).
	local DebugCl = CreateClientConVar("alex_mercer_debug_cl", "0", false, false)
	local clBuf, clSize, clFlush = {}, 0, 0
	hook.Add("Think", "alex_mercer_debug_cl", function()
		if not DebugCl:GetBool() or clSize > 20000000 then return end
		for _, ent in ipairs(ents.FindByClass("drg_alex_mercer")) do
			local seq, cyc = ent:GetSequence(), ent:GetCycle()
			local st = ent.MercerDbg
			if not st then st = {} ent.MercerDbg = st end
			local charging = ent:GetNW2Bool("MercerCharging")
			local ground = ent:GetNW2Bool("DrGBaseOnGround")
			local jump = st.cyc and math.abs(cyc - st.cyc) or 0
			-- (the flying kick hunt, 2026-10-27) every 0.1 s while a kick / its fall plays: what is really drawn
			local kick = string.find(ent:GetSequenceName(seq) or "", "kick_air", 1, true) or ent:GetNW2Bool("MercerFKickOn")
			local tick = kick and RealTime() - (st.kickT or 0) >= 0.1
			if tick then st.kickT = RealTime() end
			-- (a looping stance's wrap - 0.98 -> 0.02 - is no jump: it filled the log's cap)
			local wrap = st.cyc and st.cyc > 0.85 and cyc < 0.15
			if tick or st.seq ~= seq or charging ~= st.charging or ground ~= st.ground
				or (jump > 0.04 and st.seq == seq and not wrap) then
				local line = string.format("%.3f %.3f %s cyc %.3f (was %s %.3f) charging=%s ground=%s",
					RealTime(), CurTime(), ent:GetSequenceName(seq), cyc, st.seq and ent:GetSequenceName(st.seq) or "-",
					st.cyc or 0, tostring(charging), tostring(ground))
				clBuf[#clBuf + 1] = line
				clSize = clSize + #line
			end
			-- (the multiplayer jerk hunt, 2026-10-28) a step of his drawn position far over his recent speed (a teleport),
			-- the cycle going backwards inside one sequence (not a loop's wrap), a long frame (a hitch)
			local pos, ft = ent:GetPos(), math.max(RealFrameTime(), 0.001)
			if st.pos then
				local step = pos:Distance(st.pos)
				local spd = st.spd or step / ft
				if step > 8 and step > spd * ft * 3 + 4 then
					clBuf[#clBuf + 1] = string.format("%.3f %.3f POSJUMP %.1f u (speed %.0f u/s) seq=%s cyc=%.3f", RealTime(),
						CurTime(), step, spd, ent:GetSequenceName(seq), cyc)
				end
				st.spd = Lerp(0.2, spd, step / ft)
			end
			if st.seq == seq and st.cyc and cyc < st.cyc - 0.01 and not (st.cyc > 0.85 and cyc < 0.15) then
				clBuf[#clBuf + 1] = string.format("%.3f %.3f CYCLEBACK %s %.3f -> %.3f", RealTime(), CurTime(),
					ent:GetSequenceName(seq), st.cyc, cyc)
			end
			if RealFrameTime() > 0.05 then
				clBuf[#clBuf + 1] = string.format("%.3f %.3f HITCH frame %.0f ms seq=%s", RealTime(), CurTime(),
					RealFrameTime() * 1000, ent:GetSequenceName(seq))
			end
			st.pos = pos
			st.seq, st.cyc, st.charging, st.ground = seq, cyc, charging, ground
		end
		if #clBuf > 0 and RealTime() > clFlush then
			file.Append("alex_mercer_debug_cl.txt", table.concat(clBuf, "\n") .. "\n")
			clBuf, clFlush = {}, RealTime() + 1
		end
	end)

	-- the disguise: the consumed one's own model drawn in his place with its own idle / walk / run / jump (Mercer's
	-- anims are on the game's skeleton, not an HL2 human's); his powers (attacks, parkour, the wall, a grab - any
	-- sequence that isn't his loco / stand / jump / land) show Mercer himself through it
	local function disguiseModel(self)
		local mdl = self:GetNW2String("MercerDisguiseModel", "")
		if mdl == "" then return end
		local pm = self.MercerPuppet
		if not IsValid(pm) or pm:GetModel() ~= mdl then
			-- (a new look while disguised: the old one stays for the sweep out - ENT:Draw, MercerPuppetOld)
			if IsValid(pm) then
				if IsValid(self.MercerPuppetOld) then self.MercerPuppetOld:Remove() end
				self.MercerPuppetOld = pm
				pm:SetNoDraw(true) -- (the old look going out casts no shadow)
				self:CallOnRemove("MercerPuppetOld", function() if IsValid(pm) then pm:Remove() end end)
				-- (user 2026-10-30: "changing looks in disguise he took Mercer's own look first") the new model can come
				-- before the swap's NW2 MercerDisgLookT: with no sweep running the old puppet was dropped at once and the
				-- sweep then went out from Mercer himself - a change of look while disguised starts its sweep here, from
				-- the old one (not over a putting-on / taking-off sweep)
				if self.MercerDisgWas and not self.MercerDisgSw then
					self.MercerDisgSw = {t0 = CurTime(), up = math.random(2) == 1, look = true}
					self:MercerDisgTrace("look sweep (model)", true)
				end
			end
			pm = ClientsideModel(mdl, RENDERGROUP_OPAQUE)
			if not IsValid(pm) then return end
			pm:SetNoDraw(true)
			self.MercerPuppet = pm
			self:CallOnRemove("MercerPuppet", function() if IsValid(pm) then pm:Remove() end end)
		end
		pm:SetSkin(self:GetNW2Int("MercerDisguiseSkin", 0))
		for id, v in string.gmatch(self:GetNW2String("MercerDisguiseBG", ""), "(%d+)=(%d+)") do
			pm:SetBodygroup(tonumber(id), tonumber(v))
		end
		return pm
	end
	-- (debug: alex_mercer_debug_cl 1) the disguise's draw decisions - a look sweep, put on / taken off, and why Mercer
	-- himself would have been drawn while disguised - into garrysmod/data/alex_mercer_debug_cl.txt (each reason at most
	-- every 0.25 s; event = always)
	function ENT:MercerDisgTrace(why, event)
		local cv = GetConVar("alex_mercer_debug_cl")
		if not (cv and cv:GetBool()) then return end
		self.MercerDisgTraceT = self.MercerDisgTraceT or {}
		if not event and RealTime() < (self.MercerDisgTraceT[why] or 0) then return end
		self.MercerDisgTraceT[why] = RealTime() + 0.25
		local sw = self.MercerDisgSw
		file.Append("alex_mercer_debug_cl.txt", string.format("%.3f DISG %s seq=%s disguised=%s model=%s puppet=%s old=%s "
			.. "sweep=%s\n", RealTime(), why, self:GetSequenceName(self:GetSequence()) or "?",
			tostring(self:GetNW2Bool("MercerDisguised")), self:GetNW2String("MercerDisguiseModel", ""),
			IsValid(self.MercerPuppet) and self.MercerPuppet:GetModel() or "-", tostring(IsValid(self.MercerPuppetOld)),
			sw and ((sw.look and "look " or "onoff ") .. string.format("%.2f", CurTime() - sw.t0)) or "none"))
	end
	local function powersShowing(self)
		-- (user 2026-10-29: "in disguise, consuming someone, he must not show his own look and then change - the look
		-- stays and goes straight to the new one") a grab / consume no longer shows Mercer through the disguise: the
		-- puppet plays those anims retargeted; the wall still does
		if self:GetNW2Bool("MercerWall") then return true end
		local seq = string.lower(self:GetSequenceName(self:GetSequence()) or "")
		return not (seq:find("^mercer_") or seq:find("^alex_loco_") or seq:find("^alex_amb_") or seq:find("jump", 1, true)
			or seq:find("land", 1, true) or seq:find("fall", 1, true))
	end
	local function disguiseRetarget(self, pm)
		local RT = ALEX_MERCER_RETARGET
		if not RT then return false end
		-- (FPS: 3.4 ms a frame in disguise - the engine draws him more than once a frame) the retarget once a frame
		if pm.MercerRetFrame == FrameNumber() then
			pm.MercerDrawing = true -- (its RenderOverride draws only for us: drawAs)
			pm:DrawModel()
			pm.MercerDrawing = nil
			return true
		end
		local pr = RT.restOf(self:GetModel(), {"reference"})
		local nr = RT.restOf(pm:GetModel(), {"ragdoll", "reference"})
		if not (pr and nr) then return false end
		-- his render matrix (the wall run's tilt ...) on his bones - read with the matrix off, so it is applied once
		-- (user: the disguise was thrown back on the wall)
		local T
		local rm = self:MercerRenderMatrix()
		if rm then
			local W = self:GetWorldTransformMatrix()
			T = W * rm * W:GetInverseTR()
		end
		if self.MercerMatrixOn then
			self:DisableMatrix("RenderMultiply")
			self.MercerMatrixOn = false
		end
		self:InvalidateBoneCache()
		self:SetupBones()
		local pose = {}
		for b = 0, self:GetBoneCount() - 1 do
			local bm = self:GetBoneMatrix(b)
			if bm then pose[self:GetBoneName(b)] = T and T * bm or bm end
		end
		local base, up = self:GetPos(), nil
		if T then
			-- (the wall run's tilt: his feet and his up as drawn)
			up = T * (base + Vector(0, 0, 1)) - T * base
			base = T * base
		end
		local out = RT.retarget(pm, pose, pr, nr, base, up)
		if not out then return false end
		if not pm.MercerDisguiseSeq then
			-- (its own idle under the retarget: the bones it doesn't map - fingers, twists - keep their places)
			local sq = pm:SelectWeightedSequence(ACT_IDLE)
			if sq and sq >= 0 then pm:ResetSequence(sq) end
			pm.MercerDisguiseSeq = true
		end
		pm:SetPos(self:GetPos())
		pm:SetAngles(Angle(0, self:GetAngles().y, 0))
		pm.MercerVictimT, pm.MercerVictimTT = out, CurTime()
		pm:SetEyeTarget(EyePos())
		if not pm.MercerVictimCb then
			pm.MercerVictimCb = pm:AddCallback("BuildBonePositions", RT.buildBones)
			pm:SetRenderBounds(Vector(-120, -120, -40), Vector(120, 120, 160))
		end
		pm:InvalidateBoneCache()
		pm:SetupBones()
		pm.MercerDrawing = true
		pm:DrawModel()
		pm.MercerDrawing = nil
		pm.MercerRetFrame = FrameNumber()
		return true
	end
	-- the power arms over the disguise: the consumed one's forearms and hands under them collapse (per model, by the
	-- power's side: blade / whip the right, the shield the left, claws / hammers / musclemass both)
	local POWER_SIDE = {claws = "LR", blade = "R", hammer = "LR", whip = "R", muscle = "LR", shield = "L"}
	local function hideArms(e)
		local side = e.MercerHideSide
		if not side or side == "" then return end
		local list = e.MercerHideBones
		if not list or e.MercerHideFor ~= side then
			list = {}
			for b = 0, e:GetBoneCount() - 1 do
				local n = e:GetBoneName(b) or ""
				for c in string.gmatch(side, ".") do
					if string.find(n, "_" .. c .. "_Forearm", 1, true) or string.find(n, "_" .. c .. "_Hand", 1, true)
						or string.find(n, "_" .. c .. "_Finger", 1, true) or string.find(n, "_" .. c .. "_Ulna", 1, true)
						or string.find(n, "_" .. c .. "_Wrist", 1, true) then
						list[#list + 1] = b
					end
				end
			end
			e.MercerHideBones, e.MercerHideFor = list, side
		end
		for _, b in ipairs(list) do
			local m = e:GetBoneMatrix(b)
			if m then
				m:Scale(Vector(0.01, 0.01, 0.01))
				e:SetBoneMatrix(b, m)
			end
		end
	end
	local function puppetThink(self, pm)
		local v = self:GetVelocity():Length2D()
		local pos = self:GetPos()
		local ground = util.TraceLine({start = pos + Vector(0, 0, 4), endpos = pos - Vector(0, 0, 12), filter = self,
			mask = MASK_SOLID_BRUSHONLY}).Hit
		local act = (not ground and ACT_JUMP) or (v > 150 and ACT_RUN) or (v > 15 and ACT_WALK) or ACT_IDLE
		if pm.MercerAct ~= act then
			local seq = pm:SelectWeightedSequence(act)
			if seq < 0 and act == ACT_JUMP then seq = pm:SelectWeightedSequence(ACT_GLIDE) end
			if seq < 0 then seq = pm:SelectWeightedSequence(ACT_IDLE) end
			pm.MercerAct = act
			if seq >= 0 then pm:ResetSequence(seq) end
		end
		local gs = pm:GetSequenceGroundSpeed(pm:GetSequence())
		local rate = (gs > 1 and v > 15) and math.Clamp(v / gs, 0.5, 3) or 1
		pm:SetCycle((pm:GetCycle() + FrameTime() * rate / math.max(pm:SequenceDuration(), 0.1)) % 1)
		pm:SetPoseParameter("move_x", 1)
		pm:SetPoseParameter("move_y", 0)
		pm:SetPoseParameter("move_yaw", 0)
		pm:SetPos(pos)
		pm:SetAngles(Angle(0, self:GetAngles().y, 0))
		pm:SetupBones()
	end

	-- The consume veins (prototype_consume transform/stuff/shader_effect and the long transformations' {shader}:
	-- effectConsume). (user: in the game shimmering black veins crawl over him when he mutates - smooth, crisp, like
	-- cracks) The game's consume maps (consume_color_diffuse: black tendrils over dark biomass, + its normal map:
	-- tools/veintex.py) on a second pass of the body, alpha-tested at a threshold that falls as the veins grow in -
	-- the alpha is each tendril's distance from its edge, so they grow from their centre lines, the thick ones first
	-- - and glossy (phong over the bumps). They spread joint by joint at the wave's own times (fxprogs transform_<wave>:
	-- the earliest item on each joint) over the parts that change: the arms for the claws / hammer / fists, the right
	-- arm for the blade / whip, the left for the shield, all of him for the armour / muscles / spines. Each joint's
	-- veins grow in 0.15 s, hold, go (timeReveal 0.3 s). The armour's long transformation is the solid mode (all of the
	-- biomass) from the head down, 1-4.5 s. One bonemerged copy of the model per threshold, the joints at the other
	-- thresholds collapsed in it.
	local VEINS = {}
	do
		local REF = {0.8, 0.55, 0.3, 0.1, 0.005}
		local SOLID = #REF
		VEINS.SOLID = SOLID
		local mats = {}
		function VEINS.mat(i)
			if not mats[i] then
				local tr = "center 0 0 scale 2.5 2.5 rotate 0 translate 0 0"
				mats[i] = CreateMaterial("alex_mercer_veins" .. i, "VertexLitGeneric", {
					["$basetexture"] = "alex_mercer/fx/consume_veins", ["$bumpmap"] = "alex_mercer/fx/consume_veins_n",
					["$basetexturetransform"] = tr, ["$bumptransform"] = tr, ["$alphatest"] = "1",
					["$alphatestreference"] = tostring(REF[i]), ["$allowalphatocoverage"] = "1", ["$phong"] = "1",
					["$phongexponent"] = "18", ["$phongboost"] = "3", ["$phongfresnelranges"] = "[0.3 0.7 1]",
					["$color2"] = "[0.85 0.62 0.58]"})
			end
			return mats[i]
		end
		local ARM_KEYS = {"Clavicle", "Shoulder", "Elbow", "Forarm", "Wrist", "Index", "Middle", "Ring", "Pink", "Thumb",
			"Whip", "Grapple"}
		local function armSide(name)
			for _, k in ipairs(ARM_KEYS) do
				if string.find(name, k, 1, true) then
					local r = string.find(name, "_R", 1, true) or string.find(name, "Whip", 1, true) or string.sub(name, 1, 2) == "R_"
					return r and "R" or "L"
				end
			end
		end
		local KIND_REGION = {blade = "R", whip = "R", shield = "L", claws = "LR", hammer = "LR", muscle = "ALL",
			spines = "ALL"}
		-- the parts that change between two of his models ("" = none)
		function VEINS.region(last, mdl)
			local wasArm, isArm = string.find(last, "_armor", 1, true) ~= nil, string.find(mdl, "_armor", 1, true) ~= nil
			if wasArm ~= isArm then return "ALL" end
			local a = KIND_REGION[string.match(last, "alex_mercer_(%a+)") or ""] or ""
			local b = KIND_REGION[string.match(mdl, "alex_mercer_(%a+)") or ""] or ""
			if a == "ALL" or b == "ALL" then return "ALL" end
			if a == b then return a end
			return a .. b
		end
		-- each joint's time: the wave program's earliest item on it, else its parent's + a frame
		local function boneTimes(e, wave, region, stretch)
			local prog = ALEX_MERCER_FXPROG and ALEX_MERCER_FXPROG[wave]
			if not prog or region == "" then return nil end
			local jt = {}
			for _, it in ipairs(prog) do
				if it[2] ~= "" then jt[it[2]] = math.min(jt[it[2]] or 99, it[6]) end
			end
			local pel = math.min(jt.Spine_1 or 99, jt.Hip_L or 99, jt.Hip_R or 99)
			local function tOf(i, depth)
				local name = e:GetBoneName(i)
				if jt[name] then return jt[name] end
				if name == "Pelvis" then return pel end
				local p = e:GetBoneParent(i)
				if not p or p < 0 or depth > 40 then return pel end
				return tOf(p, depth + 1) + 0.033
			end
			local T, last = {}, 0
			for i = 0, e:GetBoneCount() - 1 do
				local name = e:GetBoneName(i)
				local side = armSide(name)
				if region == "ALL" or side and string.find(region, side, 1, true) then
					T[name] = tOf(i, 0) * (stretch or 1)
					last = math.max(last, T[name])
				end
			end
			return T, last
		end
		local function level(vs, tau)
			local c
			if tau <= 0 then return 0
			elseif tau < vs.grow then c = tau / vs.grow
			elseif tau < vs.grow + vs.hold then c = 1
			elseif tau < vs.grow + vs.hold + vs.recede then c = 1 - (tau - vs.grow - vs.hold) / vs.recede
			else return 0 end
			return math.max(1, math.min(vs.top, math.ceil(c * vs.top)))
		end
		-- a copy shows only its own threshold's joints: the others collapse to a point
		local ZERO = Vector(0, 0, 0)
		local function collapseCb(e, nb)
			local vs = e.MercerVeins
			if not vs or vs.dead then return end
			local lvl = e.MercerVeinLevel
			for i = 0, (nb or e:GetBoneCount()) - 1 do
				if vs.lvl[e:GetBoneName(i)] ~= lvl then
					local m = e:GetBoneMatrix(i)
					if m then
						m:Scale(ZERO)
						e:SetBoneMatrix(i, m)
					end
				end
			end
		end
		local function dropModels(vs)
			for _, m in pairs(vs.models) do if IsValid(m) then m:Remove() end end
			vs.models = {}
		end
		local function makeModels(self, vs)
			dropModels(vs)
			vs.mdl = self:GetModel()
			for l = 1, vs.top do
				local m = ClientsideModel(vs.mdl, RENDERGROUP_OPAQUE)
				if IsValid(m) then
					m:SetNoDraw(true)
					m:SetParent(self)
					m:AddEffects(EF_BONEMERGE)
					m.MercerVeins, m.MercerVeinLevel = vs, l
					m:AddCallback("BuildBonePositions", collapseCb)
					vs.models[l] = m
				end
			end
		end
		function VEINS.clear(self)
			if self.MercerVeins then
				self.MercerVeins.dead = true
				dropModels(self.MercerVeins)
			end
			self.MercerVeins = nil
		end
		-- a run of veins from t0: mode "fade" (a switch) or "solid" (the armour's long transformation)
		function VEINS.start(self, wave, region, t0, mode, stretch)
			local T, last = boneTimes(self, wave, region, stretch)
			if not T then return end
			VEINS.clear(self)
			local solid = mode == "solid"
			local vs = {t0 = t0, T = T, lvl = {}, models = {}, top = solid and SOLID or SOLID - 1, solid = solid,
				grow = solid and 0.3 or 0.15, hold = solid and 1.2 or 0.2, recede = solid and 0.6 or 0.3}
			vs.done = last + vs.grow + vs.hold + vs.recede + 0.05
			makeModels(self, vs)
			self.MercerVeins = vs
			self:CallOnRemove("MercerVeins", function(e) VEINS.clear(e) end)
		end
		function VEINS.draw(self)
			local vs = self.MercerVeins
			if not vs then return end
			local t = CurTime() - vs.t0
			if t > vs.done then return VEINS.clear(self) end
			if t <= 0 then return end
			-- the armour grows under its biomass: the copies follow the model swap
			if vs.mdl ~= self:GetModel() then makeModels(self, vs) end
			local used = {}
			for name, T in pairs(vs.T) do
				local l = level(vs, t - T)
				vs.lvl[name] = l
				used[l] = true
			end
			render.DepthRange(0, 0.99995)
			for l, m in pairs(vs.models) do
				if used[l] and IsValid(m) then
					render.MaterialOverride(VEINS.mat(l))
					m:SetupBones()
					m:DrawModel()
				end
			end
			render.MaterialOverride()
			render.DepthRange(0, 1)
		end
	end

	-- (user: in the game a mutation comes out of a black nothing and goes back into it) prototype_consume
	-- transform/stuff/shader_effect: the old parts' fade_out (effectConsume 0.45-0.5 s) and the new parts' fade_in (1 s),
	-- a dark band sweeping toe_to_head or head_to_toe (random, as the start node picks). The power parts = the model's
	-- materials the plain body lacks: the new ones are revealed under a sweeping clip plane with a black band at its
	-- edge (0.7 s), the old ones (a bonemerged copy of the old model, power parts only) eaten by the same band (0.45 s)
	local swapDraw
	do
		local BASE_MDL = "models/mercer/alex_mercer.mdl"
		local INVIS = "alex_mercer/fx/invisible"
		local IN_T, OUT_T, BAND = 0.7, 0.45, 20
		local baseMats, slotCache = nil, {}
		local function powerSlots(e)
			local mdl = e:GetModel()
			if slotCache[mdl] then return slotCache[mdl] end
			if not baseMats then
				baseMats = {}
				local b = ClientsideModel(BASE_MDL)
				if IsValid(b) then
					for _, m in ipairs(b:GetMaterials()) do baseMats[m] = true end
					b:Remove()
				end
			end
			local out = {}
			for i, m in ipairs(e:GetMaterials()) do if not baseMats[m] then out[i - 1] = true end end
			slotCache[mdl] = out
			return out
		end
		-- draw only the power parts (or only the rest), optionally as the band of solid consume biomass at the sweep's
		-- edge; sub-materials restored after
		-- (user: his silhouette showed through the disguise - the see-through sub-material still drew something) the
		-- parts left out are drawn with engine/writez: depth only, never a colour
		local WRITEZ = Material("engine/writez")
		local function drawParts(e, slots, onlyPower, black)
			local n = #e:GetMaterials()
			local vm = black and VEINS.mat(VEINS.SOLID)
			for i = 0, n - 1 do
				if (slots[i] ~= nil) ~= onlyPower then render.MaterialOverrideByIndex(i, WRITEZ)
				elseif vm then render.MaterialOverrideByIndex(i, vm) end
			end
			e:DrawModel()
			render.MaterialOverrideByIndex()
		end
		-- the sweep's height (toe_to_head: up, head_to_toe: down) and the clip planes keeping one side / the band
		local function clip(nrm, d) render.PushCustomClipPlane(nrm, d) end
		local function band(e, slots, h, up, below)
			-- below = the part on the swept side (revealed for the new, eaten for the old)
			local old = render.EnableClipping(true)
			local U, D = Vector(0, 0, 1), Vector(0, 0, -1)
			if below then clip(D, -h) else clip(U, h) end -- the visible part
			drawParts(e, slots, true)
			render.PopCustomClipPlane()
			-- the black band at the edge, on the visible side
			if below then clip(D, -h) clip(U, h - BAND) else clip(U, h) clip(D, -(h + BAND)) end
			drawParts(e, slots, true, true)
			render.PopCustomClipPlane()
			render.PopCustomClipPlane()
			render.EnableClipping(old)
		end
		local REGIONS = {
			{0.00, {"Pelvis", "Spine_1", "Spine_2", "Spine_3", "Clavicle_L", "Clavicle_R", "Shoulder_Con_L", "Shoulder_Con_R"}},
			{0.18, {"Hip_L", "Knee_L", "Ankle_L", "Ball_L", "Hip_R", "Knee_R", "Ankle_R", "Ball_R"}},
			{0.36, {"Shoulder_L", "Elbow_L", "Forarm_L", "Wrist_L", "Shoulder_R", "Elbow_R", "Forarm_R", "Wrist_R"}},
			{0.54, {"Neck", "Head", "Jaw", "Brow", "EyeLid"}},
		}
		local GROW_T, ARM_IN, ARM_OUT = 0.45, 1.0, 0.6
		local function growScale(k)
			if k <= 0 then return 0.6 end
			if k < 0.7 then return Lerp(k / 0.7, 0.6, 1.08) end
			return Lerp(math.min(1, (k - 0.7) / 0.3), 1.08, 1)
		end
		-- the new model's materials the old one lacks (the armour plates)
		local addedCache = {}
		local function addedSlots(e, old)
			local key = e:GetModel() .. "|" .. old:GetModel()
			if addedCache[key] then return addedCache[key] end
			local have = {}
			for _, m in ipairs(old:GetMaterials()) do have[m] = true end
			local out = {}
			for i, m in ipairs(e:GetMaterials()) do if not have[m] then out[i - 1] = true end end
			addedCache[key] = out
			return out
		end
		local function dropSwap(sw)
			if not sw then return end
			if IsValid(sw.old) then sw.old:Remove() end
			if IsValid(sw.grow) then sw.grow:Remove() end
		end
		local function armourCb(e)
			local sw = e.MercerSwap
			if not sw or not sw.armourOn then return end
			local t = CurTime() - sw.t0
			if t > ARM_IN then return end
			for _, r in ipairs(REGIONS) do
				local sc = growScale((t - r[1]) / GROW_T)
				if sc ~= 1 then
					for _, nm in ipairs(r[2]) do
						local b = e:LookupBone(nm)
						local m = b and e:GetBoneMatrix(b)
						if m then
							m:Scale(Vector(sc, sc, sc))
							e:SetBoneMatrix(b, m)
						end
					end
				end
			end
		end
		-- the armour's long transformation (alex_act_armor_transformation, 121 frames): the game draws the body and the
		-- armour together, the body's joints shrinking to 0.1 (its anim's scale channels) as the armour's grow from 0.1
		-- (alex_act_armor_transformation_armor) on the same joints - the armour grows out of him region by region. His
		-- model swaps mid-way (1.667 s); the other one is a copy playing the same frame, only the parts his lacks drawn
		local ARMOUR_ANIM = "alex_act_armor_transformation"
		local function armourMate(self)
			local mdl = self:GetModel()
			local other = string.find(mdl, "_armor", 1, true) and string.gsub(mdl, "_armor%.mdl$", ".mdl")
				or string.gsub(mdl, "%.mdl$", "_armor.mdl")
			local c = self.MercerArmourMate
			if not IsValid(c) or c:GetModel() ~= other then
				if IsValid(c) then c:Remove() end
				if not util.IsValidModel(other) or not ALEX_MERCER_SCALE_ATTACH then return end
				c = ClientsideModel(other, RENDERGROUP_OPAQUE)
				if not IsValid(c) then return end
				c:SetNoDraw(true)
				ALEX_MERCER_SCALE_ATTACH(c)
				self.MercerArmourMate = c
				self:CallOnRemove("MercerArmourMate", function(e) if IsValid(e.MercerArmourMate) then e.MercerArmourMate:Remove() end end)
			end
			local sq = c:LookupSequence(self:GetSequenceName(self:GetSequence()))
			if not sq or sq < 0 then return end
			if c:GetSequence() ~= sq then c:ResetSequence(sq) end
			c:SetPlaybackRate(0)
			c:SetCycle(self:GetCycle())
			c:SetPos(self:GetPos())
			c:SetAngles(self:GetAngles())
			local m = self:MercerRenderMatrix()
			if m then c:EnableMatrix("RenderMultiply", m) else c:DisableMatrix("RenderMultiply") end
			c:InvalidateBoneCache()
			c:SetupBones()
			drawParts(c, addedSlots(c, self), true)
		end
		-- the whole model, or (in disguise) only its power parts
		local function whole(self, powersOnly)
			if powersOnly then
				local slots = powerSlots(self)
				if next(slots) then drawParts(self, slots, true) end
				return
			end
			self:DrawModel()
		end
		function swapDraw(self, powersOnly)
			local mdl = self:GetModel()
			-- (user 2026-10-22: the armour's transformation no longer shrinks him and grows a copy - the armour sweeps
			-- in out of nothing like a mutation and his old parts fade away slowly under biomass: armourMate unused)
			local last = self.MercerLastMdl
			self.MercerLastMdl = mdl
			local sw = self.MercerSwap
			if last and last ~= mdl and string.StartWith(last, "models/mercer/") then
				dropSwap(sw)
				local old = ClientsideModel(last, RENDERGROUP_OPAQUE)
				if IsValid(old) then
					old:SetNoDraw(true)
					old:SetParent(self)
					old:AddEffects(EF_BONEMERGE)
				end
				local wasArm, isArm = string.find(last, "_armor", 1, true) ~= nil, string.find(mdl, "_armor", 1, true) ~= nil
				sw = {t0 = CurTime(), up = math.random(2) == 1, old = old, armourOn = isArm and not wasArm,
					armourOff = wasArm and not isArm}
				self.MercerSwap = sw
				local fx, ft = self:GetNW2String("MercerFx", ""), self:GetNW2Float("MercerFxT", 0)
				local wave, delay = string.match(fx, "transform_([%a_]+):([%-%d%.]+)")
				if wave == "toe_to_head" then sw.up = true elseif wave == "head_to_toe" then sw.up = false end
				-- (the armour's long transformation runs its own solid veins: the swap only moves them to the new model)
				if not (self.MercerVeins and self.MercerVeins.solid) then
					VEINS.start(self, "transform_" .. (wave or "chest_out"), VEINS.region(last, mdl),
						wave and math.min(ft + tonumber(delay), CurTime()) or CurTime() - 0.12, "fade")
				end
				-- (user: the old parts go slowly, darkening, invisible only at the very end - just before the effects end) the
				-- sweep over the old parts lasts as long as the switch's veins, minus 0.2 s
				local vs = self.MercerVeins
				sw.outT = vs and vs.done and math.Clamp(vs.t0 + vs.done - sw.t0 - 0.2, OUT_T, 2.5) or 1.4
			end
			if not sw then return whole(self, powersOnly) end
			local t = CurTime() - sw.t0
			if t > math.max(IN_T, sw.outT or OUT_T) then
				dropSwap(sw)
				self.MercerSwap = nil
				return whole(self, powersOnly)
			end
			local z0 = self:GetPos().z - 4
			local function height(k) return sw.up and z0 + 88 * k or z0 + 88 * (1 - k) end
			-- the body as usual, the new power parts revealed on the swept side
			-- (prototype_consume: the defense bank's switch is the same transform/stuff/shader_effect as a mutation's) the
			-- armour on / off: the parts that differ between the two models, swept like a mutation's
			local arm = (sw.armourOn or sw.armourOff) and IsValid(sw.old)
			local slots = arm and addedSlots(self, sw.old) or powerSlots(self)
			if not powersOnly then drawParts(self, slots, false) end
			if next(slots) then
				local k = math.Clamp(t / IN_T, 0, 1)
				band(self, slots, height(k), sw.up, sw.up)
			end
			-- the old power parts: eaten by the band (the part not yet swept stays)
			local old = sw.old
			local outT = sw.outT or OUT_T
			if IsValid(old) and t < outT then
				local oslots = arm and addedSlots(old, self) or powerSlots(old)
				if next(oslots) then
					old:SetupBones()
					-- slow at first, quicker at the end (most of the part stays till late), darkening to the biomass
					local k = math.Clamp(t / outT, 0, 1)
					local d = k * k * (3 - 2 * k)
					render.SetColorModulation(Lerp(d, 1, 0.15), Lerp(d, 1, 0.06), Lerp(d, 1, 0.06))
					band(old, oslots, height(k * k), sw.up, not sw.up)
					render.SetColorModulation(1, 1, 1)
					-- (user: he fades out under particles) the armour: biomass flaking off where the band eats his old parts
					local V = ALEX_MERCER_VFX
					if sw.armourOn and V and V.Emit and V.EMITTERS and V.EMITTERS.charge and CurTime() >= (sw.pT or 0) then
						sw.pT = CurTime() + 0.04
						local c, hz = self:GetPos(), height(k * k)
						for _ = 1, 2 do
							local a = math.random() * 2 * math.pi
							local dir = Vector(math.cos(a), math.sin(a), 0)
							V.Emit(V.EMITTERS.charge, Vector(c.x, c.y, hz) + dir * math.Rand(6, 14), dir + Vector(0, 0, 0.3),
								nil, math.Rand(0.9, 1.6), 1)
						end
					end
				end
			end
		end
	end

	-- his look drawn as disguised (want) or not; bare = a second pass this frame (the fading old look, the band):
	-- no shadow toggling, no veins / whip again
	local function drawAs(self, want, bare, oldLook)
		-- the jacket's flexes (lua/autorun/client/alex_mercer_vest.lua), after the network update, before the draw
		if ALEX_MERCER_VEST_APPLY and not bare then ALEX_MERCER_VEST_APPLY(self) end
		-- oldLook: the previous disguise's puppet, going out under a change of look
		local pm = want and (oldLook or disguiseModel(self))
		-- (user 2026-10-30: "the consumed one has no shadow - the gun has one") his own shadow is off in the disguise (it
		-- showed his silhouette) and the hand-drawn puppet had none: the look he wears is let out of NoDraw for the
		-- engine's shadow (drawn apart from RenderOverride, its bones from the retarget's callback) with a RenderOverride
		-- that skips the engine's own pass - the puppet itself is drawn here, in his Draw (the old look going out / no
		-- disguise: NoDraw)
		if pm and not oldLook and not bare then
			if pm.MercerShadowSet ~= 3 then -- (3: the puppets made under the earlier overrides get this one)
				pm.MercerShadowSet = 3
				-- (user 2026-10-30 screenshot: the disguise invisible, only its gun and shadow) DrawModel from his Draw goes
				-- through RenderOverride too: it draws when we draw it (MercerDrawing), not in the engine's own pass; and
				-- once his Draw stops placing it (he is out of view, in another room) back to NoDraw - no shadow left
				-- standing where he was last drawn (2 frames of slack: the engine may draw it before him in a frame)
				pm.RenderOverride = function(e, flags)
					if e.MercerDrawing then
						e:DrawModel(flags)
					elseif FrameNumber() - (e.MercerPlacedFrame or 0) > 2 then
						e:SetNoDraw(true)
					end
				end
				if pm.CreateShadow then pm:CreateShadow() end
				pm:DrawShadow(true)
			end
			pm.MercerPlacedFrame = FrameNumber()
			if pm:GetNoDraw() then pm:SetNoDraw(false) end
		end
		-- (user: his silhouette showed through the disguise) the engine's shadow of his own model goes while disguised
		-- (every frame: a model swap - a mutation switch - brought the networked shadow back, user)
		local disg = pm and true or false
		if not bare and (disg or self.MercerShadowOff) then
			self.MercerShadowOff = disg
			self:DrawShadow(not disg)
		end
		if pm then
			-- the full disguise (user): the consumed one's model moves with all of his anims - his bones retargeted onto
			-- its ValveBiped skeleton like the grab victim (alex_mercer_victim.lua); failing that, the old way.
			-- (user) the mutations show on it: only his power parts drawn over it, its forearms / hands under them gone
			pm.MercerHideSide = POWER_SIDE[string.match(self:GetModel(), "alex_mercer_(%a+)%.mdl$") or ""] or ""
			if disguiseRetarget(self, pm) then
				if self.MercerVeins then VEINS.clear(self) end -- (no veins over the disguise; their copies cost frames)
				-- (after the retarget's own bone callback, so it runs last)
				if not pm.MercerHideCb then pm.MercerHideCb = pm:AddCallback("BuildBonePositions", hideArms) end
				local m = self:MercerRenderMatrix()
				if m then
					self:EnableMatrix("RenderMultiply", m)
				elseif self.MercerMatrixOn then
					self:DisableMatrix("RenderMultiply")
				end
				self.MercerMatrixOn = m ~= nil
				self:InvalidateBoneCache()
				swapDraw(self, true)
				if ALEX_MERCER_WHIP and ALEX_MERCER_WHIP.Draw and not bare then ALEX_MERCER_WHIP.Draw(self) end
				return
			end
			-- no retarget this frame: the puppet the old way (its own idle / walk); (user 2026-10-30: "in disguise,
			-- consuming another, he turns back into Mercer first") a power / finisher anim no longer shows Mercer himself
			-- through it - only the wall still does (powersShowing)
			if not self:GetNW2Bool("MercerWall") then
				self:MercerDisgTrace("retarget failed")
				puppetThink(self, pm)
				pm.MercerDrawing = true
				pm:DrawModel()
				pm.MercerDrawing = nil
				return
			end
		elseif want then
			self:MercerDisgTrace("no puppet")
		end
		local m = self:MercerRenderMatrix()
		if m then
			self:EnableMatrix("RenderMultiply", m)
			self:SetRenderBounds(Vector(-80, -80, -20), Vector(80, 80, 120))
		elseif self.MercerMatrixOn then
			self:DisableMatrix("RenderMultiply")
		end
		self.MercerMatrixOn = m ~= nil
		swapDraw(self)
		if bare then return end
		-- the armour's long transformation (NW2 MercerArmourFxT): the solid biomass from the head down, 1-4.5 s
		local aft = self:GetNW2Float("MercerArmourFxT", 0)
		if aft > 0 and aft ~= self.MercerArmourFxSeen then
			self.MercerArmourFxSeen = aft
			if CurTime() - aft < 1 then VEINS.start(self, "transform_head_to_toe", "ALL", aft + 1, "solid", 2) end
		end
		VEINS.draw(self)
		-- the whipfist's whip (lua/autorun/client/alex_mercer_whip.lua)
		if ALEX_MERCER_WHIP and ALEX_MERCER_WHIP.Draw then ALEX_MERCER_WHIP.Draw(self) end
	end

	-- (user 2026-10-22: the disguise like the armour) putting it on / taking it off: the new look comes out of nothing
	-- under a sweeping clip plane with a band of solid biomass at its edge (a mutation's 0.7 s), the old one darkening
	-- and eaten slowly by the same sweep (1.5 s), biomass flaking off where it goes; the graph's transform wave over it
	local DISG_IN, DISG_OUT, DBAND = 0.7, 1.5, 20
	local DISG_FLAKE_B = {colVar = 5, life = 0.5, lifeVar = 0.5, size = 0.7, sizeVar = 1.5} -- (the transform wave's item biases)
	local function clipKeep(below, h)
		if below then render.PushCustomClipPlane(Vector(0, 0, -1), -h) else render.PushCustomClipPlane(Vector(0, 0, 1), h) end
	end
	-- The shield worn over any attack power: the shield alone (build_shield_part.py), bone-merged on him here on the client as the
	-- veins and the swap's old parts are, drawn only when he is.
	-- (user 2026-11-03, screenshot: "a transparent copy of him holds the shield, not the real one") it was a server prop of the
	-- whole shield model: it didn't merge on his bones, and its body, under an invisible material, still showed
	function ENT:MercerShieldDraw()
		if not self:GetNW2Bool("MercerShieldShown") then return end
		local m = self.MercerShieldPart
		if not IsValid(m) then
			m = ClientsideModel("models/mercer/alex_mercer_shield_part.mdl", RENDERGROUP_OPAQUE)
			if not IsValid(m) then return end
			m:SetNoDraw(true)
			m:SetParent(self)
			m:AddEffects(EF_BONEMERGE)
			self.MercerShieldPart = m
			self:CallOnRemove("alex_mercer_shield_part", function(e)
				if IsValid(e.MercerShieldPart) then e.MercerShieldPart:Remove() end
			end)
		end
		m:DrawModel()
	end

	function ENT:Draw()
		ALEX_MERCER_MPSMOOTH(self) -- (MP fix 8: drawn at the smoothed place)
		self:MercerShieldDraw()
		-- (debug trace, MP fix 8 check: the place he is really drawn at, frame to frame; the server's position steps)
		if GetConVar("alex_mercer_debug_cl"):GetBool() and self.MercerDrawFrame ~= FrameNumber() then
			self.MercerDrawFrame = FrameNumber()
			local pos, ft = self:GetPos(), math.max(RealFrameTime(), 0.001)
			local d = self.MercerDrawLast and pos:Distance(self.MercerDrawLast) or 0
			local spd = self.MercerDrawSpd or d / ft
			if d > 8 and d > spd * ft * 2.5 + 3 then
				local s = self.MercerSm
				file.Append("alex_mercer_debug_cl.txt", string.format("%.3f DRAWJUMP %.1f u (speed %.0f u/s) net=%s "
					.. "samples=%d gap=%.3f smooth=%s\n", RealTime(), d, spd, tostring(self:GetNetworkOrigin()),
					s and #s or 0, s and #s > 1 and s[#s].t - s[#s - 1].t or 0, tostring(self.MercerSmPos ~= nil)))
			end
			self.MercerDrawSpd = Lerp(0.2, spd, d / ft)
			self.MercerDrawLast = pos
		end
		local f = self:GetMercerForm()
		local want = (f and f.kind == "disguise") or self:GetNW2Bool("MercerDisguised")
		if self.MercerDisgWas == nil then self.MercerDisgWas = want end
		if want ~= self.MercerDisgWas then
			self.MercerDisgWas = want
			self.MercerDisgSw = {t0 = CurTime(), up = math.random(2) == 1}
			self:MercerDisgTrace(want and "put on" or "taken off", true)
		end
		-- (no disguise: its puppet casts no shadow)
		if not want and IsValid(self.MercerPuppet) and not self.MercerPuppet:GetNoDraw() then self.MercerPuppet:SetNoDraw(true) end
		-- (player / user 2026-10-29) a new look while disguised (NW2 MercerDisgLookT, after the consume): the same sweep,
		-- from the old disguise to the new one
		local lt = self:GetNW2Float("MercerDisgLookT", 0)
		if lt ~= self.MercerDisgLookSeen then
			self.MercerDisgLookSeen = lt
			-- (not restarted when the new model already started it)
			local cur = self.MercerDisgSw
			if want and CurTime() - lt < 1 and not (cur and cur.look and CurTime() - cur.t0 < 0.5) then
				self.MercerDisgSw = {t0 = CurTime(), up = math.random(2) == 1, look = true}
				self:MercerDisgTrace("look sweep (LookT)", true)
			end
		end
		-- the new look's model caught before the draw below (disguiseModel keeps the old puppet and starts the sweep)
		if want then disguiseModel(self) end
		local sw = self.MercerDisgSw
		local t = sw and CurTime() - sw.t0
		if not sw or t > DISG_OUT or not disguiseModel(self) then
			self.MercerDisgSw = nil
			if IsValid(self.MercerPuppetOld) then
				self.MercerPuppetOld:Remove()
				self.MercerPuppetOld = nil
			end
			return drawAs(self, want)
		end
		local z0 = self:GetPos().z - 4
		local function height(k) return sw.up and z0 + 88 * k or z0 + 88 * (1 - k) end
		local was = render.EnableClipping(true)
		-- the new look on the swept side
		local hIn = height(math.Clamp(t / DISG_IN, 0, 1))
		clipKeep(sw.up, hIn)
		drawAs(self, want)
		render.PopCustomClipPlane()
		-- its edge: the band of solid biomass
		if t < DISG_IN then
			clipKeep(sw.up, hIn)
			clipKeep(not sw.up, sw.up and hIn - DBAND or hIn + DBAND)
			render.MaterialOverride(VEINS.mat(VEINS.SOLID))
			drawAs(self, want, true)
			render.MaterialOverride()
			render.PopCustomClipPlane()
			render.PopCustomClipPlane()
		end
		-- the old look: the part not yet swept, slow at first, darkening to the biomass
		local k = math.Clamp(t / DISG_OUT, 0, 1)
		local hOut = height(k * k)
		local d = k * k * (3 - 2 * k)
		clipKeep(not sw.up, hOut)
		render.SetColorModulation(Lerp(d, 1, 0.15), Lerp(d, 1, 0.06), Lerp(d, 1, 0.06))
		if sw.look then
			-- the previous disguise; (user 2026-10-30: "he turns back into Mercer first") never Mercer himself. No old
			-- puppet: another of the same model consumed (a new look's time, the model the same - only its skin /
			-- bodygroups change), or the time come before the model - then the look he wears now is the old one (it
			-- drew nothing there: the unswept part of the body was gone for 0.7 s)
			local old = self.MercerPuppetOld
			if IsValid(old) then
				drawAs(self, true, true, old)
			else
				self:MercerDisgTrace("look sweep on the same model")
				drawAs(self, true, true)
			end
		else
			drawAs(self, not want, true)
		end
		render.SetColorModulation(1, 1, 1)
		render.PopCustomClipPlane()
		render.EnableClipping(was)
		-- biomass flaking off where it goes
		-- (user 2026-10-29: "a mess of particles above the head, too high", "match the rest") the sweep runs 88 u, the
		-- body ends near 72: no flakes above the head, and the flakes are the wave's own particles (type_effects
		-- transform_* items: scale 0.45, life x0.5, size x0.7 / var x1.5) - they were 2-3x bigger and lived twice as long
		local V = ALEX_MERCER_VFX
		if V and V.Emit and V.EMITTERS and V.EMITTERS.charge and CurTime() >= (sw.pT or 0) and hOut <= z0 + 76 then
			sw.pT = CurTime() + 0.04
			local c = self:GetPos()
			local hz = math.min(hOut, z0 + 72)
			for _ = 1, 2 do
				local a = math.random() * 2 * math.pi
				local dir = Vector(math.cos(a), math.sin(a), 0)
				V.Emit(V.EMITTERS.charge, Vector(c.x, c.y, hz) + dir * math.Rand(6, 14), dir + Vector(0, 0, 0.3), nil,
					math.Rand(0.9, 1.6) * 0.45, 1, {b = DISG_FLAKE_B})
			end
		end
	end
	-- (the full charge's effectConsume - the biomass tendrils spreading over the body from the chest - stays out: the
	-- user wants the veins only on the mutations)

end

